# ---- 입력 스킴 어댑터 -------------------------------------------------------
# 옵션에서 '마우스+키보드'를 선택하면 마우스 버튼을 키 입력으로 매핑한다.
# - 좌클릭 → Space (serve/스킬 등)
# - 우클릭 → Down
_orig_pygame_event_get = pygame.event.get

# 입력 추적(디버그) 플래그 – 기본 켜둠(사용자 요청), PINGF_INPUT_TRACE=0 으로 끌 수 있음
INPUT_TRACE = os.environ.get("PINGF_INPUT_TRACE", "1").lower() not in ("0", "false", "off")
_input_log_prev_left = False
_input_log_prev_right = False
_input_log_last_frame = -9999
_input_log_last_time = 0.0
# 이벤트 기반 이동 상태(포커스 상실 시 fallback)
MOVE_EVENT_LEFT = False
MOVE_EVENT_RIGHT = False
MOVE_EVENT_DOWN = False
MOVE_EVENT_UP = False


def _log_input_trace(frame: int,
                     keys,
                     left_raw: bool,
                     right_raw: bool,
                     snap_left: bool,
                     snap_right: bool,
                     stunned: bool,
                     wait_serve: bool,
                     serve_timer: int,
                     speed: float) -> None:
    """간헐적 이동 미반응을 추적하기 위한 경량 로그"""
    global _input_log_prev_left, _input_log_prev_right, _input_log_last_frame, _input_log_last_time
    if not INPUT_TRACE:
        return
    now = time.time()
    # 변화가 없으면 2초(120프레임)마다만 찍기
    changed = (left_raw != _input_log_prev_left) or (right_raw != _input_log_prev_right)
    if not changed and frame - _input_log_last_frame < 120:
        return
    _input_log_prev_left = left_raw
    _input_log_prev_right = right_raw
    _input_log_last_frame = frame
    _input_log_last_time = now
    print(
        "[INPUT_TRACE]"
        f" frame={frame}"
        f" left_raw={int(left_raw)} right_raw={int(right_raw)}"
        f" snapL={int(bool(snap_left))} snapR={int(bool(snap_right))}"
        f" K_LEFT={int(keys[pygame.K_LEFT])} K_RIGHT={int(keys[pygame.K_RIGHT])}"
        f" K_a={int(keys[pygame.K_a])} K_d={int(keys[pygame.K_d])}"
        f" evtL={int(MOVE_EVENT_LEFT)} evtR={int(MOVE_EVENT_RIGHT)}"
        f" stunned={stunned} wait_serve={wait_serve} serve_t={serve_timer}"
        f" speed={speed:.3f}"
        f" focus={pygame.key.get_focused()}"
    )

def _adapt_input_events(events):
    """입력 어댑터(안전 모드)

    - 좌/우 클릭 → 키 합성은 중단(프레임 루프에서 상태 병합으로 처리 중).
    - 코만도 전용: 마우스 휠로 화기 교체 지원(부작용 없음, 이벤트는 그대로 반환).
    """
    # 주: 휠/중클릭 무기 전환은 인게임(코만도) 루프에서만 처리하여 중복을 방지한다.
    return events

def _patched_event_get(*args, **kwargs):
    events = _orig_pygame_event_get(*args, **kwargs)
    if INPUT_TRACE:
        for ev in events:
            if ev.type in (pygame.KEYDOWN, pygame.KEYUP):
                ev_sc = getattr(ev, "scancode", None)
                ev_uni = getattr(ev, "unicode", "")
                ev_mod = getattr(ev, "mod", 0)
                # 이동키 상태를 이벤트/스캔코드/유니코드 기반으로 갱신 (IME/레이아웃 불문)
                try:
                    if is_move_left_event(ev):
                        globals()["MOVE_EVENT_LEFT"] = ev.type == pygame.KEYDOWN
                    elif is_move_right_event(ev):
                        globals()["MOVE_EVENT_RIGHT"] = ev.type == pygame.KEYDOWN
                    elif is_move_down_event(ev):
                        globals()["MOVE_EVENT_DOWN"] = ev.type == pygame.KEYDOWN
                    elif is_move_up_event(ev):
                        globals()["MOVE_EVENT_UP"] = ev.type == pygame.KEYDOWN
                except Exception:
                    pass
                print(
                    "[INPUT_TRACE][EVENT]"
                    f" type={'DOWN' if ev.type == pygame.KEYDOWN else 'UP'}"
                    f" key={ev.key} sc={ev_sc} uni={ev_uni!r} mod={ev_mod}"
                    f" focus={pygame.key.get_focused()}"
                )
            elif ev.type in (pygame.ACTIVEEVENT, pygame.WINDOWFOCUSGAINED, pygame.WINDOWFOCUSLOST):
                globals()["MOVE_EVENT_LEFT"] = False
                globals()["MOVE_EVENT_RIGHT"] = False
                globals()["MOVE_EVENT_DOWN"] = False
                globals()["MOVE_EVENT_UP"] = False
                print(f"[INPUT_TRACE][FOCUS] type={ev.type} gain={getattr(ev,'gain',None)} state={getattr(ev,'state',None)} focus={pygame.key.get_focused()}")
    return events

# INPUT_TRACE가 켜져 있으면 이벤트 후킹을 활성화한다.
if INPUT_TRACE:
    pygame.event.get = _patched_event_get

