def get_special_gauge():
    return special_gauge
def consume_special_gauge(amount):
    """Deduct special gauge while keeping readiness state in sync."""
    global special_gauge, special_ready
    special_gauge = max(0, special_gauge - amount)
    special_ready = special_gauge >= 350

    # GameState-backed UIs expect live values; update when available.
    try:
        game_state.special_gauge = special_gauge
        game_state.special_ready = special_ready
    except Exception:
        # During early bootstrap or tests the singleton might be absent.
        pass


def store_bgm_volume(value: float) -> float:
    """오디오 상태 모듈과 전역 변수 모두에 BGM 볼륨을 반영."""

    global bgm_volume
    global genie_assistant
    global genie_assistant
    bgm_volume = set_bgm_volume_state(value)
    return bgm_volume


def play_sound_with_volume(sound, volume=None):
    """효과음을 지정된 볼륨으로 재생"""
    global sfx_volume
    if not sound:
        return None
    if volume is None:
        volume = sfx_volume
    sound.set_volume(volume)
    return sound.play()


blacksmith_hammer_charge_sound_channel = None
poseidon_wave_sound_channel = None
stage4_magnetic_sound_channel = None


def play_poseidon_wave_sound() -> None:
    """포세이돈 물결 사운드를 단일 채널에서 재생한다."""

    global poseidon_wave_sound_channel

    if not SOUND_POSEIDON_WAVE:
        return

    channel = poseidon_wave_sound_channel
    if channel:
        try:
            if channel.get_busy():
                channel.stop()
        except Exception:
            poseidon_wave_sound_channel = None

    try:
        poseidon_wave_sound_channel = play_sound_with_volume(SOUND_POSEIDON_WAVE)
    except Exception:
        poseidon_wave_sound_channel = None


def start_stage4_magnetic_sound() -> None:
    """굴절 자기장 사운드를 루프로 재생."""

    global stage4_magnetic_sound_channel

    if not SOUND_STAGE4_MAGNETIC:
        return

    channel = stage4_magnetic_sound_channel
    if channel:
        try:
            channel.stop()
        except Exception:
            stage4_magnetic_sound_channel = None

    try:
        SOUND_STAGE4_MAGNETIC.set_volume(sfx_volume)
        stage4_magnetic_sound_channel = SOUND_STAGE4_MAGNETIC.play(-1)
    except Exception:
        stage4_magnetic_sound_channel = None


def stop_stage4_magnetic_sound() -> None:
    """굴절 자기장 사운드를 정지."""

    global stage4_magnetic_sound_channel

    channel = stage4_magnetic_sound_channel
    if channel:
        try:
            channel.stop()
        except Exception:
            pass
    elif SOUND_STAGE4_MAGNETIC:
        try:
            SOUND_STAGE4_MAGNETIC.stop()
        except Exception:
            pass

    stage4_magnetic_sound_channel = None


def start_blacksmith_hammer_charge_sound() -> None:
    """해머 쇼크 충전 사운드를 루프로 재생."""

    global blacksmith_hammer_charge_sound_channel

    if not SOUND_BLACKSMITH_HAMMER_CHARGE:
        if 'SOUND_STAGE6_BEAM_CHARGE' in globals() and SOUND_STAGE6_BEAM_CHARGE:
            try:
                play_sound_with_volume(SOUND_STAGE6_BEAM_CHARGE)
            except Exception:
                pass
        return

    channel = blacksmith_hammer_charge_sound_channel
    if channel:
        try:
            if channel.get_busy():
                return
            channel.stop()
        except Exception:
            pass
        finally:
            blacksmith_hammer_charge_sound_channel = None

    try:
        SOUND_BLACKSMITH_HAMMER_CHARGE.set_volume(sfx_volume)
    except Exception:
        pass

    try:
        blacksmith_hammer_charge_sound_channel = SOUND_BLACKSMITH_HAMMER_CHARGE.play(-1)
    except Exception:
        blacksmith_hammer_charge_sound_channel = None


def stop_blacksmith_hammer_charge_sound() -> None:
    """충전 사운드를 중지하고 채널을 정리."""

    global blacksmith_hammer_charge_sound_channel

    channel = blacksmith_hammer_charge_sound_channel
    if channel:
        try:
            channel.stop()
        except Exception:
            pass
    elif SOUND_BLACKSMITH_HAMMER_CHARGE:
        try:
            SOUND_BLACKSMITH_HAMMER_CHARGE.stop()
        except Exception:
            pass

    blacksmith_hammer_charge_sound_channel = None


