def _destroy_stage2_rocks_in_radius(
    center_x: float,
    center_y: float,
    radius: float,
    *,
    source: str,
) -> int:
    """스테이지 2 방어벽 바위를 폭발 반경 내에서 파괴한다."""

    if current_stage != 2 or animated_bg_stage2 is None:
        return 0

    destroyed_count = 0
    rocks_to_remove = []

    for rock in list(animated_bg_stage2.crisis_rocks):
        if rock.get("falling", False):
            continue
        rock_x = rock.get("x", 0)
        rock_y = rock.get("y", 0)
        if calculate_distance((rock_x, rock_y), (center_x, center_y)) <= radius:
            rocks_to_remove.append(rock)

    for rock in rocks_to_remove:
        if rock.get("is_golden", False):
            trade_point_system.spawn_star(rock["x"], rock["y"], "golden_rock")
            print("⭐ 황금 바위 파괴 - 별 생성")
        animated_bg_stage2.destroy_rock(rock)
        try:
            animated_bg_stage2.crisis_rocks.remove(rock)
        except ValueError:
            pass  # 동시 제거 등으로 이미 빠졌다면 무시
        destroyed_count += 1

    if destroyed_count > 0:
        print(f"🪨 {source} 폭발로 바위 {destroyed_count}개 파괴")

    return destroyed_count


def trigger_grenade_style_explosion(
    x: float,
    y: float,
    *,
    apply_commando_bonus: bool,
    source: str = "grenade",
    radius_scale: float = 1.0,
) -> None:
    """수류탄과 동일한 폭발 효과를 발생시킨다."""

    global grenade_shake_timer, boss_stunned_timer, boss_knockback_vel
    global special_gauge, special_ready, explosion_zones
    # NOTE(backup-restore): 백업본(0926)과 동일하게 "폭발 발생 시점"에 보스에게
    # 1회성 스턴/넉백을 즉시 적용한다. (zone 업데이트 루프 중복 적용 방지)
    # 기존 코드의 지연 적용으로 넉백 속도/지속이 어색해지는 문제를 방지.
    import items

    # 기본 반경: 백업 메인 기준 150 유지 (화력지원은 호출부에서 radius_scale=0.8 적용)
    base_radius = 150
    base_radius = max(10, int(base_radius * radius_scale))
    if apply_commando_bonus and items.commando_arm_obtained:
        explosion_radius = int(base_radius * 1.1)
        print(f"🚨 코만도암 효과 적용: 폭발 반경 {explosion_radius} (기본 {base_radius})")
    else:
        explosion_radius = base_radius

    explosion_zone = {
        "x": x,
        "y": y,
        "radius": explosion_radius,
        "duration": 15,
        "active": True,
        "source": source,
    }
    # 폭발 즉시 보스 판정 및 1회 적용(스턴 126프레임=2.1초, 넉백 40)
    try:
        # 수류탄/화력지원만 즉시 적용 (center_cube, tetro_explosion 등은 시각 효과 공유만)
        if source in ("grenade", "fire_support") and 'BOSS' in globals() and BOSS is not None:
            bx, by = get_center_pos(BOSS)
            # 중심 거리 기반 판정 (간단/일관)
            if calculate_distance((bx, by), (x, y)) <= explosion_radius:
                # 스턴(126프레임 = 2.1초)
                boss_stunned_timer = max(boss_stunned_timer, 126)
                # 폭심지로부터 멀어지는 방향
                direction = 1 if bx >= x else -1
                # 넉백 세기(백업값 복구: 40)
                power = 40.0
                boss_knockback_vel = _apply_boss_knockback_velocity(direction * power)
                # 이후 zone 루프에서 재적용되지 않도록 플래그 부여
                explosion_zone["boss_applied"] = True
    except Exception:
        # 안전 가드: 오류 발생 시에도 게임 루프 보호
        pass

    explosion_zones.append(explosion_zone)
    grenade_shake_timer = 40
    play_sound_with_volume(SOUND_GRENADE)
    print(f"💥 {source} 폭발 발생: X={x:.1f}, Y={y:.1f}, 반경={explosion_radius}")


