# 코만도 패들 이미지 생성 (고퀄리티 개선 버전)


def create_soldier_paddle_surface(
    step_phase: float = 0.0,
    swing_strength: float = 0.0,
    right_hook_strength: float = 0.0,
    *,
    include_right_arm: bool = True,
) -> pygame.Surface:
    surface = pygame.Surface((320, 108), pygame.SRCALPHA)
    block = 7
    center_x = surface.get_width() // 2
    torso_base_y = 48

    # 내부 헬퍼 함수 정의
    def rotate_point(origin: tuple[float, float], point: tuple[float, float], degrees: float) -> tuple[float, float]:
        """주어진 점을 화면 좌표계 기준으로 시계 방향 회전"""
        radians = math.radians(degrees)
        cos_v = math.cos(radians)
        sin_v = math.sin(radians)
        ox, oy = origin
        px, py = point
        translated_x = px - ox
        translated_y = py - oy
        rotated_x = translated_x * cos_v - translated_y * sin_v
        rotated_y = translated_x * sin_v + translated_y * cos_v
        return ox + rotated_x, oy + rotated_y

    def lerp_point(start: tuple[float, float], end: tuple[float, float], t: float) -> tuple[float, float]:
        return start[0] + (end[0] - start[0]) * t, start[1] + (end[1] - start[1]) * t

    def to_int_point(point: tuple[float, float]) -> tuple[int, int]:
        return int(round(point[0])), int(round(point[1]))

    phase = _resolve_mecha_phase(step_phase)
    wave = math.sin(phase * math.tau)
    torso_bob = int(math.sin(phase * math.tau) * 2)
    arm_sway = int(wave * 4)
    shoulder_shift = int(wave * 2)
    hip_sway = int(wave * 2)
    left_leg_lift = -int(max(0.0, wave) * 3)
    right_leg_lift = -int(max(0.0, -wave) * 3)

    torso_y = torso_base_y + torso_bob
    swing_strength = max(0.0, min(1.0, swing_strength))
    right_hook_strength = max(0.0, min(1.0, right_hook_strength))

    palette = {
        "helmet_base": (78, 108, 68),
        "helmet_shadow": (46, 66, 40),
        "helmet_high": (148, 180, 110),
        "goggle_strap": (52, 62, 72),
        "pack_dark": (60, 76, 48),
        "pack_light": (110, 134, 86),
        "face": (214, 188, 158),
        "skin_shadow": (178, 150, 126),
        "uniform_mid": (94, 116, 74),
        "uniform_dark": (72, 90, 58),
        "uniform_light": (140, 168, 112),
        "trim": (186, 204, 142),
        "accent": (208, 220, 156),
        "strap": (74, 54, 36),
        "strap_high": (108, 78, 50),
        "plate": (66, 82, 54),
        "plate_high": (118, 142, 96),
        "belt": (92, 62, 40),
        "belt_high": (130, 94, 60),
        "paddle_face": (220, 58, 50),
        "paddle_core": (244, 198, 164),
        "paddle_grip": (98, 60, 40),
        "arm": (124, 108, 74),
        "arm_shadow": (96, 84, 54),
        "glove": (206, 182, 150),
        "glove_shadow": (172, 144, 118),
        "pants": (98, 122, 80),
        "pants_shadow": (80, 98, 68),
        "boot": (62, 48, 34),
        "boot_high": (110, 90, 68),
        "kneepad": (112, 130, 92),
        "kneepad_trim": (178, 190, 146),
    }

    upper_camo = [(94, 118, 78), (82, 102, 68), (120, 142, 92)]
    lower_camo = [(88, 110, 74), (74, 92, 62), (104, 128, 84)]

    def draw_camo_rect(rect: pygame.Rect, base_color, overlays, density=0.32, target=None):
        target_surface = surface if target is None else target
        pygame.draw.rect(target_surface, base_color, rect, border_radius=rect.width if rect.height < 4 else 0)
        if rect.width < 3 or rect.height < 2:
            return
        patches = max(1, int(rect.width * rect.height * density / 90))
        for _ in range(patches):
            patch_w = random.randint(3, min(7, rect.width))
            patch_h = random.randint(2, min(5, rect.height))
            x = random.randint(rect.left, rect.right - patch_w)
            y = random.randint(rect.top, rect.bottom - patch_h)
            pygame.draw.rect(target_surface, random.choice(overlays), pygame.Rect(x, y, patch_w, patch_h))

    def to_int_point(point: tuple[float, float]) -> tuple[int, int]:
        return int(round(point[0])), int(round(point[1]))

    def draw_tapered_camo(rect: pygame.Rect, base_color, overlays, taper_top: int, taper_bottom: int, density=0.32):
        """Draw a trapezoidal camo block to keep the waist silhouette natural."""
        local = pygame.Surface(rect.size, pygame.SRCALPHA)
        draw_camo_rect(pygame.Rect(0, 0, rect.width, rect.height), base_color, overlays, density=density, target=local)
        mask = pygame.Surface(rect.size, pygame.SRCALPHA)
        polygon = [
            (taper_top, 0),
            (rect.width - taper_top, 0),
            (rect.width - taper_bottom, rect.height),
            (taper_bottom, rect.height),
        ]
        pygame.draw.polygon(mask, (255, 255, 255, 255), polygon)
        local.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
        surface.blit(local, rect.topleft)
        outline = [
            (rect.left + taper_top, rect.top),
            (rect.right - taper_top, rect.top),
            (rect.right - taper_bottom, rect.bottom),
            (rect.left + taper_bottom, rect.bottom),
        ]
        pygame.draw.lines(surface, palette["trim"], True, outline, 1)

    helmet_rect = pygame.Rect(center_x - int(2.6 * block), torso_y - int(3.5 * block), int(5.4 * block), int(2.8 * block))
    pygame.draw.ellipse(surface, palette["helmet_shadow"], helmet_rect)
    pygame.draw.ellipse(surface, palette["helmet_base"], helmet_rect.inflate(-int(0.6 * block), -int(0.4 * block)))
    pygame.draw.arc(surface, palette["helmet_high"], helmet_rect.inflate(-int(0.4 * block), -int(0.4 * block)), math.radians(210), math.radians(330), 2)

    back_panel = helmet_rect.inflate(-int(0.8 * block), -int(0.6 * block))
    pygame.draw.ellipse(surface, palette["helmet_base"], back_panel)
    pygame.draw.ellipse(surface, palette["helmet_high"], back_panel.inflate(-int(0.6 * block), -int(0.6 * block)), 1)

    strap_rect = pygame.Rect(center_x - int(2.4 * block), helmet_rect.centery - int(0.25 * block), int(4.8 * block), int(0.5 * block))
    pygame.draw.rect(surface, palette["goggle_strap"], strap_rect, border_radius=3)
    pygame.draw.rect(surface, palette["helmet_high"], strap_rect.inflate(-2, -2), 1, border_radius=3)

    pack_rect = pygame.Rect(center_x - int(2.1 * block), torso_y - int(0.1 * block), int(4.2 * block), int(2.4 * block))
    draw_camo_rect(pack_rect, palette["pack_dark"], upper_camo, density=0.28)
    flap_rect = pygame.Rect(pack_rect.left + int(0.2 * block), pack_rect.top + int(0.2 * block), pack_rect.width - int(0.4 * block), int(0.9 * block))
    pygame.draw.rect(surface, palette["pack_light"], flap_rect, border_radius=4)
    pygame.draw.line(surface, palette["trim"], (flap_rect.left + 3, flap_rect.bottom - 2), (flap_rect.right - 3, flap_rect.bottom - 2), 1)

    torso_width = int(6.0 * block)
    torso_height = int(2.6 * block)
    torso_rect = pygame.Rect(center_x - torso_width // 2, torso_y - int(0.4 * block), torso_width, torso_height)
    top_taper = int(0.4 * block)
    waist_taper = int(1.1 * block)
    draw_tapered_camo(torso_rect, palette["uniform_mid"], upper_camo, top_taper, waist_taper)

    plate_rect = pygame.Rect(center_x - int(2.8 * block), torso_rect.top + int(0.45 * block), int(5.6 * block), int(1.3 * block))
    pygame.draw.rect(surface, palette["plate"], plate_rect, border_radius=6)
    pygame.draw.rect(surface, palette["plate_high"], plate_rect.inflate(-int(0.45 * block), -int(0.25 * block)), 1, border_radius=5)

    molle_spacing = int(0.75 * block)
    for row in range(2):
        strap_y = plate_rect.top + int(0.35 * block) + row * molle_spacing
        pygame.draw.line(surface, palette["strap_high"], (plate_rect.left + int(0.6 * block), strap_y), (plate_rect.right - int(0.6 * block), strap_y), 2)

    pocket_size = (int(1.6 * block), int(0.7 * block))
    for offset in (-int(2.15 * block), int(0.55 * block)):
        pocket = pygame.Rect(center_x + offset, torso_rect.top + int(0.85 * block), *pocket_size)
        draw_camo_rect(pocket, palette["uniform_mid"], upper_camo, density=0.25)
        pygame.draw.rect(surface, palette["accent"], pocket, 1, border_radius=3)

    strap_width = int(0.7 * block)
    for offset in (-int(3.0 * block), int(2.4 * block)):
        strap = pygame.Rect(center_x + offset, torso_rect.top + int(0.05 * block), strap_width, torso_height - int(0.1 * block))
        pygame.draw.rect(surface, palette["strap"], strap, border_radius=4)
        pygame.draw.rect(surface, palette["strap_high"], strap.inflate(-int(0.25 * block), -int(0.3 * block)), 1, border_radius=3)

    rank_patch = pygame.Rect(center_x + int(2.8 * block), torso_rect.top + int(0.1 * block), int(1.0 * block), int(1.0 * block))
    pygame.draw.rect(surface, palette["uniform_light"], rank_patch, border_radius=2)
    pygame.draw.line(surface, palette["trim"], rank_patch.midleft, rank_patch.midright, 1)

    belt_rect = pygame.Rect(center_x - int(3.4 * block), torso_rect.bottom - int(0.15 * block), int(6.8 * block), int(0.7 * block))
    pygame.draw.rect(surface, palette["belt"], belt_rect, border_radius=4)
    pygame.draw.rect(surface, palette["belt_high"], belt_rect.inflate(-int(0.6 * block), -int(0.2 * block)), border_radius=3)

    left_shoulder = (center_x - int(3.0 * block), torso_y + shoulder_shift - 1)
    left_elbow_point = (
        left_shoulder[0] - int(1.85 * block) - arm_sway,
        torso_y - int(0.15 * block) - arm_sway // 3,
    )
    left_wrist_point = (
        left_elbow_point[0] - int(1.65 * block),
        torso_y - int(0.68 * block) - arm_sway,
    )
    upper_arm_rect = pygame.Rect(left_shoulder[0] - int(1.0 * block), torso_y - int(0.25 * block), int(1.8 * block), int(1.7 * block))
    draw_camo_rect(upper_arm_rect, palette["uniform_mid"], upper_camo, density=0.22)
    if swing_strength > 0:
        elbow_target = rotate_point(left_shoulder, left_elbow_point, -58.0)
        wrist_target = rotate_point(left_elbow_point, left_wrist_point, -82.0)
        wrist_target = (wrist_target[0] - swing_strength * 0.68 * block, wrist_target[1] - swing_strength * 0.6 * block)
        left_elbow_point = lerp_point(left_elbow_point, elbow_target, swing_strength)
        left_wrist_point = lerp_point(left_wrist_point, wrist_target, swing_strength)

    left_elbow = to_int_point(left_elbow_point)
    left_wrist = to_int_point(left_wrist_point)
    pygame.draw.line(surface, palette["arm_shadow"], left_shoulder, left_elbow, block)
    pygame.draw.line(surface, palette["arm"], left_shoulder, left_elbow, block - 2)
    pygame.draw.line(surface, palette["arm_shadow"], left_elbow, left_wrist, block - 1)
    pygame.draw.line(surface, palette["arm"], left_elbow, left_wrist, block - 3)
    pygame.draw.circle(surface, palette["glove"], left_wrist, max(2, block // 2))
    pygame.draw.circle(surface, palette["glove_shadow"], left_wrist, max(1, block // 2 - 1), 1)

    paddle_rect = pygame.Rect(left_wrist[0] - int(2.1 * block), left_wrist[1] - int(1.9 * block), int(3.6 * block), int(2.6 * block))
    pygame.draw.ellipse(surface, palette["paddle_face"], paddle_rect)
    pygame.draw.ellipse(surface, palette["paddle_core"], paddle_rect.inflate(-int(0.4 * block), -int(0.4 * block)))
    grip_rect = pygame.Rect(left_wrist[0] - int(0.4 * block), left_wrist[1] - int(0.12 * block), int(0.8 * block), int(1.35 * block))
    pygame.draw.rect(surface, palette["paddle_grip"], grip_rect, border_radius=2)

    if include_right_arm:
        right_shoulder = (center_x + int(3.05 * block), torso_y - shoulder_shift - 1)
        right_elbow_point: list[float] = [
            right_shoulder[0] + int(2.55 * block) + arm_sway // 2,
            torso_y - int(0.32 * block) - arm_sway // 3,
        ]
        right_wrist_point: list[float] = [
            right_elbow_point[0] - int(1.45 * block),
            right_elbow_point[1] - int(1.65 * block),
        ]

        if right_hook_strength > 0.0:
            if soldier_right_hook_phase == 0.0:
                print("[DEBUG] Soldier hook frame start")
            progress = soldier_right_hook_phase
            hook = right_hook_strength

            windup = max(0.0, min(1.0, progress / 0.45))
            release = max(0.0, min(1.0, (progress - 0.45) / 0.55))
            extension = pow(min(1.0, progress * 1.6), 0.8)

            windup_elbow = (
                right_shoulder[0] - (1.2 + 0.5 * windup) * block,
                torso_y - (0.6 + 1.3 * windup) * block,
            )
            windup_wrist = (
                right_shoulder[0] - (1.8 + 1.0 * windup) * block,
                torso_y - (0.9 + 1.6 * windup) * block,
            )

            release_elbow = (
                right_shoulder[0] + (2.2 + 1.1 * release) * block,
                torso_y - (0.05 + 0.4 * release) * block,
            )
            release_wrist = (
                right_shoulder[0] + (4.2 + 1.6 * release) * block,
                torso_y - (0.3 + 0.2 * release) * block,
            )

            elbow_target = (
                windup_elbow[0] * (1.0 - release) + release_elbow[0] * release,
                windup_elbow[1] * (1.0 - release) + release_elbow[1] * release,
            )
            wrist_target = (
                windup_wrist[0] * (1.0 - release) + release_wrist[0] * release,
                windup_wrist[1] * (1.0 - release) + release_wrist[1] * release,
            )

            elbow_target = (
                elbow_target[0] + (right_shoulder[0] - elbow_target[0]) * (1.0 - extension) * 0.15,
                elbow_target[1] - extension * 0.35 * block,
            )
            wrist_target = (
                wrist_target[0] + (right_shoulder[0] - wrist_target[0]) * (1.0 - extension) * 0.2,
                wrist_target[1] - extension * 0.25 * block,
            )

            blend = min(1.0, progress * 2.0)
            right_elbow_point[0] += (elbow_target[0] - right_elbow_point[0]) * blend
            right_elbow_point[1] += (elbow_target[1] - right_elbow_point[1]) * blend
            right_wrist_point[0] += (wrist_target[0] - right_wrist_point[0]) * blend
            right_wrist_point[1] += (wrist_target[1] - right_wrist_point[1]) * blend

            swing_angle = -(28.0 * windup) + (34.0 * release)
            rotated_elbow = rotate_point(right_shoulder, tuple(right_elbow_point), swing_angle)
            right_elbow_point[0], right_elbow_point[1] = rotated_elbow

            wrist_angle = swing_angle + 22.0 * release - 10.0 * windup
            rotated_wrist = rotate_point(tuple(right_elbow_point), tuple(right_wrist_point), wrist_angle)
            right_wrist_point[0], right_wrist_point[1] = rotated_wrist

            if hook > 0.08:
                swoosh_surface = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
                sweep_tail = rotate_point(
                    right_shoulder,
                    (
                        right_shoulder[0] + 3.6 * block,
                        torso_y - 0.1 * block,
                    ),
                    -(65.0 * release + 20.0 * windup),
                )
                sweep_mid = (
                    (right_elbow_point[0] + sweep_tail[0]) / 2,
                    (right_elbow_point[1] + sweep_tail[1]) / 2,
                )
                trail_points = [
                    to_int_point(right_shoulder),
                    to_int_point(sweep_tail),
                    to_int_point(tuple(right_wrist_point)),
                    to_int_point(sweep_mid),
                ]
                swoosh_alpha = int(135 * min(1.0, extension * 1.4))
                pygame.draw.polygon(
                    swoosh_surface,
                    (210, 180, 130, swoosh_alpha),
                    trail_points,
                )
                pygame.draw.polygon(
                    swoosh_surface,
                    (245, 225, 190, max(60, swoosh_alpha // 2)),
                    trail_points,
                    width=2,
                )
                surface.blit(swoosh_surface, (0, 0))

        sleeve_rect = pygame.Rect(right_shoulder[0] - int(0.65 * block), torso_y - int(0.25 * block), int(1.6 * block), int(1.5 * block))
        draw_camo_rect(sleeve_rect, palette["uniform_mid"], upper_camo, density=0.22)
        right_elbow = to_int_point(tuple(right_elbow_point))
        right_wrist = to_int_point(tuple(right_wrist_point))
        pygame.draw.line(surface, palette["arm_shadow"], right_shoulder, right_elbow, block + 1)
        pygame.draw.line(surface, palette["arm"], right_shoulder, right_elbow, block - 1)
        pygame.draw.line(surface, palette["arm_shadow"], right_elbow, right_wrist, block)
        pygame.draw.line(surface, palette["arm"], right_elbow, right_wrist, block - 2)
        forearm_guard = pygame.Rect(min(right_elbow[0], right_wrist[0]) - int(0.5 * block), right_wrist[1] - int(0.4 * block), int(1.1 * block), int(2.2 * block))
        pygame.draw.rect(surface, palette["strap"], forearm_guard, border_radius=4)
        pygame.draw.rect(surface, palette["strap_high"], forearm_guard.inflate(-2, -3), 1, border_radius=3)
        pygame.draw.circle(surface, palette["glove"], right_wrist, max(3, block // 2 + 1))
        pygame.draw.circle(surface, palette["glove_shadow"], right_wrist, max(2, block // 2), 1)
        knuckle_rect = pygame.Rect(right_wrist[0] - int(0.5 * block), right_wrist[1] - int(0.35 * block), int(1.0 * block), int(0.6 * block))
        pygame.draw.rect(surface, palette["strap_high"], knuckle_rect, border_radius=3)

    hip_y = torso_y + int(2.15 * block)
    hip_rect = pygame.Rect(center_x - int(3.2 * block) + hip_sway, hip_y, int(6.4 * block), int(0.85 * block))
    draw_tapered_camo(hip_rect, palette["pants"], lower_camo, int(0.5 * block), int(0.9 * block), density=0.3)
    pygame.draw.ellipse(surface, palette["pants_shadow"], hip_rect.inflate(-int(1.4 * block), int(0.6 * block)))

    thigh_width = int(1.5 * block)
    thigh_height = int(2.4 * block)
    leg_spacing = int(2.1 * block)
    left_leg_x = center_x - leg_spacing + hip_sway
    right_leg_x = center_x + leg_spacing + hip_sway

    left_thigh = pygame.Rect(left_leg_x - thigh_width // 2, hip_y + left_leg_lift, thigh_width, thigh_height)
    right_thigh = pygame.Rect(right_leg_x - thigh_width // 2, hip_y + right_leg_lift, thigh_width, thigh_height)
    draw_camo_rect(left_thigh, palette["pants"], lower_camo, density=0.3)
    draw_camo_rect(right_thigh, palette["pants"], lower_camo, density=0.3)

    calf_height = int(1.15 * block)
    left_calf = pygame.Rect(left_thigh.left + int(0.1 * block), left_thigh.bottom - 1, left_thigh.width - int(0.2 * block), calf_height)
    right_calf = pygame.Rect(right_thigh.left + int(0.1 * block), right_thigh.bottom - 1, right_thigh.width - int(0.2 * block), calf_height)
    draw_camo_rect(left_calf, palette["pants"], lower_camo, density=0.28)
    draw_camo_rect(right_calf, palette["pants"], lower_camo, density=0.28)

    kneepad_height = max(6, int(0.75 * block))
    for calf in (left_calf, right_calf):
        pad_rect = pygame.Rect(calf.left, calf.top + int(0.2 * block), calf.width, kneepad_height)
        pygame.draw.rect(surface, palette["kneepad"], pad_rect, border_radius=3)
        pygame.draw.rect(surface, palette["kneepad_trim"], pad_rect.inflate(-2, -2), 1, border_radius=3)

    boot_height = int(1.1 * block)
    left_boot = pygame.Rect(left_calf.left, left_calf.bottom - 1, left_calf.width, boot_height)
    right_boot = pygame.Rect(right_calf.left, right_calf.bottom - 1, right_calf.width, boot_height)
    pygame.draw.rect(surface, palette["boot"], left_boot, border_radius=2)
    pygame.draw.rect(surface, palette["boot"], right_boot, border_radius=2)
    for boot in (left_boot, right_boot):
        pygame.draw.line(surface, palette["boot_high"], (boot.left + 2, boot.top + 2), (boot.right - 2, boot.top + 2), 1)
        sole_rect = pygame.Rect(boot.left, boot.bottom - 2, boot.width, 2)
        pygame.draw.rect(surface, palette["boot_high"], sole_rect)

    return surface


SOLDIER_PADDLE_IMG = create_soldier_paddle_surface()
SOLDIER_PADDLE_IMG_NO_RIGHT_ARM = create_soldier_paddle_surface(include_right_arm=False)


def _crop_surface_alpha(surface: pygame.Surface) -> pygame.Surface:
    """알파 채널 기준으로 내용 영역만 잘라 반환."""
    rect = surface.get_bounding_rect(min_alpha=1)
    if rect.width == 0 or rect.height == 0:
        return surface.copy()
    return surface.subsurface(rect).copy()


def get_soldier_right_hook_strength() -> float:
    global soldier_right_hook_phase
    if not soldier_right_hook_active or SOLDIER_RIGHT_HOOK_DURATION <= 0 or soldier_right_hook_timer <= 0:
        soldier_right_hook_phase = 0.0
        return 0.0
    progress = 1.0 - (soldier_right_hook_timer / SOLDIER_RIGHT_HOOK_DURATION)
    progress = max(0.0, min(1.0, progress))
    soldier_right_hook_phase = progress
    base = math.sin(progress * math.pi)
    strength = max(0.0, min(1.0, base ** 0.75))
    if strength > 0:
        print(f"[DEBUG] Soldier hook strength: progress={progress:.2f}, strength={strength:.2f}, timer={soldier_right_hook_timer}")
    return strength


BLACKSMITH_CENTER_X = 122
BLACKSMITH_CENTER_Y = 44
BLACKSMITH_SCALE = 0.8
BLACKSMITH_LEFT_LEG_X = BLACKSMITH_CENTER_X - 12
BLACKSMITH_RIGHT_LEG_X = BLACKSMITH_CENTER_X + 12
BLACKSMITH_HIP_Y = BLACKSMITH_CENTER_Y + 20
BLACKSMITH_LEG_LENGTH = 15
BLACKSMITH_BASELINE_Y = BLACKSMITH_HIP_Y + BLACKSMITH_LEG_LENGTH + 6
BLACKSMITH_BASELINE_OFFSET = 10  # 스케일 후 추가로 내려 붙일 픽셀 오프셋
BLACKSMITH_SHIELD_SHIFT_X = -6  # 팔을 더 뻗어 자연스럽게 방패를 잡도록 하는 오프셋
BLACKSMITH_EMBLEM_RADIUS = 17    # 발토르 엠블럼 표준 반경 (게이지/카드 공유)


def get_blacksmith_emblem_state(time_now=None):
    """발토르 엠블럼 애니메이션 파라미터를 공유한다."""
    if time_now is None:
        time_now = pygame.time.get_ticks()
    pulse_scale = 1.0 + math.sin(time_now * 0.003) * 0.1
    rotation_angle = time_now * 0.001
    glow_intensity = abs(math.sin(time_now * 0.002))
    swing_phase = (math.sin(time_now * 0.004) + 1.0) * 0.5  # 0(복귀)~1(상승)
    rune_pulse = abs(math.sin(time_now * 0.01))
    hammer_angle = -1.05 + swing_phase * 0.45
    return {
        "time": time_now,
        "pulse_scale": pulse_scale,
        "rotation_angle": rotation_angle,
        "glow_intensity": glow_intensity,
        "swing_phase": swing_phase,
        "rune_pulse": rune_pulse,
        "hammer_angle": hammer_angle,
        "hammer_cos": math.cos(hammer_angle),
        "hammer_sin": math.sin(hammer_angle),
    }


def draw_blacksmith_emblem(surface, center_x, center_y, state, *,
                           radius=BLACKSMITH_EMBLEM_RADIUS,
                           gauge_value=None, gauge_max=None,
                           show_gauge_fx=False):
    """발토르 엠블럼 공통 렌더링 (게이지/카드 공용)."""
    pulse_scale = state["pulse_scale"]
    rotation_angle = state["rotation_angle"]
    glow_intensity = state["glow_intensity"]
    swing_phase = state["swing_phase"]
    rune_pulse = state["rune_pulse"]
    cos_a = state["hammer_cos"]
    sin_a = state["hammer_sin"]
    time_now = state["time"]

    scaled_radius = max(1, int(radius * pulse_scale))
    outer_radius = scaled_radius + 2
    outer_color = (230, 170, 110)
    base_color = (70, 45, 35)
    border_color = (200, 130, 75)
    pygame.draw.circle(surface, outer_color, (center_x, center_y), outer_radius)
    pygame.draw.circle(surface, base_color, (center_x, center_y), scaled_radius)
    pygame.draw.circle(surface, border_color, (center_x, center_y), scaled_radius, 3)

    ring_radius = max(4, int((radius - 4) * pulse_scale))
    pygame.draw.circle(surface, (115, 80, 55), (center_x, center_y), ring_radius, 1)

    gear_outer = (radius - 1) * pulse_scale
    gear_inner = gear_outer * 0.72
    tooth_count = 8
    gear_points = []
    for idx in range(tooth_count * 2):
        angle = rotation_angle + idx * math.pi / tooth_count
        length = gear_outer if idx % 2 == 0 else gear_inner
        gear_points.append(
            (
                center_x + math.cos(angle) * length,
                center_y + math.sin(angle) * length
            )
        )
    if gear_points:
        pygame.draw.polygon(surface, (150, 95, 60), gear_points)
        pygame.draw.polygon(surface, (230, 170, 110), gear_points, 2)

    hub_radius = max(2, int(gear_inner * 0.55))
    pygame.draw.circle(surface, (90, 55, 35), (center_x, center_y), hub_radius)
    pygame.draw.circle(surface, (200, 150, 90), (center_x, center_y), hub_radius, 2)

    hammer_pivot = (center_x - 4, center_y + 2)
    handle_length = 13
    handle_end = (
        hammer_pivot[0] + cos_a * handle_length,
        hammer_pivot[1] + sin_a * handle_length,
    )
    pygame.draw.line(surface, (150, 105, 70), hammer_pivot, handle_end, 3)
    pygame.draw.line(surface, (200, 160, 110), hammer_pivot, handle_end, 1)

    wrap_offset = 4
    wrap_center = (
        hammer_pivot[0] + cos_a * wrap_offset,
        hammer_pivot[1] + sin_a * wrap_offset,
    )
    pygame.draw.circle(surface, (195, 150, 95), (int(wrap_center[0]), int(wrap_center[1])), 3)

    head_length = 4
    head_half = 4
    head_center = (
        handle_end[0] + cos_a * head_length * 0.35,
        handle_end[1] + sin_a * head_length * 0.35,
    )
    perp_x = -sin_a
    perp_y = cos_a
    hammer_head_points = [
        (head_center[0] + perp_x * head_half, head_center[1] + perp_y * head_half),
        (head_center[0] - perp_x * head_half, head_center[1] - perp_y * head_half),
        (head_center[0] - perp_x * head_half + cos_a * head_length,
         head_center[1] - perp_y * head_half + sin_a * head_length),
        (head_center[0] + perp_x * head_half + cos_a * head_length,
         head_center[1] + perp_y * head_half + sin_a * head_length),
    ]
    pygame.draw.polygon(surface, (220, 185, 130), hammer_head_points)
    pygame.draw.polygon(surface, (130, 100, 70), hammer_head_points, 1)

    rune_start = (
        head_center[0] + perp_x * (head_half - 0.8),
        head_center[1] + perp_y * (head_half - 0.8),
    )
    rune_end = (
        head_center[0] - perp_x * (head_half - 0.8) + cos_a * (head_length * 0.7),
        head_center[1] - perp_y * (head_half - 0.8) + sin_a * (head_length * 0.7),
    )
    rune_color = (
        int(255 - rune_pulse * 30),
        int(205 - rune_pulse * 50),
        int(125 + rune_pulse * 30),
    )
    pygame.draw.line(surface, rune_color, rune_start, rune_end, 2)

    impact_strength = max(0.0, 0.35 - swing_phase) / 0.35
    if impact_strength > 0:
        impact_point = (center_x + 1, center_y + 4)
        spark_color = (255, 210, 140)
        for i in range(4):
            angle = time_now * 0.02 + i * (math.pi / 2)
            length = 3 + impact_strength * 5
            end_x = impact_point[0] + math.cos(angle) * length
            end_y = impact_point[1] + math.sin(angle) * length
            pygame.draw.line(surface, spark_color, impact_point, (end_x, end_y), 2)
        pygame.draw.circle(surface, (255, 240, 180), (int(impact_point[0]), int(impact_point[1])), 2 + int(impact_strength * 2))

    if show_gauge_fx and gauge_value is not None and gauge_max:
        if gauge_value > gauge_max * 0.5:
            spark_count = 3 if gauge_value < gauge_max else 5
            for i in range(spark_count):
                spark_angle = time_now * 0.015 + i * (math.tau / spark_count)
                spark_radius = radius + 6 + math.sin(time_now * 0.02 + i) * 2
                spark_x = center_x + math.cos(spark_angle) * spark_radius
                spark_y = center_y + math.sin(spark_angle) * spark_radius
                pygame.draw.circle(surface, (255, 200, 120), (int(spark_x), int(spark_y)), 2)

        if gauge_value >= 350:
            forge_ring = int(radius * 1.35 + math.sin(time_now * 0.01) * 2)
            pygame.draw.circle(surface, (255, 210, 140), (center_x, center_y), forge_ring, 1)


def _scale_blacksmith_point(point, scale=BLACKSMITH_SCALE):
    """중심 기준으로 좌표를 축소."""
    cx, cy = BLACKSMITH_CENTER_X, BLACKSMITH_CENTER_Y
    px, py = point
    return (
        int(round(cx + (px - cx) * scale)),
        int(round(cy + (py - cy) * scale))
    )


def _scale_blacksmith_sprite(surface, anchor, scale=BLACKSMITH_SCALE):
    global blacksmith_hammer_head_surface_point, blacksmith_hammer_head_local_point
    if abs(scale - 1.0) < 1e-3:
        result_surface = surface.copy()
        if blacksmith_hammer_head_local_point is not None:
            blacksmith_hammer_head_surface_point = (
                float(blacksmith_hammer_head_local_point[0]),
                float(blacksmith_hammer_head_local_point[1])
            )
        else:
            blacksmith_hammer_head_surface_point = None
        return result_surface, anchor

    scaled_size = (
        max(1, int(round(surface.get_width() * scale))),
        max(1, int(round(surface.get_height() * scale)))
    )
    scaled_surface = pygame.transform.smoothscale(surface, scaled_size)
    result_surface = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
    placement_rect = scaled_surface.get_rect(center=(BLACKSMITH_CENTER_X, BLACKSMITH_CENTER_Y))

    scaled_baseline_point = _scale_blacksmith_point(
        (BLACKSMITH_CENTER_X, BLACKSMITH_BASELINE_Y), scale
    )
    baseline_delta = BLACKSMITH_BASELINE_Y - (
        scaled_baseline_point[1] + (placement_rect.centery - BLACKSMITH_CENTER_Y)
    )
    baseline_delta += BLACKSMITH_BASELINE_OFFSET
    placement_rect.y += baseline_delta
    result_surface.blit(scaled_surface, placement_rect)

    scaled_anchor = _scale_blacksmith_point(anchor, scale)
    offset_x = placement_rect.centerx - BLACKSMITH_CENTER_X
    offset_y = placement_rect.centery - BLACKSMITH_CENTER_Y
    scaled_anchor = (scaled_anchor[0] + offset_x, scaled_anchor[1] + offset_y)
    if blacksmith_hammer_head_local_point is not None:
        scaled_head = _scale_blacksmith_point(
            (
                int(round(blacksmith_hammer_head_local_point[0])),
                int(round(blacksmith_hammer_head_local_point[1]))
            ),
            scale,
        )
        blacksmith_hammer_head_surface_point = (
            float(scaled_head[0] + offset_x),
            float(scaled_head[1] + offset_y)
        )
    else:
        blacksmith_hammer_head_surface_point = None
    return result_surface, scaled_anchor

SMASHER_CARD_IMG = _crop_surface_alpha(SMASHER_PADDLE_IMG)


def _draw_blacksmith_shield(surface, shield_center, angle_deg=-4):
    """발토르 방패를 별도 서피스로 생성해 손에 붙인다."""

    shield_surface = pygame.Surface((88, 110), pygame.SRCALPHA)
    pivot_x = shield_surface.get_width() // 2
    pivot_y = 22

    outer_rect = pygame.Rect(pivot_x - 22, pivot_y - 20, 44, 96)
    pygame.draw.ellipse(shield_surface, (66, 70, 78), outer_rect)
    pygame.draw.ellipse(shield_surface, (140, 148, 160), outer_rect, width=4)

    middle_rect = outer_rect.inflate(-6, -12)
    pygame.draw.ellipse(shield_surface, (95, 102, 120), middle_rect)
    pygame.draw.ellipse(shield_surface, (55, 60, 74), middle_rect, width=3)

    boss_rect = middle_rect.inflate(-10, -26)
    pygame.draw.ellipse(shield_surface, (210, 170, 80), boss_rect)
    pygame.draw.ellipse(shield_surface, (120, 90, 40), boss_rect.inflate(-6, -10))

    pygame.draw.line(shield_surface, (225, 200, 120), (pivot_x, middle_rect.top + 6), (pivot_x, middle_rect.bottom - 8), 2)
    pygame.draw.line(shield_surface, (225, 200, 120), (middle_rect.left + 8, pivot_y + 2), (middle_rect.right - 8, pivot_y + 2), 2)

    rivet_rx = (outer_rect.width // 2) - 4
    rivet_ry = (outer_rect.height // 2) - 10
    for i in range(6):
        rad = i * (math.pi / 3)
        rx = pivot_x + int(math.cos(rad) * rivet_rx)
        ry = pivot_y + int(math.sin(rad) * rivet_ry)
        pygame.draw.circle(shield_surface, (180, 186, 198), (rx, ry), 3)
        pygame.draw.circle(shield_surface, (120, 130, 142), (rx, ry), 1)

    strap_rect = pygame.Rect(pivot_x - 6, pivot_y - 18, 12, 36)
    pygame.draw.rect(shield_surface, (70, 42, 28), strap_rect, border_radius=4)
    pygame.draw.rect(shield_surface, (110, 72, 48), strap_rect.inflate(-4, -10), border_radius=3)

    rotated = pygame.transform.rotate(shield_surface, angle_deg)
    surface.blit(rotated, rotated.get_rect(center=shield_center))

def _draw_blacksmith_upper(
    surface,
    shield_swing=0.0,
    hammer_swing=0.0,
    walk_wave=0.0,
    walk_bob=0.0,
    walk_lean=0.0,
    force_hammer_visibility: bool | None = None,
    request_pose: bool = False,
    umbrella_pose: bool = False,
    umbrella_raise: float = 0.0,
    hammerless_walk: bool = False,
):
    global blacksmith_hammer_head_local_point
    global blacksmith_hammer_pivot_local_point, blacksmith_hammer_forward_vector
    pose_data: dict[str, tuple[float, float]] | None = {} if request_pose else None
    cx = BLACKSMITH_CENTER_X
    cy = BLACKSMITH_CENTER_Y
    shield_amount = max(0.0, min(1.0, shield_swing))
    lift_curve = shield_amount ** 1.1  # 0~1 범위, 후반부에서 더 많이 들어 올리기
    umbrella_raise = max(0.0, min(1.0, umbrella_raise))
    umbrella_pose_active = umbrella_pose

    swing_pre_blend = 0.0
    swing_main_blend = 0.0
    recover_pre_blend = 0.0
    recover_main_blend = 0.0
    umbrella_swing_active = False
    umbrella_swing_stage = 0
    umbrella_swing_progress_value = 0.0
    swing_dir = 1
    if umbrella_pose_active:
        try:
            umbrella_swing_active = blacksmith_umbrella_swing_active
            umbrella_swing_stage = blacksmith_umbrella_swing_stage
            umbrella_swing_progress_value = blacksmith_umbrella_swing_progress
            recover_pre_blend = blacksmith_umbrella_swing_recover_pre
            recover_main_blend = blacksmith_umbrella_swing_recover_main
            swing_dir = -1 if blacksmith_umbrella_swing_direction < 0 else 1
        except NameError:
            umbrella_swing_active = False
            umbrella_swing_stage = 0
            umbrella_swing_progress_value = 0.0
            recover_pre_blend = 0.0
            recover_main_blend = 0.0
            swing_dir = 1
        umbrella_swing_progress_value = max(0.0, min(1.0, umbrella_swing_progress_value))
        if umbrella_swing_active:
            if umbrella_swing_stage == 0:
                swing_pre_blend = 1.0 - pow(1.0 - umbrella_swing_progress_value, 3)
            else:
                swing_pre_blend = 1.0
                swing_main_blend = max(0.0, min(1.0, umbrella_swing_progress_value))
        else:
            swing_pre_blend = 0.0
            swing_main_blend = 0.0

    if force_hammer_visibility is not None:
        show_hammer = force_hammer_visibility
    else:
        try:
            show_hammer = blacksmith_hammer_available or blacksmith_hammer_shock_charging
        except NameError:
            show_hammer = True
    if umbrella_pose_active:
        show_hammer = False

    hammerless_walk_active = hammerless_walk or (not show_hammer and not umbrella_pose_active)

    hammer_amount = max(0.0, min(1.0, hammer_swing))
    try:
        manual_timer_active = blacksmith_manual_hammer_timer > 0
    except NameError:
        manual_timer_active = False
    if manual_timer_active and hammer_amount > 0.0:
        exponent = globals().get("BLACKSMITH_TURRET_MANUAL_SWING_EXPONENT", 1.0)
        if exponent <= 0.0:
            exponent = 1.0
        if exponent != 1.0:
            hammer_amount = math.pow(hammer_amount, exponent if exponent > 0 else 1.0)
        offset = globals().get("BLACKSMITH_TURRET_MANUAL_SWING_OFFSET", 0.0)
        if offset != 0.0:
            hammer_amount = min(1.0, max(0.0, hammer_amount + offset))
    if umbrella_pose_active:
        hammer_amount = 0.0
    if not show_hammer:
        hammer_amount = 0.0
    hammer_prepare_phase = min(1.0, hammer_amount * 1.35)
    hammer_prepare_curve = math.sin(hammer_prepare_phase * (math.pi / 2)) if hammer_prepare_phase > 0 else 0.0
    hammer_release_phase = 0.0
    if hammer_amount > 0.3:
        hammer_release_phase = min(1.0, (hammer_amount - 0.3) / 0.7)
    hammer_release_curve = math.sin(hammer_release_phase * (math.pi / 2)) if hammer_release_phase > 0 else 0.0
    hammer_raise = max(0.0, min(1.0, hammer_prepare_curve))
    hammer_drop = max(0.0, min(1.0, hammer_release_curve))

    # 방패를 들며 몸 쪽으로 끌어당기는 느낌을 위해 팔 좌표 보정
    arm_dx = int(round(-3 * lift_curve))
    arm_dy = int(round(-4 * lift_curve))

    walk_wave = max(-1.0, min(1.0, walk_wave))
    walk_bob = max(-1.0, min(1.0, walk_bob))
    walk_lean = max(-1.0, min(1.0, walk_lean))
    body_bob = int(round(walk_bob * 3))
    lean_push = int(round(walk_lean * 2))
    shoulder_roll = int(round(walk_wave * 2))
    left_arm_offset_x = int(round(-walk_wave * 6)) + lean_push
    right_arm_offset_x = int(round(walk_wave * 6)) + lean_push
    left_arm_offset_y = int(round(-walk_wave * 2))
    right_arm_offset_y = int(round(walk_wave * 2))
    elbow_sway = int(round(-walk_wave))
    wrist_pitch = int(round(walk_wave * 3))

    head_top = cy - 26 + body_bob
    torso_y = cy - 2 + body_bob
    shoulder_span = 46

    # 뒤통수 머리와 헬멧 베이스
    pygame.draw.ellipse(surface, (70, 48, 28), (cx - 20, head_top + 6, 40, 32))
    pygame.draw.ellipse(surface, (148, 158, 170), (cx - 16, head_top, 32, 24))

    # 바이킹 헬멧 장식
    pygame.draw.rect(surface, (110, 120, 135), (cx - 18, head_top + 12, 36, 8), border_radius=3)
    for i in range(4):
        pygame.draw.circle(surface, (210, 210, 215), (cx - 12 + i * 8, head_top + 16), 2)
    left_horn = [(cx - 14, head_top + 6), (cx - 26, head_top + 2), (cx - 32, head_top - 10), (cx - 20, head_top - 14), (cx - 10, head_top - 4)]
    right_horn = [(cx + 14, head_top + 6), (cx + 26, head_top + 2), (cx + 32, head_top - 10), (cx + 20, head_top - 14), (cx + 10, head_top - 4)]
    pygame.draw.polygon(surface, (220, 216, 205), left_horn)
    pygame.draw.polygon(surface, (150, 130, 110), left_horn, 2)
    pygame.draw.polygon(surface, (220, 216, 205), right_horn)
    pygame.draw.polygon(surface, (150, 130, 110), right_horn, 2)

    # 얼굴과 수염
    face_rect = pygame.Rect(cx - 11, head_top + 10, 22, 16)
    pygame.draw.ellipse(surface, (212, 192, 162), face_rect)
    pygame.draw.arc(surface, (90, 70, 55), (cx - 10, head_top + 12, 20, 10), math.pi, 2 * math.pi, 2)
    nose = [(cx - 2, head_top + 16), (cx, head_top + 10), (cx + 2, head_top + 16)]
    pygame.draw.polygon(surface, (198, 168, 138), nose)
    beard_poly = [
        (cx - 18, head_top + 20), (cx - 16, head_top + 32), (cx - 10, head_top + 40),
        (cx, head_top + 46), (cx + 10, head_top + 40), (cx + 16, head_top + 32), (cx + 18, head_top + 20)
    ]
    pygame.draw.polygon(surface, (120, 70, 35), beard_poly)
    for braid_offset in (-8, 8):
        braid_top = head_top + 28
        pygame.draw.ellipse(surface, (105, 60, 30), (cx + braid_offset - 3, braid_top, 6, 10))
        pygame.draw.ellipse(surface, (150, 95, 55), (cx + braid_offset - 2, braid_top + 6, 4, 8))
    pygame.draw.line(surface, (70, 45, 25), (cx - 8, head_top + 32), (cx - 6, head_top + 38), 2)
    pygame.draw.line(surface, (70, 45, 25), (cx + 8, head_top + 32), (cx + 6, head_top + 38), 2)

    pygame.draw.polygon(surface, (96, 74, 52), [
        (cx - shoulder_span, torso_y + 6 - shoulder_roll),
        (cx - 22 + lean_push // 2, torso_y - 10 - shoulder_roll),
        (cx + 22 + lean_push // 2, torso_y - 10 + shoulder_roll),
        (cx + shoulder_span, torso_y + 6 + shoulder_roll),
        (cx + 30 + lean_push, torso_y + 28),
        (cx - 30 + lean_push, torso_y + 28)
    ])

    # 겹겹이 입은 갑옷과 앞치마
    pygame.draw.rect(surface, (140, 145, 155), (cx - 18 + lean_push, torso_y - 2, 36, 26), border_radius=6)
    pygame.draw.rect(surface, (85, 62, 42), (cx - 24 + lean_push, torso_y + 12, 48, 22), border_radius=6)
    pygame.draw.rect(surface, (55, 40, 28), (cx - 20 + lean_push, torso_y + 18, 40, 18), border_radius=4)
    pygame.draw.arc(surface, (215, 200, 150), (cx - 22 + lean_push, torso_y + 10, 44, 22), math.pi, 2 * math.pi, 2)
    pygame.draw.line(surface, (70, 48, 32), (cx + lean_push, torso_y + 18), (cx + lean_push, torso_y + 32), 2)
    pygame.draw.circle(surface, (180, 180, 170), (cx - 26 + lean_push - shoulder_roll, torso_y + 6 - shoulder_roll), 6)
    pygame.draw.circle(surface, (180, 180, 170), (cx + 26 + lean_push + shoulder_roll, torso_y + 6 + shoulder_roll), 6)

    # === 왼팔과 방패 ===
    if umbrella_pose_active:
        def _round_left(point: tuple[float, float]) -> tuple[int, int]:
            return (int(round(point[0])), int(round(point[1])))

        shoulder_point = (
            cx - 32 + lean_push - shoulder_roll + arm_dx * 0.4,
            torso_y + 4 + arm_dy + left_arm_offset_y * 0.25 - shoulder_roll * 0.5,
        )
        rest_hand = (
            cx - 34 + arm_dx + left_arm_offset_x,
            torso_y + 12 + arm_dy + left_arm_offset_y + 2,
        )
        raised_hand = (
            cx - 38 + arm_dx * 0.2 + left_arm_offset_x * 0.2 + lean_push * 0.3,
            head_top - 42,
        )
        hand_point = (
            rest_hand[0] + (raised_hand[0] - rest_hand[0]) * umbrella_raise,
            rest_hand[1] + (raised_hand[1] - rest_hand[1]) * umbrella_raise,
        )
        swing_lateral = 18.0 * swing_pre_blend + 38.0 * swing_main_blend
        swing_vertical = 12.0 * swing_pre_blend + 24.0 * swing_main_blend
        hand_point = (
            hand_point[0] - swing_lateral * swing_dir,
            hand_point[1] - swing_vertical,
        )
        elbow_mix = 0.52 - 0.08 * umbrella_raise + 0.05 * swing_main_blend
        elbow_point = (
            shoulder_point[0] + (hand_point[0] - shoulder_point[0]) * elbow_mix - 6.0 * swing_dir,
            shoulder_point[1] + (hand_point[1] - shoulder_point[1]) * elbow_mix + 8.0,
        )
        upper_arm_poly = [
            _round_left((shoulder_point[0] - 6.0, shoulder_point[1] - 4.0)),
            _round_left((shoulder_point[0] + 6.0, shoulder_point[1] + 6.0)),
            _round_left((elbow_point[0] + 4.5, elbow_point[1] + 8.0)),
            _round_left((elbow_point[0] - 7.0, elbow_point[1] - 4.0)),
        ]
        pygame.draw.polygon(surface, (132, 108, 82), upper_arm_poly)
        pygame.draw.polygon(surface, (115, 95, 65), [
            _round_left((shoulder_point[0] + 2.0, shoulder_point[1] + 2.0)),
            _round_left((elbow_point[0] + 3.0, elbow_point[1] + 6.0)),
            _round_left((elbow_point[0] - 4.0, elbow_point[1] + 2.0)),
            _round_left((shoulder_point[0] - 3.0, shoulder_point[1] - 2.0)),
        ])
        forearm_poly = [
            _round_left((elbow_point[0] - 6.0, elbow_point[1] - 2.0)),
            _round_left((elbow_point[0] + 6.0, elbow_point[1] + 4.0)),
            _round_left((hand_point[0] + 8.0, hand_point[1] + 4.0)),
            _round_left((hand_point[0] - 2.0, hand_point[1] - 4.0)),
        ]
        pygame.draw.polygon(surface, (122, 98, 72), forearm_poly)
        pygame.draw.polygon(surface, (108, 88, 62), [
            _round_left((elbow_point[0] - 2.0, elbow_point[1] + 2.0)),
            _round_left((hand_point[0] + 4.0, hand_point[1] + 2.0)),
            _round_left((hand_point[0] + 1.0, hand_point[1] - 2.0)),
            _round_left((elbow_point[0] - 4.0, elbow_point[1] - 2.0)),
        ])
        hand_center = (hand_point[0] + 2.0, hand_point[1] - 4.0)
        pygame.draw.circle(surface, (205, 185, 155), _round_left(hand_center), 6)
        pygame.draw.line(
            surface,
            (188, 168, 138),
            _round_left((hand_center[0] - 4.0, hand_center[1] - 3.0)),
            _round_left((hand_center[0] + 2.0, hand_center[1] - 5.0)),
            2,
        )
        pivot_raise = 10.0 + 6.0 * umbrella_raise + 10.0 * swing_pre_blend + 14.0 * swing_main_blend
        pivot_point_left = (
            hand_center[0] - 2.0,
            hand_center[1] - pivot_raise,
        )
        head_offset = 64.0 + 26.0 * umbrella_raise + 18.0 * swing_pre_blend + 30.0 * swing_main_blend
        head_point_left = (
            pivot_point_left[0] - 4.0 - 6.0 * swing_main_blend * swing_dir,
            pivot_point_left[1] - head_offset,
        )
        blacksmith_hammer_head_local_point = (float(head_point_left[0]), float(head_point_left[1]))
        blacksmith_hammer_pivot_local_point = (float(pivot_point_left[0]), float(pivot_point_left[1]))
        direction_vec_left = pygame.math.Vector2(
            head_point_left[0] - pivot_point_left[0],
            head_point_left[1] - pivot_point_left[1],
        )
        if direction_vec_left.length_squared() <= 1e-6:
            direction_vec_left = pygame.math.Vector2(0.0, -1.0)
        else:
            direction_vec_left = direction_vec_left.normalize()
        blacksmith_hammer_forward_vector = (float(direction_vec_left.x), float(direction_vec_left.y))
        if pose_data is not None:
            pose_data["pivot"] = (float(pivot_point_left[0]), float(pivot_point_left[1]))
            pose_data["forward"] = (
                float(direction_vec_left.x),
                float(direction_vec_left.y),
            )
            pose_data["wrist"] = (float(hand_center[0]), float(hand_center[1]))
            pose_data["head"] = (float(head_point_left[0]), float(head_point_left[1]))
    else:
        left_arm_x = cx - 20 + BLACKSMITH_SHIELD_SHIFT_X + arm_dx + left_arm_offset_x
        left_arm_y = torso_y - 10 + arm_dy + left_arm_offset_y
        elbow_x = left_arm_x - 8 + elbow_sway
        elbow_y = left_arm_y - 4 - elbow_sway

        arm_points = [
            (cx - 34 + arm_dx + left_arm_offset_x, torso_y - 4 + arm_dy + left_arm_offset_y),
            (cx - 36 + arm_dx + left_arm_offset_x, torso_y + 2 + arm_dy + left_arm_offset_y),
            (elbow_x - 4, elbow_y + 4),
            (elbow_x - 1, elbow_y - 4),
            (left_arm_x - 2, left_arm_y - 10),
            (left_arm_x + 4, left_arm_y - 14),
            (left_arm_x + 6, left_arm_y - 4),
            (cx - 24 + arm_dx + left_arm_offset_x, torso_y - 10 + arm_dy + left_arm_offset_y)
        ]
        pygame.draw.polygon(surface, (132, 108, 82), arm_points)

        # 팔 음영
        pygame.draw.polygon(surface, (115, 95, 65), [
            (elbow_x - 2, elbow_y - 2),
            (left_arm_x - 1, left_arm_y - 8),
            (left_arm_x + 4, left_arm_y - 2),
            (elbow_x + 3, elbow_y + 4)
        ])

        # 손 (더 정교하게)
        hand_rect = pygame.Rect(left_arm_x - 6, left_arm_y - 12, 14, 10)
        pygame.draw.ellipse(surface, (205, 185, 155), hand_rect)
        pygame.draw.ellipse(surface, (188, 168, 138), hand_rect.inflate(-2, -2))

        shield_forward = int(round(20 * lift_curve))
        shield_lift = int(round(12 * lift_curve))
        shield_diagonal_shift = int(round(8 * lift_curve))
        shield_center = (
            left_arm_x - 20 + shield_forward + shield_diagonal_shift + int(round(left_arm_offset_x * 0.3)),
            left_arm_y + 22 - shield_lift - shield_diagonal_shift + int(round(-walk_wave * 4))
        )
        swing_angle = -12 - 80 * lift_curve + walk_wave * 8 + lean_push * 2
        _draw_blacksmith_shield(surface, shield_center, angle_deg=swing_angle)

    # 오른팔과 망치 - 이동 시 자연스러운 기합 자세 유지
    hammer_arm_backward = int(round(18 * hammer_raise))
    hammer_arm_forward_hit = int(round(46 * hammer_drop))
    hammer_arm_forward = hammer_arm_forward_hit - hammer_arm_backward
    hammer_arm_drop = int(round(6 * hammer_raise)) + int(round(28 * hammer_drop))
    hammer_shoulder_lift = int(round(14 * hammer_raise))
    hammer_shoulder_dip = int(round(10 * hammer_drop))
    hammer_forward_twist = int(round(14 * hammer_drop))

    right_shoulder = (
        float(cx + 28 + hammer_forward_twist - hammer_arm_forward + right_arm_offset_x + lean_push),
        float(torso_y - hammer_shoulder_lift + hammer_shoulder_dip + right_arm_offset_y // 2 - shoulder_roll),
    )
    right_elbow = (
        float(cx + 46 + hammer_forward_twist - hammer_arm_forward + right_arm_offset_x + lean_push),
        float(torso_y + 12 - int(round(8 * hammer_raise)) + hammer_arm_drop // 2 + right_arm_offset_y // 2),
    )
    right_wrist = (
        float(cx + 56 + hammer_forward_twist - hammer_arm_forward // 2 + right_arm_offset_x + lean_push),
        float(
            torso_y
            + 24
            - int(round(8 * hammer_raise))
            + hammer_arm_drop
            + right_arm_offset_y
            + wrist_pitch
            + int(round(12 * hammer_drop))
        ),
    )

    hammerless_swing = 0.0
    if hammerless_walk_active:
        swing = max(-1.0, min(1.0, walk_wave))
        swing_forward = swing * 16.0
        swing_vertical = swing * 10.0
        right_shoulder = (
            right_shoulder[0] + swing_forward * 0.35,
            right_shoulder[1] - swing_vertical * 0.25,
        )
        right_elbow = (
            right_elbow[0] + swing_forward * 0.72,
            right_elbow[1] - swing_vertical * 0.55,
        )
        right_wrist = (
            right_wrist[0] + swing_forward * 1.05,
            right_wrist[1] - swing_vertical * 0.85,
        )
        hammerless_swing = swing

    def _round_point(point: tuple[float, float]) -> tuple[int, int]:
        return (int(round(point[0])), int(round(point[1])))

    if umbrella_pose_active:
        def _blend_point(p0: tuple[float, float], p1: tuple[float, float]) -> tuple[float, float]:
            return (
                p0[0] + (p1[0] - p0[0]) * umbrella_raise,
                p0[1] + (p1[1] - p0[1]) * umbrella_raise,
            )

        target_shoulder = (
            right_shoulder[0] + 2.0,
            right_shoulder[1] - 10.0,
        )
        target_elbow = (
            right_elbow[0] + 6.0,
            right_elbow[1] - 34.0,
        )
        target_wrist = (
            right_wrist[0] + 4.0,
            right_wrist[1] - 56.0,
        )
        right_shoulder = _blend_point(right_shoulder, target_shoulder)
        right_elbow = _blend_point(right_elbow, target_elbow)
        right_wrist = _blend_point(right_wrist, target_wrist)

    if umbrella_pose_active:
        effective_pre = swing_pre_blend if swing_pre_blend > 0 else recover_pre_blend
        effective_main = swing_main_blend if swing_main_blend > 0 else recover_main_blend
        effective_pre = max(0.0, min(1.0, effective_pre))
        effective_main = max(0.0, min(1.0, effective_main))

        if effective_pre > 0:
            right_shoulder = (
                right_shoulder[0] - 4.0 * effective_pre * swing_dir,
                right_shoulder[1] - 12.0 * effective_pre,
            )
            right_elbow = (
                right_elbow[0] - 12.0 * effective_pre * swing_dir,
                right_elbow[1] - 28.0 * effective_pre,
            )
            right_wrist = (
                right_wrist[0] - 20.0 * effective_pre * swing_dir,
                right_wrist[1] - 36.0 * effective_pre,
            )

        if effective_main > 0:
            swing_curve = math.sin(effective_main * math.pi)
            lateral_shift = 34.0 * effective_main
            upward_shift = 36.0 * swing_curve
            forward_drop = 10.0 * effective_main
            right_shoulder = (
                right_shoulder[0] - lateral_shift * 0.5 * swing_dir,
                right_shoulder[1] - upward_shift / 3.0,
            )
            right_elbow = (
                right_elbow[0] - lateral_shift * 0.9 * swing_dir,
                right_elbow[1] - upward_shift,
            )
            right_wrist = (
                right_wrist[0] - lateral_shift * 1.35 * swing_dir,
                right_wrist[1] - upward_shift - forward_drop,
            )
    arm_polygon_points = [
        (right_shoulder[0] - 6.0, right_shoulder[1] + 2.0),
        (right_elbow[0] - 10.0, right_elbow[1] - 2.0),
        (right_elbow[0] - 2.0, right_elbow[1] + 6.0),
        (right_shoulder[0] + 6.0, right_shoulder[1] + 8.0),
    ]
    pygame.draw.polygon(surface, (132, 108, 82), [_round_point(p) for p in arm_polygon_points])
    forearm_polygon_points = [
        (right_elbow[0] - 2.0, right_elbow[1] + 4.0),
        (right_wrist[0] - 6.0, right_wrist[1] + 2.0),
        (right_wrist[0] + 12.0, right_wrist[1] + 6.0),
        (right_elbow[0] + 4.0, right_elbow[1]),
    ]
    pygame.draw.polygon(surface, (122, 98, 72), [_round_point(p) for p in forearm_polygon_points])
    hand_center = (right_wrist[0] + 6.0, right_wrist[1] + 4.0)
    if hammerless_walk_active:
        hand_center = (
            right_wrist[0] + 4.0,
            right_wrist[1] + 3.0 + (-hammerless_swing) * 2.5,
        )
    if umbrella_pose_active:
        hand_center = (
            right_wrist[0] + 1.0 - 3.0 * swing_main_blend * swing_dir,
            right_wrist[1]
            - (1.0 + 4.0 * umbrella_raise + 10.0 * swing_pre_blend + 16.0 * swing_main_blend),
        )
    pygame.draw.circle(surface, (205, 185, 155), _round_point(hand_center), 6)
    if umbrella_pose_active:
        pygame.draw.line(
            surface,
            (188, 168, 138),
            _round_point((hand_center[0] - 3.0, hand_center[1] - 4.0)),
            _round_point((hand_center[0] + 3.0, hand_center[1] - 6.0)),
            2,
        )

    hammer_ax = right_wrist[0] + 6 - int(round(10 * hammer_raise)) + int(round(16 * hammer_drop))

    grip_ratio = 0.5
    if umbrella_pose_active:
        grip_ratio = 0.35 - 0.05 * swing_main_blend
    pivot = pygame.math.Vector2(hand_center[0], hand_center[1])
    if umbrella_pose_active:
        pivot = pygame.math.Vector2(
            hand_center[0],
            hand_center[1] - (1 + 4 * swing_pre_blend + 6 * swing_main_blend),
        )
    swing_angle = -math.radians(110) + hammer_drop * math.radians(150)
    swing_angle += hammer_raise * math.radians(10)
    if umbrella_pose_active:
        swing_angle = -math.pi / 2 + math.radians(8 * (1.0 - umbrella_raise))
        swing_angle -= math.radians(18 * swing_pre_blend) * swing_dir
        swing_angle -= math.radians(32 * swing_main_blend) * swing_dir
    direction_vec = pygame.math.Vector2(math.cos(swing_angle), math.sin(swing_angle))
    if direction_vec.length_squared() == 0:
        direction_vec = pygame.math.Vector2(0, -1)
    forward_vec = direction_vec.normalize()
    perp_vec = pygame.math.Vector2(-forward_vec.y, forward_vec.x)

    handle_length = 46
    if umbrella_pose_active:
        handle_length = 64 + int(round(10 * swing_main_blend))
    handle_half_width = 5
    if umbrella_pose_active:
        handle_half_width = 4
    top_offset = handle_length * (1.0 - grip_ratio)
    bottom_offset = handle_length * grip_ratio
    handle_top = pivot + forward_vec * top_offset
    handle_bottom_point = pivot - forward_vec * bottom_offset
    handle_dir = handle_bottom_point - handle_top
    if handle_dir.length_squared() == 0:
        handle_dir = pygame.math.Vector2(0, 1)
    handle_dir = handle_dir.normalize()

    normalized_forward = forward_vec.normalize() if forward_vec.length_squared() else pygame.math.Vector2(0, -1)
    if not umbrella_pose_active:
        blacksmith_hammer_pivot_local_point = (float(pivot.x), float(pivot.y))
        blacksmith_hammer_forward_vector = (float(normalized_forward.x), float(normalized_forward.y))
        if pose_data is not None:
            pose_data["pivot"] = (float(pivot.x), float(pivot.y))
            pose_data["forward"] = (
                float(normalized_forward.x),
                float(normalized_forward.y),
            )
            pose_data["wrist"] = (float(right_wrist[0]), float(right_wrist[1]))
    elif pose_data is not None and "wrist" not in pose_data:
        pose_data["wrist"] = (float(hand_center[0]), float(hand_center[1]))

    if not show_hammer:
        blacksmith_hammer_head_local_point = None
        blacksmith_hammer_pivot_local_point = None
        blacksmith_hammer_forward_vector = (0.0, -1.0)

    if show_hammer:
        handle_poly = [
            _vec_to_int_pair(handle_top + perp_vec * handle_half_width),
            _vec_to_int_pair(handle_top - perp_vec * handle_half_width),
            _vec_to_int_pair(handle_bottom_point - perp_vec * handle_half_width),
            _vec_to_int_pair(handle_bottom_point + perp_vec * handle_half_width),
        ]
        pygame.draw.polygon(surface, (90, 60, 36), handle_poly)

        detail_poly = [
            _vec_to_int_pair(handle_top + perp_vec * (handle_half_width - 2)),
            _vec_to_int_pair(handle_top - perp_vec * (handle_half_width - 2)),
            _vec_to_int_pair(handle_bottom_point - perp_vec * (handle_half_width - 2)),
            _vec_to_int_pair(handle_bottom_point + perp_vec * (handle_half_width - 2)),
        ]
        pygame.draw.polygon(surface, (60, 35, 18), detail_poly, width=0)

        for stripe_pos in range(6, int(handle_length), 6):
            stripe_center = handle_top + handle_dir * stripe_pos
            stripe_start = _vec_to_int_pair(stripe_center - perp_vec * (handle_half_width - 2))
            stripe_end = _vec_to_int_pair(stripe_center + perp_vec * (handle_half_width - 2))
            pygame.draw.line(surface, (110, 82, 52), stripe_start, stripe_end, 2)

        cap_length = 10
        cap_vec = forward_vec * cap_length
        cap_poly = [
            _vec_to_int_pair(handle_top + perp_vec * handle_half_width),
            _vec_to_int_pair(handle_top - perp_vec * handle_half_width),
            _vec_to_int_pair(handle_top + cap_vec - perp_vec * handle_half_width),
            _vec_to_int_pair(handle_top + cap_vec + perp_vec * handle_half_width),
        ]
        pygame.draw.polygon(surface, (112, 76, 48), cap_poly)

        head_offset_along = 20
        head_center = handle_top + forward_vec * head_offset_along
        head_half_long = 20
        head_half_short = 11
        head_long_vec = perp_vec * head_half_long
        head_short_vec = forward_vec * head_half_short
        head_corners = [
            _vec_to_int_pair(head_center + head_long_vec + head_short_vec),
            _vec_to_int_pair(head_center - head_long_vec + head_short_vec),
            _vec_to_int_pair(head_center - head_long_vec - head_short_vec),
            _vec_to_int_pair(head_center + head_long_vec - head_short_vec),
        ]
        pygame.draw.polygon(surface, (176, 182, 196), head_corners)

        inner_scale = 0.7
        inner_center = head_center - forward_vec * 2
        inner_long_vec = head_long_vec * inner_scale
        inner_short_vec = head_short_vec * inner_scale
        inner_corners = [
            _vec_to_int_pair(inner_center + inner_long_vec + inner_short_vec),
            _vec_to_int_pair(inner_center - inner_long_vec + inner_short_vec),
            _vec_to_int_pair(inner_center - inner_long_vec - inner_short_vec),
            _vec_to_int_pair(inner_center + inner_long_vec - inner_short_vec),
        ]
        pygame.draw.polygon(surface, (210, 215, 228), inner_corners)

        ridge_start = _vec_to_int_pair(head_center - head_long_vec * 0.7 + head_short_vec * 0.6)
        ridge_end = _vec_to_int_pair(head_center + head_long_vec * 0.7 + head_short_vec * 0.6)
        pygame.draw.line(surface, (120, 130, 142), ridge_start, ridge_end, 2)

        spike_tip = head_center + head_long_vec + head_short_vec * 0.1
        spike_poly = [
            _vec_to_int_pair(spike_tip),
            _vec_to_int_pair(spike_tip - head_long_vec * 0.3 + head_short_vec * 0.3),
            _vec_to_int_pair(spike_tip - head_long_vec * 0.3 - head_short_vec * 0.3),
        ]
        pygame.draw.polygon(surface, (140, 155, 168), spike_poly)

        emblem_center = head_center + head_short_vec * 0.1
        pygame.draw.circle(surface, (230, 215, 130), (int(emblem_center.x), int(emblem_center.y)), 5)
        pygame.draw.line(
            surface,
            (240, 160, 60),
            _vec_to_int_pair(emblem_center - head_long_vec * 0.3 - head_short_vec * 0.2),
            _vec_to_int_pair(emblem_center + head_long_vec * 0.3 + head_short_vec * 0.2),
            2,
        )

        blacksmith_hammer_head_local_point = (float(head_center.x), float(head_center.y))
        if pose_data is not None:
            pose_data["head"] = (
                float(head_center.x),
                float(head_center.y),
            )
    else:
        empty_hand = pygame.Rect(0, 0, 10, 18)
        empty_hand.center = hand_center
        pygame.draw.ellipse(surface, (205, 185, 155), empty_hand)
        if not umbrella_pose_active:
            blacksmith_hammer_head_local_point = None
        if pose_data is not None and not umbrella_pose_active:
            pose_data["head"] = (
                float((handle_top + handle_bottom_point).x / 2),
                float((handle_top + handle_bottom_point).y / 2),
            )

    # 어깨 장식
    left_shoulder_center = (cx - 32 + lean_push - shoulder_roll, torso_y + 8 - shoulder_roll)
    right_shoulder_center = (cx + 32 + lean_push + shoulder_roll, torso_y + 8 + shoulder_roll)
    pygame.draw.circle(surface, (195, 200, 210), left_shoulder_center, 7)
    pygame.draw.circle(surface, (195, 200, 210), right_shoulder_center, 7)
    pygame.draw.circle(surface, (110, 120, 135), left_shoulder_center, 3)
    pygame.draw.circle(surface, (110, 120, 135), right_shoulder_center, 3)

    if request_pose:
        return pose_data


def _draw_blacksmith_umbrella_overlay(
    surface: pygame.Surface,
    pivot_point: tuple[float, float],
    head_point: tuple[float, float],
    raise_amount: float,
    open_amount: float,
):
    """발토르 망치를 토르쉴드로 연출하기 위한 오버레이."""
    global blacksmith_umbrella_overlay_bounds
    global blacksmith_umbrella_swing_direction
    blacksmith_umbrella_overlay_bounds = None
    pivot_vec = pygame.math.Vector2(pivot_point)
    head_vec = pygame.math.Vector2(head_point)
    direction = head_vec - pivot_vec
    if direction.length_squared() <= 1e-4:
        direction = pygame.math.Vector2(0, -1)
    else:
        direction = direction.normalize()

    swing_pre_blend = 0.0
    swing_main_blend = 0.0
    try:
        swing_active = blacksmith_umbrella_swing_active
        swing_stage = blacksmith_umbrella_swing_stage
        swing_progress_value = blacksmith_umbrella_swing_progress
    except NameError:
        swing_active = False
        swing_stage = 0
        swing_progress_value = 0.0

    if swing_active:
        swing_progress_value = max(0.0, min(1.0, swing_progress_value))
        if swing_stage == 0:
            swing_pre_blend = 1.0 - pow(1.0 - swing_progress_value, 3)
        else:
            swing_pre_blend = 1.0
            swing_main_blend = swing_progress_value
    else:
        swing_pre_blend = 0.0
        swing_main_blend = 0.0

    swing_dir = -1 if blacksmith_umbrella_swing_direction < 0 else 1

    if swing_pre_blend > 0:
        ready_dir = pygame.math.Vector2(0.3 * swing_dir, -1.0).normalize()
        direction = direction.lerp(ready_dir, swing_pre_blend * 0.8)
    if swing_main_blend > 0:
        sweep_curve = math.sin(swing_main_blend * math.pi)
        sweep_dir = pygame.math.Vector2(-0.9 * swing_dir, -0.45 + 0.2 * sweep_curve)
        if sweep_dir.length_squared() > 1e-6:
            target_sweep = sweep_dir.normalize()
            direction = direction.lerp(target_sweep, min(1.0, 1.2 * swing_main_blend))
    if direction.length_squared() <= 1e-4:
        direction = pygame.math.Vector2(0, -1)
    else:
        direction = direction.normalize()
    target_dir = pygame.math.Vector2(0, -1)
    mix = max(0.0, min(1.0, raise_amount))
    direction = direction.lerp(target_dir, mix)
    if direction.length_squared() <= 1e-4:
        direction = target_dir
    direction = direction.normalize()

    # 드워프 양산 방패: 얇고 가로로 긴 금속 플레이트
    axis_right = pygame.math.Vector2(-direction.y, direction.x)
    axis_up = (-direction).normalize()

    close_factor = 1.0 - open_amount
    tilt_strength = close_factor ** 0.6
    tilt_angle = tilt_strength * math.radians(75)
    if swing_pre_blend > 0 and swing_main_blend <= 0:
        tilt_angle -= swing_pre_blend * math.radians(35) * swing_dir
    if swing_main_blend > 0:
        swing_tilt = (swing_pre_blend * 0.5 + swing_main_blend * 1.0) * math.radians(80)
        tilt_angle += swing_tilt * swing_dir
    if abs(tilt_angle) > 1e-4:
        cos_t = math.cos(tilt_angle)
        sin_t = math.sin(tilt_angle)
        rotated_right = axis_right * cos_t - axis_up * sin_t
        rotated_up = axis_right * sin_t + axis_up * cos_t
        if rotated_right.length_squared() > 1e-6:
            axis_right = rotated_right.normalize()
        if rotated_up.length_squared() > 1e-6:
            axis_up = rotated_up.normalize()

    forward_offset = 32 + open_amount * 54 - close_factor * 6
    if swing_main_blend > 0:
        swing_bias = (close_factor * 18 - (28 * swing_pre_blend + 58 * swing_main_blend)) * swing_dir
        vertical_bias = -8 * swing_pre_blend + 28 * swing_main_blend
    elif swing_pre_blend > 0:
        swing_bias = (close_factor * 18 + 20 * swing_pre_blend) * swing_dir
        vertical_bias = -12 * swing_pre_blend
    else:
        swing_bias = close_factor * 18 * swing_dir
        vertical_bias = 0
    shield_width = (80 + open_amount * 260) * (1.0 + 0.18 * swing_main_blend)
    shield_height = (18 + open_amount * 40) * (1.0 + 0.22 * swing_pre_blend + 0.35 * swing_main_blend)
    shield_center = pivot_vec + direction * forward_offset + axis_right * swing_bias + axis_up * vertical_bias

    def to_world(dx: float, dy: float) -> pygame.math.Vector2:
        return shield_center + axis_right * dx + axis_up * dy

    top_taper = 0.22 + open_amount * 0.18
    mid_taper = 0.28 + open_amount * 0.24
    bottom_taper = 0.34 + open_amount * 0.26
    half_w_top = shield_width * top_taper
    half_w_mid = shield_width * mid_taper
    half_w_bottom = shield_width * bottom_taper
    half_h = shield_height * 0.5

    # 초승달 모양의 곡선 방패를 위한 포인트 생성
    num_points = 36  # 부드러운 곡선을 위한 포인트 수 증가
    outline_local = []
    
    # 상단 곡선 (초승달의 바깥쪽 볼록한 부분)
    for i in range(num_points + 1):
        t = i / num_points  # 0에서 1까지
        x = (t - 0.5) * shield_width
        
        # 초승달의 상단 곡선 - 더 얕은 아치
        outer_curve = 0.5 + 0.15 * open_amount
        y = -math.sin(t * math.pi) * shield_height * outer_curve - shield_height * 0.08
        outline_local.append((x, y))
    
    # 하단 곡선 (초승달의 안쪽 오목한 부분) - 역순으로 추가
    for i in range(num_points, -1, -1):
        t = i / num_points
        x = (t - 0.5) * shield_width
        
        # 초승달의 하단 곡선 - 중앙이 얇아지는 효과
        inner_wave = 0.08 + 0.28 * open_amount
        thickness = 0.18 + 0.42 * (1 - math.sin(t * math.pi)) * (0.6 + 0.4 * open_amount)
        y = -math.sin(t * math.pi) * shield_height * inner_wave + shield_height * thickness
        outline_local.append((x, y))
    outline_world = [to_world(x, y) for x, y in outline_local]
    outline_int = [_vec_to_int_pair(p) for p in outline_world]

    global blacksmith_umbrella_hitbox_raw
    xs = [p.x for p in outline_world]
    ys = [p.y for p in outline_world]
    if xs and ys:
        min_x = min(xs)
        max_x = max(xs)
        min_y = min(ys)
        max_y = max(ys)
        blacksmith_umbrella_overlay_bounds = (min_x, max_x)
        if swing_main_blend > 0:
            blacksmith_umbrella_hitbox_raw = {
                "pivot_x": float(pivot_vec.x),
                "pivot_y": float(pivot_vec.y),
                "center_x": float(shield_center.x),
                "center_y": float(shield_center.y),
                "min_x": float(min_x),
                "max_x": float(max_x),
                "min_y": float(min_y),
                "max_y": float(max_y),
                "dir_x": float(direction.x),
                "dir_y": float(direction.y),
            }
        else:
            blacksmith_umbrella_hitbox_raw = None
    else:
        blacksmith_umbrella_overlay_bounds = None
        blacksmith_umbrella_hitbox_raw = None

    try:
        divine_active = is_blacksmith_divine_stone_active()
    except NameError:
        divine_active = False

    if divine_active:
        base_color = (
            int(168 + 18 * open_amount),
            int(176 + 22 * open_amount),
            int(186 + 24 * open_amount),
        )
        shadow_color = (
            int(118 + 12 * open_amount),
            int(126 + 14 * open_amount),
            int(134 + 16 * open_amount),
        )
        highlight_color = (
            int(222 + 12 * open_amount),
            int(230 + 14 * open_amount),
            int(240 + 16 * open_amount),
        )
        # 강화 디바인스톤 여부에 따라 토르쉴드 색상 팔레트를 변경
        try:
            divine_state = globals().get("blacksmith_divine_stone_state")
            reinforced_divine = bool(divine_state and divine_state.get("reinforced", False))
        except Exception:
            reinforced_divine = False

        if reinforced_divine:
            # 검붉은 보라색 계열 팔레트
            upper_band_layer_colors = [
                (120, 80, 130),
                (100, 60, 110),
            ]
            upper_band_outline_color = (70, 36, 90)
            upper_band_highlight_color = (210, 180, 235)
            lower_band_layer_colors = [
                (90, 50, 105),
                (72, 38, 88),
            ]
            lower_band_outline_color = (60, 30, 78)
            lower_band_highlight_color = (195, 160, 225)
            rune_base_color = (200, 160, 230)
            rune_glow_color = (255, 220, 255)
            rivet_shadow_color = (70, 40, 90)
            rivet_body_color = (150, 110, 185)
            rivet_highlight_color = (220, 190, 245)
            rivet_core_color = (245, 230, 255)
            hammer_body_color = (210, 140, 210)
            hammer_highlight_color = (240, 200, 250)
            hammer_outline_color = (110, 70, 130)
            hammer_shadow_color = (80, 46, 102)
            strap_color = (130, 80, 150)
        else:
            upper_band_layer_colors = [
                (212, 220, 236),
                (192, 204, 224),
            ]
            upper_band_outline_color = (136, 148, 168)
            upper_band_highlight_color = (236, 244, 255)
            lower_band_layer_colors = [
                (188, 198, 216),
                (170, 182, 204),
            ]
            lower_band_outline_color = (126, 138, 156)
            lower_band_highlight_color = (230, 238, 250)
            rune_base_color = (206, 220, 238)
            rune_glow_color = (255, 255, 255)
            rivet_shadow_color = (96, 108, 128)
            rivet_body_color = (148, 158, 178)
            rivet_highlight_color = (214, 224, 240)
            rivet_core_color = (236, 246, 255)
            hammer_body_color = (214, 226, 240)
            hammer_highlight_color = (238, 248, 255)
            hammer_outline_color = (122, 132, 148)
            hammer_shadow_color = (112, 118, 134)
            strap_color = (142, 152, 170)
    else:
        base_color = (
            int(132 + 12 * open_amount),
            int(118 + 18 * open_amount),
            int(102 + 20 * open_amount),
        )
        shadow_color = (
            int(82 + 8 * open_amount),
            int(68 + 10 * open_amount),
            int(54 + 12 * open_amount),
        )
        highlight_color = (
            int(164 + 8 * open_amount),
            int(150 + 12 * open_amount),
            int(134 + 16 * open_amount),
        )
        upper_band_layer_colors = [
            (194, 170, 130),
            (184, 160, 120),
        ]
        upper_band_outline_color = (80, 68, 48)
        upper_band_highlight_color = (210, 196, 160)
        lower_band_layer_colors = [
            (164, 140, 110),
            (154, 130, 100),
        ]
        lower_band_outline_color = (70, 58, 40)
        lower_band_highlight_color = (200, 186, 150)
        rune_base_color = (210, 188, 130)
        rune_glow_color = (255, 235, 180)
        rivet_shadow_color = (64, 50, 34)
        rivet_body_color = (104, 90, 74)
        rivet_highlight_color = (182, 160, 130)
        rivet_core_color = (202, 180, 150)
        hammer_body_color = (218, 200, 152)
        hammer_highlight_color = (238, 220, 172)
        hammer_outline_color = (90, 76, 56)
        hammer_shadow_color = (70, 56, 36)
        strap_color = (96, 78, 60)
    
    # 메인 방패 본체 (그라데이션 레이어)
    for i in range(3):
        offset = i * 2
        grad_color = (
            base_color[0] + (highlight_color[0] - base_color[0]) * (i / 3),
            base_color[1] + (highlight_color[1] - base_color[1]) * (i / 3),
            base_color[2] + (highlight_color[2] - base_color[2]) * (i / 3)
        )
        offset_outline = []
        for point in outline_local:
            offset_x = point[0] * (1 - offset * 0.005)
            offset_y = point[1] * (1 - offset * 0.01) 
            offset_outline.append((offset_x, offset_y))
        offset_world = [to_world(x, y) for x, y in offset_outline]
        offset_int = [_vec_to_int_pair(p) for p in offset_world]
        pygame.draw.polygon(surface, grad_color, offset_int)
    
    # 메인 테두리
    pygame.draw.polygon(surface, shadow_color, outline_int, width=4)
    # 내부 하이라이트 테두리
    inner_outline = []
    for point in outline_local:
        inner_x = point[0] * 0.95
        inner_y = point[1] * 0.9
        inner_outline.append((inner_x, inner_y))
    inner_world = [to_world(x, y) for x, y in inner_outline]
    inner_int = [_vec_to_int_pair(p) for p in inner_world]
    inner_outline_color = (
        226,
        232,
        242,
    ) if divine_active else (188, 174, 158)
    pygame.draw.polygon(surface, inner_outline_color, inner_int, width=2)

    # 상하 금속 판재 층 (메탈릭 효과 강화)
    band_thickness = shield_height * (0.24 + 0.18 * open_amount)
    
    # 상단 밴드 - 초승달 곡선을 따라가는 밴드
    upper_band_base = []
    band_num_points = 20
    for i in range(band_num_points):
        t = i / (band_num_points - 1)
        x = (t - 0.5) * shield_width * 0.9
        
        # 초승달 모양에 맞춘 상단 밴드 곡선
        base_y = -math.sin(t * math.pi) * shield_height * 0.5 - shield_height * 0.15
        band_y = base_y - band_thickness * 0.3
        
        upper_band_base.append((x, band_y))
    
    # 상단 밴드 그라데이션 레이어
    for layer, layer_color in enumerate(upper_band_layer_colors):
        layer_band_points = []
        for x, y in upper_band_base:
            layer_band_points.append(_vec_to_int_pair(to_world(x, y + layer * 1.5)))
        pygame.draw.polygon(surface, layer_color, layer_band_points)

    upper_band = [_vec_to_int_pair(to_world(x, y)) for x, y in upper_band_base]
    pygame.draw.polygon(surface, upper_band_outline_color, upper_band, width=2)
    # 상단 하이라이트 라인
    highlight_line = [_vec_to_int_pair(to_world(x, y - band_thickness * 0.15)) for x, y in upper_band_base[:4]]
    pygame.draw.lines(surface, upper_band_highlight_color, False, highlight_line, 2)

    # 하단 밴드 - 초승달 곡선을 따라가는 밴드  
    lower_band_base = []
    for i in range(band_num_points):
        t = i / (band_num_points - 1)
        x = (t - 0.5) * shield_width * 0.95
        
        # 초승달 모양에 맞춘 하단 밴드 곡선
        thickness = 0.25 + 0.45 * (1 - math.sin(t * math.pi))
        base_y = -math.sin(t * math.pi) * shield_height * 0.05 + shield_height * (thickness - 0.1)
        band_y = base_y + band_thickness * 0.2
        
        lower_band_base.append((x, band_y))
    
    # 하단 밴드 그라데이션 레이어
    for layer, layer_color in enumerate(lower_band_layer_colors):
        layer_band_points = []
        for x, y in lower_band_base:
            layer_band_points.append(_vec_to_int_pair(to_world(x, y - layer * 1.5)))
        pygame.draw.polygon(surface, layer_color, layer_band_points)

    lower_band = [_vec_to_int_pair(to_world(x, y)) for x, y in lower_band_base]
    pygame.draw.polygon(surface, lower_band_outline_color, lower_band, width=2)
    # 하단 하이라이트 라인
    highlight_line_lower = [_vec_to_int_pair(to_world(x, y + band_thickness * 0.1)) for x, y in lower_band_base[2:5]]
    pygame.draw.lines(surface, lower_band_highlight_color, False, highlight_line_lower, 2)

    # 중앙 룬 라인 (발광 애니메이션 효과) - 초승달 곡선 따라 배치
    current_time = pygame.time.get_ticks() / 1000.0  # 초 단위로 변환
    
    for i in range(-2, 3):
        # 각 룬마다 다른 위상으로 펄스 효과
        phase_offset = i * 0.5
        pulse_intensity = (math.sin(current_time * 2.0 + phase_offset) + 1.0) / 2.0  # 0~1 범위
        
        # 색상 보간
        rune_color = (
            int(rune_base_color[0] + (rune_glow_color[0] - rune_base_color[0]) * pulse_intensity),
            int(rune_base_color[1] + (rune_glow_color[1] - rune_base_color[1]) * pulse_intensity),
            int(rune_base_color[2] + (rune_glow_color[2] - rune_base_color[2]) * pulse_intensity)
        )
        
        # 룬의 x 위치에 따른 t 값 계산
        rune_x = i * shield_width * 0.16
        t = (rune_x / shield_width) + 0.5  # 0~1 범위로 정규화
        
        # 초승달 곡선에 맞춰 룬의 상하 위치 계산
        curve_y = -math.sin(t * math.pi) * shield_height * 0.4
        top_y = curve_y - shield_height * 0.25
        bottom_y = curve_y + shield_height * 0.25
        
        top = to_world(rune_x, top_y)
        bottom = to_world(rune_x, bottom_y)
        
        # 글로우 효과 (여러 겹으로 그리기)
        if pulse_intensity > 0.5:
            glow_alpha = int((pulse_intensity - 0.5) * 100)
            for glow_size in range(3, 0, -1):
                glow_surface = pygame.Surface((int(shield_width), int(shield_height * 2)), pygame.SRCALPHA)
                pygame.draw.line(glow_surface, (*rune_glow_color, glow_alpha // glow_size), 
                               (int(top.x - shield_center.x + shield_width/2), int(top.y - shield_center.y + shield_height)), 
                               (int(bottom.x - shield_center.x + shield_width/2), int(bottom.y - shield_center.y + shield_height)), 
                               3 + glow_size * 2)
                surface.blit(glow_surface, (int(shield_center.x - shield_width/2), int(shield_center.y - shield_height)), special_flags=pygame.BLEND_ADD)
        
        # 메인 룬 라인
        pygame.draw.line(surface, rune_color, _vec_to_int_pair(top), _vec_to_int_pair(bottom), 4)
        # 초승달 곡선에 맞춘 가로 틱
        left_tick = to_world(rune_x - shield_width * 0.05, curve_y)
        right_tick = to_world(rune_x + shield_width * 0.05, curve_y)
        pygame.draw.line(surface, rune_color, _vec_to_int_pair(left_tick), _vec_to_int_pair(right_tick), 3)

    # 리벳 (메탈릭 효과 강화) - 초승달 곡선 따라 배치
    # 3개의 곡선 라인을 따라 리벳 배치
    for row in range(3):
        row_factor = row / 2  # 0, 0.5, 1
        count = 7 if row == 1 else 6  # 중앙 줄은 더 많이
        
        for j in range(count):
            t = j / (count - 1) if count > 1 else 0.5
            x = (t - 0.5) * shield_width * 0.86
            
            # 초승달 곡선에 맞춘 y 위치
            base_curve_y = -math.sin(t * math.pi) * shield_height * 0.5
            # 각 줄마다 다른 오프셋 적용
            y_offset = (row_factor - 0.5) * shield_height * 0.8
            y = base_curve_y + y_offset
            
            pos = to_world(x, y)
            # 리벳 그림자
            pygame.draw.circle(surface, rivet_shadow_color, _vec_to_int_pair(pos), 5)
            # 리벳 본체
            pygame.draw.circle(surface, rivet_body_color, _vec_to_int_pair(pos), 4)
            # 리벳 하이라이트
            highlight_pos = (int(pos.x - 1), int(pos.y - 1))
            pygame.draw.circle(surface, rivet_highlight_color, highlight_pos, 2)
            # 중앙 반사광
            pygame.draw.circle(surface, rivet_core_color, highlight_pos, 1)

    # 가장자리 보강 스트랩 - 초승달 곡선에 맞춰 조정
    for side in (-1, 1):
        # 스트랩 시작과 끝 지점의 t 값
        start_t = (0.42 * side + 0.5)  # x 위치를 t로 변환
        end_t = (0.68 * side + 0.5)
        
        # 초승달 곡선에 맞춘 y 위치 계산
        start_curve_y = -math.sin(start_t * math.pi) * shield_height * 0.5
        end_curve_y = -math.sin(end_t * math.pi) * shield_height * 0.6
        
        strap_start = to_world(-shield_width * 0.42 * side, start_curve_y + shield_height * 0.35)
        strap_end = to_world(-shield_width * 0.68 * side, end_curve_y - shield_height * 0.2)
        
        # 곡선 스트랩을 위한 중간 점
        mid_t = (start_t + end_t) / 2
        mid_x = -shield_width * 0.55 * side
        mid_curve_y = -math.sin(mid_t * math.pi) * shield_height * 0.55
        mid_point = to_world(mid_x, mid_curve_y)
        
        # 곡선으로 스트랩 그리기
        strap_points = [_vec_to_int_pair(strap_start), _vec_to_int_pair(mid_point), _vec_to_int_pair(strap_end)]
        pygame.draw.lines(surface, strap_color, False, strap_points, 5)

    # 중심부 망치 장식 (입체감 강화)
    hammer_length = shield_width * 0.45
    hammer_thickness = shield_height * 0.18
    
    # 망치 그림자 레이어
    shadow_offset = 2
    hammer_shadow_pts = [
        to_world(-hammer_length * 0.5 + shadow_offset, -hammer_thickness * 0.5 + shadow_offset),
        to_world(-hammer_length * 0.15 + shadow_offset, -hammer_thickness * 0.5 + shadow_offset),
        to_world(hammer_length * 0.15 + shadow_offset, -hammer_thickness * 0.5 + shadow_offset),
        to_world(hammer_length * 0.5 + shadow_offset, hammer_thickness * 0.1 + shadow_offset),
        to_world(hammer_length * 0.15 + shadow_offset, hammer_thickness * 0.5 + shadow_offset),
        to_world(-hammer_length * 0.15 + shadow_offset, hammer_thickness * 0.5 + shadow_offset),
    ]
    pygame.draw.polygon(surface, hammer_shadow_color, [_vec_to_int_pair(p) for p in hammer_shadow_pts])
    
    # 망치 메인 바디
    hammer_pts = [
        to_world(-hammer_length * 0.5, -hammer_thickness * 0.5),
        to_world(-hammer_length * 0.15, -hammer_thickness * 0.5),
        to_world(hammer_length * 0.15, -hammer_thickness * 0.5),
        to_world(hammer_length * 0.5, hammer_thickness * 0.1),
        to_world(hammer_length * 0.15, hammer_thickness * 0.5),
        to_world(-hammer_length * 0.15, hammer_thickness * 0.5),
    ]
    pygame.draw.polygon(surface, hammer_body_color, [_vec_to_int_pair(p) for p in hammer_pts])
    
    # 망치 하이라이트
    highlight_pts = [
        to_world(-hammer_length * 0.4, -hammer_thickness * 0.3),
        to_world(-hammer_length * 0.1, -hammer_thickness * 0.3),
        to_world(hammer_length * 0.1, -hammer_thickness * 0.3),
        to_world(hammer_length * 0.3, 0),
    ]
    pygame.draw.polygon(surface, hammer_highlight_color, [_vec_to_int_pair(p) for p in highlight_pts])
    
    # 망치 아웃라인
    pygame.draw.polygon(surface, hammer_outline_color, [_vec_to_int_pair(p) for p in hammer_pts], width=3)

    # 토르쉴드 내구도에 따른 금(크랙) 표현
    damage_stage = 0
    gauge_value = BLACKSMITH_UMBRELLA_GAUGE_MAX
    try:
        gauge_value = max(0, min(BLACKSMITH_UMBRELLA_GAUGE_MAX, blacksmith_umbrella_gauge))
    except NameError:
        gauge_value = BLACKSMITH_UMBRELLA_GAUGE_MAX

    damage_stage = max(0, min(len(BLACKSMITH_UMBRELLA_CRACK_SEGMENTS), BLACKSMITH_UMBRELLA_GAUGE_MAX - gauge_value))

    if damage_stage > 0:
        flash_timer = globals().get("blacksmith_umbrella_damage_flash_timer", 0)
        flash_frames = BLACKSMITH_UMBRELLA_DAMAGE_FLASH_FRAMES if BLACKSMITH_UMBRELLA_DAMAGE_FLASH_FRAMES > 0 else 1
        flash_strength = max(0.0, min(1.0, flash_timer / flash_frames))

        base_crack_color = (186, 178, 168)
        highlight_color = (250, 244, 234)
        crack_color = tuple(
            min(255, int(base_crack_color[i] + (highlight_color[i] - base_crack_color[i]) * flash_strength + damage_stage * 6))
            for i in range(3)
        )
        crack_shadow = (58, 46, 38)
        crack_width = max(1, int(shield_height * 0.02) + damage_stage // 2)

        for stage_idx in range(damage_stage):
            for start_norm, end_norm in BLACKSMITH_UMBRELLA_CRACK_SEGMENTS[stage_idx]:
                start = to_world(start_norm[0] * shield_width, start_norm[1] * shield_height)
                end = to_world(end_norm[0] * shield_width, end_norm[1] * shield_height)
                start_pt = _vec_to_int_pair(start)
                end_pt = _vec_to_int_pair(end)
                pygame.draw.line(surface, crack_shadow, start_pt, end_pt, max(1, crack_width + 1))
                pygame.draw.line(surface, crack_color, start_pt, end_pt, crack_width)

        if damage_stage >= 3:
            # 교차점에 작은 반짝임 추가
            junction_color = tuple(min(255, c + 20) for c in crack_color)
            junction_radius = max(1, int(shield_height * 0.018))
            core_radius = max(1, junction_radius - 1)
            junction_points = [
                to_world(0.0, 0.0),
                to_world(-0.06 * shield_width, 0.12 * shield_height),
                to_world(0.06 * shield_width, 0.12 * shield_height),
            ]
            for point in junction_points:
                center = _vec_to_int_pair(point)
                pygame.draw.circle(surface, crack_shadow, center, junction_radius)
                pygame.draw.circle(surface, junction_color, center, core_radius)

    # 방패 충격 효과 (전역 변수 체크)
    global blacksmith_shield_impact_timer
    if 'blacksmith_shield_impact_timer' in globals() and blacksmith_shield_impact_timer > 0:
        # 충격파 효과
        impact_radius = (30 - blacksmith_shield_impact_timer) * 4
        impact_alpha = int(blacksmith_shield_impact_timer * 8)
        if impact_alpha > 0:
            impact_surface = pygame.Surface((int(shield_width * 1.5), int(shield_height * 3)), pygame.SRCALPHA)
            impact_center = (int(shield_width * 0.75), int(shield_height * 1.5))
            # 여러 겹의 충격파
            for ring in range(3):
                ring_radius = impact_radius - ring * 10
                if ring_radius > 0:
                    ring_alpha = max(0, impact_alpha - ring * 30)
                    pygame.draw.circle(impact_surface, (255, 235, 180, ring_alpha), 
                                     impact_center, int(ring_radius), 3)
            surface.blit(impact_surface, (int(shield_center.x - shield_width * 0.75), 
                                         int(shield_center.y - shield_height * 1.5)), 
                        special_flags=pygame.BLEND_ADD)

    xs = [p.x for p in outline_world]
    blacksmith_umbrella_overlay_bounds = (min(xs), max(xs)) if xs else None


def _draw_blacksmith_legs(surface, step=0):
    hip_y = BLACKSMITH_HIP_Y
    leg_len = BLACKSMITH_LEG_LENGTH
    knee_y = hip_y + 7
    base_boot_y = hip_y + leg_len + 2

    left_base = BLACKSMITH_LEFT_LEG_X
    right_base = BLACKSMITH_RIGHT_LEG_X

    sway = max(-8, min(8, step))
    left_sway = -sway
    right_sway = sway

    left_thigh_x = left_base + left_sway // 3
    left_shin_x = left_base + left_sway
    right_thigh_x = right_base + right_sway // 3
    right_shin_x = right_base + right_sway

    left_boot_lift = max(0, left_sway) // 2
    right_boot_lift = max(0, right_sway) // 2
    left_boot_y = base_boot_y - left_boot_lift
    right_boot_y = base_boot_y - right_boot_lift

    # 왼쪽 다리 (앞뒤로 움직임)
    left_thigh = [
        (left_thigh_x - 5, hip_y),
        (left_thigh_x - 6, hip_y + 4),
        (left_thigh_x - 5, knee_y),
        (left_thigh_x + 5, knee_y),
        (left_thigh_x + 6, hip_y + 4),
        (left_thigh_x + 5, hip_y)
    ]
    pygame.draw.polygon(surface, (108, 88, 64), left_thigh)

    left_shin = [
        (left_shin_x - 4, knee_y + 1),
        (left_shin_x - 5, hip_y + leg_len),
        (left_shin_x - 2, left_boot_y + 2),
        (left_shin_x + 2, left_boot_y + 2),
        (left_shin_x + 5, hip_y + leg_len),
        (left_thigh_x + 4, knee_y + 1)
    ]
    pygame.draw.polygon(surface, (108, 88, 64), left_shin)

    pygame.draw.polygon(surface, (68, 52, 36), [
        (left_shin_x - 6, left_boot_y),
        (left_shin_x - 6, left_boot_y + 6),
        (left_shin_x + 6, left_boot_y + 6),
        (left_shin_x + 6, left_boot_y)
    ])

    # 오른쪽 다리 (반대 방향 스윙)
    right_thigh = [
        (right_thigh_x - 5, hip_y),
        (right_thigh_x - 6, hip_y + 4),
        (right_thigh_x - 5, knee_y),
        (right_thigh_x + 5, knee_y),
        (right_thigh_x + 6, hip_y + 4),
        (right_thigh_x + 5, hip_y)
    ]
    pygame.draw.polygon(surface, (108, 88, 64), right_thigh)

    right_shin = [
        (right_shin_x - 4, knee_y + 1),
        (right_shin_x - 5, hip_y + leg_len),
        (right_shin_x - 2, right_boot_y + 2),
        (right_shin_x + 2, right_boot_y + 2),
        (right_shin_x + 5, hip_y + leg_len),
        (right_thigh_x + 4, knee_y + 1)
    ]
    pygame.draw.polygon(surface, (108, 88, 64), right_shin)

    pygame.draw.polygon(surface, (68, 52, 36), [
        (right_shin_x - 6, right_boot_y),
        (right_shin_x - 6, right_boot_y + 6),
        (right_shin_x + 6, right_boot_y + 6),
        (right_shin_x + 6, right_boot_y)
    ])

    # 무릎 보호대와 스타드
    pygame.draw.circle(surface, (150, 130, 110), (left_thigh_x, knee_y + 1), 5)
    pygame.draw.circle(surface, (95, 80, 62), (left_thigh_x, knee_y + 1), 3)
    pygame.draw.circle(surface, (150, 130, 110), (right_thigh_x, knee_y + 1), 5)
    pygame.draw.circle(surface, (95, 80, 62), (right_thigh_x, knee_y + 1), 3)

def create_blacksmith_paddle_umbrella(progress: float) -> pygame.Surface:
    progress = max(0.0, min(1.0, progress))
    raise_amount = min(1.0, progress / 0.45)
    open_amount = max(0.0, (progress - 0.35) / 0.65)

    global blacksmith_hammer_head_local_point, blacksmith_hammer_head_surface_point
    global blacksmith_umbrella_body_offset, blacksmith_umbrella_hitbox_extents
    global blacksmith_umbrella_hitbox_extents_strict
    global blacksmith_umbrella_hitbox_vertical, blacksmith_umbrella_hitbox_center_offset
    global blacksmith_umbrella_hitbox_direction, blacksmith_umbrella_hitbox_raw
    global blacksmith_umbrella_swing_direction, blacksmith_umbrella_swing_stage

    swing_dir = -1 if blacksmith_umbrella_swing_direction < 0 else 1

    walk_wave = 0.0
    walk_bob = 0.0
    walk_lean = 0.0
    leg_step = 0
    if blacksmith_walking_active:
        cycle_frames = max(1, int(BLACKSMITH_WALKING_CYCLE * BLACKSMITH_UMBRELLA_WALK_CYCLE_MULT))
        walk_progress = (blacksmith_walking_timer % cycle_frames) / cycle_frames
        phase = walk_progress * 2 * math.pi
        base_wave = math.sin(phase)
        base_bob = math.sin(phase + math.pi / 2)
        walk_wave = base_wave * BLACKSMITH_UMBRELLA_WALK_WAVE_SCALE
        walk_bob = base_bob * BLACKSMITH_UMBRELLA_WALK_BOB_SCALE
        walk_lean = blacksmith_walk_direction * BLACKSMITH_UMBRELLA_WALK_LEAN
        leg_step = int(round(base_wave * BLACKSMITH_UMBRELLA_WALK_STEP_PIXELS))

    base_width = 250
    body_height = 120
    # 양쪽 스윙 모두 왼쪽 스윙의 padding 값 사용으로 일관된 anchor 계산 보장
    # 왼쪽 스윙이 정상 동작하므로 이 설정을 양쪽 모두에 적용
    left_padding = 210  # 토르쉴드가 왼쪽으로 크게 펼쳐질 때 잘리지 않도록 여유 공간 확보
    right_padding = 60
    final_width = base_width + left_padding + right_padding
    final_height = 620
    body_surface = pygame.Surface((base_width, body_height), pygame.SRCALPHA)
    pose = _draw_blacksmith_upper(
        body_surface,
        shield_swing=0.0,
        hammer_swing=0.0,
        walk_wave=walk_wave,
        walk_bob=walk_bob,
        walk_lean=walk_lean,
        force_hammer_visibility=False,
        request_pose=True,
        umbrella_pose=True,
        umbrella_raise=raise_amount,
    )
    _draw_blacksmith_legs(body_surface, leg_step)

    surface = pygame.Surface((final_width, final_height), pygame.SRCALPHA)
    body_offset_x = left_padding
    body_offset_y = final_height - body_height
    surface.blit(body_surface, (body_offset_x, body_offset_y))
    blacksmith_umbrella_body_offset = (body_offset_x, body_offset_y)

    pivot_point: tuple[float, float] | None = None
    head_point: tuple[float, float] | None = None
    if isinstance(pose, dict):
        pivot_raw = pose.get("pivot")
        head_raw = pose.get("head")
        if pivot_raw and head_raw:
            pivot_point = (pivot_raw[0] + body_offset_x, pivot_raw[1] + body_offset_y)
            head_point = (head_raw[0] + body_offset_x, head_raw[1] + body_offset_y)

    prev_head_local = blacksmith_hammer_head_local_point
    prev_head_surface = blacksmith_hammer_head_surface_point
    if blacksmith_hammer_head_local_point is not None:
        blacksmith_hammer_head_local_point = (
            blacksmith_hammer_head_local_point[0] + body_offset_x,
            blacksmith_hammer_head_local_point[1] + body_offset_y,
        )

    if pivot_point and head_point:
        vertical_offset = 76 - 20 * raise_amount + BLACKSMITH_UMBRELLA_VISUAL_OFFSET_Y
        pivot_point = (pivot_point[0], pivot_point[1] + vertical_offset)
        head_point = (head_point[0], head_point[1] + vertical_offset)
        _draw_blacksmith_umbrella_overlay(surface, pivot_point, head_point, raise_amount, open_amount)

    debug_pivot = pivot_point

    anchor_point = (
        BLACKSMITH_CENTER_X + body_offset_x,
        BLACKSMITH_CENTER_Y + body_offset_y,
    )
    scaled_surface, scaled_anchor = _scale_blacksmith_sprite(surface, anchor_point)

    if scaled_anchor is not None:
        bounds = scaled_surface.get_bounding_rect(min_alpha=1)
        surface_rect = scaled_surface.get_rect()
        center_x = surface_rect.centerx
        scale_value = BLACKSMITH_SCALE if abs(BLACKSMITH_SCALE) > 1e-5 else 1.0
        anchor_offset_x = int(round((scaled_anchor[0] - center_x) / scale_value))
        # 유지 보수를 위해 디버그 토글은 남겨두되 기본 출력은 비활성화한다.
        if DEBUG_BLACKSMITH_UMBRELLA_ANCHOR:
            pass
        padding_bias = (left_padding - right_padding) / 2.0
        if abs(padding_bias) > 0.01:
            # 양쪽 스윙 모두 동일한 padding bias 적용으로 대칭적 동작 보장
            # 이렇게 해야 패들 순간이동과 히트박스 불일치 문제가 해결됨
            anchor_offset_x -= int(round(padding_bias / scale_value))

        raw_anchor_offset_x = anchor_offset_x

        global blacksmith_umbrella_anchor_left, blacksmith_umbrella_anchor_right
        # 양쪽 스윙 모두 동일한 anchor 값 사용으로 패들 순간이동 방지
        # 왼쪽 스윙이 정상 동작하므로 양쪽 모두 동일한 기준점 사용
        blacksmith_umbrella_anchor_left = raw_anchor_offset_x
        blacksmith_umbrella_anchor_right = raw_anchor_offset_x

        # 스윙 시작 시 피벗이 급격히 변하며 보이는 '순간 이동'을 완화하되,
        # 그래픽/히트박스 정합성은 유지하기 위해 raw 값을 부드럽게 추적한다.
        # (도형·히트박스 모두 동일한 오프셋을 사용하므로 정합성 유지)
        global blacksmith_umbrella_anchor_smoothed_x
        try:
            current = float(blacksmith_umbrella_anchor_smoothed_x)
        except NameError:
            current = float(raw_anchor_offset_x)
        target = float(raw_anchor_offset_x)
        # 한 프레임당 최대 이동량을 제한해 갑작스런 점프를 방지
        max_step = 5.0
        delta = target - current
        if delta > max_step:
            step = max_step
        elif delta < -max_step:
            step = -max_step
        else:
            step = delta
        new_value = current + step
        blacksmith_umbrella_anchor_smoothed_x = new_value
        anchor_offset_x = int(round(new_value))

        if DEBUG_BLACKSMITH_UMBRELLA_ANCHOR:
            pass

        baseline_offset_y = max(0, int(round(bounds.bottom - BLACKSMITH_BASELINE_Y + BLACKSMITH_CONTACT_EXTRA_Y)))
        blacksmith_umbrella_body_offset = (anchor_offset_x, baseline_offset_y)

        overlay_bounds = blacksmith_umbrella_overlay_bounds
        base_half = (PADDLE_WIDTH / 2) * scale_value
        default_half = base_half * 0.85 * 1.8

        raw_data = blacksmith_umbrella_hitbox_raw if debug_pivot is not None else None
        if overlay_bounds is not None and raw_data is not None:
            pivot_x = debug_pivot[0]
            min_x, max_x = overlay_bounds
            left_pixels = max(0.0, pivot_x - min_x) + BLACKSMITH_UMBRELLA_HITBOX_MARGIN
            right_pixels = max(0.0, max_x - pivot_x) + BLACKSMITH_UMBRELLA_HITBOX_MARGIN

            # 보수적 모드(기존): 기본 패들 절반 + 여분의 30%만 확장
            extra_left = max(0.0, left_pixels * scale_value - base_half)
            extra_right = max(0.0, right_pixels * scale_value - base_half)
            left_extent = base_half + extra_left * 0.3
            right_extent = base_half + extra_right * 0.3

            # 엄격 모드: 오버레이 폴리곤 경계와 동일한 반경 사용
            left_strict = left_pixels * scale_value
            right_strict = right_pixels * scale_value
            blacksmith_umbrella_hitbox_extents_strict = (left_strict, right_strict)
        else:
            left_extent = right_extent = default_half
            raw_data = None
            blacksmith_umbrella_hitbox_raw = None
            blacksmith_umbrella_hitbox_extents_strict = (default_half, default_half)

        blacksmith_umbrella_hitbox_extents = (left_extent, right_extent)

        if raw_data is not None and debug_pivot is not None:
            pivot_y = debug_pivot[1]
            min_y = raw_data.get("min_y", pivot_y)
            max_y = raw_data.get("max_y", pivot_y)
            up_pixels = max(0.0, pivot_y - min_y) + BLACKSMITH_UMBRELLA_HITBOX_MARGIN
            down_pixels = max(0.0, max_y - pivot_y) + BLACKSMITH_UMBRELLA_HITBOX_MARGIN
            up_extent = up_pixels * scale_value
            down_extent = down_pixels * scale_value
            blacksmith_umbrella_hitbox_vertical = (up_extent, down_extent)

            center_offset_x = (raw_data.get("center_x", pivot_y) - raw_data.get("pivot_x", pivot_y)) * scale_value
            center_offset_y = (raw_data.get("center_y", pivot_y) - raw_data.get("pivot_y", pivot_y)) * scale_value
            blacksmith_umbrella_hitbox_center_offset = (center_offset_x, center_offset_y)

            dir_x = raw_data.get("dir_x", 0.0)
            dir_y = raw_data.get("dir_y", -1.0)
            mag = math.hypot(dir_x, dir_y)
            if mag > 1e-4:
                blacksmith_umbrella_hitbox_direction = (dir_x / mag, dir_y / mag)
            else:
                blacksmith_umbrella_hitbox_direction = (0.0, -1.0)
        else:
            blacksmith_umbrella_hitbox_vertical = (0.0, 0.0)
            blacksmith_umbrella_hitbox_center_offset = (0.0, 0.0)
            blacksmith_umbrella_hitbox_direction = (0.0, -1.0)
            blacksmith_umbrella_hitbox_raw = None
    else:
        blacksmith_umbrella_body_offset = (0, 0)
        blacksmith_umbrella_hitbox_extents = (0.0, 0.0)
        blacksmith_umbrella_hitbox_vertical = (0.0, 0.0)
        blacksmith_umbrella_hitbox_center_offset = (0.0, 0.0)
        blacksmith_umbrella_hitbox_direction = (0.0, -1.0)
        blacksmith_umbrella_hitbox_raw = None

    blacksmith_hammer_head_local_point = prev_head_local
    blacksmith_hammer_head_surface_point = prev_head_surface

    return scaled_surface


def create_blacksmith_paddle_base(include_hammer: bool = True) -> pygame.Surface:
    global blacksmith_hammer_head_local_point, blacksmith_hammer_head_surface_point, blacksmith_hammer_charge_position
    global blacksmith_hammer_pivot_local_point, blacksmith_hammer_forward_vector
    prev_local = blacksmith_hammer_head_local_point
    prev_surface = blacksmith_hammer_head_surface_point
    prev_charge = blacksmith_hammer_charge_position
    prev_pivot = blacksmith_hammer_pivot_local_point
    prev_forward = blacksmith_hammer_forward_vector
    surface: pygame.Surface | None = None
    result_surface: pygame.Surface | None = None
    try:
        surface = pygame.Surface((250, 120), pygame.SRCALPHA)
        _draw_blacksmith_upper(
            surface,
            shield_swing=0.0,
            hammer_swing=0.0,
            force_hammer_visibility=include_hammer,
        )
        _draw_blacksmith_legs(surface, 0)
        scaled_surface, _ = _scale_blacksmith_sprite(surface, (BLACKSMITH_CENTER_X, BLACKSMITH_CENTER_Y))
        result_surface = scaled_surface
    finally:
        blacksmith_hammer_head_local_point = prev_local
        blacksmith_hammer_head_surface_point = prev_surface
        blacksmith_hammer_charge_position = prev_charge
        blacksmith_hammer_pivot_local_point = prev_pivot
        blacksmith_hammer_forward_vector = prev_forward
    if result_surface is not None:
        return result_surface
    if surface is not None:
        return surface
    raise RuntimeError("Failed to create blacksmith paddle surface")

def create_blacksmith_paddle_walking(*, force_hammer: bool | None = None):
    global blacksmith_walking_timer, blacksmith_walk_direction
    surface = pygame.Surface((250, 120), pygame.SRCALPHA)
    progress = (blacksmith_walking_timer % BLACKSMITH_WALKING_CYCLE) / BLACKSMITH_WALKING_CYCLE
    walk_wave = math.sin(progress * 2 * math.pi)
    walk_bob = math.sin(progress * 2 * math.pi + math.pi / 2)
    walk_lean = blacksmith_walk_direction * 0.6
    _draw_blacksmith_upper(
        surface,
        shield_swing=0.0,
        hammer_swing=0.0,
        walk_wave=walk_wave,
        walk_bob=walk_bob,
        walk_lean=walk_lean,
        force_hammer_visibility=force_hammer,
        hammerless_walk=(force_hammer is False),
    )
    step = int(walk_wave * 8)
    _draw_blacksmith_legs(surface, step)
    scaled_surface, _ = _scale_blacksmith_sprite(surface, (BLACKSMITH_CENTER_X, BLACKSMITH_CENTER_Y))
    return scaled_surface

def create_blacksmith_paddle_swinging():
    global blacksmith_shield_swing_timer

    surface = pygame.Surface((250, 120), pygame.SRCALPHA)

    if BLACKSMITH_SHIELD_SWING_DURATION > 0:
        progress = 1.0 - (blacksmith_shield_swing_timer / BLACKSMITH_SHIELD_SWING_DURATION)
        progress = max(0.0, min(1.0, progress))
    else:
        progress = 0.0
    swing_amount = math.sin(progress * math.pi)

    _draw_blacksmith_upper(surface, shield_swing=swing_amount, hammer_swing=0.0)
    _draw_blacksmith_legs(surface, 0)
    scaled_surface, _ = _scale_blacksmith_sprite(surface, (BLACKSMITH_CENTER_X, BLACKSMITH_CENTER_Y))
    return scaled_surface


def create_blacksmith_paddle_hammering():
    global blacksmith_hammer_swing_phase

    surface = pygame.Surface((250, 120), pygame.SRCALPHA)

    if BLACKSMITH_HAMMER_SWING_DURATION > 0:
        phase_ratio = blacksmith_hammer_swing_phase / BLACKSMITH_HAMMER_SWING_DURATION
    else:
        phase_ratio = 0.0
    phase_ratio = max(0.0, min(1.0, phase_ratio))
    _draw_blacksmith_upper(surface, shield_swing=0.0, hammer_swing=phase_ratio)
    _draw_blacksmith_legs(surface, 0)
    scaled_surface, _ = _scale_blacksmith_sprite(surface, (BLACKSMITH_CENTER_X, BLACKSMITH_CENTER_Y))
    return scaled_surface


def _get_blacksmith_existing_building_rects() -> list[pygame.Rect]:
    """현재 필드에 존재하는 발토르 건물(포탑/디바인/청사진) 사각형 목록을 반환한다.

    - 포탑 본체 및 포탑 청사진
    - 디바인스톤 본체 및 디바인스톤 청사진
    """
    rects: list[pygame.Rect] = []

    # 포탑 본체
    if blacksmith_turret_active and blacksmith_turret_state:
        turret_rect = blacksmith_turret_state.get("rect")
        if turret_rect is not None:
            rects.append(turret_rect)

    # 포탑 청사진
    if blacksmith_turret_blueprint_active and blacksmith_turret_blueprint_rect is not None:
        rects.append(blacksmith_turret_blueprint_rect)

    # 디바인스톤 본체
    if blacksmith_divine_stone_state is not None:
        stone_rect = blacksmith_divine_stone_state.get("rect")
        if stone_rect is not None:
            rects.append(stone_rect)

    # 디바인스톤 청사진
    if blacksmith_divine_blueprint_active and blacksmith_divine_blueprint_rect is not None:
        rects.append(blacksmith_divine_blueprint_rect)

    return rects


def _resolve_blacksmith_blueprint_position(blueprint_rect: pygame.Rect, margin: int = 8) -> pygame.Rect:
    """발토르 건물 청사진이 기존 건물과 겹치지 않도록 가로 위치를 조정한다.

    이미 포탑/디바인스톤이 있는 위치에 청사진이 생성되면,
    좌우로 한 칸씩 옮겨가며 겹치지 않는 위치를 탐색한다.
    """
    existing_rects = _get_blacksmith_existing_building_rects()
    if not existing_rects:
        return blueprint_rect

    def collides(test_rect: pygame.Rect) -> bool:
        for other in existing_rects:
            # 약간의 여유 간격을 두고 충돌 판정
            expanded = other.inflate(margin * 2, margin * 2)
            if test_rect.colliderect(expanded):
                return True
        return False

    # 처음 위치가 겹치지 않으면 그대로 사용
    if not collides(blueprint_rect):
        return blueprint_rect

    min_center_x = blueprint_rect.width // 2
    max_center_x = WIDTH - blueprint_rect.width // 2
    original_center_x = blueprint_rect.centerx

    # 청사진 너비 기준으로 좌우로 한 칸씩 이동하며 위치 탐색
    step = max(1, blueprint_rect.width + margin)
    max_steps = max(1, (WIDTH // step) + 2)

    for offset in range(1, max_steps + 1):
        for direction in (1, -1):
            new_center_x = original_center_x + direction * offset * step
            if new_center_x < min_center_x or new_center_x > max_center_x:
                continue
            candidate = blueprint_rect.copy()
            candidate.centerx = new_center_x
            if not collides(candidate):
                blueprint_rect.centerx = new_center_x
                return blueprint_rect

    # 적절한 위치를 찾지 못한 경우, 화면 경계 안에서만 정규화하여 반환
    blueprint_rect.centerx = max(min_center_x, min(max_center_x, original_center_x))
    return blueprint_rect


def handle_blacksmith_turret_input(down_pressed, down_just_pressed, force_blueprint=False):
    """발토르 포탑 설치/건설 입력을 처리한다."""
    global blacksmith_turret_blueprint_active, blacksmith_turret_blueprint_rect
    global blacksmith_turret_build_progress, blacksmith_turret_active
    global blacksmith_turret_state, special_gauge, special_ready
    global is_waiting_for_serve, is_player_serve
    global blacksmith_hammer_swing_active, blacksmith_hammer_swing_phase
    global blacksmith_trail_timer
    global blacksmith_manual_hammer_timer, blacksmith_manual_hammer_increment
    global blacksmith_hammer_swing_slow_timer, blacksmith_hammer_slow_decay_step
    global blacksmith_turret_partial_drain, blacksmith_turret_xp_partial_drain
    global blacksmith_divine_blueprint_active, blacksmith_divine_blueprint_rect
    global blacksmith_divine_build_progress, blacksmith_divine_partial_drain
    global blacksmith_divine_stone_state, blacksmith_divine_stage_owner
    global frame_counter
    global blacksmith_build_menu_active
    global blacksmith_umbrella_open, blacksmith_umbrella_anim_timer, blacksmith_umbrella_retracting
    global blacksmith_umbrella_retracting, blacksmith_umbrella_anim_direction
    global blacksmith_umbrella_swing_active, blacksmith_umbrella_swing_timer
    global blacksmith_umbrella_swing_stage, blacksmith_umbrella_swing_progress

    sync_blacksmith_state()
    state = BLACKSMITH_CONTROLLER.state
    divine_runtime = state.divine
    turret_runtime = state.turret

    construction_active = False
    hammer_engaged_this_frame = False

    if blacksmith_umbrella_open and not blacksmith_umbrella_retracting:
        stop_blacksmith_construction_sound()
        return down_just_pressed

    if selected_character_type != "blacksmith":
        stop_blacksmith_construction_sound()
        return down_just_pressed

    if not blacksmith_hammer_available and not blacksmith_hammer_shock_charging:
        return down_just_pressed

    if is_waiting_for_serve or is_player_serve:
        stop_blacksmith_construction_sound()
        return down_just_pressed

    if blacksmith_build_menu_active:
        stop_blacksmith_construction_sound()
        return down_just_pressed

    if (
        force_blueprint
        and not blacksmith_turret_blueprint_active
        and not blacksmith_turret_active
    ):
        blueprint_width = BLACKSMITH_TURRET_BLUEPRINT_WIDTH
        blueprint_height = BLACKSMITH_TURRET_BLUEPRINT_HEIGHT
        blueprint_rect = pygame.Rect(0, 0, blueprint_width, blueprint_height)
        base_x = max(blueprint_width // 2, min(WIDTH - blueprint_width // 2, PLAYER.centerx))
        base_y = HEIGHT - 5
        blueprint_rect.midbottom = (base_x, base_y)
        blueprint_rect = _resolve_blacksmith_blueprint_position(blueprint_rect)
        blacksmith_turret_blueprint_rect = blueprint_rect
        print(f"[DEBUG] Blueprint created: player_bottom={PLAYER.bottom}, blueprint_bottom={blueprint_rect.bottom}, top={blueprint_rect.top}")
        blacksmith_turret_build_progress = 0
        blacksmith_turret_blueprint_active = True
        blacksmith_turret_partial_drain = 0.0
        try:
            play_sound_with_volume(SOUND_ITEM_GET)
        except Exception:
            pass
        down_just_pressed = False
        blacksmith_hammer_swing_active = False
        blacksmith_hammer_swing_slow_timer = 0
        blacksmith_hammer_slow_decay_step = 0
        blacksmith_hammer_swing_phase = 0
        blacksmith_manual_hammer_timer = 0
        blacksmith_manual_hammer_increment = 1
    elif (
        down_just_pressed
        and not blacksmith_turret_blueprint_active
        and not blacksmith_turret_active
    ):
        stop_blacksmith_construction_sound()
        return down_just_pressed

    if (
        blacksmith_turret_blueprint_active
        and not blacksmith_turret_active
        and blacksmith_turret_blueprint_rect is not None
    ):
        if down_pressed:
            distance = abs(PLAYER.centerx - blacksmith_turret_blueprint_rect.centerx)
            if distance <= BLACKSMITH_TURRET_BUILD_RADIUS:
                if not blacksmith_hammer_swing_active:
                    blacksmith_hammer_swing_phase = 0
                blacksmith_hammer_swing_slow_timer = 0
                blacksmith_hammer_slow_decay_step = 0
                blacksmith_hammer_swing_active = True
                hammer_increment = 1
                if frame_counter % 2 == 0:
                    hammer_increment = 2
                blacksmith_hammer_swing_phase = (
                    blacksmith_hammer_swing_phase + hammer_increment
                ) % max(1, BLACKSMITH_HAMMER_SWING_DURATION)
                hammer_engaged_this_frame = True
                drain_per_frame = (BLACKSMITH_TURRET_GAUGE_DRAIN_PER_SEC / FPS) * get_blacksmith_construction_speed_multiplier()
                gauge_spent = False
                progress_gain = 0
                if special_gauge > 0:
                    construction_active = True
                    blacksmith_turret_partial_drain += drain_per_frame
                    gauge_spent = True
                    drain_units = int(blacksmith_turret_partial_drain)
                    if drain_units > 0:
                        actual_drain = min(drain_units, special_gauge)
                        if actual_drain > 0:
                            special_gauge -= actual_drain
                            blacksmith_turret_partial_drain -= actual_drain
                            special_ready = special_gauge >= 350
                            construction_active = True
                            progress_gain = actual_drain
                        else:
                            gauge_spent = False
                else:
                    gauge_spent = False
                if gauge_spent and progress_gain > 0:
                    blacksmith_turret_build_progress = min(
                        BLACKSMITH_TURRET_BUILD_TIME,
                        blacksmith_turret_build_progress + progress_gain
                    )
                    if frame_counter % 4 == 0 and blacksmith_turret_blueprint_rect:
                        smoke_x = blacksmith_turret_blueprint_rect.centerx + random.uniform(-8, 8)
                        smoke_y = blacksmith_turret_blueprint_rect.top + random.uniform(-6, 4)
                        effects_manager.spawn_construction_smoke(smoke_x, smoke_y, count=2)
                    if blacksmith_turret_build_progress >= BLACKSMITH_TURRET_BUILD_TIME:
                        turret_rect = pygame.Rect(0, 0, BLACKSMITH_TURRET_BASE_WIDTH, BLACKSMITH_TURRET_BASE_HEIGHT)
                        turret_rect.midbottom = blacksmith_turret_blueprint_rect.midbottom
                        # 레벨 1 포탑 기본 자동 발사 주기(5초)
                        base_interval = BLACKSMITH_TURRET_FIRE_INTERVAL
                        blacksmith_turret_state = {
                            "rect": turret_rect,
                            "fire_timer": base_interval,
                            "fire_interval": base_interval,
                            "hp": BLACKSMITH_TURRET_BASE_HP,
                            "max_hp": BLACKSMITH_TURRET_BASE_HP,
                            "level": BLACKSMITH_TURRET_BASE_LEVEL,
                            "xp": 0.0,
                            # 1레벨 포탑은 먼저 강화(레벨 2) 단계까지 게이지를 채운 뒤,
                            # 이후부터는 오버드라이브 게이지(Blacksmith_TURRET_XP_REQUIRED)를 사용한다.
                            "xp_max": float(BLACKSMITH_TURRET_REINFORCE_COST),
                            "aim_angle": -math.pi / 2,
                            "display_angle": -math.pi / 2,
                            "recoil_timer": 0,
                            "recoil_offset": 0.0,
                            "base_fire_interval": base_interval,
                            "overdrive_active": False,
                            "overdrive_timer": 0,
                            "overdrive_fire_window": 0,
                            "overdrive_shots_remaining": 0,
                            "overdrive_shot_cooldown": 0,
                            "overdrive_glow_phase": 0.0,
                            "overdrive_flash_timer": 0,
                            "overdrive_recoil_boost": 1.0,
                            "overdrive_speed_boost": 1.0,
                            "overdrive_stun_multiplier": 1.0,
                            "overdrive_knockback_multiplier": 1.0,
                            "overdrive_divine_active": False,
                            "overheat_timer": 0,
                            "overheat_smoke_timer": 0,
                            "homing_cooldown": 0,
                            "homing_burst_timer": 0,
                            "homing_burst_shots": 0,
                        }
                        blacksmith_turret_active = True
                        blacksmith_turret_blueprint_active = False
                        blacksmith_turret_blueprint_rect = None
                        blacksmith_turret_build_progress = 0
                        blacksmith_turret_partial_drain = 0.0
                        
                        # 손상 효과 매니저에 포탑 등록
                        damage_manager = get_damage_manager()
                        damage_manager.register_building("turret", turret_rect, BLACKSMITH_TURRET_BASE_HP)
                        try:
                            play_sound_with_volume(SOUND_STAGE6_BEAM_CHARGE)
                        except Exception:
                            pass
                        blacksmith_hammer_swing_active = False
                        blacksmith_hammer_swing_slow_timer = 0
                        blacksmith_hammer_slow_decay_step = 0
                        blacksmith_hammer_swing_phase = 0
                        blacksmith_manual_hammer_timer = 0
                        blacksmith_manual_hammer_increment = 1
                    elif frame_counter % 30 == 0:
                        print(f"[DEBUG] Turret build: {blacksmith_turret_build_progress}/{BLACKSMITH_TURRET_BUILD_TIME}, gauge={special_gauge}, phase={blacksmith_hammer_swing_phase}")
                else:
                    if frame_counter % 45 == 0:
                        print(f"[DEBUG] Turret build paused (gauge={special_gauge}, partial={blacksmith_turret_partial_drain:.2f})")
    else:
        if (
            blacksmith_turret_active
            and blacksmith_turret_state
            and down_pressed
            and blacksmith_turret_state.get("rect") is not None
        ):
            distance = abs(PLAYER.centerx - blacksmith_turret_state["rect"].centerx)
            if distance <= BLACKSMITH_TURRET_BUILD_RADIUS:
                hammer_engaged_this_frame = True

    if (
        blacksmith_divine_blueprint_active
        and blacksmith_divine_blueprint_rect is not None
        and blacksmith_divine_stone_state is None
    ):
        if down_pressed:
            distance = abs(PLAYER.centerx - blacksmith_divine_blueprint_rect.centerx)
            if distance <= BLACKSMITH_DIVINE_BUILD_RADIUS:
                if not blacksmith_hammer_swing_active:
                    blacksmith_hammer_swing_phase = 0
                blacksmith_hammer_swing_slow_timer = 0
                blacksmith_hammer_slow_decay_step = 0
                blacksmith_hammer_swing_active = True
                hammer_increment = 1
                if frame_counter % 2 == 0:
                    hammer_increment = 2
                blacksmith_hammer_swing_phase = (
                    blacksmith_hammer_swing_phase + hammer_increment
                ) % max(1, BLACKSMITH_HAMMER_SWING_DURATION)
                hammer_engaged_this_frame = True
                drain_per_frame = (BLACKSMITH_DIVINE_GAUGE_DRAIN_PER_SEC / FPS) * get_blacksmith_construction_speed_multiplier()
                gauge_spent = False
                progress_gain = 0
                if special_gauge > 0:
                    construction_active = True
                    blacksmith_divine_partial_drain += drain_per_frame
                    drain_units = int(blacksmith_divine_partial_drain)
                    if drain_units > 0:
                        actual_drain = min(drain_units, special_gauge)
                        if actual_drain > 0:
                            special_gauge -= actual_drain
                            blacksmith_divine_partial_drain -= actual_drain
                            special_ready = special_gauge >= 350
                            gauge_spent = True
                            progress_gain = actual_drain
                if gauge_spent and progress_gain > 0:
                    blacksmith_divine_build_progress = min(
                        BLACKSMITH_DIVINE_BUILD_TIME,
                        blacksmith_divine_build_progress + progress_gain,
                    )
                    if frame_counter % 6 == 0:
                        smoke_x = blacksmith_divine_blueprint_rect.centerx + random.uniform(-6, 6)
                        smoke_y = blacksmith_divine_blueprint_rect.bottom - BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT + random.uniform(-6, 4)
                        effects_manager.spawn_construction_smoke(smoke_x, smoke_y, count=2)
                    if blacksmith_divine_build_progress >= BLACKSMITH_DIVINE_BUILD_TIME:
                        stone_width, stone_height = BLACKSMITH_DIVINE_STONE_SIZE
                        stone_rect = pygame.Rect(0, 0, stone_width, stone_height)
                        anchor_y = blacksmith_divine_blueprint_rect.bottom - BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT
                        stone_rect.midbottom = (blacksmith_divine_blueprint_rect.centerx, anchor_y)
                        blacksmith_divine_stone_state = {
                            "rect": stone_rect,
                            "hp": BLACKSMITH_DIVINE_STONE_MAX_HP,
                            "max_hp": BLACKSMITH_DIVINE_STONE_MAX_HP,
                            "pulse": 0,
                            "cooldown": 0,
                            "deploy_timer": 0,
                            "level": 1,
                            "xp": 0.0,
                            "xp_max": 400.0,
                            "reinforced": False,
                            # 디바인쉴드(강화디바인스톤 전용) 게이지/상태
                            "shield_xp": 0.0,
                            "shield_xp_max": float(BLACKSMITH_DIVINE_SHIELD_COST),
                            "shield_ready": False,
                            "shield_active": False,
                            "shield_timer": 0,
                            "shield_overheat": 0,
                            "shield_hits": 0,
                            "shield_ripple_effects": [],
                        }
                        stage_value = globals().get("current_stage")
                        if stage_value is not None:
                            blacksmith_divine_stage_owner = stage_value
                        divine_runtime.state = blacksmith_divine_stone_state
                        divine_runtime.blueprint_active = False
                        divine_runtime.blueprint_rect = None
                        divine_runtime.build_progress = 0
                        divine_runtime.partial_drain = 0.0
                        effects_manager.spawn_star_particles(stone_rect.centerx, stone_rect.centery, count=12)
                        effects_manager.spawn_construction_smoke(stone_rect.centerx, stone_rect.bottom - 10, count=6, spread=18)
                        
                        # 손상 효과 매니저에 디바인스톤 등록
                        damage_manager = get_damage_manager()
                        damage_manager.register_building("divine_stone", stone_rect, BLACKSMITH_DIVINE_STONE_MAX_HP)
                        try:
                            play_sound_with_volume(SOUND_STAGE6_BEAM_CHARGE)
                        except Exception:
                            pass
                        blacksmith_divine_blueprint_active = False
                        blacksmith_divine_blueprint_rect = None
                        blacksmith_divine_build_progress = 0
                        blacksmith_divine_partial_drain = 0.0
                        blacksmith_hammer_swing_active = False
                        blacksmith_hammer_swing_slow_timer = 0
                        blacksmith_hammer_slow_decay_step = 0
                        blacksmith_hammer_swing_phase = 0
                        push_blacksmith_state()
                else:
                    if frame_counter % 45 == 0:
                        print(
                            f"[DEBUG] Divine build paused (gauge={special_gauge}, partial={blacksmith_divine_partial_drain:.2f})"
                        )
        else:
            blacksmith_divine_partial_drain = 0.0
    elif not blacksmith_divine_blueprint_active:
        blacksmith_divine_partial_drain = 0.0

    # 강화 디바인스톤 업그레이드 (포탑과 동일하게 망치질로 강화)
    if (
        blacksmith_divine_stone_state is not None
        and down_pressed
        and not blacksmith_divine_stone_state.get("reinforced", False)
    ):
        stone_rect = blacksmith_divine_stone_state.get("rect")
        if stone_rect is not None:
            distance = abs(PLAYER.centerx - stone_rect.centerx)
            if distance <= BLACKSMITH_DIVINE_BUILD_RADIUS:
                if not blacksmith_hammer_swing_active:
                    blacksmith_hammer_swing_phase = 0
                blacksmith_hammer_swing_slow_timer = 0
                blacksmith_hammer_slow_decay_step = 0
                blacksmith_hammer_swing_active = True
                # 포탑 강화와 동일하게 망치질 애니메이션 진행
                hammer_increment = 1
                if frame_counter % 2 == 0:
                    hammer_increment = 2
                blacksmith_hammer_swing_phase = (
                    blacksmith_hammer_swing_phase + hammer_increment
                ) % max(1, BLACKSMITH_HAMMER_SWING_DURATION)
                hammer_engaged_this_frame = True

                # 강화 디바인스톤 업그레이드 소요 시간을 약 11초로 맞춘다 (300 게이지 / 11초)
                drain_per_sec = 300.0 / 11.0
                drain_per_frame = (drain_per_sec / FPS) * get_blacksmith_construction_speed_multiplier()
                gained_xp = 0

                if special_gauge > 0:
                    construction_active = True
                    partial = float(blacksmith_divine_stone_state.get("reinforce_partial", 0.0))
                    partial += drain_per_frame
                    drain_units = int(partial)
                    if drain_units > 0:
                        actual_drain = min(drain_units, special_gauge)
                        if actual_drain > 0:
                            special_gauge -= actual_drain
                            partial -= actual_drain
                            special_ready = special_gauge >= 350
                            gained_xp = actual_drain
                    blacksmith_divine_stone_state["reinforce_partial"] = partial

                if gained_xp > 0:
                    current_xp = blacksmith_divine_stone_state.get("xp", 0.0) + gained_xp
                    xp_max = max(1.0, float(blacksmith_divine_stone_state.get("xp_max", 300.0)))
                    if current_xp >= xp_max:
                        # 강화 디바인스톤으로 업그레이드
                        blacksmith_divine_stone_state["xp"] = xp_max
                        blacksmith_divine_stone_state["reinforced"] = True
                        blacksmith_divine_stone_state["level"] = int(
                            blacksmith_divine_stone_state.get("level", 1)
                        ) + 1
                        try:
                            current_max_hp = int(
                                blacksmith_divine_stone_state.get("max_hp", BLACKSMITH_DIVINE_STONE_MAX_HP)
                            )
                        except Exception:
                            current_max_hp = BLACKSMITH_DIVINE_STONE_MAX_HP
                        new_max_hp = current_max_hp + 1
                        blacksmith_divine_stone_state["max_hp"] = new_max_hp
                        blacksmith_divine_stone_state["hp"] = new_max_hp

                        # 손상 이펙트 매니저에 재등록하여 체력 상태를 초기화
                        try:
                            damage_manager = get_damage_manager()
                            damage_manager.register_building("divine_stone", stone_rect, new_max_hp)
                        except Exception:
                            pass

                        # 강화 연출 효과
                        try:
                            effects_manager.spawn_star_particles(stone_rect.centerx, stone_rect.centery, count=14)
                            effects_manager.spawn_construction_smoke(
                                stone_rect.centerx,
                                stone_rect.bottom - 10,
                                count=8,
                                spread=20,
                            )
                            play_sound_with_volume(SOUND_STAGE6_BEAM_CHARGE)
                        except Exception:
                            pass

                        blacksmith_divine_stone_state["reinforce_partial"] = 0.0
                        print("[DEBUG] Divine stone reinforced (upgraded)")
                        push_blacksmith_state()
                    else:
                        blacksmith_divine_stone_state["xp"] = current_xp
                        if frame_counter % 45 == 0:
                            print(f"[DEBUG] Divine XP: {current_xp:.1f}/{xp_max:.1f}")
            else:
                # 범위 밖으로 벗어나면 부분 드레인만 리셋
                blacksmith_divine_stone_state["reinforce_partial"] = 0.0

    # 강화디바인스톤 전용 디바인쉴드 차지(↓ 키/마우스 우클릭 유지)
    if (
        blacksmith_divine_stone_state is not None
        and down_pressed
        and blacksmith_divine_stone_state.get("reinforced", False)
    ):
        divine_state = blacksmith_divine_stone_state
        stone_rect = divine_state.get("rect")
        if stone_rect is not None:
            # 과부하 상태에서는 디바인쉴드 게이지를 채울 수 없다.
            shield_overheat = int(divine_state.get("shield_overheat", 0))
            shield_active = bool(divine_state.get("shield_active", False))
            if shield_overheat <= 0 and not shield_active:
                distance = abs(PLAYER.centerx - stone_rect.centerx)
                vertical_front_overlap = PLAYER.bottom >= (stone_rect.top - 12)
                standing_in_front = PLAYER.centerx <= stone_rect.centerx
                engaged_for_shield = (
                    distance <= BLACKSMITH_DIVINE_BUILD_RADIUS
                    and vertical_front_overlap
                    and standing_in_front
                )
                if engaged_for_shield:
                    if not blacksmith_hammer_swing_active:
                        blacksmith_hammer_swing_phase = 0
                    blacksmith_hammer_swing_slow_timer = 0
                    blacksmith_hammer_slow_decay_step = 0
                    blacksmith_hammer_swing_active = True
                    hammer_increment = 1
                    if frame_counter % 2 == 0:
                        hammer_increment = 2
                    blacksmith_hammer_swing_phase = (
                        blacksmith_hammer_swing_phase + hammer_increment
                    ) % max(1, BLACKSMITH_HAMMER_SWING_DURATION)
                    hammer_engaged_this_frame = True

                    drain_per_sec = BLACKSMITH_DIVINE_SHIELD_GAUGE_DRAIN_PER_SEC
                    drain_per_frame = (drain_per_sec / FPS) * get_blacksmith_construction_speed_multiplier()
                    gained_xp = 0

                    if special_gauge > 0:
                        construction_active = True
                        partial = float(divine_state.get("shield_partial", 0.0))
                        partial += drain_per_frame
                        drain_units = int(partial)
                        if drain_units > 0:
                            actual_drain = min(drain_units, special_gauge)
                            if actual_drain > 0:
                                special_gauge -= actual_drain
                                partial -= actual_drain
                                special_ready = special_gauge >= 350
                                gained_xp = actual_drain
                        divine_state["shield_partial"] = partial

                    if gained_xp > 0:
                        shield_xp = float(divine_state.get("shield_xp", 0.0)) + gained_xp
                        shield_xp_max = max(
                            1.0, float(divine_state.get("shield_xp_max", float(BLACKSMITH_DIVINE_SHIELD_COST)))
                        )
                        if shield_xp >= shield_xp_max:
                            divine_state["shield_xp"] = shield_xp_max
                            divine_state["shield_ready"] = True
                            divine_state["shield_partial"] = 0.0
                            print("[DEBUG] Divine shield ready")
                        else:
                            divine_state["shield_xp"] = shield_xp
                            if frame_counter % 45 == 0:
                                print(
                                    f"[DEBUG] Divine shield XP: {shield_xp:.1f}/{shield_xp_max:.1f}"
                                )

    if blacksmith_turret_active and blacksmith_turret_state:
        turret_rect = blacksmith_turret_state.get("rect")
        turret_level = int(blacksmith_turret_state.get("level", BLACKSMITH_TURRET_BASE_LEVEL))
        xp_max = max(1.0, blacksmith_turret_state.get("xp_max", float(BLACKSMITH_TURRET_XP_REQUIRED)))
        overheat_timer = int(blacksmith_turret_state.get("overheat_timer", 0))
        if blacksmith_turret_state.get("overdrive_active"):
            blacksmith_turret_xp_partial_drain = 0.0
        elif overheat_timer > 0:
            blacksmith_turret_xp_partial_drain = 0.0
        elif down_pressed and turret_rect is not None:
            distance = abs(PLAYER.centerx - turret_rect.centerx)
            engaged_for_charge = distance <= BLACKSMITH_TURRET_BUILD_RADIUS
            if engaged_for_charge:
                if not blacksmith_hammer_swing_active:
                    blacksmith_hammer_swing_phase = 0
                blacksmith_hammer_swing_slow_timer = 0
                blacksmith_hammer_slow_decay_step = 0
                blacksmith_hammer_swing_active = True
                blacksmith_hammer_swing_phase = (
                    blacksmith_hammer_swing_phase + 1
                ) % max(1, BLACKSMITH_HAMMER_SWING_DURATION)
                hammer_engaged_this_frame = True
                # 레벨 1: 강화 포탑으로 업그레이드하기 위한 게이지(250pt, 약 10초)
                # 레벨 2 이상: 오버드라이브 게이지 충전(300pt, 약 3초)
                if turret_level < BLACKSMITH_TURRET_MAX_LEVEL:
                    drain_per_sec = BLACKSMITH_TURRET_REINFORCE_GAUGE_DRAIN_PER_SEC
                else:
                    drain_per_sec = BLACKSMITH_TURRET_OVERDRIVE_GAUGE_DRAIN_PER_SEC
                drain_per_frame = (drain_per_sec / FPS) * get_blacksmith_turret_charge_speed_multiplier()
                gained_xp = 0
                if special_gauge > 0:
                    construction_active = True
                    blacksmith_turret_xp_partial_drain += drain_per_frame
                    drain_units = int(blacksmith_turret_xp_partial_drain)
                    if drain_units > 0:
                        actual_drain = min(drain_units, special_gauge)
                        if actual_drain > 0:
                            special_gauge -= actual_drain
                            blacksmith_turret_xp_partial_drain -= actual_drain
                            special_ready = special_gauge >= 350
                            gained_xp = actual_drain
                if gained_xp > 0:
                    current_xp = blacksmith_turret_state.get("xp", 0.0) + gained_xp
                    if current_xp >= xp_max:
                        if turret_level < BLACKSMITH_TURRET_MAX_LEVEL:
                            # 강화 포탑(레벨 2)으로 업그레이드
                            new_level = min(BLACKSMITH_TURRET_MAX_LEVEL, turret_level + 1)
                            blacksmith_turret_state["level"] = new_level
                            # 포탑 최대 체력 +1 및 전부 회복
                            try:
                                current_max_hp = int(
                                    blacksmith_turret_state.get("max_hp", BLACKSMITH_TURRET_BASE_HP)
                                )
                            except Exception:
                                current_max_hp = BLACKSMITH_TURRET_BASE_HP
                            new_max_hp = current_max_hp + 1
                            blacksmith_turret_state["max_hp"] = new_max_hp
                            blacksmith_turret_state["hp"] = new_max_hp
                            try:
                                rect = blacksmith_turret_state.get("rect")
                                if rect is not None:
                                    damage_manager = get_damage_manager()
                                    damage_manager.register_building("turret", rect, new_max_hp)
                            except Exception:
                                pass
                            # 강화 포탑은 자동 발사 주기를 4초로 단축
                            if new_level >= BLACKSMITH_TURRET_MAX_LEVEL:
                                new_interval = BLACKSMITH_TURRET_FIRE_INTERVAL_LVL2
                                blacksmith_turret_state["base_fire_interval"] = new_interval
                                blacksmith_turret_state["fire_interval"] = new_interval
                                blacksmith_turret_state["fire_timer"] = min(
                                    blacksmith_turret_state.get("fire_timer", new_interval),
                                    new_interval,
                                )
                            # 업그레이드 후에는 오버드라이브용 게이지로 전환
                            blacksmith_turret_state["xp_max"] = float(BLACKSMITH_TURRET_XP_REQUIRED)
                            blacksmith_turret_state["xp"] = 0.0
                            blacksmith_turret_xp_partial_drain = 0.0
                            try:
                                rect = blacksmith_turret_state.get("rect")
                                if rect is not None:
                                    effects_manager.spawn_star_particles(rect.centerx, rect.centery, count=14)
                                    effects_manager.spawn_flame_particles(rect.centerx, rect.top - 8, count=10)
                            except Exception:
                                pass
                            try:
                                play_sound_with_volume(SOUND_STAGE6_BEAM_CHARGE)
                            except Exception:
                                pass
                            print(f"[DEBUG] Turret upgraded to level {new_level} (reinforced)")
                            push_blacksmith_state()
                        else:
                            # 포탑 드라이브 준비완료. 자동 발동하지 않고 SPACE 입력을 기다린다.
                            blacksmith_turret_state["xp"] = xp_max
                            blacksmith_turret_state["overdrive_ready"] = True
                            # UI 힌트: 잠시 점화 이펙트 강조 및 디바인 힌트 유지
                            try:
                                turret_runtime.overdrive_ui_timer = BLACKSMITH_TURRET_OVERDRIVE_UI_DURATION
                                turret_runtime.overdrive_ui_divine = is_blacksmith_divine_stone_active()
                            except Exception:
                                pass
                            push_blacksmith_state()
                            blacksmith_turret_xp_partial_drain = 0.0
                    else:
                        blacksmith_turret_state["xp"] = current_xp
                        if frame_counter % 45 == 0:
                            print(f"[DEBUG] Turret XP: {current_xp:.1f}/{xp_max:.1f}")
                if gained_xp > 0:
                    construction_active = True
            else:
                blacksmith_turret_xp_partial_drain = 0.0
        else:
            blacksmith_turret_xp_partial_drain = 0.0
    else:
        blacksmith_turret_xp_partial_drain = 0.0

    if blacksmith_manual_hammer_timer > 0:
        if not hammer_engaged_this_frame:
            if not blacksmith_hammer_swing_active:
                blacksmith_hammer_swing_phase = 0
            blacksmith_hammer_swing_active = True
            if BLACKSMITH_HAMMER_SWING_DURATION > 0:
                increment = blacksmith_manual_hammer_increment
                if increment <= 0:
                    increment = 1
                blacksmith_hammer_swing_phase = min(
                    BLACKSMITH_HAMMER_SWING_DURATION,
                    blacksmith_hammer_swing_phase + increment,
                )
        blacksmith_manual_hammer_timer = max(0, blacksmith_manual_hammer_timer - 1)
        if blacksmith_manual_hammer_timer == 0:
            blacksmith_manual_hammer_increment = 1
        hammer_engaged_this_frame = True

    if not hammer_engaged_this_frame and blacksmith_hammer_swing_active:
        if blacksmith_hammer_swing_slow_timer > 0:
            cycle = blacksmith_hammer_slow_decay_step % 3
            decay = 1 if cycle < 2 else 2
            blacksmith_hammer_slow_decay_step += 1
        else:
            decay = BLACKSMITH_HAMMER_SWING_DECAY_NORMAL
        if blacksmith_hammer_swing_phase > 0:
            blacksmith_hammer_swing_phase = max(0, blacksmith_hammer_swing_phase - decay)
        if blacksmith_hammer_swing_slow_timer > 0:
            blacksmith_hammer_swing_slow_timer = max(0, blacksmith_hammer_swing_slow_timer - 1)
        if blacksmith_hammer_swing_phase <= 0:
            blacksmith_hammer_swing_active = False
            blacksmith_hammer_swing_slow_timer = 0
            blacksmith_hammer_slow_decay_step = 0

    if construction_active:
        # 포탑/디바인스톤/벽돌 등 어떤 건설 작업이든
        # 실제 게이지가 소모되는 프레임에서는 동일한 건설 사운드를 재생한다.
        start_blacksmith_construction_sound()
    else:
        # 건설 중이지만 잠시 멈춘 상태(게이지 소모 없음)에서는 사운드를 일시정지만 하고,
        # 더 이상 어떤 건설/강화도 진행 중이 아니면 완전히 정지한다.
        turret_xp_pending = (
            blacksmith_turret_active
            and blacksmith_turret_state
            and not blacksmith_turret_state.get("overdrive_active")
            and blacksmith_turret_state.get("xp", 0.0)
            < blacksmith_turret_state.get("xp_max", float(BLACKSMITH_TURRET_XP_REQUIRED))
        )
        divine_xp_pending = (
            blacksmith_divine_stone_state is not None
            and not blacksmith_divine_stone_state.get("reinforced", False)
            and blacksmith_divine_stone_state.get("xp", 0.0)
            < float(blacksmith_divine_stone_state.get("xp_max", 300.0))
        )
        if blacksmith_turret_blueprint_active or blacksmith_divine_blueprint_active or turret_xp_pending or divine_xp_pending:
            pause_blacksmith_construction_sound()
        else:
            stop_blacksmith_construction_sound()

    sync_blacksmith_state()
    return down_just_pressed


def _vec_to_int_pair(vec: pygame.math.Vector2 | tuple[float, float]) -> tuple[int, int]:
    if isinstance(vec, pygame.math.Vector2):
        return (int(round(vec.x)), int(round(vec.y)))
    return (int(round(vec[0])), int(round(vec[1])))


