def _create_blacksmith_build_icon(label: str, base_color: tuple[int, int, int], glyph_surface: pygame.Surface | None = None) -> pygame.Surface:
    icon = pygame.Surface(BLACKSMITH_BUILD_ICON_SIZE, pygame.SRCALPHA)
    w, h = BLACKSMITH_BUILD_ICON_SIZE
    pygame.draw.rect(icon, (30, 30, 40, 220), (0, 0, w, h), border_radius=8)
    pygame.draw.rect(icon, (*base_color, 70), (2, 2, w - 4, h - 4), border_radius=6)
    pygame.draw.rect(icon, (*base_color, 160), (4, 4, w - 8, h - 8), width=2, border_radius=6)
    if glyph_surface is not None:
        glyph_rect = glyph_surface.get_rect(center=(w // 2, h // 2))
        icon.blit(glyph_surface, glyph_rect)
    else:
        font = FontStyle.tiny()
        text = font.render(label, True, (245, 245, 255))
        icon.blit(text, text.get_rect(center=(w // 2, h // 2)))
    return icon

def _create_divine_stone_icon() -> pygame.Surface:
    icon = pygame.Surface(BLACKSMITH_BUILD_ICON_SIZE, pygame.SRCALPHA)
    w, h = BLACKSMITH_BUILD_ICON_SIZE
    cx, cy = w // 2, h // 2 + 4
    base_rect = pygame.Rect(cx - 16, cy + 6, 32, 10)
    pygame.draw.ellipse(icon, (55, 45, 35, 230), base_rect)
    pygame.draw.ellipse(icon, (120, 100, 70, 200), base_rect.inflate(-6, -2))

    stone_surface = pygame.Surface((26, 34), pygame.SRCALPHA)
    pygame.draw.polygon(
        stone_surface,
        (210, 220, 240),
        [
            (13, 2),
            (22, 10),
            (20, 26),
            (13, 32),
            (6, 26),
            (4, 10),
        ],
    )
    pygame.draw.polygon(
        stone_surface,
        (120, 180, 255),
        [
            (13, 6),
            (18, 12),
            (16, 24),
            (13, 28),
            (10, 24),
            (8, 12),
        ],
    )
    pygame.draw.polygon(
        stone_surface,
        (255, 255, 255),
        [(13, 8), (16, 14), (13, 20), (10, 14)],
        width=2,
    )
    icon.blit(stone_surface, stone_surface.get_rect(center=(cx, cy - 6)))

    glow_surface = pygame.Surface((w, h), pygame.SRCALPHA)
    pygame.draw.circle(glow_surface, (90, 180, 255, 80), (cx, cy - 12), 20)
    icon.blit(glow_surface, (0, 0))

    font = FontStyle.tiny()
    label = font.render("2", True, (255, 255, 255))
    icon.blit(label, label.get_rect(center=(cx, cy - 22)))
    return icon

def _create_turret_icon() -> pygame.Surface:
    icon = pygame.Surface(BLACKSMITH_BUILD_ICON_SIZE, pygame.SRCALPHA)
    cx, cy = BLACKSMITH_BUILD_ICON_SIZE[0] // 2, BLACKSMITH_BUILD_ICON_SIZE[1] // 2 + 4
    pygame.draw.rect(icon, (70, 55, 35), (cx - 12, cy + 4, 24, 8), border_radius=4)
    pygame.draw.rect(icon, (130, 120, 110), (cx - 10, cy - 14, 20, 24), border_radius=6)
    pygame.draw.rect(icon, (90, 80, 70), (cx - 6, cy - 10, 12, 16), border_radius=4)
    pygame.draw.line(icon, (210, 180, 90), (cx, cy - 20), (cx, cy - 36), 5)
    pygame.draw.circle(icon, (235, 205, 120), (cx, cy - 36), 6)
    font = FontStyle.tiny()
    label = font.render("1", True, (255, 255, 255))
    icon.blit(label, label.get_rect(center=(cx, cy - 24)))
    return icon

def _blacksmith_get_buildable_options(*, state=None) -> list[str]:
    """현재 건설 가능한 발토르 건물 옵션 목록을 계산한다."""

    if state is None:
        sync_blacksmith_state()
        state = BLACKSMITH_CONTROLLER.state

    options: list[str] = []
    turret = state.turret
    divine = state.divine

    if not turret.active and not turret.blueprint_active:
        options.append("turret")
    if divine.state is None and not divine.blueprint_active:
        options.append("divine_stone")

    return options


def blacksmith_has_available_buildings() -> bool:
    if selected_character_type != "blacksmith":
        return False
    if blacksmith_hammer_shock_charging or not blacksmith_hammer_available:
        return False

    sync_blacksmith_state()
    state = BLACKSMITH_CONTROLLER.state

    return bool(_blacksmith_get_buildable_options(state=state))


def blacksmith_open_build_menu():
    if not blacksmith_has_available_buildings():
        return
    if 'PLAYER' not in globals() or PLAYER is None:
        return
    sync_blacksmith_state()
    state = BLACKSMITH_CONTROLLER.state
    state.build_menu_active = True
    state.down_hold_frames = 0
    push_blacksmith_state()


def blacksmith_close_build_menu():
    sync_blacksmith_state()
    state = BLACKSMITH_CONTROLLER.state
    state.build_menu_active = False
    state.down_hold_frames = 0
    push_blacksmith_state()


def blacksmith_can_build(option: str) -> bool:
    sync_blacksmith_state()
    state = BLACKSMITH_CONTROLLER.state
    turret = state.turret
    divine = state.divine

    if option == "turret":
        return not turret.active and not turret.blueprint_active
    if option == "divine_stone":
        return divine.state is None and not divine.blueprint_active
    return False


def blacksmith_start_divine_stone():
    if 'PLAYER' not in globals() or PLAYER is None:
        return False

    sync_blacksmith_state()
    state = BLACKSMITH_CONTROLLER.state
    divine = state.divine

    if divine.state is not None or divine.blueprint_active:
        return False

    global blacksmith_divine_stage_owner
    stage_value = globals().get("current_stage")
    if stage_value is not None:
        blacksmith_divine_stage_owner = stage_value

    blueprint_width = BLACKSMITH_DIVINE_STONE_SIZE[0]
    blueprint_height = BLACKSMITH_DIVINE_STONE_SIZE[1] + BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT
    rect = pygame.Rect(0, 0, blueprint_width, blueprint_height)
    base_x = max(blueprint_width // 2, min(WIDTH - blueprint_width // 2, PLAYER.centerx))
    base_y = HEIGHT - 5
    rect.midbottom = (base_x, base_y)
    rect = _resolve_blacksmith_blueprint_position(rect)
    divine.blueprint_rect = rect
    divine.build_progress = 0
    divine.partial_drain = 0.0
    divine.blueprint_active = True
    try:
        play_sound_with_volume(SOUND_ITEM_GET)
    except Exception:
        pass
    effects_manager.spawn_construction_smoke(rect.centerx, rect.bottom - 12, count=6, spread=24)
    push_blacksmith_state()
    return True


def blacksmith_select_build_option(option: str):
    global blacksmith_build_menu_active
    if selected_character_type != "blacksmith":
        return
    if option not in BLACKSMITH_BUILD_OPTIONS:
        return
    if not blacksmith_can_build(option):
        return
    blacksmith_close_build_menu()
    if option == "turret":
        handle_blacksmith_turret_input(False, True, True)
    elif option == "divine_stone":
        blacksmith_start_divine_stone()

