def _is_divine_state_active(state: dict[str, object] | None) -> bool:
    """디바인스톤 상태 객체가 실제로 필드에 존재하는지 판정한다."""

    if not state:
        return False

    if state.get("hp", 0) <= 0:
        return False

    rect = state.get("rect")
    return rect is not None and getattr(rect, "width", 0) > 0 and getattr(rect, "height", 0) > 0


def is_blacksmith_divine_stone_active() -> bool:
    """디바인스톤이 건설되어 필드에 남아있는지 여부를 반환한다."""

    owner_stage = globals().get("blacksmith_divine_stage_owner")
    current_stage_value = globals().get("current_stage")
    if owner_stage is not None and current_stage_value is not None and owner_stage != current_stage_value:
        return False

    if _is_divine_state_active(globals().get("blacksmith_divine_stone_state")):
        return True

    controller = globals().get("BLACKSMITH_CONTROLLER")
    if controller is None:
        return False

    try:
        runtime_state = controller.state.divine.state
    except AttributeError:
        return False

    return _is_divine_state_active(runtime_state)


def get_blacksmith_umbrella_recover_interval_frames() -> int:
    """현재 상황에 맞는 토르쉴드 게이지 회복 간격(프레임)을 계산한다."""

    if is_blacksmith_divine_stone_active():
        # 강화 여부까지 확인하여 단계별 회복 주기 적용
        try:
            state = globals().get("blacksmith_divine_stone_state")
            if not _is_divine_state_active(state):
                controller = globals().get("BLACKSMITH_CONTROLLER")
                try:
                    state = controller.state.divine.state if controller is not None else None
                except AttributeError:
                    state = None
            reinforced = bool(state and state.get("reinforced", False))
        except Exception:
            reinforced = False

        if reinforced:
            return BLACKSMITH_UMBRELLA_RECOVER_INTERVAL_REINFORCED_FRAMES
        return BLACKSMITH_UMBRELLA_RECOVER_INTERVAL_DIVINE_FRAMES
    return BLACKSMITH_UMBRELLA_RECOVER_INTERVAL_BASE_FRAMES


def get_blacksmith_umbrella_gauge_gain() -> int:
    """현재 토르쉴드 패들 충돌 시 기본 게이지 획득량을 반환한다."""

    global blacksmith_blocking_penalty_timer

    if is_blacksmith_divine_stone_active():
        # 디바인스톤이 활성화된 경우, 강화 여부에 따라 게이지 획득량을 달리 적용한다.
        try:
            state = globals().get("blacksmith_divine_stone_state")
            # 전역 상태가 비어 있으면 컨트롤러 런타임 상태를 참조
            if not _is_divine_state_active(state):
                controller = globals().get("BLACKSMITH_CONTROLLER")
                try:
                    state = controller.state.divine.state if controller is not None else None
                except AttributeError:
                    state = None
            reinforced = bool(state and state.get("reinforced", False))
        except Exception:
            reinforced = False

        if reinforced:
            base_gain = BLACKSMITH_UMBRELLA_GAUGE_GAIN_WITH_REINFORCED_DIVINE
        else:
            base_gain = BLACKSMITH_UMBRELLA_GAUGE_GAIN_WITH_DIVINE
    else:
        base_gain = BLACKSMITH_UMBRELLA_GAUGE_GAIN_BASE

    if blacksmith_blocking_penalty_timer > 0:
        reduced_gain = int(round(base_gain * (1.0 - BLACKSMITH_BLOCKING_PENALTY_RATIO)))
        print(
            f"[DEBUG BLOCKING] penalty active timer={blacksmith_blocking_penalty_timer} base={base_gain} reduced={reduced_gain}"
        )
        return max(1, reduced_gain)

    if base_gain != BLACKSMITH_UMBRELLA_GAUGE_GAIN_BASE:
        print(f"[DEBUG BLOCKING] no penalty base={base_gain}")

    return base_gain


# === 강화디바인스톤 토르쉴드 검기 발사체 설정 ===
BLACKSMITH_DIVINE_SLASH_SPEED = 15.0
BLACKSMITH_DIVINE_SLASH_LIFETIME_FRAMES = int(1.6 * FPS)
BLACKSMITH_DIVINE_SLASH_RADIUS = 14
BLACKSMITH_DIVINE_SLASH_WALL_MARGIN = 8
BLACKSMITH_DIVINE_SLASH_MIN_ANGLE_DEG = 35.0
BLACKSMITH_DIVINE_SLASH_MAX_ANGLE_DEG = 50.0
BLACKSMITH_DIVINE_SLASH_GAUGE_COST = 30  # 강화디바인스톤 검기 발사 시 소모 게이지
blacksmith_divine_slash_projectiles: list[dict[str, object]] = []
BLACKSMITH_DIVINE_SLASH_DELAY_MS = int(0.4 * 1000)
blacksmith_divine_slash_scheduled: dict[str, object] | None = None


def _spawn_blacksmith_divine_slash_from_shield(swing_direction: int) -> None:
    """강화디바인스톤이 있을 때 토르쉴드 스윙으로 검기 발사체를 생성한다."""

    global blacksmith_divine_slash_projectiles
    global paddle_scale_ratio
    global blacksmith_umbrella_body_offset, blacksmith_umbrella_hitbox_center_offset
    global blacksmith_umbrella_open

    if swing_direction == 0:
        return

    # 디바인스톤이 실제 필드에 존재하고 강화된 상태인지 확인
    state = globals().get("blacksmith_divine_stone_state")
    if not _is_divine_state_active(state):
        return
    if not bool(state.get("reinforced", False)):
        return
    # 디바인쉴드 과부하 상태에서는 검기를 발사하지 않는다.
    try:
        if int(state.get("shield_overheat", 0)) > 0:
            return
    except Exception:
        pass

    # 강화디바인스톤이 필드에 있고 발토르가 플레이 중일 때
    # 게이지가 40 미만이면 검기를 발사하지 않는다.
    try:
        if globals().get("selected_character_type") == "blacksmith":
            current_gauge = float(globals().get("special_gauge", 0))
            if current_gauge < BLACKSMITH_DIVINE_SLASH_GAUGE_COST:
                return
    except Exception:
        # 테스트나 초기화 단계에서 게이지가 없을 수 있으므로 조용히 무시
        pass

    if "PLAYER" not in globals() or PLAYER is None:
        return

    # 발사체 수를 제한해 과도한 스팸을 방지
    if len(blacksmith_divine_slash_projectiles) >= 6:
        return

    try:
        angle_deg = random.uniform(
            BLACKSMITH_DIVINE_SLASH_MIN_ANGLE_DEG,
            BLACKSMITH_DIVINE_SLASH_MAX_ANGLE_DEG,
        )
    except Exception:
        angle_deg = (BLACKSMITH_DIVINE_SLASH_MIN_ANGLE_DEG + BLACKSMITH_DIVINE_SLASH_MAX_ANGLE_DEG) * 0.5

    angle_rad = math.radians(angle_deg)
    speed = BLACKSMITH_DIVINE_SLASH_SPEED

    # swing_direction: +1 = 왼쪽 스윙, -1 = 오른쪽 스윙
    # → 입력 방향과 동일하게 발사되도록 매핑
    #    (왼쪽 스윙(+1) → 왼쪽으로, 오른쪽 스윙(-1) → 오른쪽으로)
    dir_sign = -1 if swing_direction > 0 else 1
    vx = dir_sign * speed * math.sin(angle_rad)
    vy = -speed * math.cos(angle_rad)  # 항상 위쪽(y 축 음수)으로 진행

    # 토르쉴드 방패의 중앙 근처에서 발사
    scale_applied = paddle_scale_ratio if paddle_scale_ratio > 0 else 1.0
    origin_x = float(PLAYER.centerx)
    origin_y = float(PLAYER.centery)
    try:
        if blacksmith_umbrella_open:
            body_offset_x, body_offset_y = blacksmith_umbrella_body_offset
            center_off_x, center_off_y = blacksmith_umbrella_hitbox_center_offset
            origin_x += int(round(body_offset_x * scale_applied))
            origin_x += int(round(center_off_x * scale_applied))
            origin_y += int(round(center_off_y * scale_applied))
            # 방패 중심이 패들보다 약간 위에 있으므로 소폭 위로 보정
            origin_y -= 10
    except Exception:
        origin_y -= 40

    projectile: dict[str, object] = {
        "x": origin_x,
        "y": origin_y,
        "vx": vx,
        "vy": vy,
        "life": int(BLACKSMITH_DIVINE_SLASH_LIFETIME_FRAMES),
        "bounced": False,
        "boss_hit": False,
        "trail": [],  # 궤적 저장용 리스트
        "swing_dir": swing_direction,  # 스윙 방향 저장
        "ball_gauge_given": False,  # 공 타격 시 게이지 보상 1회 제한
    }
    blacksmith_divine_slash_projectiles.append(projectile)

    # 발토르가 플레이 중이고 검기가 실제로 발사될 때 게이지 40 소모
    if globals().get("selected_character_type") == "blacksmith":
        try:
            consume_special_gauge(BLACKSMITH_DIVINE_SLASH_GAUGE_COST)
        except Exception:
            # 튜토리얼/테스트 등 게이지 시스템이 초기화되지 않은 경우에도 검기 발사는 유지
            pass

    # 검기 시작 이펙트
    try:
        effects_manager.spawn_star_particles(int(origin_x), int(origin_y), count=6)
    except Exception:
        pass


