blacksmith_turret_boss_hit_count = 0  # 체력형 보스 추가 피해 누적 카운터

BLACKSMITH_TURRET_ICON = _create_turret_icon()
BLACKSMITH_DIVINE_ICON = _create_divine_stone_icon()
BLACKSMITH_CARD_IMG = _crop_surface_alpha(BLACKSMITH_PADDLE_IMG)


def _genie_preview_blit_scaled(surface: pygame.Surface, source: pygame.Surface, dest_rect: pygame.Rect) -> bool:
    if source is None:
        return False
    src_w, src_h = source.get_size()
    if src_w <= 0 or src_h <= 0 or dest_rect.width <= 0 or dest_rect.height <= 0:
        return False

    scale = min(dest_rect.width / src_w, dest_rect.height / src_h)
    if scale <= 0:
        return False

    new_size = (max(1, int(src_w * scale)), max(1, int(src_h * scale)))
    if new_size != source.get_size():
        scaled = pygame.transform.smoothscale(source, new_size)
    else:
        scaled = source

    blit_rect = scaled.get_rect(center=dest_rect.center)
    surface.blit(scaled, blit_rect)
    return True


def _render_thor_shield_preview(surface: pygame.Surface, rect: pygame.Rect) -> bool:
    overlay = pygame.Surface(rect.size, pygame.SRCALPHA)
    scale = 0.10
    pivot_x = rect.width * 0.26
    pivot_y = rect.height * 0.52
    base_dx = rect.width * 0.4
    base_dy = -rect.height * 0.05

    cycle_ms = 6000
    phase = pygame.time.get_ticks() % cycle_ms
    max_angle = 42.0  # degrees

    if phase < 2000:
        swing_angle = 0.0
    elif phase < 3500:
        t = (phase - 2000) / 1500.0
        swing_angle = -max_angle * t
    elif phase < 5000:
        t = (phase - 3500) / 1500.0
        swing_angle = -max_angle + (2 * max_angle * t)
    else:
        t = (phase - 5000) / 1000.0
        swing_angle = max_angle * (1.0 - t)

    angle_rad = math.radians(swing_angle)
    cos_a = math.cos(angle_rad)
    sin_a = math.sin(angle_rad)
    swing_dx = base_dx * cos_a - base_dy * sin_a
    swing_dy = base_dx * sin_a + base_dy * cos_a

    pivot_point = (pivot_x, pivot_y)
    head_point = (pivot_x + swing_dx, pivot_y + swing_dy)
    _draw_blacksmith_umbrella_overlay(
        overlay,
        pivot_point,
        head_point,
        raise_amount=1.0 * scale,
        open_amount=1.0 * scale,
    )
    surface.blit(overlay, rect.topleft, special_flags=pygame.BLEND_PREMULTIPLIED)
    return True


def _render_blacksmith_build_preview(surface: pygame.Surface, rect: pygame.Rect) -> bool:
    if BLACKSMITH_TURRET_ICON is None or BLACKSMITH_DIVINE_ICON is None:
        return False

    icon_w, icon_h = BLACKSMITH_BUILD_ICON_SIZE
    spacing = 12
    available_width = rect.width - spacing
    if available_width <= 0:
        return False

    scale = min(
        available_width / (icon_w * 2),
        rect.height / icon_h if icon_h > 0 else 1.0,
    )
    scale = max(scale, 0.1)
    scaled_size = (max(1, int(icon_w * scale)), max(1, int(icon_h * scale)))

    turret_icon = pygame.transform.smoothscale(BLACKSMITH_TURRET_ICON, scaled_size)
    divine_icon = pygame.transform.smoothscale(BLACKSMITH_DIVINE_ICON, scaled_size)

    offset_x = (scaled_size[0] // 2) + int(spacing * 0.5)
    center = rect.center

    left_rect = turret_icon.get_rect(center=(center[0] - offset_x, center[1]))
    right_rect = divine_icon.get_rect(center=(center[0] + offset_x, center[1]))

    surface.blit(turret_icon, left_rect)
    surface.blit(divine_icon, right_rect)

    return True


def _render_blacksmith_hammer_preview(surface: pygame.Surface, rect: pygame.Rect) -> bool:
    hammer_surface = _get_blacksmith_thrown_hammer_surface()
    if hammer_surface is None:
        return False

    _genie_preview_blit_scaled(surface, hammer_surface, rect)

    overlay = pygame.Surface(rect.size, pygame.SRCALPHA)
    radius = int(min(rect.width, rect.height) * 0.45)
    pygame.draw.circle(
        overlay,
        (120, 200, 255, 110),
        (rect.width // 2, rect.height // 2),
        max(1, radius),
    )
    surface.blit(overlay, rect.topleft, special_flags=pygame.BLEND_ADD)
    return True


def _draw_genie_keycap(
    surface: pygame.Surface,
    center: tuple[int, int],
    label: str,
    *,
    width: int = 64,
    height: int = 44,
    active: bool = False,
) -> None:
    """지니 미리보기에 사용하는 키캡 장식."""

    rect = pygame.Rect(0, 0, width, height)
    rect.center = center

    base = (255, 228, 168) if active else (236, 240, 255)
    border = (255, 182, 110) if active else (132, 164, 226)
    inner = (255, 246, 224) if active else (248, 250, 255)

    pygame.draw.rect(surface, base, rect, border_radius=12)
    pygame.draw.rect(surface, inner, rect.inflate(-6, -6), border_radius=10)
    pygame.draw.rect(surface, border, rect, width=2, border_radius=12)

    font = FontStyle.body() if len(label) <= 2 else FontStyle.small()
    glyph = font.render(label, True, (28, 34, 54))
    surface.blit(glyph, glyph.get_rect(center=rect.center))


def _render_smasher_genie_preview(
    surface: pygame.Surface,
    rect: pygame.Rect,
    animation_id: str,
    ticks: int,
) -> bool:
    """스매셔 전용 지니 튜토리얼 미리보기."""

    preview = pygame.Surface(rect.size, pygame.SRCALPHA)
    width, height = rect.size
    center = (width // 2, height // 2)
    title_font = FontStyle.small()
    body_font = FontStyle.tiny()
    pulse = 0.3 + 0.2 * math.sin(ticks / 260.0)

    if animation_id == "smasher_drive":
        radius = int(min(width, height) * 0.28)
        ring = pygame.Surface((radius * 2 + 48, radius * 2 + 48), pygame.SRCALPHA)
        ring_center = (ring.get_width() // 2, ring.get_height() // 2)

        inner_radius = radius + int(12 * pulse)
        pygame.draw.circle(ring, (40, 210, 255, 60), ring_center, inner_radius + 6)
        pygame.draw.circle(ring, (40, 210, 255, 150), ring_center, radius, width=4)
        pygame.draw.circle(ring, (170, 120, 255, 140), ring_center, max(4, radius // 2), width=3)
        preview.blit(ring, ring.get_rect(center=center))

        headline = title_font.render("PERFECT TIMING", True, (224, 236, 255))
        preview.blit(headline, headline.get_rect(midtop=(center[0], center[1] - radius - 58)))

        gauge = body_font.render("게이지 160 이상", True, (214, 230, 255))
        preview.blit(gauge, gauge.get_rect(midtop=(center[0], center[1] + radius + 14)))

        _draw_genie_keycap(preview, (center[0] - radius - 46, center[1] + 2), "←", active=True)
        _draw_genie_keycap(preview, (center[0] + radius + 46, center[1] + 2), "→", active=True)
        _draw_genie_keycap(preview, (center[0], center[1] + radius + 62), "SPACE", width=122, active=True)

        ball = pygame.Surface((28, 28), pygame.SRCALPHA)
        pygame.draw.circle(ball, (255, 255, 200), (14, 14), 14)
        pygame.draw.circle(ball, (120, 255, 210), (14, 14), 12)
        pygame.draw.circle(ball, (255, 255, 255), (11, 11), 4)
        preview.blit(ball, ball.get_rect(center=center))

    elif animation_id == "smasher_power":
        bar_width = int(width * 0.68)
        bar_height = 28
        bar_rect = pygame.Rect(0, 0, bar_width, bar_height)
        bar_rect.center = (center[0], center[1] - 12)
        bar_rect.move_ip(int(width * 0.16) - bar_rect.left, 0)

        frame = bar_rect.inflate(28, 22)
        pygame.draw.rect(preview, (24, 36, 68, 190), frame, border_radius=18)
        pygame.draw.rect(preview, (120, 150, 210, 90), frame, width=2, border_radius=18)

        ratio = min(1.0, 350 / 500)
        filled = pygame.Rect(bar_rect.left, bar_rect.top, max(1, int(bar_rect.width * ratio)), bar_rect.height)
        gradient = pygame.Surface(filled.size, pygame.SRCALPHA)
        for x in range(filled.width):
            t = x / max(1, filled.width - 1)
            color = (
                int(255 * (0.6 + 0.4 * t)),
                int(120 + 90 * t),
                int(90 + 50 * (1 - t)),
                215,
            )
            pygame.draw.line(gradient, color, (x, 0), (x, filled.height))
        preview.blit(gradient, filled.topleft)
        pygame.draw.rect(preview, (255, 214, 168), bar_rect, width=2, border_radius=12)

        gauge = title_font.render("350 / 500 게이지", True, (236, 240, 255))
        preview.blit(gauge, gauge.get_rect(midtop=(center[0], bar_rect.bottom + 10)))

        _draw_genie_keycap(preview, (center[0], bar_rect.top - 54), "SPACE", width=122, active=True)
        _draw_genie_keycap(preview, (bar_rect.left - 50, bar_rect.centery + 60), "←")
        _draw_genie_keycap(preview, (center[0], bar_rect.centery + 60), "직선")
        _draw_genie_keycap(preview, (bar_rect.right + 50, bar_rect.centery + 60), "→")

        arrow_len = int(width * 0.18)
        for direction, offset in ((-1, -arrow_len), (0, 0), (1, arrow_len)):
            start = (center[0], center[1] + 18)
            end = (center[0] + offset, center[1] + (0 if direction else -38))
            pygame.draw.line(preview, (255, 205, 150), start, end, 4)
            if direction == 0:
                tip = [(end[0] - 12, end[1] - 6), (end[0] + 12, end[1] - 6), (end[0], end[1] - 18)]
            else:
                tip = [
                    (end[0], end[1] - 12),
                    (end[0] + 12 * (-direction), end[1] + 6),
                    (end[0], end[1] + 12),
                ]
            pygame.draw.polygon(preview, (255, 170, 110), tip)

    elif animation_id == "smasher_short":
        lane_top = int(height * 0.2)
        lane_bottom = int(height * 0.74)
        lane = pygame.Rect(center[0] - 3, lane_top, 6, lane_bottom - lane_top)
        pygame.draw.rect(preview, (90, 160, 255, 150), lane, border_radius=3)

        glow = pygame.Surface((42, 42), pygame.SRCALPHA)
        pygame.draw.circle(glow, (140, 220, 255, 120), (21, 21), int(17 + 6 * pulse))
        preview.blit(glow, glow.get_rect(center=(center[0], lane_top)))

        ball = pygame.Surface((28, 28), pygame.SRCALPHA)
        pygame.draw.circle(ball, (255, 240, 180), (14, 14), 14)
        pygame.draw.circle(ball, (255, 120, 120), (14, 14), 12)
        pygame.draw.circle(ball, (255, 255, 255), (10, 10), 4)
        offset = int(44 * (0.5 + 0.5 * math.sin(ticks / 300.0)))
        preview.blit(ball, ball.get_rect(center=(center[0], lane_bottom - offset)))

        status = title_font.render("쇼트 카운터 활성", True, (234, 240, 255))
        preview.blit(status, status.get_rect(midtop=(center[0], lane_bottom + 12)))

        _draw_genie_keycap(preview, (center[0], lane_bottom + 64), "↑", active=True)
        gauge = body_font.render("게이지 100", True, (214, 230, 255))
        preview.blit(gauge, gauge.get_rect(midtop=(center[0], lane_bottom + 100)))

    else:
        return False

    surface.blit(preview, rect.topleft)
    return True


def _render_blacksmith_turret_preview(surface: pygame.Surface, rect: pygame.Rect) -> bool:
    try:
        state_controller = BLACKSMITH_CONTROLLER.state
    except NameError:
        return False

    temp_surface = pygame.Surface(rect.size, pygame.SRCALPHA)

    scale = min(
        (rect.width / max(1, BLACKSMITH_TURRET_BASE_WIDTH)) * 0.3,
        (rect.height / max(1, BLACKSMITH_TURRET_BASE_HEIGHT)) * 0.3,
    )
    scale = max(scale, 0.15)

    turret_width = max(12, int(BLACKSMITH_TURRET_BASE_WIDTH * scale))
    turret_height = max(12, int(BLACKSMITH_TURRET_BASE_HEIGHT * scale))
    turret_rect = pygame.Rect(0, 0, turret_width, turret_height)
    turret_rect.center = (rect.width // 2, int(rect.height * 0.55))

    base_interval = BLACKSMITH_TURRET_FIRE_INTERVAL
    turret_state_preview = {
        "rect": turret_rect,
        "fire_timer": base_interval,
        "fire_interval": base_interval,
        "hp": BLACKSMITH_TURRET_BASE_HP,
        "max_hp": BLACKSMITH_TURRET_BASE_HP,
        "level": BLACKSMITH_TURRET_BASE_LEVEL,
        "xp": 0.0,
        "xp_max": float(BLACKSMITH_TURRET_XP_REQUIRED),
        "aim_angle": -math.pi / 2,
        "display_angle": -math.pi / 2,
        "recoil_timer": 0,
        "recoil_offset": 0.0,
        "base_fire_interval": base_interval,
        "overdrive_active": False,
        "overdrive_timer": 0,
        "overdrive_fire_window": 0,
        "overdrive_shots_remaining": 0,
        "overdrive_shot_cooldown": 0,
        "overdrive_glow_phase": 0.0,
        "overdrive_flash_timer": 0,
        "overdrive_recoil_boost": 1.0,
        "overdrive_speed_boost": 1.0,
        "overdrive_stun_multiplier": 1.0,
        "overdrive_knockback_multiplier": 1.0,
        "overdrive_divine_active": False,
        "overheat_timer": 0,
        "overheat_smoke_timer": 0,
        "display_angle_accel": 0.0,
        "homing_cooldown": 0,
        "homing_burst_timer": 0,
        "homing_burst_shots": 0,
    }

    fire_cycle_ms = 3000
    fire_phase = pygame.time.get_ticks() % fire_cycle_ms
    flash_duration = 220
    projectile_duration = 1200
    show_flash = fire_phase < flash_duration
    projectile_active = fire_phase < projectile_duration
    progress = min(1.0, fire_phase / projectile_duration) if projectile_active else 0.0
    flash_frames = max(1, int(0.15 * FPS))
    turret_state_preview["overdrive_flash_timer"] = flash_frames if show_flash else 0
    turret_state_preview["overdrive_glow_phase"] = pygame.time.get_ticks() / 240.0

    projectiles_preview: list[dict[str, object]] = []
    if projectile_active:
        scale_x = turret_rect.width / BLACKSMITH_TURRET_DESIGN_WIDTH
        scale_y = turret_rect.height / BLACKSMITH_TURRET_DESIGN_HEIGHT
        pivot_point = pygame.math.Vector2(
            turret_rect.centerx,
            turret_rect.top + BLACKSMITH_TURRET_HEAD_PIVOT_OFFSET * scale_y,
        )
        angle = turret_state_preview["display_angle"]
        forward_vec = pygame.math.Vector2(math.cos(angle), math.sin(angle))
        if forward_vec.length_squared() == 0:
            forward_vec = pygame.math.Vector2(0, -1)
        else:
            forward_vec = forward_vec.normalize()
        muzzle_distance = BLACKSMITH_TURRET_MUZZLE_LENGTH * scale_x
        muzzle_world = pivot_point + forward_vec * muzzle_distance
        travel_distance = muzzle_distance + rect.width * 0.9 * progress
        projectile_pos = muzzle_world + forward_vec * travel_distance
        muzzle_tip = muzzle_world + forward_vec * max(4, scale_x * 6)
        projectile_radius = max(3, int(8 * scale))
        missile_speed = 14.0
        projectiles_preview.append(
            {
                "x": float(projectile_pos.x),
                "y": float(projectile_pos.y),
                "vx": float(forward_vec.x * missile_speed),
                "vy": float(forward_vec.y * missile_speed),
                "radius": projectile_radius,
                "overdrive": False,
                "trail_timer": int(pygame.time.get_ticks() / 6),
            }
        )

    # 백업
    turret_backup = copy.deepcopy(state_controller.turret)
    divine_backup = copy.deepcopy(state_controller.divine)
    globals_backup_keys = [
        "blacksmith_turret_active",
        "blacksmith_turret_state",
        "blacksmith_turret_blueprint_active",
        "blacksmith_turret_blueprint_rect",
        "blacksmith_turret_projectiles",
        "blacksmith_turret_build_progress",
        "blacksmith_turret_partial_drain",
        "blacksmith_turret_xp_partial_drain",
        "blacksmith_turret_manual_cooldown",
        "blacksmith_turret_overdrive_ui_timer",
        "blacksmith_turret_overdrive_ui_divine",
        "blacksmith_turret_overheat_timer",
        "blacksmith_turret_overheat_smoke_timer",
        "blacksmith_divine_blueprint_active",
        "blacksmith_divine_blueprint_rect",
        "blacksmith_divine_build_progress",
        "blacksmith_divine_partial_drain",
        "blacksmith_divine_stone_state",
    ]
    globals_backup = {k: copy.deepcopy(globals().get(k)) for k in globals_backup_keys}

    try:
        # 프리뷰용 전역/상태 설정
        globals()["blacksmith_turret_active"] = True
        globals()["blacksmith_turret_state"] = turret_state_preview
        globals()["blacksmith_turret_blueprint_active"] = False
        globals()["blacksmith_turret_blueprint_rect"] = None
        globals()["blacksmith_turret_projectiles"] = projectiles_preview
        globals()["blacksmith_turret_build_progress"] = 0
        globals()["blacksmith_turret_partial_drain"] = 0.0
        globals()["blacksmith_turret_xp_partial_drain"] = 0.0
        globals()["blacksmith_turret_manual_cooldown"] = 0
        globals()["blacksmith_turret_overdrive_ui_timer"] = 0
        globals()["blacksmith_turret_overdrive_ui_divine"] = False
        globals()["blacksmith_turret_overheat_timer"] = 0
        globals()["blacksmith_turret_overheat_smoke_timer"] = 0
        globals()["blacksmith_divine_blueprint_active"] = False
        globals()["blacksmith_divine_blueprint_rect"] = None
        globals()["blacksmith_divine_build_progress"] = 0
        globals()["blacksmith_divine_partial_drain"] = 0.0
        globals()["blacksmith_divine_stone_state"] = None

        state_controller.turret.active = True
        state_controller.turret.blueprint_active = False
        state_controller.turret.blueprint_rect = None
        state_controller.turret.build_progress = 0
        state_controller.turret.state = turret_state_preview
        state_controller.turret.projectiles = projectiles_preview
        state_controller.turret.partial_drain = 0.0
        state_controller.turret.xp_partial_drain = 0.0
        state_controller.turret.manual_cooldown = 0
        state_controller.turret.overdrive_ui_timer = 0
        state_controller.turret.overdrive_ui_divine = False
        state_controller.turret.overheat_timer = 0
        state_controller.turret.overheat_smoke_timer = 0

        state_controller.divine.state = None
        state_controller.divine.blueprint_active = False
        state_controller.divine.blueprint_rect = None
        state_controller.divine.build_progress = 0
        state_controller.divine.partial_drain = 0.0

        draw_blacksmith_turret_elements(temp_surface)

        surface.blit(temp_surface, rect.topleft, special_flags=pygame.BLEND_PREMULTIPLIED)
        return True
    finally:
        # 상태 복구
        state_controller.turret = turret_backup
        state_controller.divine = divine_backup

        for key, value in globals_backup.items():
            globals()[key] = value

        # 컨트롤러와 전역 동기화
        try:
            BLACKSMITH_CONTROLLER.apply_to_globals()
        except Exception:
            pass


