# 발토르 전용 상태/컨트롤러 초기화
BLACKSMITH_CONTROLLER = BlacksmithController(sys.modules[__name__])
BLACKSMITH_CONTROLLER.sync_from_globals()

BLACKSMITH_OVERDRIVE_GRADIENT_SURFACE = None
BLACKSMITH_OVERDRIVE_VIGNETTE_SURFACE = None


def sync_blacksmith_state() -> None:
    """전역 → 상태 객체 동기화."""
    BLACKSMITH_CONTROLLER.sync_from_globals()


def push_blacksmith_state() -> None:
    """상태 객체 → 전역 동기화."""
    BLACKSMITH_CONTROLLER.apply_to_globals()


def _clone_rect(rect):
    try:
        return rect.copy() if rect is not None else None
    except Exception:
        return None


def _capture_blacksmith_structures_for_persist() -> dict | None:
    """현재 발토르 건축물 상태를 다음 스테이지로 넘기기 위해 스냅샷한다."""
    sync_blacksmith_state()
    state = BLACKSMITH_CONTROLLER.state
    snapshot: dict = {}

    # 포탑 상태 스냅샷 (완성된 포탑만)
    if state.turret.active and isinstance(state.turret.state, dict):
        tstate = dict(state.turret.state)
        if tstate.get("rect") is not None:
            tstate["rect"] = _clone_rect(tstate.get("rect"))
        # 프레임/연기/과열 등 일시 상태는 초기화
        tstate["overheat_timer"] = 0
        tstate["overheat_smoke_timer"] = 0
        tstate["overdrive_active"] = False
        snapshot["turret"] = tstate
        try:
            snapshot["turret_x"] = int(tstate["rect"].centerx)
        except Exception:
            pass

    # 디바인 스톤 상태 스냅샷 (필드에 존재할 때만)
    divine_state = state.divine.state or globals().get("blacksmith_divine_stone_state")
    if _is_divine_state_active(divine_state):
        dstate = dict(divine_state)
        if dstate.get("rect") is not None:
            dstate["rect"] = _clone_rect(dstate.get("rect"))
        snapshot["divine"] = dstate
        try:
            snapshot["divine_x"] = int(dstate["rect"].centerx)
        except Exception:
            pass

    return snapshot or None


def _restore_blacksmith_structures_from_persist(persist: dict, *, stage_num: int) -> None:
    """스냅샷에서 발토르 건축물을 복원한다."""
    state = BLACKSMITH_CONTROLLER.state

    # 디바인 스톤 복원
    dstate = persist.get("divine")
    if isinstance(dstate, dict):
        # 위치 고정 (X: 저장값, Y: 스테이지 바닥 기준 재계산)
        try:
            rect = dstate["rect"]
            saved_x = int(persist.get("divine_x", rect.centerx))
            anchor_y = HEIGHT - BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT
            rect.midbottom = (
                max(rect.width // 2, min(WIDTH - rect.width // 2, saved_x)),
                anchor_y,
            )
        except Exception:
            pass
        state.divine.state = dstate
        # 현재 스테이지 소유로 업데이트 (활성화 가드 통과용)
        globals()["blacksmith_divine_stage_owner"] = stage_num

    # 포탑 복원
    tstate = persist.get("turret")
    if isinstance(tstate, dict):
        # 위치 고정 (X: 저장값, Y: 스테이지 바닥 기준 재계산)
        try:
            trect = tstate["rect"]
            saved_x = int(persist.get("turret_x", trect.centerx))
            base_y = HEIGHT - 5
            trect.midbottom = (
                max(trect.width // 2, min(WIDTH - trect.width // 2, saved_x)),
                base_y,
            )
        except Exception:
            pass
        state.turret.active = True
        state.turret.blueprint_active = False
        state.turret.state = tstate
        state.turret.projectiles.clear()
        state.turret.manual_cooldown = 0
        state.turret.overheat_timer = 0
        state.turret.overheat_smoke_timer = 0

    # 전역 반영 (그리기/충돌 등 레거시 경로를 위해)
    BLACKSMITH_CONTROLLER.apply_to_globals()

    # 1프레임 보정용 락 포지션 설정 (다른 초기화 경로에서 중앙으로 스냅되는 경우 재보정)
    globals()["blacksmith_persist_lock_pos"] = {
        "turret_x": persist.get("turret_x"),
        "divine_x": persist.get("divine_x"),
        "turret_frames": 6,
        "divine_frames": 6,
    }

def reset_blacksmith_state(*, preserve_divine: bool = False, stage_num: int | None = None) -> None:
    """발토르 전용 런타임 상태 초기화.

    Args:
        preserve_divine: True일 때 동일 스테이지 내에서 디바인스톤 상태를 유지한다.
        stage_num: 현재 스테이지 번호. preserve_divine와 함께 전달되어야 한다.
    """

    stop_blacksmith_construction_sound()

    global blacksmith_divine_stage_owner

    preserved_divine: dict[str, object] | None = None
    if preserve_divine:
        sync_blacksmith_state()
        state = BLACKSMITH_CONTROLLER.state
        divine_runtime = state.divine
        stage_owner = blacksmith_divine_stage_owner

        if stage_owner is not None and (stage_num is None or stage_owner == stage_num):
            preserved_state = None
            if divine_runtime.state is not None:
                preserved_state = dict(divine_runtime.state)
                rect = preserved_state.get("rect")
                if rect is not None:
                    preserved_state["rect"] = rect.copy()

            preserved_blueprint_rect = None
            if divine_runtime.blueprint_rect is not None:
                preserved_blueprint_rect = divine_runtime.blueprint_rect.copy()

            preserved_divine = {
                "state": preserved_state,
                "blueprint_active": divine_runtime.blueprint_active,
                "blueprint_rect": preserved_blueprint_rect,
                "build_progress": divine_runtime.build_progress,
                "partial_drain": divine_runtime.partial_drain,
                "stage_owner": stage_owner,
            }

    BLACKSMITH_CONTROLLER.reset()

    if preserved_divine and (
        preserved_divine["state"] is not None or preserved_divine["blueprint_active"]
    ):
        state = BLACKSMITH_CONTROLLER.state
        divine_runtime = state.divine
        divine_runtime.state = preserved_divine["state"]
        divine_runtime.blueprint_active = preserved_divine["blueprint_active"]
        divine_runtime.blueprint_rect = preserved_divine["blueprint_rect"]
        divine_runtime.build_progress = preserved_divine["build_progress"]
        divine_runtime.partial_drain = preserved_divine["partial_drain"]
        BLACKSMITH_CONTROLLER.apply_to_globals(
            attrs=(
                "blacksmith_divine_stone_state",
                "blacksmith_divine_blueprint_active",
                "blacksmith_divine_blueprint_rect",
                "blacksmith_divine_build_progress",
                "blacksmith_divine_partial_drain",
            )
        )
        blacksmith_divine_stage_owner = preserved_divine["stage_owner"]
    else:
        blacksmith_divine_stage_owner = None

    global blacksmith_hammer_swing_slow_timer
    global blacksmith_hammer_shock_last_stage, blacksmith_hammer_shock_cooldown_total
    global blacksmith_umbrella_gauge, blacksmith_umbrella_recharge_progress
    global blacksmith_umbrella_damage_flash_timer, blacksmith_umbrella_last_hit_frame
    global blacksmith_umbrella_hit_lock
    global blacksmith_umbrella_retract_grace_timer
    global blacksmith_blocking_penalty_timer, blacksmith_blocking_toast_timer
    global blacksmith_blocking_skill_timer, blacksmith_blocking_bonus_pending
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    global blacksmith_blocking_bonus_ready, blacksmith_blocking_bonus_window_timer
    blacksmith_hammer_swing_slow_timer = 0
    stop_blacksmith_hammer_charge_sound()
    blacksmith_umbrella_gauge = BLACKSMITH_UMBRELLA_GAUGE_MAX
    blacksmith_umbrella_recharge_progress = 0
    blacksmith_umbrella_damage_flash_timer = 0
    blacksmith_umbrella_last_hit_frame = -1000
    blacksmith_umbrella_retract_start_frame = -1000
    blacksmith_umbrella_retract_grace_timer = 0
    blacksmith_blocking_penalty_timer = 0
    blacksmith_blocking_toast_timer = 0
    blacksmith_blocking_skill_timer = 0
    blacksmith_blocking_bonus_pending = False
    blacksmith_blocking_bonus_ready = False
    blacksmith_blocking_bonus_window_timer = 0
    blacksmith_blocking_bonus_ready = False
    blacksmith_blocking_bonus_window_timer = 0
    blacksmith_umbrella_hit_lock = False
    blacksmith_hammer_shock_last_stage = 0
    blacksmith_hammer_shock_cooldown_total = 0


def start_blacksmith_construction_sound():
    if SOUND_CONSTRUCTION is None:
        return

    sync_blacksmith_state()
    audio_state = BLACKSMITH_CONTROLLER.state.construction_audio

    if audio_state.playing:
        return

    channel = audio_state.channel
    if channel:
        try:
            channel.unpause()
            audio_state.playing = True
            audio_state.channel = channel
            push_blacksmith_state()
            return
        except Exception:
            channel = None

    try:
        channel = SOUND_CONSTRUCTION.play(-1)
    except Exception:
        channel = None

    audio_state.channel = channel
    audio_state.playing = True if channel else False
    push_blacksmith_state()


def stop_blacksmith_construction_sound():
    sync_blacksmith_state()
    audio_state = BLACKSMITH_CONTROLLER.state.construction_audio

    if not audio_state.playing and not audio_state.channel:
        return

    try:
        if audio_state.channel:
            audio_state.channel.stop()
        elif SOUND_CONSTRUCTION:
            SOUND_CONSTRUCTION.stop()
    except Exception:
        pass

    audio_state.channel = None
    audio_state.playing = False
    push_blacksmith_state()


def pause_blacksmith_construction_sound():
    sync_blacksmith_state()
    audio_state = BLACKSMITH_CONTROLLER.state.construction_audio

    if not audio_state.playing:
        return

    try:
        if audio_state.channel:
            audio_state.channel.pause()
        elif SOUND_CONSTRUCTION:
            SOUND_CONSTRUCTION.stop()
    except Exception:
        pass

    audio_state.playing = False
    push_blacksmith_state()

def create_soldier_paddle_animated(*, include_right_arm: bool = True) -> pygame.Surface:
    """휘두르기 애니메이션이 적용된 코만도 패들 이미지 생성"""
    global soldier_swing_timer

    if SOLDIER_SWING_DURATION <= 0:
        return create_soldier_paddle_surface()

    swing_progress = 1.0 - (soldier_swing_timer / SOLDIER_SWING_DURATION)
    swing_strength = math.sin(max(0.0, min(1.0, swing_progress)) * math.pi)
    right_hook_strength = get_soldier_right_hook_strength()
    return create_soldier_paddle_surface(
        swing_strength=swing_strength,
        right_hook_strength=right_hook_strength,
        include_right_arm=include_right_arm,
    )


def create_soldier_paddle_walking(*, include_right_arm: bool = True) -> pygame.Surface:
    """걷기 애니메이션이 적용된 코만도 패들 이미지 생성"""
    global soldier_walking_timer

    if SOLDIER_WALKING_CYCLE <= 0:
        return create_soldier_paddle_surface()

    phase = (soldier_walking_timer % SOLDIER_WALKING_CYCLE) / SOLDIER_WALKING_CYCLE
    right_hook_strength = get_soldier_right_hook_strength()
    return create_soldier_paddle_surface(
        step_phase=phase,
        right_hook_strength=right_hook_strength,
        include_right_arm=include_right_arm,
    )


