psycho_sound_channel = None  # 사이코볼 사운드 채널
# Stage 3 쿠로미 석회화 관련 변수는 Stage3MenheraWorld 클래스로 이동됨
# === 대쉬 스피릿 레이저 시스템 ===
dash_spirit_lasers = []  # [(start_x, start_y, end_x, end_y, remaining_time, direction, electric_offset), ...]
DASH_SPIRIT_LASER_DURATION = 360  # 6초 (60fps 기준)

# === 물자보급 스킬 시스템 ===
supply_runtime = SupplyDropRuntime()
supply_drop_state = supply_runtime.state
SUPPLY_DROP_HOLD_REQUIRED = supply_drop_state.config.hold_required
SUPPLY_DROP_HOLD_THRESHOLD = supply_drop_state.config.hold_threshold
SUPPLY_DROP_GAUGE_COST = supply_drop_state.config.gauge_cost


def start_supply_radio_loop(*, duration_frames: int = 30, play_sound: bool = True) -> None:
    """무전기 애니메이션과 사운드를 시작하거나 연장한다."""

    safe_duration = max(1, int(duration_frames))

    if not play_sound:
        # 화력지원 등에서 애니메이션만 유지하려는 호출은 기존 동작을 그대로 사용한다.
        supply_start_radio_loop(
            supply_runtime,
            resource_path,
            duration_frames=safe_duration,
            play_sound=play_sound,
        )
        return

    channel_busy = False
    radio_channel = getattr(supply_runtime, "_radio_channel", None)
    if radio_channel is not None:
        try:
            channel_busy = radio_channel.get_busy()
        except Exception:
            channel_busy = False

    if channel_busy:
        # 이미 루프가 재생 중이면 타이머만 연장하고 중복 재생을 방지한다.
        state = supply_runtime.state
        state.radio_motion = True
        state.radio_timer = max(state.radio_timer, safe_duration)
        state.radio_duration = max(state.radio_duration, safe_duration)
        supply_runtime.hold_active = True
        supply_ensure_radio_audio(
            supply_runtime,
            resource_path,
            volume=0.6,
        )
        return

    supply_start_radio_loop(
        supply_runtime,
        resource_path,
        duration_frames=safe_duration,
        play_sound=play_sound,
    )


def stop_supply_radio_loop(keep_animation: bool = False, *, force: bool = False) -> None:
    """무전기 루프 사운드를 중단하고 상태를 정리한다."""

    global fire_support_radio_loop_active
    fire_support_radio_loop_active = False
    supply_stop_radio_loop(supply_runtime, keep_animation=keep_animation, force=force)


def update_supply_drop_system() -> None:
    """물자보급 시스템 전체 업데이트"""

