def draw_bazooka_recoil_effect(screen: pygame.Surface) -> None:
    """바주카포 반동 시각 효과 그리기"""
    global bazooka_recoil_timer, bazooka_recoil_direction, bazooka_recoil_strength
    
    if bazooka_recoil_timer <= 0:
        return
        
    # 반동 진행도 (1.0 → 0.0)
    progress = bazooka_recoil_timer / 20.0
    
    # 플레이어 패들 중심점
    player_center_x = PLAYER.centerx
    player_center_y = PLAYER.centery
    
    # 잔상 효과 - 반동 반대 방향으로
    afterimage_count = 3
    for i in range(afterimage_count):
        alpha = int(80 * progress * (1 - i / afterimage_count))
        if alpha > 0:
            # 잔상 위치 (반동 반대 방향)
            offset_x = -bazooka_recoil_direction * bazooka_recoil_strength * (i + 1) * 0.3 * progress
            afterimage_x = int(player_center_x + offset_x)
            
            # 잔상 그리기
            afterimage_surface = pygame.Surface((PLAYER.width, PLAYER.height), pygame.SRCALPHA)
            afterimage_surface.set_alpha(alpha)
            
            # 코만도 캐릭터 실루엣
            pygame.draw.rect(afterimage_surface, (100, 100, 100), 
                           (0, 0, PLAYER.width, PLAYER.height))
            
            screen.blit(afterimage_surface, 
                       (afterimage_x - PLAYER.width // 2, 
                        PLAYER.y))
    
    # 속도선 효과
    if progress > 0.5:
        line_count = 5
        for i in range(line_count):
            # 속도선 위치
            line_y = player_center_y + (i - line_count // 2) * 15
            line_start_x = player_center_x - bazooka_recoil_direction * 30
            line_end_x = player_center_x - bazooka_recoil_direction * (50 + i * 10) * progress
            
            # 속도선 그리기
            line_alpha = int(150 * (progress - 0.5) * 2)
            line_color = (255, 200, 100, line_alpha) if line_alpha < 255 else (255, 200, 100)
            pygame.draw.line(screen, line_color[:3], 
                           (line_start_x, line_y), 
                           (line_end_x, line_y), 2)
    
    # 충격파 효과
    if progress > 0.7:
        shock_radius = int((1 - progress) * 100)  # 0 → 30
        shock_alpha = int((progress - 0.7) * 3 * 255)  # 투명 → 불투명 → 투명
        if shock_alpha > 0 and shock_alpha < 255:
            pygame.draw.circle(screen, (255, 255, 255), 
                             (player_center_x, player_center_y), 
                             shock_radius, 2)

    aircraft = supply_drop_state.aircraft
    if aircraft:
        if aircraft.active:
            aircraft.draw(screen)

        for particle in aircraft.smoke_particles[:]:
            particle['y'] += particle['vy']
            particle['x'] += particle['vx']
            particle['life'] -= 1
            if particle['life'] <= 0:
                aircraft.smoke_particles.remove(particle)
                continue
            alpha = min(255, particle['life'] * 4)
            size = particle['size'] + (60 - particle['life']) * 0.3
            smoke_surf = pygame.Surface((size * 2, size * 2), pygame.SRCALPHA)
            color = (*particle['color'], alpha)
            pygame.draw.circle(smoke_surf, color, (size, size), size)
            screen.blit(smoke_surf, (particle['x'] - size, particle['y'] - size))

        for particle in aircraft.explosion_particles[:]:
            particle['x'] += particle['vx']
            particle['y'] += particle['vy']
            particle['vy'] += 0.3
            particle['life'] -= 1
            if particle['life'] <= 0:
                aircraft.explosion_particles.remove(particle)
                continue
            life_ratio = particle['life'] / 120.0
            size = int(particle['size'] * life_ratio)
            if size <= 0:
                continue
            outer_color = (
                min(255, particle['color'][0] + 30),
                min(255, particle['color'][1] + 20),
                particle['color'][2],
            )
            pygame.draw.circle(screen, outer_color, (int(particle['x']), int(particle['y'])), size + 2)
            pygame.draw.circle(screen, particle['color'], (int(particle['x']), int(particle['y'])), size)
            if size > 3:
                highlight = (255, 255, min(255, particle['color'][2] + 100))
                pygame.draw.circle(screen, highlight, (int(particle['x']), int(particle['y'])), size // 3)

        for particle in aircraft.debris_particles[:]:
            particle['x'] += particle['vx']
            particle['y'] += particle['vy']
            particle['vy'] += 0.5
            particle['life'] -= 1
            if particle['life'] <= 0:
                aircraft.debris_particles.remove(particle)
                continue
            if particle['y'] >= screen.get_height() - 50:
                particle['y'] = screen.get_height() - 50
                particle['vy'] *= -0.5
                particle['vx'] *= 0.8
            pygame.draw.rect(
                screen,
                particle['color'],
                (particle['x'], particle['y'], particle['width'], particle['height']),
            )

    supply_draw_items(screen, supply_drop_state)


def activate_supply_drop_item(item_name: str) -> None:
    """Handle collection of a supply-drop item."""

    import items
    try:
        item_label = get_item_name_korean(item_name)
    except Exception:
        item_label = item_name

    print(f"🔍 아이템 검색 시작: {item_label}")

    # 화기류 특수 처리
    if item_name == "bazooka":
        if soldier_controller.add_weapon("bazooka"):
            print(f"🚀 바주카포 획득! 현재 화기류: {soldier_controller.weapons}")
            from item_effects.bazooka import get_bazooka_instance
            bazooka = get_bazooka_instance()
            bazooka.equip()
            try:
                if SOUND_ITEM_GET:
                    SOUND_ITEM_GET.play()
            except Exception:
                pass
        return

    if item_name == "ak47":
        if soldier_controller.add_weapon("ak47"):
            print(f"🔫 AK-47 획득! 현재 화기류: {soldier_controller.weapons}")
            ak47 = get_ak47_instance()
            ak47.activate(None, None)
            ak47.active = True  # 활성 상태로 설정
            try:
                if SOUND_ITEM_GET:
                    SOUND_ITEM_GET.play()
            except Exception:
                pass
        return

    if item_name == "net_gun":
        if soldier_controller.add_weapon("net_gun"):
            print(f"🕸️ 그물덫총 획득! 현재 화기류: {soldier_controller.weapons}")
            net_gun = get_net_gun_instance()
            net_gun.reload()
            net_gun.equip()
            try:
                if SOUND_ITEM_GET:
                    SOUND_ITEM_GET.play()
            except Exception:
                pass
        return

    if item_name == "fire_support":
        if soldier_controller.add_weapon("fire_support"):
            print(f"✈️ 화력지원 장비 획득! 현재 화기류: {soldier_controller.weapons}")
            fire_support = get_fire_support_instance()
            fire_support.on_acquired()
            fire_support.equip()
            try:
                if SOUND_ITEM_GET:
                    SOUND_ITEM_GET.play()
            except Exception:
                pass
        return

    if item_name == "suicide_drone":
        if soldier_controller.add_weapon("suicide_drone"):
            print(f"🚁 {get_item_name_korean('suicide_drone')} 획득! 현재 화기류: {soldier_controller.weapons}")
            globals()["soldier_drone_ammo"] = SUICIDE_DRONE_MAX_AMMO
            _reset_suicide_drone_state()
            try:
                if SOUND_ITEM_GET:
                    SOUND_ITEM_GET.play()
            except Exception:
                pass
        return

    # 일반 아이템 처리
    item_data = None
    for item in items.ITEM_TYPES:
        if item["name"] == item_name:
            item_data = item.copy()
            print(f"✅ 아이템 정보 발견: {item_data}")
            break

    if item_data:
        store_active_item(item_data)
        print(f"💎 물자보급 아이템 획득 완료: {item_name}")
        try:
            if SOUND_ITEM_GET:
                SOUND_ITEM_GET.play()
        except Exception:
            pass
    else:
        print(f"⚠️ 아이템 정보를 찾을 수 없음: {item_name}")

# === 군용 비행기 클래스 ===
class SupplyAircraft:
    DEFAULT_ALTITUDE = 50

    def __init__(
        self,
        direction="left_to_right",
        *,
        screen_width: int | None = None,
        screen_height: int | None = None,
        engine_sound: pygame.mixer.Sound | None = None,
    ):
        """
        군용 비행기 초기화
        Args:
            direction: "left_to_right" 또는 "right_to_left"
        """
        self.direction = direction
        self.width = 80
        self.height = 30
        self.speed = 2

        self.screen_width = screen_width if screen_width is not None else WIDTH
        self.screen_height = screen_height if screen_height is not None else HEIGHT
        self.engine_sound = engine_sound
        
        # 위치 초기화
        if direction == "left_to_right":
            self.x = -self.width
        else:
            self.x = self.screen_width + self.width
        
        self.y = self.DEFAULT_ALTITUDE  # 화면 상단에서 50픽셀 아래 (전역 고정 고도)
        self.active = True
        
        # 등장 후 대기 시간 (0.8초)
        self.spawn_delay = 48  # 48 프레임 = 0.8초
        self.spawn_timer = 0  # 등장 후 경과 시간
        
        # 무적 시간 (1초)
        self.invulnerable_time = 60  # 60 프레임 = 1초
        
        self.drop_timer = 0
        # 더 불규칙한 드랍 타이밍 (0.2~2.5초 사이의 완전 랜덤)
        self.next_drop_time = random.randint(12, 150)  # 매우 넓은 범위
        self.items_dropped = 0
        self.max_items = random.randint(1, 3)  # 1~3개 아이템 투척
        
        # 드랍 패턴 랜덤화를 위한 추가 변수
        self.drop_pattern = random.choice(["normal", "burst", "delayed"])  # 드랍 패턴
        self.burst_count = 0  # 연속 드랍용
        
        # 추락 관련 변수
        self.is_crashing = False
        self.crash_velocity_y = 0
        self.crash_rotation = 0
        self.crash_angle = 0  # 추락 각도
        self.explosion_particles = []
        self.smoke_particles = []  # 연기 파티클
        self.debris_particles = []  # 파편 파티클
        self.crash_phase = 0  # 0: 초기, 1: 가속, 2: 최종 추락
        self.exploded = False
        
        # 사운드 재생
        self.sound_channel = None
        if self.engine_sound is not None:
            try:
                self.sound_channel = self.engine_sound.play(-1)  # 무한 반복 재생
                self.sound_channel.set_volume(0.7)  # 볼륨 조절
            except Exception:  # noqa: BLE001
                self.sound_channel = None
        
    def update(self):
        """비행기 업데이트"""
        if not self.active:
            return

        if self.exploded:
            self._update_particles()
            if not (self.smoke_particles or self.explosion_particles or self.debris_particles):
                self.active = False
            return
            
        if self.is_crashing:
            # 추락 중일 때
            # 추락 단계별 다른 가속도 적용
            if self.crash_phase == 0:  # 초기 단계 - 매우 천천히
                self.crash_velocity_y += 0.05  # 더 느린 가속도
                if self.crash_velocity_y > 1.5:
                    self.crash_phase = 1
            elif self.crash_phase == 1:  # 중간 단계 - 조금씩 빨라짐
                self.crash_velocity_y += 0.1
                if self.crash_velocity_y > 3:
                    self.crash_phase = 2
            else:  # 최종 단계 - 빨라지지만 여전히 천천히
                self.crash_velocity_y += 0.15
                # 최대 속도 제한
                if self.crash_velocity_y > 5:
                    self.crash_velocity_y = 5
                
            self.y += self.crash_velocity_y
            self.crash_rotation += min(10, 2 + self.crash_velocity_y * 0.3)  # 회전도 더 천천히
            self.crash_angle += 2  # 추락 각도 증가
            
            # 연속적인 연기 생성
            if random.randint(1, 3) == 1:  # 33% 확률로 연기 생성
                self.create_smoke_particle()
            
            # 바닥에 닿으면 폭발
            if self.y > self.screen_height - 80:  # 플레이어 패들 근처
                self.explode()
                return
        else:
            # 정상 비행 중
            # 등장 타이머 업데이트
            self.spawn_timer += 1
            
            # 비행기 이동
            if self.direction == "left_to_right":
                self.x += self.speed
                if self.x > self.screen_width + self.width:
                    self.stop_sound()  # 사운드 중지
                    self.active = False
            else:
                self.x -= self.speed
                if self.x < -self.width:
                    self.stop_sound()  # 사운드 중지
                    self.active = False
                    
            # 등장 후 0.5초가 지났을 때만 아이템 투척 가능
            if self.spawn_timer >= self.spawn_delay:
                # 아이템 투척 타이머 (불규칙한 타이밍)
                self.drop_timer += 1
                # 드랍 패턴에 따라 다른 로직 적용
                if self.drop_pattern == "burst" and self.burst_count < 2 and self.items_dropped < self.max_items:
                    # 연속 드랍 패턴: 짧은 간격으로 2개 연속 드랍
                    if self.drop_timer >= 10:  # 0.17초마다
                        self.drop_item()
                        self.drop_timer = 0
                        self.burst_count += 1
                        self.items_dropped += 1
                        if self.burst_count >= 2:
                            # 연속 드랍 후 긴 대기
                            self.next_drop_time = random.randint(90, 180)  # 1.5~3초
                            self.drop_pattern = "normal"
                            
                elif self.drop_timer >= self.next_drop_time and self.items_dropped < self.max_items:
                    self.drop_item()
                    self.drop_timer = 0
                    self.items_dropped += 1
                    
                    # 다음 드랍 타이밍을 매우 불규칙하게 설정
                    if self.drop_pattern == "delayed":
                        # 지연 패턴: 긴 간격
                        self.next_drop_time = random.randint(120, 210)  # 2~3.5초
                    else:
                        # 일반 패턴: 완전 랜덤
                        choices = [
                            random.randint(10, 30),   # 매우 빠른 드랍 (0.17~0.5초)
                            random.randint(40, 80),   # 중간 속도 (0.67~1.33초)
                            random.randint(100, 180), # 느린 드랍 (1.67~3초)
                        ]
                        self.next_drop_time = random.choice(choices)
                    
                    # 마지막 아이템일 때는 패턴 변경
                    if self.items_dropped == self.max_items - 1:
                        self.drop_pattern = random.choice(["normal", "delayed"])

        self._update_particles()

    def drop_item(self):
        """아이템 투척"""
        
        # 랜덤 아이템 선택 (이미 보유한 화기류는 제외)
        base_weights = {
            "grenade": 1.0,
            "molotov": 1.0,
            "flare": 1.0,
            "spider_mine": 0.9,
            "bazooka": 0.45,
            "ak47": 0.9,
            "net_gun": 0.45,
            "ammo_box": 0.6,
            "fire_support": 0.35,
            "suicide_drone": 0.35,
        }
        firearm_names = {"bazooka", "ak47", "net_gun", "fire_support", "suicide_drone"}

        # 정확한 화기 인벤토리를 읽어 중복 드랍을 방지
        controller = globals().get("soldier_controller")
        if controller is not None and hasattr(controller, "weapons"):
            soldier_weapon_list = list(controller.weapons)
        else:
            soldier_weapon_list = globals().get("soldier_weapons", [])
        owned_firearm_count = len({w for w in soldier_weapon_list if w in firearm_names})
        firearm_penalty = max(0.25, 1.0 - 0.25 * owned_firearm_count)  # 0.25씩 감소, 최소 25%

        available_items = []
        available_weights = []
        for item_name in supply_drop_state.config.items:
            if item_name in soldier_weapon_list:
                continue

            weight = base_weights.get(item_name, 1.0)
            if item_name in firearm_names:
                weight *= firearm_penalty

            available_items.append(item_name)
            available_weights.append(weight)

        # 모든 후보가 제거되면 기본 투척류로 폴백
        if not available_items:
            available_items = list(supply_drop_state.config.items[:3])  # 안전장치: 기본 투척류만 사용
            available_weights = [1, 1, 1]

        item_name = random.choices(available_items, weights=available_weights, k=1)[0]
        try:
            item_label = get_item_name_korean(item_name)
        except Exception:
            item_label = item_name
        print(f"🎁🎁🎁 [물자보급 드롭] {item_label} 드롭! 🎁🎁🎁")
        
        # 아이템 투척 위치를 비행기 위치에서 약간 랜덤하게
        drop_offset_x = random.randint(-20, 20)  # 좌우로 약간 흔들림
        drop_x = self.x + self.width // 2 + drop_offset_x
        safe_margin = 32  # 낙하산+상자 그래픽이 화면 밖으로 나가지 않도록 여유를 둔다
        drop_x = max(safe_margin, min(self.screen_width - safe_margin, drop_x))
        drop_y = self.y + self.height
        
        # 바람 효과를 위한 수평 속도 랜덤
        wind_effect = random.uniform(-0.5, 0.5)  # 좌우 바람 효과
        
        # 낙하 속도도 약간 랜덤화
        fall_speed = random.uniform(2.0, 3.0)  # 2.0~3.0 사이 랜덤
        
        # 낙하산 아이템 생성
        parachute_item = {
            "name": item_name,
            "x": drop_x,
            "y": drop_y,
            "vx": wind_effect,  # 수평 속도 (바람 효과)
            "vy": fall_speed,  # 낙하 속도 (랜덤)
            "parachute_open": True,
            "rotation": 0,
            "sway": 0,  # 좌우 흔들림
            "active": True
        }
        
        supply_drop_state.items.append(parachute_item)
        
    def get_rect(self):
        """비행기의 충돌 박스 반환"""
        return pygame.Rect(self.x, self.y, self.width, self.height)
    
    def check_ball_collision(self, ball_rect, hit_by="player"):
        """공과의 충돌 체크 - 플레이어가 쏜 공만 격추 가능"""
        # 무적 시간 동안은 충돌 무시
        if self.spawn_timer < self.invulnerable_time:
            return False
            
        if not self.is_crashing and self.get_rect().colliderect(ball_rect):
            # 플레이어가 쏜 공만 격추 가능
            if hit_by == "player":
                self.is_crashing = True
                self.crash_velocity_y = 0.5  # 초기 속도를 더 느리게 (1 → 0.5)
                self.crash_phase = 0  # 추락 단계 초기화
                # 초기 폭발 및 연기 파티클 생성
                self.create_crash_particles()
                self.create_initial_smoke()
                print("💥 비행기가 플레이어의 공에 맞아 추락합니다!")
                return True
            else:
                # 보스가 쏜 공은 통과
                return False
        return False
    
    def check_paddle_brick_collision(self, player_paddle, boss_paddle, bricks):
        """패들과 벽돌과의 충돌 체크"""
        # 무적 시간 동안은 충돌 무시
        if self.spawn_timer < self.invulnerable_time:
            return False
            
        if self.is_crashing:
            return False  # 이미 추락 중이면 무시
            
        aircraft_rect = self.get_rect()
        
        # 플레이어 패들과 충돌 체크
        if player_paddle and aircraft_rect.colliderect(player_paddle):
            self.is_crashing = True
            self.crash_velocity_y = 0.5
            self.crash_phase = 0
            self.create_crash_particles()
            self.create_initial_smoke()
            print("💥 비행기가 플레이어 패들에 충돌하여 추락합니다!")
            return True
            
        # 보스 패들과는 충돌하지 않음 (통과)
        # 비행기는 플레이어 공에 맞았을 때만 추락함
            
        # 벽돌과 충돌 체크
        if bricks:
            for brick in bricks:
                if brick.get("visible", True) and aircraft_rect.colliderect(brick["rect"]):
                    self.is_crashing = True
                    self.crash_velocity_y = 0.5
                    self.crash_phase = 0
                    self.create_crash_particles()
                    self.create_initial_smoke()
                    print("💥 비행기가 벽돌에 충돌하여 추락합니다!")
                    # 벽돌은 파괴하지 않음 (비행기만 추락)
                    return True
                    
        return False
    
    def create_crash_particles(self):
        """추락 시 초기 폭발 파티클 생성"""
        # 작은 폭발과 불꽃 파티클
        for _ in range(15):
            self.explosion_particles.append({
                'x': self.x + self.width // 2 + random.randint(-10, 10),
                'y': self.y + self.height // 2 + random.randint(-5, 5),
                'vx': random.uniform(-3, 3),
                'vy': random.uniform(-3, 2),
                'color': random.choice([(255, 100, 0), (255, 200, 0), (255, 150, 50)]),
                'size': random.randint(2, 5),
                'life': random.randint(15, 30)
            })
    
    def create_initial_smoke(self):
        """초기 연기 생성"""
        for _ in range(10):
            self.smoke_particles.append({
                'x': self.x + self.width // 2 + random.randint(-15, 15),
                'y': self.y + self.height // 2,
                'vx': random.uniform(-1, 1),
                'vy': random.uniform(-2, -0.5),  # 연기는 위로
                'size': random.randint(5, 10),
                'color': (80, 80, 80),  # 회색 연기
                'alpha': 150,
                'life': random.randint(40, 60)
            })
    
    def create_smoke_particle(self):
        """추락 중 연속적인 연기 생성"""
        # 비행기 뒤쪽에서 연기 생성
        smoke_x = self.x + self.width // 2 - (10 if self.direction == "left_to_right" else -10)
        self.smoke_particles.append({
            'x': smoke_x + random.randint(-5, 5),
            'y': self.y + self.height // 2 + random.randint(-5, 5),
            'vx': random.uniform(-0.5, 0.5),
            'vy': random.uniform(-1.5, -0.5),
            'size': random.randint(8, 15),
            'color': (70, 70, 70),  # 진한 회색 연기
            'alpha': 180,
            'life': random.randint(50, 80)
        })
    
    def explode(self):
        """바닥에 닿았을 때 현실적인 폭발"""
        explosion_center_x = self.x + self.width // 2
        explosion_center_y = self.y + self.height // 2
        
        print(f"💥 비행기 폭발! 위치: ({explosion_center_x}, {explosion_center_y})")
        
        # 플레이어와의 거리 계산 및 스턴/넉백 효과
        global player_missile_stunned_timer, player_missile_knockback_vel
        if PLAYER:
            player_center_x = PLAYER.x + PADDLE_WIDTH // 2
            player_center_y = PLAYER.y + PADDLE_HEIGHT // 2
            
            # 폭발 중심으로부터의 거리 계산
            distance = math.sqrt((player_center_x - explosion_center_x)**2 + 
                               (player_center_y - explosion_center_y)**2)
            
            # 100픽셀 반경 내에 있으면 스턴과 넉백 적용
            if distance <= 100:
                # 0.3초 스턴 효과 (스테이지5 화염탄과 동일)
                player_missile_stunned_timer = int(0.3 * FPS)  # 0.3초 = 18프레임
                
                # 스테이지5 홍련의 화염탄 수준의 넉백 (기본 9, 방향에 따라)
                if player_center_x < explosion_center_x:
                    # 플레이어가 폭발 왼쪽에 있으면 왼쪽으로 넉백
                    player_missile_knockback_vel = _scale_knockback(-12)  # 화염탄(9)보다 약간 강하게
                else:
                    # 플레이어가 폭발 오른쪽에 있으면 오른쪽으로 넉백
                    player_missile_knockback_vel = _scale_knockback(12)
                
                # 거리에 따른 넉백 강도 조정 (가까울수록 강함)
                knockback_multiplier = 1.0 - (distance / 100)  # 0~1 사이 값
                player_missile_knockback_vel *= (0.5 + 0.5 * knockback_multiplier)  # 최소 50% ~ 최대 100%
                
                print(f"💥 플레이어 폭발 피해! 거리: {distance:.1f}px, 넉백: {player_missile_knockback_vel:.1f}")
        
        # 🔥 화염 파티클 - 적당한 강도로 조정
        for _ in range(25):  # 50 → 25개로 줄임
            angle = random.uniform(0, 2 * 3.14159)
            speed = random.uniform(5, 15)  # 8-25 → 5-15로 줄임
            self.explosion_particles.append({
                'x': explosion_center_x + random.randint(-10, 10),
                'y': explosion_center_y + random.randint(-5, 5),
                'vx': speed * math.cos(angle),
                'vy': speed * math.sin(angle) - 5,  # 위쪽으로 적당히
                'color': random.choice([(255, 100, 0), (255, 150, 0), (255, 200, 50)]),  # 주황빛 화염
                'size': random.randint(8, 18),  # 크기 조정
                'life': random.randint(30, 60)  # 수명 줄임
            })
        
        # 🛠️ 현실적인 금속 파편 - 날카로운 조각들
        for _ in range(35):  # 40 → 35개로 조정
            angle = random.uniform(0, 2 * 3.14159)
            speed = random.uniform(8, 20)  # 적당한 속도
            # 불규칙한 파편 모양
            fragment_type = random.choice(['shard', 'chunk', 'wire', 'plate'])
            
            if fragment_type == 'shard':  # 날카로운 파편
                self.debris_particles.append({
                    'x': explosion_center_x,
                    'y': explosion_center_y,
                    'vx': speed * math.cos(angle),
                    'vy': speed * math.sin(angle) - random.uniform(3, 8),
                    'width': random.randint(2, 6),
                    'height': random.randint(8, 20),
                    'color': random.choice([(90, 90, 90), (120, 120, 120), (150, 150, 150)]),
                    'rotation': random.uniform(0, 360),
                    'rotation_speed': random.uniform(-20, 20),
                    'life': random.randint(60, 120),
                    'type': 'shard'
                })
            elif fragment_type == 'chunk':  # 덩어리 파편
                self.debris_particles.append({
                    'x': explosion_center_x,
                    'y': explosion_center_y,
                    'vx': speed * math.cos(angle) * 0.7,  # 무거워서 조금 느림
                    'vy': speed * math.sin(angle) - random.uniform(2, 5),
                    'width': random.randint(6, 12),
                    'height': random.randint(6, 12),
                    'color': random.choice([(60, 60, 60), (80, 80, 80), (100, 100, 100)]),
                    'rotation': random.uniform(0, 360),
                    'rotation_speed': random.uniform(-15, 15),
                    'life': random.randint(80, 150),
                    'type': 'chunk'
                })
            elif fragment_type == 'wire':  # 전선 파편
                self.debris_particles.append({
                    'x': explosion_center_x,
                    'y': explosion_center_y,
                    'vx': speed * math.cos(angle),
                    'vy': speed * math.sin(angle) - random.uniform(1, 4),
                    'width': random.randint(1, 3),
                    'height': random.randint(10, 25),
                    'color': random.choice([(40, 40, 40), (80, 60, 40), (120, 100, 80)]),
                    'rotation': random.uniform(0, 360),
                    'rotation_speed': random.uniform(-30, 30),
                    'life': random.randint(70, 130),
                    'type': 'wire'
                })
            else:  # plate - 판금 파편
                self.debris_particles.append({
                    'x': explosion_center_x,
                    'y': explosion_center_y,
                    'vx': speed * math.cos(angle),
                    'vy': speed * math.sin(angle) - random.uniform(2, 6),
                    'width': random.randint(8, 15),
                    'height': random.randint(3, 8),
                    'color': random.choice([(100, 100, 100), (130, 130, 130), (160, 160, 160)]),
                    'rotation': random.uniform(0, 360),
                    'rotation_speed': random.uniform(-25, 25),
                    'life': random.randint(70, 140),
                    'type': 'plate'
                })
        
        # 💨 연기 - 적당한 양으로 조정
        for _ in range(20):  # 40 → 20개로 줄임
            self.smoke_particles.append({
                'x': explosion_center_x + random.randint(-25, 25),
                'y': explosion_center_y + random.randint(-15, 15),
                'vx': random.uniform(-2, 2),
                'vy': random.uniform(-5, -1),
                'size': random.randint(15, 35),  # 크기 조정
                'color': (60, 60, 60),  # 적당한 회색
                'alpha': 180,  # 투명도 조정
                'life': random.randint(60, 100)
            })
        
        # 폭발음 재생 (적당한 볼륨)
        try:
            explosion_sound = pygame.mixer.Sound(resource_path(os.path.join("sounds", "explosion.wav")))
            explosion_sound.set_volume(0.5)  # 0.8 → 0.5로 줄임
            explosion_sound.play()
        except:
            pass
        
        # 비행기 사운드 중지
        self.stop_sound()
        self.is_crashing = False
        self.crash_velocity_y = 0
        self.exploded = True
        
    
    def stop_sound(self):
        """비행기 사운드 중지"""
        if self.sound_channel:
            self.sound_channel.stop()
            self.sound_channel = None

    def _update_particles(self):
        # 연기 파티클 업데이트
        for particle in self.smoke_particles[:]:
            particle['x'] += particle['vx']
            particle['y'] += particle['vy']
            particle['vy'] -= 0.1  # 연기는 위로 올라감
            particle['life'] -= 1
            particle['size'] += 0.3  # 연기가 퍼짐
            particle['alpha'] = max(0, particle['alpha'] - 2)

            if particle['life'] <= 0 or particle['alpha'] <= 0:
                self.smoke_particles.remove(particle)

        # 폭발 파티클 업데이트
        for particle in self.explosion_particles[:]:
            particle['x'] += particle['vx']
            particle['y'] += particle['vy']
            particle['vy'] += 0.3  # 중력
            particle['life'] -= 1

            if particle['life'] <= 0:
                self.explosion_particles.remove(particle)

        # 파편 파티클 업데이트
        for particle in self.debris_particles[:]:
            particle['x'] += particle['vx']
            particle['y'] += particle['vy']
            particle['vy'] += 0.5  # 파편은 중력 영향 더 받음
            particle['rotation'] += particle['rotation_speed']
            particle['life'] -= 1

            # 바닥에 닿으면 튀어오름
            if particle['y'] > self.screen_height - 60 and particle['vy'] > 0:
                particle['vy'] *= -0.6  # 에너지 손실과 함께 튀어오름
                particle['vx'] *= 0.8

            if particle['life'] <= 0:
                self.debris_particles.remove(particle)

    def draw(self, screen):
        """비행기 그리기 - Fi 156 Storch 스타일 군용 경비행기"""
        if not self.active:
            return
            
        # 무적 상태일 때 깜빡임 효과
        if self.spawn_timer < self.invulnerable_time:
            # 4프레임마다 깜빡임
            if (self.spawn_timer // 4) % 2 == 0:
                return  # 깜빡임으로 무적 상태 표시
            
        # 연기 파티클 그리기 (뒤쪽에 그려서 비행기 뒤에 나타나게)
        for particle in self.smoke_particles:
            smoke_surf = pygame.Surface((particle['size'] * 2, particle['size'] * 2), pygame.SRCALPHA)
            alpha = int(particle['alpha'])
            smoke_color = (80, 80, 80, alpha)
            pygame.draw.circle(smoke_surf, smoke_color, 
                             (particle['size'], particle['size']), 
                             particle['size'])
            screen.blit(smoke_surf, 
                       (int(particle['x'] - particle['size']), 
                        int(particle['y'] - particle['size'])))
        
        # 현실적인 파편 파티클 그리기
        for particle in self.debris_particles:
            # 파편 타입에 따라 다른 모양으로 그리기
            fragment_type = particle.get('type', 'chunk')
            
            if fragment_type == 'shard':  # 날카로운 파편 - 삼각형
                debris_surf = pygame.Surface((particle['width'] * 4, particle['height'] * 4), pygame.SRCALPHA)
                center_x = particle['width'] * 2
                center_y = particle['height'] * 2
                points = [
                    (center_x, center_y - particle['height']),  # 위쪽 끝
                    (center_x - particle['width']//2, center_y + particle['height']//2),  # 왼쪽 아래
                    (center_x + particle['width']//2, center_y + particle['height']//2)   # 오른쪽 아래
                ]
                pygame.draw.polygon(debris_surf, particle['color'], points)
                
            elif fragment_type == 'wire':  # 전선 - 얇은 직선
                debris_surf = pygame.Surface((particle['width'] * 4, particle['height'] * 4), pygame.SRCALPHA)
                center_x = particle['width'] * 2
                center_y = particle['height'] * 2
                pygame.draw.rect(debris_surf, particle['color'], 
                               (center_x - particle['width']//2, center_y - particle['height']//2,
                                particle['width'], particle['height']))
                
            elif fragment_type == 'plate':  # 판금 - 평평한 사각형
                debris_surf = pygame.Surface((particle['width'] * 3, particle['height'] * 3), pygame.SRCALPHA)
                center_x = particle['width'] * 1.5
                center_y = particle['height'] * 1.5
                # 테두리가 있는 사각형
                pygame.draw.rect(debris_surf, particle['color'], 
                               (center_x - particle['width']//2, center_y - particle['height']//2,
                                particle['width'], particle['height']))
                # 가장자리 강조
                edge_color = tuple(min(255, c + 30) for c in particle['color'])
                pygame.draw.rect(debris_surf, edge_color, 
                               (center_x - particle['width']//2, center_y - particle['height']//2,
                                particle['width'], particle['height']), 1)
                
            else:  # chunk - 불규칙한 덩어리
                debris_surf = pygame.Surface((particle['width'] * 3, particle['height'] * 3), pygame.SRCALPHA)
                center_x = particle['width'] * 1.5
                center_y = particle['height'] * 1.5
                # 불규칙한 다각형 모양
                points = []
                for i in range(6):  # 6각형 기반
                    angle = i * 60 + particle['rotation']
                    radius = random.uniform(particle['width'] * 0.3, particle['width'] * 0.7)
                    x = center_x + radius * math.cos(math.radians(angle))
                    y = center_y + radius * math.sin(math.radians(angle))
                    points.append((x, y))
                pygame.draw.polygon(debris_surf, particle['color'], points)
            
            # 회전 적용
            rotated_debris = pygame.transform.rotate(debris_surf, particle['rotation'])
            debris_x = int(particle['x'] - rotated_debris.get_width() // 2)
            debris_y = int(particle['y'] - rotated_debris.get_height() // 2)
            screen.blit(rotated_debris, (debris_x, debris_y))
            
        # 현실적인 화염 파티클 그리기
        for particle in self.explosion_particles:
            # 화염 모양을 위한 불규칙한 원형
            flame_surf = pygame.Surface((particle['size'] * 3, particle['size'] * 3), pygame.SRCALPHA)
            center_x = particle['size'] * 1.5
            center_y = particle['size'] * 1.5
            
            # 화염의 핵심부 (밝은 색)
            core_size = max(2, particle['size'] // 2)
            core_color = tuple(min(255, c + 50) for c in particle['color'])
            pygame.draw.circle(flame_surf, core_color, (int(center_x), int(center_y)), core_size)
            
            # 화염의 외곽부 (어두운 색)
            outer_size = particle['size']
            # 화염 모양을 위한 여러 개의 작은 원들
            for i in range(3):
                offset_x = random.randint(-2, 2)
                offset_y = random.randint(-2, 2)
                flame_size = max(1, outer_size - i * 2)
                flame_alpha = max(50, 255 - i * 60)
                
                if len(particle['color']) == 3:
                    flame_color = particle['color'] + (flame_alpha,)
                else:
                    flame_color = particle['color'][:3] + (flame_alpha,)
                    
                flame_pos = (int(center_x + offset_x), int(center_y + offset_y))
                pygame.draw.circle(flame_surf, flame_color, flame_pos, flame_size)
            
            flame_x = int(particle['x'] - flame_surf.get_width() // 2)
            flame_y = int(particle['y'] - flame_surf.get_height() // 2)
            screen.blit(flame_surf, (flame_x, flame_y))
            
        # 추락 중일 때는 회전된 비행기 그리기
        if self.is_crashing:
            # 추락 중 추가 연기 효과 (비행기에서 나오는 검은 연기)
            trail_length = min(5, int(self.crash_velocity_y))
            for i in range(trail_length):
                trail_alpha = max(20, 80 - i * 15)
                trail_size = 8 + i * 2
                trail_surf = pygame.Surface((trail_size * 2, trail_size * 2), pygame.SRCALPHA)
                pygame.draw.circle(trail_surf, (40, 40, 40, trail_alpha), 
                                 (trail_size, trail_size), trail_size)
                trail_y = self.y - i * 10 - self.height // 2
                screen.blit(trail_surf, 
                          (int(self.x + self.width // 2 - trail_size), 
                           int(trail_y)))

        if self.exploded:
            return

        # 색상 정의
        fuselage_color = (120, 120, 100)  # 밝은 카키색 동체
        dark_green = (60, 80, 60)  # 진한 녹색
        canopy_color = (180, 200, 220)  # 밝은 청회색 (캐노피)
        strut_color = (80, 80, 80)  # 회색 (지지대)
        black = (30, 30, 30)
        
        # 추락 중일 때 회전 각도 적용
        if self.is_crashing:
            # 회전을 위한 임시 Surface 생성
            temp_surf = pygame.Surface((self.width + 40, self.height + 40), pygame.SRCALPHA)
            # 임시 Surface의 중심에 비행기를 그리기
            draw_x = 20
            draw_y = 20
        else:
            temp_surf = None
            draw_x = self.x
            draw_y = self.y
        
        if self.direction == "left_to_right":
            # === 왼쪽에서 오른쪽으로 비행 ===
            
            # 메인 날개 (높은 위치의 직선형 날개)
            draw_surface = temp_surf if self.is_crashing else screen
            pygame.draw.polygon(draw_surface, fuselage_color, [
                (draw_x + 15, draw_y),
                (draw_x + 65, draw_y),
                (draw_x + 65, draw_y + 8),
                (draw_x + 15, draw_y + 8)
            ])
            
            # 날개 지지대 (특징적인 스트럿)
            for i in range(2):
                strut_x = draw_x + 25 + i * 20
                pygame.draw.line(draw_surface, strut_color, 
                               (strut_x, draw_y + 8), 
                               (strut_x - 3, draw_y + 20), 2)
            
            # 동체 (가늘고 긴 형태)
            pygame.draw.polygon(draw_surface, fuselage_color, [
                (draw_x + 5, draw_y + 15),
                (draw_x + 75, draw_y + 12),
                (draw_x + 75, draw_y + 23),
                (draw_x + 5, draw_y + 20)
            ])
            
            # 조종석 캐노피 (높고 큰 창문)
            pygame.draw.polygon(draw_surface, canopy_color, [
                (draw_x + 40, draw_y + 10),
                (draw_x + 55, draw_y + 10),
                (draw_x + 55, draw_y + 18),
                (draw_x + 40, draw_y + 18)
            ])
            
            # 꼬리날개 (수직/수평 안정판)
            pygame.draw.polygon(draw_surface, dark_green, [
                (draw_x, draw_y + 12),
                (draw_x + 15, draw_y + 15),
                (draw_x + 15, draw_y + 20),
                (draw_x, draw_y + 23)
            ])
            
            # 프로펠러
            prop_x = draw_x + 78
            prop_y = draw_y + 17
            # 프로펠러 블레이드 (회전 효과)
            angle = pygame.time.get_ticks() * 0.5
            for i in range(3):
                blade_angle = angle + i * 120
                end_x = prop_x + int(8 * math.cos(math.radians(blade_angle)))
                end_y = prop_y + int(8 * math.sin(math.radians(blade_angle)))
                pygame.draw.line(draw_surface, black, (prop_x, prop_y), (end_x, end_y), 2)
            
            # 랜딩기어 (고정식)
            pygame.draw.line(draw_surface, black, (draw_x + 35, draw_y + 23), (draw_x + 35, draw_y + 28), 2)
            pygame.draw.line(draw_surface, black, (draw_x + 50, draw_y + 23), (draw_x + 50, draw_y + 28), 2)
            pygame.draw.circle(draw_surface, black, (draw_x + 35, draw_y + 29), 2)
            pygame.draw.circle(draw_surface, black, (draw_x + 50, draw_y + 29), 2)
            
        else:
            # === 오른쪽에서 왼쪽으로 비행 (좌우 반전) ===
            draw_surface = temp_surf if self.is_crashing else screen
            
            # 메인 날개
            pygame.draw.polygon(draw_surface, fuselage_color, [
                (draw_x + 15, draw_y),
                (draw_x + 65, draw_y),
                (draw_x + 65, draw_y + 8),
                (draw_x + 15, draw_y + 8)
            ])
            
            # 날개 지지대
            for i in range(2):
                strut_x = draw_x + 35 + i * 20
                pygame.draw.line(draw_surface, strut_color, 
                               (strut_x, draw_y + 8), 
                               (strut_x + 3, draw_y + 20), 2)
            
            # 동체
            pygame.draw.polygon(draw_surface, fuselage_color, [
                (draw_x + 75, draw_y + 15),
                (draw_x + 5, draw_y + 12),
                (draw_x + 5, draw_y + 23),
                (draw_x + 75, draw_y + 20)
            ])
            
            # 조종석 캐노피
            pygame.draw.polygon(draw_surface, canopy_color, [
                (draw_x + 25, draw_y + 10),
                (draw_x + 40, draw_y + 10),
                (draw_x + 40, draw_y + 18),
                (draw_x + 25, draw_y + 18)
            ])
            
            # 꼬리날개
            pygame.draw.polygon(draw_surface, dark_green, [
                (draw_x + 80, draw_y + 12),
                (draw_x + 65, draw_y + 15),
                (draw_x + 65, draw_y + 20),
                (draw_x + 80, draw_y + 23)
            ])
            
            # 프로펠러
            prop_x = draw_x + 2
            prop_y = draw_y + 17
            angle = pygame.time.get_ticks() * 0.5
            for i in range(3):
                blade_angle = angle + i * 120
                end_x = prop_x + int(8 * math.cos(math.radians(blade_angle)))
                end_y = prop_y + int(8 * math.sin(math.radians(blade_angle)))
                pygame.draw.line(draw_surface, black, (prop_x, prop_y), (end_x, end_y), 2)
            
            # 랜딩기어
            pygame.draw.line(draw_surface, black, (draw_x + 30, draw_y + 23), (draw_x + 30, draw_y + 28), 2)
            pygame.draw.line(draw_surface, black, (draw_x + 45, draw_y + 23), (draw_x + 45, draw_y + 28), 2)
            pygame.draw.circle(draw_surface, black, (draw_x + 30, draw_y + 29), 2)
            pygame.draw.circle(draw_surface, black, (draw_x + 45, draw_y + 29), 2)
        
        # 추락 중이면 회전하여 그리기
        if self.is_crashing:
            # 비행기를 회전시킨 후 화면에 그리기
            rotated_surf = pygame.transform.rotate(temp_surf, self.crash_rotation)
            # 회전 후 위치 조정 (중심을 맞추기 위해)
            rot_rect = rotated_surf.get_rect(center=(self.x + self.width // 2, self.y + self.height // 2))
            screen.blit(rotated_surf, rot_rect)

