def _ensure_berserk_aura_surface() -> pygame.Surface:
    """광폭 오오라 렌더링용 서피스를 지연 생성"""
    global berserk_aura_surface
    if berserk_aura_surface is None:
        berserk_aura_surface = pygame.Surface(BERSERK_AURA_SIZE, pygame.SRCALPHA)
    return berserk_aura_surface


def activate_berserk_potion(duration_frames: int | None = None, *, play_sound: bool = True) -> None:
    """광폭물약 효과 활성화"""
    global berserk_potion_active, berserk_potion_timer

    frames = duration_frames if duration_frames is not None else BERSERK_POTION_DURATION_FRAMES
    frames = max(0, frames)

    berserk_potion_active = True
    berserk_potion_timer = frames
    # 가로형 게이지 스택 등록
    try:
        _hg_on_activate('berserk_potion')
    except Exception:
        pass

    gm = _get_global_manager()
    gm.set('berserk_potion_active', True)
    gm.set('berserk_potion_timer_frames', frames)
    gm.set('berserk_potion_duration_frames', BERSERK_POTION_DURATION_FRAMES)
    gm.set('berserk_potion_refresh', False)

    if play_sound:
        try:
            play_sound_with_volume(SOUND_DRINK)
        except Exception:  # noqa: BLE001
            fallback_sound = gm.get('SOUND_ACTIVE_ITEM')
            if fallback_sound:
                try:
                    fallback_sound.play()
                except Exception:  # noqa: BLE001
                    pass


def deactivate_berserk_potion() -> None:
    """광폭물약 효과 비활성화"""
    global berserk_potion_active, berserk_potion_timer

    if not berserk_potion_active and berserk_potion_timer == 0:
        return

    berserk_potion_active = False
    berserk_potion_timer = 0
    # 가로형 게이지 스택에서 제거
    try:
        _hg_on_deactivate('berserk_potion')
    except Exception:
        pass

    gm = _get_global_manager()
    gm.set('berserk_potion_active', False)
    gm.set('berserk_potion_timer_frames', 0)


def sync_berserk_potion_from_global_manager() -> None:
    """외부 시스템에서 요청된 광폭물약 상태를 동기화"""
    gm = _get_global_manager()
    refresh_requested = gm.get('berserk_potion_refresh', False)
    gm_active = gm.get('berserk_potion_active', False)
    gm_timer = gm.get('berserk_potion_timer_frames', 0)

    if refresh_requested or (gm_active and not berserk_potion_active):
        activate_berserk_potion(gm_timer if gm_timer else BERSERK_POTION_DURATION_FRAMES, play_sound=False)
        gm.set('berserk_potion_refresh', False)
    elif not gm_active and berserk_potion_active:
        deactivate_berserk_potion()


def get_blacksmith_construction_speed_multiplier() -> float:
    """발토르 건설/업그레이드 진행 배수를 반환"""
    return BERSERK_POTION_BUILD_MULTIPLIER if berserk_potion_active and berserk_potion_timer > 0 else 1.0


def get_blacksmith_manual_cooldown_multiplier() -> float:
    """발토르 포탑 수동 발사 쿨다운 배수를 반환"""
    return BERSERK_POTION_MANUAL_COOLDOWN_MULTIPLIER if berserk_potion_active and berserk_potion_timer > 0 else 1.0


def get_blacksmith_turret_charge_speed_multiplier() -> float:
    """발토르 포탑 수동 게이지 충전 속도 배수를 반환"""
    if (
        selected_character_type == "blacksmith"
        and berserk_potion_active
        and berserk_potion_timer > 0
    ):
        return BERSERK_POTION_TURRET_CHARGE_SPEED_MULTIPLIER
    return 1.0


def _apply_blacksmith_berserk_gauge_bonus(amount: int) -> int:
    """광폭물약 발동 중 발토르 게이지 충전량 배수를 적용"""
    if (
        selected_character_type == "blacksmith"
        and berserk_potion_active
        and berserk_potion_timer > 0
    ):
        return max(1, int(math.ceil(amount * BERSERK_POTION_GAUGE_GAIN_MULTIPLIER)))
    return amount


def draw_berserk_aura(surface: pygame.Surface, center: tuple[int, int]) -> None:
    """광폭물약 활성화 시 붉은 화염 오오라를 그린다."""
    aura_surface = _ensure_berserk_aura_surface()
    aura_surface.fill((0, 0, 0, 0))

    ticks = pygame.time.get_ticks()
    base_radius = 56

    for layer in range(4):
        phase = (ticks * 0.0025) + layer * 1.1
        sine = math.sin(phase)
        radius = max(18, base_radius - layer * 10 + sine * 4)
        offset_y = int(sine * 8)
        color = (
            min(255, 210 + layer * 10),
            max(0, 70 + layer * 35),
            max(0, 20 + layer * 25),
            70 + layer * 40,
        )
        pygame.draw.circle(
            aura_surface,
            color,
            (BERSERK_AURA_SIZE[0] // 2, BERSERK_AURA_SIZE[1] // 2 + offset_y),
            int(radius),
        )

    glow_strength = (math.sin(ticks * 0.01) + 1.0) * 0.5
    pygame.draw.circle(
        aura_surface,
        (255, 180, 110, int(180 * glow_strength)),
        (BERSERK_AURA_SIZE[0] // 2, BERSERK_AURA_SIZE[1] // 2),
        22,
    )

    dest_x = int(center[0] - BERSERK_AURA_SIZE[0] / 2)
    dest_y = int(center[1] - BERSERK_AURA_SIZE[1] / 2)
    surface.blit(aura_surface, (dest_x, dest_y), special_flags=pygame.BLEND_ADD)


def soldier_switch_weapon(index: int, *, play_sound: bool = True) -> str:
    """코만도 화기 인덱스 변경 및 관련 장비 상태 정리"""
    global soldier_controller
    global fire_support_slot_restore_pending, fire_support_slot_restore_index

    if not soldier_controller.weapons:
        return "pistol"

    safe_index = max(0, min(index, len(soldier_controller.weapons) - 1))
    soldier_controller.set_current_weapon(safe_index)
    soldier_controller.switch_cooldown = soldier_controller.switch_cooldown_frames
    soldier_controller.ui_highlight_timer = soldier_controller.ui_highlight_duration

    current_weapon = soldier_controller.weapons[soldier_controller.current_index]
    # 교체 직후 발사 억제 프레임 부여(잔류 좌클릭/SPACE를 흡수)
    global soldier_weapon_switch_suppress_frames
    soldier_weapon_switch_suppress_frames = max(soldier_weapon_switch_suppress_frames, 3)

    fire_support_weapon = get_fire_support_instance()
    if current_weapon == "bazooka":
        from item_effects.bazooka import get_bazooka_instance

        bazooka = get_bazooka_instance()
        if bazooka:
            bazooka.equip()
        if "net_gun" in soldier_controller.weapons:
            net = get_net_gun_instance()
            if hasattr(net, "unequip"):
                net.unequip()
        fire_support_weapon.unequip()
    elif current_weapon == "pistol":
        if "bazooka" in soldier_controller.weapons:
            from item_effects.bazooka import get_bazooka_instance

            bazooka = get_bazooka_instance()
            if bazooka and hasattr(bazooka, "unequip"):
                bazooka.unequip()
        if "ak47" in soldier_controller.weapons:
            ak47 = get_ak47_instance()
            if ak47 and (ak47.remaining_time > 0 or ak47.current_ammo > 0 or ak47.bullets):
                ak47.active = True
        if "net_gun" in soldier_controller.weapons:
            net = get_net_gun_instance()
            if hasattr(net, "unequip"):
                net.unequip()
        fire_support_weapon.unequip()
    elif current_weapon == "ak47":
        if "bazooka" in soldier_controller.weapons:
            from item_effects.bazooka import get_bazooka_instance

            bazooka = get_bazooka_instance()
            if bazooka and hasattr(bazooka, "unequip"):
                bazooka.unequip()
        ak47 = get_ak47_instance()
        if ak47 and (ak47.remaining_time > 0 or ak47.current_ammo > 0 or ak47.bullets):
            ak47.active = True
        if "net_gun" in soldier_controller.weapons:
            net = get_net_gun_instance()
            if hasattr(net, "unequip"):
                net.unequip()
        fire_support_weapon.unequip()
    elif current_weapon == "net_gun":
        net = get_net_gun_instance()
        if net and hasattr(net, "equip"):
            net.equip()
        if "bazooka" in soldier_controller.weapons:
            from item_effects.bazooka import get_bazooka_instance

            bazooka = get_bazooka_instance()
            if bazooka and hasattr(bazooka, "unequip"):
                bazooka.unequip()
        if "ak47" in soldier_controller.weapons:
            ak47 = get_ak47_instance()
            if ak47 and (ak47.remaining_time > 0 or ak47.current_ammo > 0 or ak47.bullets):
                ak47.active = True
        fire_support_weapon.unequip()
    elif current_weapon == "fire_support":
        if fire_support_weapon.is_locked():
            # 폭격 진행 중에도 슬롯을 유지해 HUD 애니메이션과 상태 확인을 허용한다.
            soldier_controller.switch_cooldown = 0
            soldier_controller.ui_highlight_timer = soldier_controller.ui_highlight_duration
        fire_support_weapon.equip()
        if "bazooka" in soldier_controller.weapons:
            from item_effects.bazooka import get_bazooka_instance

            bazooka = get_bazooka_instance()
            if bazooka and hasattr(bazooka, "unequip"):
                bazooka.unequip()
        if "net_gun" in soldier_controller.weapons:
            net = get_net_gun_instance()
            if hasattr(net, "unequip"):
                net.unequip()
        ak47 = get_ak47_instance()
        if ak47:
            # 주의: AK-47은 활성 상태(active)가 총알 시스템의 업데이트/렌더 조건으로 사용된다.
            # 기존에는 화기류를 fire_support로 전환할 때 active를 False로 내려
            # 남아 있는 탄환이 화면에서 사라지고, 잔탄이 있어도 즉시 "비활성"처럼 보이는 버그가 발생했다.
            # active는 "보유/유효" 상태를 의미하도록 유지하고, 무기 전환은 equip 개념만 다루도록 한다.
            # 따라서 여기서는 강제 비활성화를 수행하지 않는다.
            # (잔탄이 0이고 내구도까지 소진되면 item_effects.ak47.update() 내부에서 안전하게 비활성화됨)
            pass

    if current_weapon != "fire_support":
        fire_support_slot_restore_pending = False
        fire_support_slot_restore_index = None

    print(f"🔄 화기 교체: {current_weapon}")

    if play_sound:
        try:
            switch_sound = pygame.mixer.Sound(resource_path("sounds/weapon_switch.wav"))
            switch_sound.set_volume(0.3)
            switch_sound.play()
        except Exception:
            pass

    return current_weapon


# === 자폭드론 조작/폭발 유틸리티 ===
def _reset_suicide_drone_state() -> None:
    globals()['suicide_drone_active'] = False
    globals()['suicide_drone_rect'] = None
    globals()['suicide_drone_player_lock'] = None
    globals()['suicide_drone_grace_timer'] = 0
    globals()['suicide_drone_vel'] = [0.0, 0.0]
    globals()['suicide_drone_rotor_angle'] = 0.0


def _launch_suicide_drone() -> bool:
    """자폭드론을 발진시킨다. 탄환 1개 소모, 플레이어 위치에 생성."""
    global soldier_drone_ammo, suicide_drone_active, suicide_drone_rect, suicide_drone_player_lock, suicide_drone_vel, suicide_drone_rotor_angle
    global suicide_drone_ball_speed_backup, suicide_drone_ball_boost_active
    if suicide_drone_active or soldier_drone_ammo <= 0:
        return False
    drone_size = 48  # 기존 대비 2배 크기
    suicide_drone_rect = pygame.Rect(
        PLAYER.centerx - drone_size // 2,
        PLAYER.top - drone_size - 6,
        drone_size,
        drone_size,
    )
    soldier_drone_ammo = max(0, soldier_drone_ammo - 1)
    suicide_drone_active = True
    suicide_drone_player_lock = (PLAYER.centerx, PLAYER.centery)
    globals()['suicide_drone_grace_timer'] = SUICIDE_DRONE_GRACE_FRAMES
    suicide_drone_vel = [0.0, 0.0]
    suicide_drone_rotor_angle = 0.0
    return True


def _spawn_drone_fire_zone(cx: float, cy: float) -> None:
    """자폭드론 폭발 후 화염 궤적(화염병과 동일 규격)을 남긴다."""
    import items
    base_width = 150
    base_height = 60
    fire_width = int(base_width * (1.1 if items.commando_arm_obtained else 1.0))
    fire_height = int(base_height * (1.1 if items.commando_arm_obtained else 1.0))
    fire_zone = {
        "x": cx,
        "y": cy,
        "width": fire_width,
        "height": fire_height,
        "duration": 150,  # 2.5초
        "flames": [],
        "spread_timer": 0,
        "push_timer": 0,
    }
    for _ in range(15):
        flame = {
            "x": cx + random.uniform(-30, 30),
            "y": cy + random.uniform(-10, 10),
            "size": random.uniform(8, 20),
            "lifetime": random.uniform(20, 40),
            "color_phase": random.uniform(0, 1),
        }
        fire_zone["flames"].append(flame)
    fire_zones.append(fire_zone)


def _detonate_suicide_drone(reason: str = "manual") -> None:
    """자폭드론 폭발 처리"""
    global suicide_drone_active, suicide_drone_rect, suicide_drone_player_lock, boss_stunned_timer
    global suicide_drone_ball_speed_backup, suicide_drone_ball_boost_active
    if not suicide_drone_active or suicide_drone_rect is None:
        return
    cx, cy = suicide_drone_rect.center
    try:
        trigger_grenade_style_explosion(cx, cy, apply_commando_bonus=False, source="suicide_drone", radius_scale=1.0)
    except Exception:
        pass
    # 보스가 폭발 반경 내에 있을 때만 스턴 적용
    try:
        if 'BOSS' in globals() and BOSS is not None:
            bx, by = get_center_pos(BOSS)
            explosion_radius = 150  # suicide_drone은 radius_scale=1.0, 코만도암 보너스 미적용
            if calculate_distance((bx, by), (cx, cy)) <= explosion_radius:
                boss_stunned_timer = max(boss_stunned_timer, int(0.8 * 60))
    except Exception:
        pass
    _spawn_drone_fire_zone(cx, cy)
    # ball_hit 시에는 공속 복원 정보 유지, 그 외에는 즉시 초기화
    if reason != "ball_hit":
        suicide_drone_ball_speed_backup = 0.0
        suicide_drone_ball_boost_active = False
    _reset_suicide_drone_state()
    # 무기 전환 중복 입력을 막기 위해 짧은 쿨다운
    soldier_controller.switch_cooldown = max(soldier_controller.switch_cooldown, soldier_controller.switch_cooldown_frames // 2)


def update_suicide_drone(keys, manual_trigger_edge: bool, mouse_pressed_edge: bool = False) -> None:
    """자폭드론 조종 및 충돌 체크"""
    if not suicide_drone_active or suicide_drone_rect is None:
        return
    global suicide_drone_ball_speed_backup, suicide_drone_ball_boost_active
    # 입력 벡터
    dx = (-1 if is_move_left_pressed(keys) else 0) + (1 if is_move_right_pressed(keys) else 0)
    dy = (-1 if is_move_up_pressed(keys) else 0) + (1 if is_move_down_pressed(keys) else 0)
    # 가속 기반 이동
    if dx == 0 and dy == 0:
        # 감속
        suicide_drone_vel[0] *= 0.90
        suicide_drone_vel[1] *= 0.90
        if abs(suicide_drone_vel[0]) < 0.05:
            suicide_drone_vel[0] = 0.0
        if abs(suicide_drone_vel[1]) < 0.05:
            suicide_drone_vel[1] = 0.0
    else:
        if dx != 0 and dy != 0:
            dx *= 0.7071
            dy *= 0.7071
        suicide_drone_vel[0] += dx * SUICIDE_DRONE_ACCEL
        suicide_drone_vel[1] += dy * SUICIDE_DRONE_ACCEL
        # 최고속 제한
        speed = (suicide_drone_vel[0] ** 2 + suicide_drone_vel[1] ** 2) ** 0.5
        if speed > SUICIDE_DRONE_MAX_SPEED:
            scale = SUICIDE_DRONE_MAX_SPEED / speed
            suicide_drone_vel[0] *= scale
            suicide_drone_vel[1] *= scale

    suicide_drone_rect.x += int(suicide_drone_vel[0])
    suicide_drone_rect.y += int(suicide_drone_vel[1])

    # 로터 속도는 현재 속도에 따라 가변
    speed_now = (suicide_drone_vel[0] ** 2 + suicide_drone_vel[1] ** 2) ** 0.5
    globals()['suicide_drone_rotor_speed'] = 18.0 + min(20.0, speed_now * 2.0)
    # 화면 경계 클램프
    suicide_drone_rect.clamp_ip(pygame.Rect(0, 0, WIDTH, HEIGHT))

    # 로터 애니메이션
    globals()['suicide_drone_rotor_angle'] = (globals().get('suicide_drone_rotor_angle', 0.0) + suicide_drone_rotor_speed) % 360

    # 플레이어는 제자리 고정
    if suicide_drone_player_lock:
        PLAYER.centerx, PLAYER.centery = suicide_drone_player_lock

    if globals().get('suicide_drone_grace_timer', 0) > 0:
        globals()['suicide_drone_grace_timer'] -= 1

    # 수동 폭발 입력 (에지 트리거 + 그레이스 이후)
    if globals().get('suicide_drone_grace_timer', 0) <= 0 and (manual_trigger_edge or mouse_pressed_edge):
        _detonate_suicide_drone("manual")
        return

    # 보스 충돌 시 즉시 폭발
    try:
        if globals().get('suicide_drone_grace_timer', 0) <= 0 and suicide_drone_rect.colliderect(BOSS):
            _detonate_suicide_drone("boss_hit")
            return
    except Exception:
        pass

    # 공과 충돌 시: 공 속도/각도 부채꼴 가속 후 폭발
    try:
        if globals().get('suicide_drone_grace_timer', 0) <= 0 and suicide_drone_rect.colliderect(BALL):
            # 원래 속도 백업 (보스 반격 시 복원용)
            original_speed = math.hypot(ball_vel[0], ball_vel[1]) if ball_vel else 0.0
            suicide_drone_ball_speed_backup = original_speed
            suicide_drone_ball_boost_active = True

            print(f"[DRONE] 공 충돌: 원속도 {original_speed:.2f} -> 3.0배 가속")

            # 가속 및 방향 재설정: 보스(위쪽) 방향으로 좁은 부채꼴 랜덤 (거의 수직)
            base_speed = original_speed if original_speed > 0 else BALL_BASE_SPEED
            boosted_speed = base_speed * 3.0
            angle_deg = random.uniform(-25, 25)  # 좌우 25도 범위로 더 수직에 가깝게
            rad = math.radians(angle_deg)
            ball_vel[0] = boosted_speed * math.sin(rad)
            ball_vel[1] = -abs(boosted_speed * math.cos(rad))  # 항상 보스(위) 방향
            try:
                game_vars.ball.vel[0] = ball_vel[0]
                game_vars.ball.vel[1] = ball_vel[1]
            except Exception:
                pass
            print(f"[DRONE] 가속 후 속도 {boosted_speed:.2f}, 각도 {angle_deg:.1f}°, vel=({ball_vel[0]:.2f},{ball_vel[1]:.2f})")
            _detonate_suicide_drone("ball_hit")
            return
    except Exception:
        pass

    # 보스 뒷벽(상단) 충돌 시 폭발: 공 실점 라인과 동일하게 화면 상단에 닿으면 폭발
    try:
        if globals().get('suicide_drone_grace_timer', 0) <= 0 and suicide_drone_rect.top <= 0:
            _detonate_suicide_drone("boss_back_wall")
            return
    except Exception:
        pass
    


def apply_fire_support_slot_restore() -> None:
    """화력지원 호출 중 UI 슬롯이 다른 무기로 튀지 않도록 보호한다."""
    global soldier_controller
    global fire_support_slot_restore_pending, fire_support_slot_restore_index
    global player_up_pressed, soldier_weapon_menu_active

    if not fire_support_slot_restore_pending:
        return

    if 'soldier_controller' not in globals() or soldier_controller is None:
        fire_support_slot_restore_pending = False
        fire_support_slot_restore_index = None
        return

    try:
        weapons = soldier_controller.weapons
        current_index = soldier_controller.current_index
    except AttributeError:
        fire_support_slot_restore_pending = False
        fire_support_slot_restore_index = None
        return

    restore_index = fire_support_slot_restore_index
    if restore_index is None or not weapons or not (0 <= restore_index < len(weapons)):
        fire_support_slot_restore_pending = False
        fire_support_slot_restore_index = None
        return

    if weapons[restore_index] != "fire_support":
        fire_support_slot_restore_pending = False
        fire_support_slot_restore_index = None
        return

    fire_support_weapon = get_fire_support_instance()
    if not fire_support_weapon.is_active() and not fire_support_weapon.is_locked():
        fire_support_slot_restore_pending = False
        fire_support_slot_restore_index = None
        return

    player_forcing_switch = player_up_pressed or soldier_weapon_menu_active
    if player_forcing_switch and current_index != restore_index:
        fire_support_slot_restore_pending = False
        fire_support_slot_restore_index = None
        return

    if current_index != restore_index:
        soldier_controller.set_current_weapon(restore_index)
        soldier_controller.ui_highlight_timer = soldier_controller.ui_highlight_duration


def handle_fire_support_lockout() -> None:
    """화력지원 호출 중에도 슬롯을 유지해 UI 애니메이션을 계속 보여준다."""
    global soldier_controller
    global fire_support_slot_restore_pending, fire_support_slot_restore_index

    if 'soldier_controller' not in globals() or soldier_controller is None:
        return

    try:
        weapons = soldier_controller.weapons
        current_index = soldier_controller.current_index
    except AttributeError:
        return

    if not weapons or not (0 <= current_index < len(weapons)):
        return

    if weapons[current_index] != "fire_support":
        return

    fire_support_slot_restore_index = current_index
    fire_support_slot_restore_pending = True
    # 강제로 현재 슬롯을 재적용해 다른 무기로 튀는 것을 방지한다.
    soldier_controller.set_current_weapon(current_index)
    # 화력지원 애니메이션 유지 및 즉시 재전환 허용.
    soldier_controller.switch_cooldown = 0
    soldier_controller.ui_highlight_timer = soldier_controller.ui_highlight_duration


def get_weapon_menu_icon(weapon_name: str, size: int = 40) -> pygame.Surface:
    """병기 선택 HUD에서 사용할 소형 아이콘 Surface 반환"""
    icon_surface = pygame.Surface((size, size), pygame.SRCALPHA)
    custom_only_weapons = {"pistol", "net_gun"}
    if weapon_name not in custom_only_weapons:
        candidate_paths = (
            resource_path(f"items/{weapon_name}.png"),
            resource_path(f"items/legendary/{weapon_name}.png"),
        )
        if any(os.path.exists(path) for path in candidate_paths):
            existing_icon = get_item_icon(weapon_name)
            if existing_icon:
                return pygame.transform.smoothscale(existing_icon, (size, size))

    center = (size // 2, size // 2)

    if weapon_name == "pistol":
        body_rect = pygame.Rect(0, 0, int(size * 0.55), int(size * 0.28))
        body_rect.center = (center[0], center[1] - 4)
        pygame.draw.rect(icon_surface, (70, 70, 70), body_rect, border_radius=3)
        pygame.draw.rect(icon_surface, (110, 110, 110), body_rect, 2, border_radius=3)
        grip_rect = pygame.Rect(0, 0, int(size * 0.18), int(size * 0.35))
        grip_rect.midtop = (body_rect.left + grip_rect.width // 2 + 2, body_rect.bottom - 2)
        pygame.draw.rect(icon_surface, (60, 45, 35), grip_rect, border_radius=2)
        pygame.draw.rect(icon_surface, (30, 25, 20), grip_rect, 1, border_radius=2)
        barrel = pygame.Rect(body_rect.right - 2, body_rect.top + 4, int(size * 0.18), body_rect.height - 8)
        pygame.draw.rect(icon_surface, (120, 120, 120), barrel)

    elif weapon_name == "bazooka":
        tube_rect = pygame.Rect(int(size * 0.08), center[1] - int(size * 0.14), int(size * 0.84), int(size * 0.28))
        pygame.draw.rect(icon_surface, (82, 86, 66), tube_rect, border_radius=4)
        pygame.draw.rect(icon_surface, (52, 56, 44), tube_rect, 2, border_radius=4)
        muzzle_radius = int(size * 0.16)
        muzzle_center = (tube_rect.right, center[1])
        pygame.draw.circle(icon_surface, (40, 40, 40), muzzle_center, muzzle_radius)
        pygame.draw.circle(icon_surface, (18, 18, 18), muzzle_center, muzzle_radius - 3)
        grip_rect = pygame.Rect(int(size * 0.35), center[1] + 2, int(size * 0.16), int(size * 0.18))
        pygame.draw.rect(icon_surface, (55, 55, 55), grip_rect)

    elif weapon_name == "ak47":
        body_rect = pygame.Rect(int(size * 0.1), center[1] - int(size * 0.10), int(size * 0.7), int(size * 0.2))
        pygame.draw.rect(icon_surface, (90, 70, 50), body_rect, border_radius=3)
        pygame.draw.rect(icon_surface, (40, 30, 20), body_rect, 1, border_radius=3)
        barrel_rect = pygame.Rect(body_rect.right, center[1] - 3, int(size * 0.2), 6)
        pygame.draw.rect(icon_surface, (45, 45, 45), barrel_rect)
        stock_points = [
            (body_rect.left - int(size * 0.12), center[1] - int(size * 0.08)),
            (body_rect.left - int(size * 0.22), center[1]),
            (body_rect.left - int(size * 0.12), center[1] + int(size * 0.12)),
            (body_rect.left - int(size * 0.04), center[1] + int(size * 0.10)),
        ]
        pygame.draw.polygon(icon_surface, (82, 60, 32), stock_points)
        mag_points = [
            (body_rect.centerx - 2, center[1] + int(size * 0.02)),
            (body_rect.centerx + int(size * 0.2), center[1] + int(size * 0.18)),
            (body_rect.centerx + int(size * 0.12), center[1] + int(size * 0.26)),
            (body_rect.centerx - int(size * 0.12), center[1] + int(size * 0.16)),
        ]
        pygame.draw.polygon(icon_surface, (60, 45, 30), mag_points)

    elif weapon_name == "net_gun":
        body_rect = pygame.Rect(int(size * 0.15), center[1] - int(size * 0.12), int(size * 0.55), int(size * 0.24))
        pygame.draw.rect(icon_surface, (80, 90, 120), body_rect, border_radius=4)
        pygame.draw.rect(icon_surface, (40, 50, 70), body_rect, 2, border_radius=4)
        net_rect = pygame.Rect(body_rect.right - 4, center[1] - int(size * 0.20), int(size * 0.30), int(size * 0.40))
        pygame.draw.rect(icon_surface, (120, 180, 200, 180), net_rect, border_radius=6)
        for i in range(4):
            pygame.draw.line(icon_surface, (200, 220, 230), (net_rect.left, net_rect.top + i * net_rect.height // 3), (net_rect.right, net_rect.top + i * net_rect.height // 3), 1)
            pygame.draw.line(icon_surface, (200, 220, 230), (net_rect.left + i * net_rect.width // 3, net_rect.top), (net_rect.left + i * net_rect.width // 3, net_rect.bottom), 1)
        grip = pygame.Rect(body_rect.centerx - int(size * 0.06), body_rect.bottom - 2, int(size * 0.12), int(size * 0.18))
        pygame.draw.rect(icon_surface, (55, 55, 70), grip)

    else:
        fallback_rect = pygame.Rect(int(size * 0.2), int(size * 0.2), int(size * 0.6), int(size * 0.6))
        pygame.draw.rect(icon_surface, (90, 100, 110), fallback_rect, border_radius=6)
        pygame.draw.rect(icon_surface, (50, 60, 70), fallback_rect, 2, border_radius=6)

    return icon_surface
