def handle_tears():
    global tears_active, tears_timer, falling_tears
    if not tears_active:
        return
    tears_timer -= 1
    if tears_timer <= 0:
        tears_active = False
        falling_tears = []
        return
    # 스탑워치 활성화 시 눈물 업데이트 중지
    if stopwatch_active and stopwatch_timer > 0:
        return
    
    for tear in falling_tears:
        tear[3] = tear[1]  # 이전 y 저장
        tear[1] += tear[2]
# === 눈물의 비 그리기 함수 ===
def draw_stage3_tail_whip():
    """Stage 3 멘헤라걸 꼬리 채찍 애니메이션 그리기"""
    global stage3_tail_whip_active, stage3_tail_whip_animation_timer, current_stage
    
    if current_stage != 3 or not stage3_tail_whip_active:
        return
    
    # 꼬리 채찍 애니메이션 그리기
    if stage3_tail_whip_animation_timer > 0:
        # 애니메이션 진행도 계산 (0.0 ~ 1.0)
        progress = 1.0 - (stage3_tail_whip_animation_timer / 60.0)
        
        # 화면 중앙 좌표
        center_x = WIDTH // 2
        center_y = HEIGHT // 2
        
        # 꼬리 시작점 (멘헤라걸 위치)
        tail_start_x = center_x
        tail_start_y = center_y - 100
        
        # 꼬리 끝점 (채찍질 애니메이션)
        # 왼쪽에서 오른쪽으로 휘두르는 애니메이션
        angle = -math.pi/2 + (math.pi * progress)  # -90도에서 90도까지
        tail_length = 200
        tail_end_x = tail_start_x + int(tail_length * math.cos(angle))
        tail_end_y = tail_start_y + int(tail_length * math.sin(angle))
        
        # 꼬리 곡선 그리기 (베지어 곡선)
        control_x = tail_start_x + int(tail_length * 0.5 * math.cos(angle - math.pi/4))
        control_y = tail_start_y + int(tail_length * 0.5 * math.sin(angle - math.pi/4))
        
        # 꼬리 그리기 (분홍색 그라데이션)
        num_segments = 20
        for i in range(num_segments):
            t1 = i / num_segments
            t2 = (i + 1) / num_segments
            
            # 베지어 곡선 계산
            x1 = int((1-t1)**2 * tail_start_x + 2*(1-t1)*t1 * control_x + t1**2 * tail_end_x)
            y1 = int((1-t1)**2 * tail_start_y + 2*(1-t1)*t1 * control_y + t1**2 * tail_end_y)
            x2 = int((1-t2)**2 * tail_start_x + 2*(1-t2)*t2 * control_x + t2**2 * tail_end_x)
            y2 = int((1-t2)**2 * tail_start_y + 2*(1-t2)*t2 * control_y + t2**2 * tail_end_y)
            
            # 꼬리 두께 (끝으로 갈수록 얇아짐)
            thickness = int(8 * (1 - t1))
            if thickness > 0:
                # 분홍색 그라데이션
                color_intensity = int(255 * (1 - t1 * 0.5))
                color = (255, color_intensity, 200 + int(55 * t1))
                pygame.draw.line(SCREEN, color, (x1, y1), (x2, y2), thickness)
        
        # 채찍 효과 (반짝임)
        if stage3_tail_whip_animation_timer == 30:  # 충돌 시점
            # 충격파 효과
            for radius in range(20, 100, 20):
                alpha = int(255 * (1 - radius / 100))
                impact_surf = pygame.Surface((radius * 2, radius * 2), pygame.SRCALPHA)
                pygame.draw.circle(impact_surf, (255, 100, 200, alpha), (radius, radius), radius, 2)
                SCREEN.blit(impact_surf, (tail_end_x - radius, tail_end_y - radius))
        
        # 꼬리 끝 장식 (하트 모양)
        if thickness > 2:
            heart_size = 15
            heart_surf = pygame.Surface((heart_size * 2, heart_size * 2), pygame.SRCALPHA)
            # 하트 그리기
            pygame.draw.circle(heart_surf, (255, 100, 200), (heart_size // 2, heart_size // 2), heart_size // 2)
            pygame.draw.circle(heart_surf, (255, 100, 200), (heart_size + heart_size // 2, heart_size // 2), heart_size // 2)
            pygame.draw.polygon(heart_surf, (255, 100, 200), 
                               [(0, heart_size // 2), (heart_size * 2, heart_size // 2), 
                                (heart_size, heart_size * 2)])
            SCREEN.blit(heart_surf, (tail_end_x - heart_size, tail_end_y - heart_size))

def draw_tears():
    if current_stage == 3 and tears_active:
        #  성능 최적화: 눈물 이미지 미리 설정
        img = TEAR_IMG.copy()
        img.set_alpha(180)
        img_width_half = TEAR_IMG.get_width() // 2
        img_height_half = TEAR_IMG.get_height() // 2
        #  성능 최적화: 화면 밖 눈물은 그리지 않음
        for x, y, speed, prev_y in falling_tears:
            if -LARGE_SIZE <= x <= WIDTH + LARGE_SIZE and -LARGE_SIZE <= y <= HEIGHT + LARGE_SIZE:  # 화면 경계 체크
                SCREEN.blit(img, (x - img_width_half, y - img_height_half))
def check_collision_wrapper(obj1, obj2):
    """충돌 검사 래퍼 - 마이그레이션 모드에서는 새 시스템 사용"""
    global MIGRATION_MODE, collision_system
    
    if MIGRATION_MODE and collision_system:
        # 새로운 충돌 시스템 사용
        if hasattr(obj1, 'rect') and hasattr(obj2, 'rect'):
            return collision_system.check_rect_rect_collision(obj1, obj2)
        elif hasattr(obj1, 'radius') and hasattr(obj2, 'rect'):
            return collision_system.check_circle_rect_collision(obj1, obj2)
        elif hasattr(obj1, 'rect') and hasattr(obj2, 'radius'):
            return collision_system.check_circle_rect_collision(obj2, obj1)
        else:
            # 폴백: pygame의 기본 충돌 검사
            if hasattr(obj1, 'colliderect'):
                return obj1.colliderect(obj2)
    else:
        # 레거시 충돌 검사
        if hasattr(obj1, 'colliderect'):
            return obj1.colliderect(obj2)
    return False

def check_tear_collisions():
    global falling_tears, player_slow_timer, player_slow_timer_max
    new_tears = []
    
    # 연막 안에 있으면 눈물샤워에 면역
    player_in_smoke = is_player_in_smoke()
    
    for tear in falling_tears:
        x, y, speed, prev_y = tear
        tear_rect = pygame.Rect(x, y, 10, 10)
        
        # 직접적인 충돌 검사 사용 (버그 수정)
        if tear_rect.colliderect(PLAYER):
            # 연막 안에 있으면 면역 - 눈물이 부딪혀도 효과 없음
            if player_in_smoke:
                # 연막이 눈물을 막아주는 시각적 효과 (선택사항)
                for _ in range(3):
                    angle = random.uniform(0, 360)
                    speed = random.uniform(0.5, 1.5)
                    vx = math.cos(math.radians(angle)) * speed
                    vy = math.sin(math.radians(angle)) * speed
                    # 연막색 파티클로 표시
                    tear_particles.append([
                        tear_rect.centerx, tear_rect.centery,
                        vx, vy,
                        100,  # 회색 파티클
                        random.randint(1, 2)
                    ])
                continue  # 충돌한 눈물 제거 (데미지는 없음)
            else:
                # 연막 밖에서는 정상적으로 데미지 받음
                player_slow_timer = 130  # 2초간 느려짐 (60fps 기준)
                player_slow_timer_max = player_slow_timer
                
                # 눈물 맞았을 때 사운드 재생
                try:
                    tears_sound = pygame.mixer.Sound(resource_path("sounds/tears.wav"))
                    tears_sound.set_volume(0.6)
                    play_sound_with_volume(tears_sound)
                except:
                    pass  # 사운드 파일이 없으면 무시
                
                #  성능 최적화: 파티클 개수를 절반으로 줄임 (12 → 6)
                for _ in range(6):
                    angle = random.uniform(200, 340)
                    speed = random.uniform(1.0, 3.0)
                    vx = math.cos(math.radians(angle)) * speed
                    vy = math.sin(math.radians(angle)) * speed
                    tear_particles.append([
                        PLAYER.centerx, PLAYER.top,
                        vx, vy,
                        255,
                        random.randint(2, 4)
                    ])
                continue  # 충돌한 눈물 제거
        else:
            new_tears.append(tear)
    falling_tears = new_tears
def apply_effect(effect_name):
    global PADDLE_WIDTH, PLAYER_SPEED, special_gauge, special_gauge_max, special_ready
    global aipill_active, selected_character_type  #  AI 필 변수 추가
    #  아이템 사용 기록 (효과적인 사용인지 간단히 판단)
    was_effective = True  # 대부분의 아이템은 효과적으로 간주
    if effect_name == "gauge_boost" and special_gauge >= 70:
        was_effective = False  # 게이지가 이미 충분할 때는 비효과적
    elif effect_name == "gauge_charge" and special_gauge >= (special_gauge_max - 50):
        was_effective = False  # 게이지가 거의 풀일 때는 비효과적
    record_item_usage(effect_name, was_effective=was_effective)

    if effect_name == "repair_kit" and selected_character_type != "blacksmith":
        print("⚠️ 수리키트는 발토르 전용 아이템입니다.")
        return False
    if effect_name == "berserk_potion" and selected_character_type != "blacksmith":
        print("⚠️ 광폭물약은 발토르 전용 아이템입니다.")
        return False

    # 캐릭터 고유 스킬성 아이템 사용을 실력 분석에 반영
    if effect_name in ("repair_kit", "berserk_potion"):
        record_character_skill_usage()

    #  엑티브 아이템 사용 효과음 재생 (패시브 아이템 제외)
    if effect_name not in ["battery", "chargebag", "spikeboots", "dashgear", "gauge_charge", "life_elixir"]:
        play_active_item_sound()
    if effect_name == "long_paddle":
        PADDLE_WIDTH = int(PADDLE_WIDTH * 1.5)
        print("!   1.5 !")
    elif effect_name == "speed_up":
        PLAYER_SPEED *= 1.3
        print("!   30% !")
    elif effect_name == "gauge_boost":
        special_gauge = min(100, special_gauge + 30)
        print("!   30 !")
    elif effect_name == "long_boost":
        activate_long_boost()
        print("! 5   1.5!")
    elif effect_name == "gauge_charge":  #  게이지 충전 아이템
        # 물약 마시는 효과음 재생
        try:
            play_sound_with_volume(SOUND_DRINK)
        except:
            pass
        #  동적 최대치 계산 적용
        current_max = get_max_gauge()
        special_gauge = min(current_max, special_gauge + 220)
        #  게이지가 400 이상이면 special_ready 활성화
        if special_gauge >= 350:  # 파워스매시 발동 조건
            special_ready = True
        print("!   220 !")
    elif effect_name == "aipill":  #  AI 필 아이템 활성화
        activate_aipill("active_item")
        print("Aipill  -  :", special_gauge)
        print("Aipill  !")
    elif effect_name == "battery":  #  배터리 아이템 (패시브 아이템이므로 apply_effect에서 처리하지 않음)
        # 배터리는 store_passive_item에서 처리됨
        pass
    elif effect_name == "wall":  #  벽돌 설치 아이템 활성화
        activate_wall()
    elif effect_name == "molotov":  #  화염병 아이템 활성화
        # 라운드 시작 3초 제한 체크
        current_time = pygame.time.get_ticks()
        if current_time - round_start_time < 3000:  # 3초 미만
            remaining_time = (3000 - (current_time - round_start_time)) / 1000
            print(f"🔥 화기류 사용 제한 중 (남은 시간: {remaining_time:.1f}초)")
            return False
        activate_molotov()
        print("!    !")
    elif effect_name == "grenade":  #  수류탄 아이템 활성화
        # 라운드 시작 3초 제한 체크
        current_time = pygame.time.get_ticks()
        if current_time - round_start_time < 3000:  # 3초 미만
            remaining_time = (3000 - (current_time - round_start_time)) / 1000
