        gas_tube_start = (base_x + int(w * 0.55), base_y + int(h * 0.34))
        gas_tube_end = (base_x + int(w * 0.82), base_y + int(h * 0.34))
        pygame.draw.line(screen, metal_mid, gas_tube_start, gas_tube_end, 2)

        barrel_width = max(3, int(w * 0.22))
