def try_trigger_foul_whistle(loss_type: str) -> bool:
    """반칙호루라기 발동을 시도하고 성공 여부를 반환."""

    global round_losses, deuce_losses, foul_whistle_pending_round_reset, ball_vel

    try:
        from item_effects.foul_whistle import get_foul_whistle_instance

        whistle = get_foul_whistle_instance()
    except Exception as exc:
        print(f"[WARN] 반칙호루라기 인스턴스 준비 실패: {exc}")
        return False

    if not whistle.try_trigger():
        return False

    if loss_type == "deuce":
        deuce_losses = max(0, deuce_losses - 1)
    else:
        round_losses = max(0, round_losses - 1)
        game_state.round_losses = round_losses

    foul_whistle_pending_round_reset = True

    try:
        ball_vel[0] = 0
        ball_vel[1] = 0
    except Exception:
        pass

    try:
        BALL.centerx = WIDTH // 2
        BALL.centery = HEIGHT // 2
    except Exception:
        pass

    print("📢 심판이 무효를 선언합니다! 라운드가 다시 시작됩니다.")
    return True
def store_active_item(item_data):
    global active_item_slot, selected_item_index, aipill_active, last_item_use_time, long_boost_active
    # Aipill 활성화 시에는 아이템 획득 불가
    if aipill_active:
        return
    # long_boost가 이미 활성화되어 있으면 long_boost 아이템 획득 불가
    if item_data["name"] == "long_boost" and long_boost_active:
        print("!")
        return
    if item_data["name"] == "fire_support" and selected_character_type != "soldier":
        # 화력지원은 군인 전용 화기이므로 다른 캐릭터는 획득하지 않는다.
        return
    # 패시브 아이템들은 엑티브 슬롯에 추가하지 않음
    if item_data["name"] in ["speedboots", "speedgear", "battery", "slot_add", "revival", "master", "cooltime", "chargebag", "spikeboots", "dashgear", "bulkup", "sensor", "dashholder", "gravitybelt", "dowsing_pendulum", "technical_vest", "commando_arm", "fuel_pouch", "bluetooth_ring", "foul_whistle", "star_detector", "smartphone", "knee_pads", "ragnarok_hammer", "hermes_shoes", "poseidon_trident"]:
        return
    allow_overflow = item_data.pop("allow_overflow", False)
    is_overflow_pickup = len(item_state_adapter.active_items()) >= get_effective_max_item_slots()
    if is_overflow_pickup and not allow_overflow:
        return

    # 모든 액티브 아이템에 대해 아이콘 설정 (아이템 관리창과 동일한 아이콘 사용)
    if "icon" not in item_data or item_data["icon"] is None:
        item_data["icon"] = get_item_icon(item_data["name"])

    if "icon_animation_frames" not in item_data:
        animation_frames = items.get_item_icon_animation(item_data["name"])
        if animation_frames:
            item_data["icon_animation_frames"] = animation_frames
            item_data.setdefault("icon_animation_speed", 6)

    # 아이템에 last_use 필드 추가 (전역 쿨타임 적용)
    current_time = pygame.time.get_ticks()
    item_data["last_use"] = last_item_use_time
    item_data["temporary_overflow"] = is_overflow_pickup

    item_state_adapter.append_active_item(item_data)
    _set_selected_item_index(len(item_state_adapter.active_items()) - 1)

    # 아이템 획득 효과 표시 (아이템 위치에서) - 옛날 버전 활성화
    show_item_obtained_effect(item_data, item_data.get("x"), item_data.get("y"))
