        for i in range(4):
            alpha = 40 - i * 8
            pygame.draw.rect(inner_shadow, (0, 0, 0, alpha), (0, i, inner_rect.width, 1))
        SCREEN.blit(inner_shadow, (inner_rect.x, inner_rect.y))

        # 채움 (좌→우)
        fill_w = max(1, int((v_width - 4) * remaining_ratio))
