def show_tutorial_drive_dialogue():
    """튜토리얼 드라이브 연습 대화"""
    clock = pygame.time.Clock()
    
    # 폰트 설정
    font_large = FontStyle.subtitle()  # 32pt 화자 이름용
    font_dialogue = FontStyle.body()  # 24pt 대화 내용용
    
    # 색상 정의
    BOSS_COLOR = (255, 100, 100)  # 조교 텍스트 색상 (빨간색)
    PLAYER_COLOR = (100, 200, 255)  # 플레이어 텍스트 색상 (파란색)
    
    # 현재 게임 화면을 그대로 캡처 (기존 게임 상태를 보존)
    background = SCREEN.copy()
    
    dialogues = [
        ("조교", "핑파이터에서 기본적인 모든 공격은"),
        ("조교", "공을 때린 방향으로 직선으로 날아간다."),
        ("조교", "하지만 스매셔는 이 공에 회전을 넣어"),
        ("조교", "곡선으로 휘게 만들 수 있지."),
        ("플레이어", "오오..."),
        ("조교", "회전이 들어간 공은 방향을 예측하기 어렵기 때문에"),
        ("조교", "적이 가드를 하는데 있어 상당히 애를 먹는다."),
        ("조교", "이번에 배워볼 기술은 바로 '드라이브'이다."),
        ("조교", "매우 좋은 공격기술이지만"),
        ("조교", "이 드라이브는 핑파이터에서 가장 난이도가 높은 기술이다."),
        ("조교", "일정 타이밍에 맞춰서 키를 입력해야하기 때문인데"),
        ("조교", "감만 익히면 크게 어렵지 않다."),
        ("조교", "공이 내 몸의 일정 궤도내에 들어오면"),
        ("조교", "드라이브 모니터가 표시가 된다."),
        ("드라이브 시범", ""),  # 드라이브 모니터 표시 시범
        ("조교", "이때 타이밍에 맞춰"),
        ("조교", "← + 스페이스 키를 누르면\n왼쪽 방향으로 드라이브 발사"),
        ("조교", "→ + 스페이스 키를 누르면\n오른쪽 방향으로 드라이브 발사."),
        ("드라이브 애니메이션", ""),  # 드라이브 애니메이션 시범
        ("조교", "타이밍에 맞춰서 정확히 동시에 눌러야"),
        ("조교", "드라이브가 발동되므로"),
        ("조교", "드라이브 감각을 우선 익히는 연습을 해보겠다."),
        ("조교", "드라이브 실시!"),
        ("플레이어", "실시!"),
    ]
    
    current_dialogue = 0
    running = True
    text_animation_timer = 0
    displayed_text = ""
    target_text = ""
    
    while running:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_8:
                    # 8번키로 튜토리얼 챕터 스킵
                    print("🎮 8번 키: 드라이브 대화 중 챕터 스킵 요청")
                    return "skip_chapter"  # 특별한 반환값으로 챕터 스킵 신호
                elif event.key in [pygame.K_SPACE, pygame.K_RETURN]:
                    # 텍스트가 다 표시되지 않았으면 전체 표시, 아니면 다음 대화로
                    if displayed_text and len(displayed_text) < len(target_text):
                        displayed_text = target_text
                    else:
                        current_dialogue += 1
                        if current_dialogue >= len(dialogues):
                            return True  # 대화 종료
                        # 다음 대화 초기화
                        displayed_text = ""
                        text_animation_timer = 0
                        if current_dialogue < len(dialogues):
                            target_text = dialogues[current_dialogue][1]
        
        # 배경 그리기
        SCREEN.blit(background, (0, 0))
        
        if current_dialogue < len(dialogues):
            speaker, text = dialogues[current_dialogue]
            
            # 첫 대화 시작 시 target_text 설정
            if not target_text and text:
                target_text = text
            
            if speaker == "드라이브 시범":
                # 드라이브 모니터 표시 시범
                show_drive_monitor_demo(background)
                # 데모 후 자동으로 다음 대화로 진행
                current_dialogue += 1
                if current_dialogue >= len(dialogues):
                    return True
                displayed_text = ""
                text_animation_timer = 0
                target_text = dialogues[current_dialogue][1] if current_dialogue < len(dialogues) else ""
                continue  # 다음 루프로 바로 진행
            elif speaker == "드라이브 애니메이션":
                # 드라이브 애니메이션 시범
                show_drive_animation_demo(background)
                # 데모 후 자동으로 다음 대화로 진행
                current_dialogue += 1
                if current_dialogue >= len(dialogues):
                    return True
                displayed_text = ""
                text_animation_timer = 0
                target_text = dialogues[current_dialogue][1] if current_dialogue < len(dialogues) else ""
                continue  # 다음 루프로 바로 진행
            else:
                # 일반 대화 표시 (배경 캡처 화면 위에)
                SCREEN.blit(background, (0, 0))
                
                # 텍스트 애니메이션 (글자 하나씩 표시)
                if len(displayed_text) < len(target_text):
                    text_animation_timer += 1
                    if text_animation_timer % 2 == 0:  # 텍스트 타이핑 속도 조절
                        displayed_text += target_text[len(displayed_text)]
                
                # 텍스트 배경 (검은색 반투명)
                text_bg_height = 80
                text_bg = pygame.Surface((WIDTH, text_bg_height), pygame.SRCALPHA)
                text_bg.fill((0, 0, 0, 180))
                text_y_position = HEIGHT - 150
                SCREEN.blit(text_bg, (0, text_y_position))
                
                # 화자 이름과 대화 텍스트 처리
                speaker_color = BOSS_COLOR if speaker == "조교" else PLAYER_COLOR
                full_text = f"[{speaker}] {displayed_text}"
                text_surface = font_dialogue.render(full_text, True, speaker_color)
                text_rect = text_surface.get_rect(center=(WIDTH // 2, text_y_position + text_bg_height // 2))
                
                # 텍스트 그림자 효과
                shadow_surface = font_dialogue.render(full_text, True, (0, 0, 0))
                shadow_rect = text_rect.copy()
                shadow_rect.x += 2
                shadow_rect.y += 2
                SCREEN.blit(shadow_surface, shadow_rect)
                
                # 실제 텍스트
                SCREEN.blit(text_surface, text_rect)
        
        pygame.display.flip()
        clock.tick(60)
    
    return True

