def draw_tutorial_power_counter():
    """튜토리얼 파워스매싱 카운터 UI 표시 (3회 파워스매싱 카운트)"""
    import math  # 함수 시작시 import
    global tutorial_power_counter_active, tutorial_power_count, tutorial_displayed_power_count
    
    # 파워스매싱 카운터가 활성화되었을 때만 표시
    if not tutorial_power_counter_active or current_stage != 50:
        return
    
    # 점진적 애니메이션 업데이트
    if tutorial_displayed_power_count < tutorial_power_count:
        # 부드러운 애니메이션 속도 (프레임당 0.05 증가)
        tutorial_displayed_power_count = min(tutorial_displayed_power_count + 0.05, tutorial_power_count)
    
    # 폰트 설정
    font_large = FontStyle.body()      # 24pt - 숫자용
    font_medium = FontStyle.small()    # 18pt
    
    # 오른쪽 상단 위치 (다른 카운터와 동일한 위치)
    ui_x = WIDTH - 100
    ui_y = 50
    
    # 미니멀한 반투명 배경
    bg_width = 180
    bg_height = 90
    bg_x = ui_x - bg_width // 2
    bg_y = ui_y - 15
    
    # 반투명 배경 (은은하게)
    bg_surf = pygame.Surface((bg_width, bg_height), pygame.SRCALPHA)
    pygame.draw.rect(bg_surf, (20, 25, 40, 120), (0, 0, bg_width, bg_height), border_radius=8)
    pygame.draw.rect(bg_surf, (255, 50, 200, 40), (0, 0, bg_width, bg_height), border_radius=8, width=1)  # 보라색 테두리
    SCREEN.blit(bg_surf, (bg_x, bg_y))
    
    # 컴팩트한 원형 진행도
    circle_radius = 22
    circle_center_x = ui_x - 50
    circle_center_y = ui_y + 10
    
    # 배경 원
    pygame.draw.circle(SCREEN, (40, 45, 60, 180), (circle_center_x, circle_center_y), circle_radius, 2)
    
    # 진행도 원호 그리기 (3분할)
    if tutorial_displayed_power_count > 0:
        progress = tutorial_displayed_power_count / 3  # 3회 기준
        # 시작 각도 -90도 (12시 방향)
        start_angle = -math.pi / 2
        # 진행도에 따른 종료 각도
        end_angle = start_angle + (2 * math.pi * progress)
        
        # 아크를 작은 선분들로 그리기
        num_segments = 50
        for i in range(num_segments):
            t1 = i / num_segments
            t2 = (i + 1) / num_segments
            angle1 = start_angle + (end_angle - start_angle) * t1
            angle2 = start_angle + (end_angle - start_angle) * t2
            
            x1 = circle_center_x + circle_radius * math.cos(angle1)
            y1 = circle_center_y + circle_radius * math.sin(angle1)
            x2 = circle_center_x + circle_radius * math.cos(angle2)
            y2 = circle_center_y + circle_radius * math.sin(angle2)
            
            # 진행도 색상
            if tutorial_power_count < 1:
                color = (255, 100, 150)  # 핑크색
            elif tutorial_power_count < 2:
                color = (255, 100, 200)  # 밝은 보라색
            elif tutorial_power_count < 3:
                color = (200, 100, 255)  # 보라색
            else:
                color = (150, 50, 255)  # 진한 보라색 (완료)
            
            pygame.draw.line(SCREEN, color, (x1, y1), (x2, y2), 3)
    
    # 숫자 표시
    counter_text = f"{tutorial_power_count}/3"
    counter_surface = font_large.render(counter_text, True, (255, 255, 255))
    counter_rect = counter_surface.get_rect(center=(circle_center_x, circle_center_y))
    SCREEN.blit(counter_surface, counter_rect)
    
    # 파워스매싱 아이콘 그리기 (원형 진행도 오른쪽에) - 번개 효과
    power_x = circle_center_x + circle_radius + 25
    power_y = circle_center_y
    
    # 파워스매싱 아이콘 서페이스
    icon_surf = pygame.Surface((60, 40), pygame.SRCALPHA)
    
    # 번개 모양 그리기
    lightning_color = (255, 200, 50) if tutorial_power_count >= 2 else (200, 150, 50)
    
    # 번개 패스
    lightning_points = [
        (20, 5),
        (30, 15),
        (25, 20),
        (35, 30),
        (25, 25),
        (30, 20),
        (20, 10)
    ]
    pygame.draw.polygon(icon_surf, lightning_color, lightning_points)
    
    # 번개 효과 (빛나는 효과)
    for i in range(3):
        alpha = 100 - i * 30
        bigger_points = [(x + i, y + i) for x, y in lightning_points]
        lightning_glow = pygame.Surface((60, 40), pygame.SRCALPHA)
        pygame.draw.polygon(lightning_glow, (*lightning_color, alpha), bigger_points, 1)
        icon_surf.blit(lightning_glow, (0, 0))
    
    # 아이콘 블릿
    SCREEN.blit(icon_surf, (power_x - 10, power_y - 20))
    
    # "POWER" 텍스트
    power_text = "POWER"
    power_surface = font_medium.render(power_text, True, (255, 200, 50))
    power_rect = power_surface.get_rect(center=(ui_x, ui_y + 40))
    SCREEN.blit(power_surface, power_rect)
    
    # 축하 효과 (3회 완료 시)
    global tutorial_power_counter_celebration, tutorial_power_counter_celebration_timer
    if 'tutorial_power_counter_celebration' not in globals():
        tutorial_power_counter_celebration = False
        tutorial_power_counter_celebration_timer = 0
    
    if tutorial_power_counter_celebration:
        current_time = pygame.time.get_ticks()
        if current_time - tutorial_power_counter_celebration_timer < 3000:  # 3초간 표시
            # 축하 텍스트
            complete_text = "완료!"
            complete_color = (
                random.randint(200, 255),
                random.randint(100, 255),
                random.randint(200, 255)
            )
            complete_surface = font_large.render(complete_text, True, complete_color)
            complete_rect = complete_surface.get_rect(center=(ui_x, ui_y - 40))
            SCREEN.blit(complete_surface, complete_rect)
            
            # 별 효과
            for _ in range(3):
                star_x = ui_x + random.randint(-60, 60)
                star_y = ui_y + random.randint(-30, 30)
                star_size = random.randint(2, 5)
                pygame.draw.circle(SCREEN, (255, 255, 100), (star_x, star_y), star_size)
        else:
            tutorial_power_counter_celebration = False

def show_drive_monitor_demo(background):
    """드라이브 모니터 표시 시범"""
    clock = pygame.time.Clock()
    
    # 폰트 설정 (챕터2와 동일)
    font_medium = FontStyle.body()    # 24pt 대사용
    font_small = FontStyle.small()    # 18pt 안내용
    BOSS_COLOR = (255, 100, 100)  # 조교 텍스트 색상
    CYAN = (0, 255, 255)  # 안내 텍스트 색상
    
    # 색상 그라데이션 설정
    gradient_colors = [
        (255, 255, 100),  # 노란색
        (255, 200, 100),  # 주황색
        (255, 150, 200),  # 핑크
        (200, 150, 255),  # 보라색
        (150, 200, 255),  # 하늘색
        (100, 255, 200),  # 민트색
    ]
    color_change_duration = 2000  # 2초마다 색상 변경
    
    # 데모용 매개변수 - 실제 게임과 동일한 조건
    boss_x = WIDTH // 2
    boss_y = 120  # 챕터2와 동일한 높이
    
    # 조교 이미지 미리 로드 (중복 방지)
    try:
        boss_img_path = resource_path("boss_tutorial.png")
        boss_img = pygame.image.load(boss_img_path).convert_alpha()
        boss_img = pygame.transform.scale(boss_img, (80, 100))
    except:
        boss_img = None
    
    # 드라이브 시범 설정
    demo_phases = [
        {'direction': 'left', 'completed': False, 'demo_time': 0},
        {'direction': 'right', 'completed': False, 'demo_time': 0}
    ]
    current_phase = 0
    waiting_for_space = False
    phase_start_time = pygame.time.get_ticks()
    
    # 공을 멀리서 날아오게 하기 - 실제 게임 상황과 비슷하게
    ball_start_x = boss_x - 300  # 화면 왼쪽에서 시작
    ball_start_y = HEIGHT - 150  # 플레이어 높이 근처에서 시작
    ball_target_x = boss_x
    ball_target_y = boss_y + 80  # 보스 패들 아래쪽
    
    # 애니메이션 지속 시간
    animation_duration = 2000  # 2초 (현실적인 속도)
    drive_text_timer = 0  # DRIVE! 텍스트 표시 타이머
    drive_text_duration = 500   # 0.5초 동안 표시
    
    while current_phase < len(demo_phases):
        # 이벤트 처리
        for event in pygame.event.get():
            if event.type == pygame.KEYDOWN:
                if event.key == pygame.K_SPACE and waiting_for_space:
                    # 스페이스바를 누르면 다음 페이즈로
                    demo_phases[current_phase]['completed'] = True
                    current_phase += 1
                    phase_start_time = pygame.time.get_ticks()
                    waiting_for_space = False
                    if current_phase >= len(demo_phases):
                        return  # 데모 완료
        
        # 챕터2 스타일: 실제 게임 필드 표시
        SCREEN.fill((20, 30, 60))  # 어두운 파란 배경
        
        # 중앙선 그리기
        pygame.draw.line(SCREEN, (100, 100, 100), (0, HEIGHT // 2), (WIDTH, HEIGHT // 2), 2)
        
        # 중앙 원 그리기
        pygame.draw.circle(SCREEN, (100, 100, 100), (WIDTH // 2, HEIGHT // 2), 80, 2)
        
        # 현재 페이즈 시간 계산
        elapsed_time = pygame.time.get_ticks() - phase_start_time
        
        # 애니메이션 진행 상태
        if elapsed_time < animation_duration:
            # 애니메이션 재생 중
            progress = min(1.0, elapsed_time / animation_duration)
            demo_phases[current_phase]['demo_time'] = elapsed_time
        else:
            # 애니메이션 완료, 스페이스바 대기 및 반복 재생
            waiting_for_space = True
            # 애니메이션 반복을 위해 시간 리셋
            if waiting_for_space:
                phase_start_time = pygame.time.get_ticks()
                elapsed_time = 0
                progress = 0.0
        
        # 현재 드라이브 방향에 따라 공 시작 위치 설정
        if demo_phases[current_phase]['direction'] == 'left':
            # 왼쪽 드라이브: 공이 왼쪽에서 날아옴
            ball_start_x = boss_x - 300
            ball_target_x = boss_x - 50  # 보스 왼쪽으로
        else:
            # 오른쪽 드라이브: 공이 오른쪽에서 날아옴
            ball_start_x = boss_x + 300
            ball_target_x = boss_x + 50  # 보스 오른쪽으로
        
        # 실제 공 과 같은 포물선 궤적 + 가속 효과
        smooth_progress = progress ** 0.8  # 처음에는 느리고 점점 빨라짐
        ball_x = ball_start_x + (ball_target_x - ball_start_x) * smooth_progress
        
        # Y 축은 포물선 궤적으로
        arc_height = -50  # 포물선 높이
        ball_y = ball_start_y + (ball_target_y - ball_start_y) * smooth_progress
        ball_y += arc_height * 4 * smooth_progress * (1 - smooth_progress)  # 포물선 공식
        
        # 조교(보스) 그리기 - 실제 게임에서 사용하는 이미지들 사용
        boss_img = None
        
        # 튜토리얼에서는 조교 이미지 사용
        if current_stage == 50:  # Tutorial stage
            try:
                boss_img_path = resource_path("boss_tutorial.png")
                boss_img = pygame.image.load(boss_img_path).convert_alpha()
                boss_img = pygame.transform.scale(boss_img, (80, 100))
            except:
                # 이미지 로드 실패시 기본 이미지
                boss_img = pygame.Surface((80, 100), pygame.SRCALPHA)
                pygame.draw.rect(boss_img, BOSS_COLOR, (0, 0, 80, 100), border_radius=10)
        else:
            # 실제 스테이지별 보스 이미지 사용
            if current_stage == 1:
                boss_img = BOSS_IMG_STAGE1
                boss_img = pygame.transform.scale(boss_img, (BOSS_IMG_WIDTH, BOSS_IMG_HEIGHT))
            elif current_stage == 2:
                boss_img = draw_crocodile_boss(boss_x, boss_y, ball_x, ball_y)
            elif current_stage == 3:
                boss_img = BOSS_IMG_STAGE3
                boss_img = pygame.transform.scale(boss_img, (BOSS_IMG_WIDTH, BOSS_IMG_HEIGHT))
            elif current_stage == 4:
                boss_img = BOSS_IMG_STAGE4
                boss_img = pygame.transform.scale(boss_img, (BOSS_IMG_STAGE4_WIDTH, BOSS_IMG_STAGE4_HEIGHT))
            elif current_stage == 5:
                boss_img = BOSS_IMG_STAGE5
                boss_img = pygame.transform.scale(boss_img, (BOSS_IMG_STAGE5_WIDTH, BOSS_IMG_STAGE5_HEIGHT))
            elif current_stage == 6:
                boss_img = draw_aircraft_carrier_boss(0, boss_x)
            else:
                # 기본 보스 이미지
                boss_img = pygame.Surface((BOSS_IMG_WIDTH, BOSS_IMG_HEIGHT), pygame.SRCALPHA)
                pygame.draw.rect(boss_img, BOSS_COLOR, (0, 0, BOSS_IMG_WIDTH, BOSS_IMG_HEIGHT), border_radius=10)
        
        # 보스 그리기
        if boss_img:
            boss_rect = boss_img.get_rect(center=(boss_x, boss_y))
            SCREEN.blit(boss_img, boss_rect)
        
        # 공 그리기 - 실제 게임과 동일한 디테일
        ball_color = (255, 200, 0)  # 노란색 공
        ball_radius = 8  # 실제 게임 공 크기
        
        # 공 속도에 따른 잔상 효과 (실제 게임처럼)
        if progress > 0.1:  # 초반에는 잔상 없음
            for i in range(3):
                trail_alpha = 100 - i * 30
                trail_offset = i * 15
                trail_x = ball_x - (ball_x - ball_start_x) * (trail_offset / 300)
                trail_y = ball_y - (ball_y - ball_start_y) * (trail_offset / 300)
                trail_surface = pygame.Surface((ball_radius * 3, ball_radius * 3), pygame.SRCALPHA)
                pygame.draw.circle(trail_surface, (*ball_color, trail_alpha), 
                                 (ball_radius * 1.5, ball_radius * 1.5), ball_radius)
                SCREEN.blit(trail_surface, (int(trail_x - ball_radius * 1.5), int(trail_y - ball_radius * 1.5)))
        
        # 메인 공
        pygame.draw.circle(SCREEN, (255, 255, 150), (int(ball_x), int(ball_y)), ball_radius + 2)  # 외곽 글로우
        pygame.draw.circle(SCREEN, ball_color, (int(ball_x), int(ball_y)), ball_radius)  # 메인 공
        pygame.draw.circle(SCREEN, (255, 255, 255), (int(ball_x - 2), int(ball_y - 2)), 2)  # 하이라이트
        
        # 드라이브 모니터 표시 - 실제 게임처럼 공이 가까이 올 때만 활성화
        distance = ((ball_x - boss_x) ** 2 + (ball_y - boss_y) ** 2) ** 0.5
        drive_range = 70  # 실제 게임 드라이브 가능 범위 (크기 감소)
        
        # 드라이브 범위에 가까워지면 표시 (더 넓은 범위에서 페이드 인)
        if distance < drive_range * 2:  # 드라이브 범위의 2배 내에서부터 표시 시작
            # 드라이브 가능 영역 표시 - 단일 원
            if distance < drive_range:
                # 범위 내에서 강한 표시
                alpha = int(200 + 55 * (1 - distance / drive_range))  # 거리에 따른 투명도
            else:
                # 범위 밖이지만 가까이 있을 때 희미하게 표시 (페이드 아웃)
                fade_distance = distance - drive_range
                max_fade = drive_range  # 페이드 아웃 거리
                if fade_distance < max_fade:
                    alpha = int(100 * (1 - fade_distance / max_fade))
                else:
                    alpha = 0
            
            # 단일 드라이브 모니터 원 (실제 게임과 동일)
            if alpha > 0:
                # 더 큰 서페이스로 원을 그림
                circle_surface = pygame.Surface((drive_range * 2 + 10, drive_range * 2 + 10), pygame.SRCALPHA)
                pygame.draw.circle(circle_surface, (0, 255, 255, min(255, alpha)), 
                                 (drive_range + 5, drive_range + 5), drive_range, 3)
                # 내부 원 추가 (더 선명한 표시)
                if distance < drive_range:
                    pygame.draw.circle(circle_surface, (0, 255, 255, min(100, alpha // 2)), 
                                     (drive_range + 5, drive_range + 5), drive_range - 3, 1)
                SCREEN.blit(circle_surface, (boss_x - drive_range - 5, boss_y - drive_range - 5))
            
            # 공이 드라이브 범위에 들어오면 DRIVE! 표시 (거리 기반 + 시간 지속)
            if distance < drive_range:
                # 드라이브 텍스트 - 게임체적인 폰트와 효과
                font = FontStyle.body()
                # 텍스트 크기 변화 (펄싱 효과)
                pulse = abs(math.sin(elapsed_time * 0.005)) * 0.3 + 0.7
                text_color = (0, int(255 * pulse), int(255 * pulse))
                drive_text = font.render("DRIVE!", True, text_color)
                text_rect = drive_text.get_rect(center=(boss_x, boss_y - 60))
                SCREEN.blit(drive_text, text_rect)
            # 공이 범위를 벗어나도 잠시 더 표시 (페이드 아웃)
            elif distance < drive_range * 1.5:
                # 드라이브 텍스트 - 페이드 아웃 효과
                font = FontStyle.body()
                pulse = abs(math.sin(elapsed_time * 0.005)) * 0.3 + 0.7
                fade = 1.0 - (distance - drive_range) / (drive_range * 0.5)
                text_color = (0, int(255 * pulse * fade), int(255 * pulse * fade))
                drive_text = font.render("DRIVE!", True, text_color)
                text_rect = drive_text.get_rect(center=(boss_x, boss_y - 60))
                SCREEN.blit(drive_text, text_rect)
            
                # 타이밍 인디케이터 - 더 세련된 UI
                timing_progress = 1.0 - (distance / drive_range)
                bar_width = 60  # 더 작은 크기
                bar_height = 6
                bar_x = boss_x - bar_width // 2
                bar_y = boss_y - 85
                
                # 배경 바 (둥근 모서리)
                bar_surface = pygame.Surface((bar_width + 4, bar_height + 4), pygame.SRCALPHA)
                pygame.draw.rect(bar_surface, (30, 30, 30, 200), (0, 0, bar_width + 4, bar_height + 4), border_radius=3)
                pygame.draw.rect(bar_surface, (100, 100, 100, 150), (0, 0, bar_width + 4, bar_height + 4), 1, border_radius=3)
                SCREEN.blit(bar_surface, (bar_x - 2, bar_y - 2))
                
                # 진행 바 (그라디언트 효과)
                if timing_progress > 0:
                    progress_width = int(bar_width * timing_progress)
                    progress_surface = pygame.Surface((progress_width, bar_height), pygame.SRCALPHA)
                    for x in range(progress_width):
                        gradient_alpha = int(200 + 55 * (x / bar_width))
                        gradient_color = (0, 200 + int(55 * (x / bar_width)), 200 + int(55 * (x / bar_width)), gradient_alpha)
                        pygame.draw.line(progress_surface, gradient_color, (x, 0), (x, bar_height))
                    SCREEN.blit(progress_surface, (bar_x, bar_y))
        
        # 챕터2 스타일 텍스트 배경 (항상 표시)
        text_bg_height = 80
        text_bg = pygame.Surface((WIDTH, text_bg_height), pygame.SRCALPHA)
        text_bg.fill((0, 0, 0, 180))
        text_y_position = HEIGHT - 150
        SCREEN.blit(text_bg, (0, text_y_position))
        
        # 시범 안내 텍스트 표시
        # 항상 동일한 텍스트 표시 - 방향별 메시지 제거
        display_text = "[조교] 드라이브 모니터가 표시가 된다."
        
        # 현재 시간 가져오기
        current_time = pygame.time.get_ticks()
        
        # 색상 계산 (그라데이션)
        color_time = current_time % (color_change_duration * len(gradient_colors))
        color_index = int(color_time / color_change_duration)
        next_color_index = (color_index + 1) % len(gradient_colors)
        
        # 현재 색상과 다음 색상 사이의 보간값 계산
        transition_progress = (color_time % color_change_duration) / color_change_duration
        
        # 부드러운 전환을 위한 사인 함수 적용
        smooth_progress = (math.sin((transition_progress - 0.5) * math.pi) + 1) / 2
        
        # 색상 보간
        current_color = gradient_colors[color_index]
        next_color = gradient_colors[next_color_index]
        
        interpolated_color = (
            int(current_color[0] + (next_color[0] - current_color[0]) * smooth_progress),
            int(current_color[1] + (next_color[1] - current_color[1]) * smooth_progress),
            int(current_color[2] + (next_color[2] - current_color[2]) * smooth_progress)
        )
        
        # 텍스트 렌더링 (그라데이션 색상 적용)
        text_surface = font_medium.render(display_text, True, interpolated_color)
        text_rect = text_surface.get_rect(center=(WIDTH // 2, text_y_position + text_bg_height // 2))
        
        # 텍스트 그림자 효과
        shadow_surface = font_medium.render(display_text, True, (0, 0, 0))
        shadow_rect = text_rect.copy()
        shadow_rect.x += 2
        shadow_rect.y += 2
        SCREEN.blit(shadow_surface, shadow_rect)
        
        # 실제 텍스트
        SCREEN.blit(text_surface, text_rect)
        
        # 스페이스바 안내 (사용자 요청으로 제거)
        # if waiting_for_space:
        #     instruction = "SPACE - 계속"
        #     text_color = CYAN
        #     inst_surface = font_small.render(instruction, True, text_color)
        #     inst_rect = inst_surface.get_rect(bottomright=(WIDTH - 20, HEIGHT - 20))
        #     
        #     # 깜빡임 효과
        #     if pygame.time.get_ticks() % 1000 < 500:
        #         SCREEN.blit(inst_surface, inst_rect)
        
        pygame.display.flip()
        clock.tick(60)

def show_drive_animation_demo(background):
    """드라이브 애니메이션 시범"""
    clock = pygame.time.Clock()
    
    # 폰트 설정 (챕터2와 동일)
    font_medium = FontStyle.body()    # 24pt 대사용
    font_small = FontStyle.small()    # 18pt 안내용
    BOSS_COLOR = (255, 100, 100)  # 조교 텍스트 색상
    CYAN = (0, 255, 255)  # 안내 텍스트 색상
    
    # 드라이브 시범 설정
    demo_phases = [
        {'direction': 'left', 'completed': False},
        {'direction': 'right', 'completed': False}
    ]
    current_phase = 0
    waiting_for_space = False
    phase_start_time = pygame.time.get_ticks()
    animation_duration = 1200  # 1.2초 애니메이션 (살짝 느리게)
    
    # 데모 상태
    demo_state = {
        'boss_x': WIDTH // 2,
        'boss_y': 100,
        'ball_x': WIDTH // 2,
        'ball_y': HEIGHT // 2,
        'drive_start': 0,
        'drive_duration': 1200,  # 1.2초
        'curve_points': [],
    }
    
    while current_phase < len(demo_phases):
        for event in pygame.event.get():
            if event.type == pygame.KEYDOWN:
                if event.key == pygame.K_SPACE and waiting_for_space:
                    # 스페이스바를 누르면 다음 페이즈로
                    demo_phases[current_phase]['completed'] = True
                    current_phase += 1
                    phase_start_time = pygame.time.get_ticks()
                    waiting_for_space = False
                    if current_phase >= len(demo_phases):
                        return  # 데모 완료
        
        current_time = pygame.time.get_ticks()
        elapsed = current_time - phase_start_time
        
        # 애니메이션 진행 상태 확인
        if elapsed < animation_duration:
            # 애니메이션 재생 중
            progress = min(1.0, elapsed / animation_duration)
        else:
            # 애니메이션 완료, 스페이스바 대기
            progress = 1.0
            if not waiting_for_space:
                waiting_for_space = True
            
            # 애니메이션 반복 재생
            if waiting_for_space:
                phase_start_time = pygame.time.get_ticks()
                elapsed = 0
                progress = 0.0
        
        SCREEN.blit(background, (0, 0))
        
        # 보스 그리기
        try:
            boss_img_path = resource_path("boss_tutorial.png")
            boss_img = pygame.image.load(boss_img_path)
            boss_img = pygame.transform.scale(boss_img, (80, 100))
            boss_rect = boss_img.get_rect(center=(demo_state['boss_x'], demo_state['boss_y']))
            SCREEN.blit(boss_img, boss_rect)
        except:
            pygame.draw.rect(SCREEN, (200, 100, 100), 
                           (demo_state['boss_x'] - 40, demo_state['boss_y'] - 50, 80, 100))
        
        # 현재 phase에 따라 드라이브 방향 설정
        if demo_phases[current_phase]['direction'] == 'left':
            # 왼쪽 드라이브 설정
            if progress == 0:
                # 초기화: 공을 보스 오른쪽에서 시작
                demo_state['ball_x'] = demo_state['boss_x'] + 100
                demo_state['ball_y'] = demo_state['boss_y']
                # 왼쪽 곡선 경로 생성 - 벽에 부딪히도록 조정
                demo_state['curve_points'] = []
                import math
                wall_x = 10  # 왼쪽 벽 위치
                
                # 부드러운 베지어 곡선으로 전체 경로 생성
                total_points = 40
                
                # 제어점들 정의 (베지어 곡선용)
                p0 = (demo_state['boss_x'] + 100, demo_state['boss_y'])  # 시작점
                p1 = (demo_state['boss_x'] - 100, demo_state['boss_y'] + 100)  # 첫 번째 제어점
                p2 = (wall_x + 50, demo_state['boss_y'] + 300)  # 두 번째 제어점 (벽 근처)
                p3 = (wall_x + 200, demo_state['boss_y'] + 500)  # 끝점
                
                # 3차 베지어 곡선으로 부드러운 궤적 생성
                for i in range(total_points):
                    t = i / (total_points - 1)
                    
                    # 베지어 곡선 공식: B(t) = (1-t)³P₀ + 3(1-t)²tP₁ + 3(1-t)t²P₂ + t³P₃
                    u = 1 - t
                    tt = t * t
                    uu = u * u
                    uuu = uu * u
                    ttt = tt * t
                    
                    x = (uuu * p0[0] + 
                         3 * uu * t * p1[0] + 
                         3 * u * tt * p2[0] + 
                         ttt * p3[0])
                    
                    y = (uuu * p0[1] + 
                         3 * uu * t * p1[1] + 
                         3 * u * tt * p2[1] + 
                         ttt * p3[1])
                    
                    # 화면 경계 확인
                    x = max(wall_x, min(x, WIDTH - 10))
                    y = max(50, min(y, HEIGHT - 50))
                    demo_state['curve_points'].append((x, y))
            
            # 드라이브 애니메이션
            if progress > 0.2:  # 0.4초 후 드라이브 시작
                drive_progress = (progress - 0.2) / 0.8
                point_idx = min(int(drive_progress * len(demo_state['curve_points'])), 
                              len(demo_state['curve_points']) - 1)
                if point_idx >= 0:
                    demo_state['ball_x'], demo_state['ball_y'] = demo_state['curve_points'][point_idx]
                
                # 곡선 궤적 표시
                if len(demo_state['curve_points']) > 1:
                    for i in range(1, min(point_idx + 1, len(demo_state['curve_points']))):
                        pygame.draw.line(SCREEN, (255, 255, 0, 150),
                                       demo_state['curve_points'][i-1],
                                       demo_state['curve_points'][i], 3)
                
                # 벽 충돌 효과 (60% 지점에서) - 베지어 곡선 기준으로 조정
                if point_idx == int(len(demo_state['curve_points']) * 0.6):  # 벽에 부딪힌 순간
                    # 충돌 플래시 효과
                    flash_surface = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
                    pygame.draw.circle(flash_surface, (255, 255, 255, 100), 
                                     (int(demo_state['ball_x']), int(demo_state['ball_y'])), 50)
                    SCREEN.blit(flash_surface, (0, 0))
                    # 충돌 파티클 효과
                    for j in range(5):
                        particle_x = demo_state['ball_x'] + random.randint(-20, 20)
                        particle_y = demo_state['ball_y'] + random.randint(-20, 20)
                        pygame.draw.circle(SCREEN, (255, 200, 0), (int(particle_x), int(particle_y)), 3)
        
        else:  # 오른쪽 드라이브
            # 오른쪽 드라이브 설정
            if progress == 0:
                # 초기화: 공을 보스 왼쪽에서 시작
                demo_state['ball_x'] = demo_state['boss_x'] - 100
                demo_state['ball_y'] = demo_state['boss_y']
                # 오른쪽 곡선 경로 생성 - 벽에 부딪히도록 조정
