                    (-8, -10),  # 상단 왼쪽
                    (-2, -4),   # 중간 왼쪽
                    (-5, 0),    # 중앙 왼쪽
                    (2, -2),    # 중앙
                    (-1, 2),    # 중앙 아래
                    (5, 8),     # 하단 오른쪽
                    (8, 10),    # 끝점
                    (3, 6),     # 아래쪽 포인트
                    (6, 2),     # 중간 오른쪽
                    (0, 4),     # 중앙 복귀
                    (3, 0),     # 상단 복귀
                    (-3, 2),    # 왼쪽 복귀
