def spawn_trade_point_star(x, y, source_type="wall"):
    """트레이드 포인트 별 생성 - 새로운 시스템 사용"""
    global trade_point_system
    trade_point_system.spawn_star(x, y, source_type)
    print(f"    ! (: {source_type})")

def update_trade_point_stars():
    """트레이드 포인트 별과 파티클 업데이트 - 새로운 시스템 사용"""
    global trade_point_system, trade_point_collected, current_stage
    global stage3_hearts_collected, stage4_crows_collected  # 레거시 호환성
    
    # 플레이어 패들과 공 위치로 업데이트 (둘 다 별을 수집할 수 있음)
    player_rect = PLAYER  # PLAYER는 이미 pygame.Rect 객체
    ball_rect = BALL  # BALL도 pygame.Rect 객체
    collected = trade_point_system.update(ball_rect, player_rect)
    
    # 수집된 개수 업데이트
    if collected > 0:
        trade_point_collected = trade_point_system.get_collected_count()
        
        # 레거시 변수 업데이트 (호환성)
        if current_stage == 3:
            stage3_hearts_collected = trade_point_collected
        elif current_stage == 4:
            stage4_crows_collected = trade_point_collected
            
        print(f"   ! : {trade_point_collected}")
        
        # 획득 효과음
        try:
            coin_sound = pygame.mixer.Sound(resource_path("sounds/coin.wav"))
            play_sound_with_volume(coin_sound)
        except:
            pass
    
    return  # 기존 코드는 무시
    
    # 아래는 기존 코드 (실행되지 않음)
    new_stars = []
    for star in trade_point_stars:
        if star['collected']:
            continue
            
        # 물리 업데이트
        star['x'] += star['vx']
        star['y'] += star['vy']
        star['vy'] += 0.12  # 중력 (하트보다 약간 가벼움)
        star['rotation'] += star['rotation_speed']
        star['life'] -= 1
        star['sparkle_phase'] += 0.15
        star['glow_intensity'] = 0.7 + 0.3 * abs(math.sin(star['sparkle_phase']))
        
        # 좌우 흔들림 (부드러운 떠다니는 효과)
        star['x'] += math.sin(star['y'] * 0.015 + star['sparkle_phase']) * 1.2
        
        # 플레이어 패들과 충돌 체크
        star_rect = pygame.Rect(star['x'] - star['size'], star['y'] - star['size'],
                                star['size'] * 2, star['size'] * 2)
        if star_rect.colliderect(PLAYER) and star['life'] > 0:
            # 트레이드 포인트 획득
            trade_point_collected += 1
            
            # 레거시 변수 업데이트 (호환성)
            if current_stage == 3:
                stage3_hearts_collected += 1
            elif current_stage == 4:
                stage4_crows_collected += 1
            
            print(f"   ! : {trade_point_collected}")
            
            # 텍스트 효과 추가
            trade_point_texts.append({
                'x': star['x'],
                'y': star['y'] - 20,
                'text': '+1 Star Point',
                'life': 80,
                'alpha': 255,
                'scale': 1.0
            })
            
            # 획득 파티클 폭발 효과
            for _ in range(15):
                particle = {
                    'x': star['x'],
                    'y': star['y'],
                    'vx': random.uniform(-3, 3),
                    'vy': random.uniform(-4, 1),
                    'size': random.uniform(2, 4),
                    'life': random.randint(40, 80),
                    'alpha': 255,
                    'color_shift': random.uniform(0, 1)
                }
                trade_point_particles.append(particle)
            
            # 획득 효과음
            try:
                coin_sound = pygame.mixer.Sound(resource_path("sounds/coin.wav"))
                play_sound_with_volume(coin_sound)
            except:
                pass
            
            star['collected'] = True
            continue
        
        # 화면 안에 있고 수명이 남은 별만 유지
        if star['life'] > 0 and star['y'] < HEIGHT + 50:
            new_stars.append(star)
    
    trade_point_stars = new_stars
    
    # 파티클 업데이트
    new_particles = []
    for particle in trade_point_particles:
        particle['x'] += particle['vx']
        particle['y'] += particle['vy']
        particle['vy'] += 0.05  # 약한 중력
        particle['vx'] *= 0.98  # 공기 저항
        particle['life'] -= 1
        particle['alpha'] = int(255 * (particle['life'] / 60))  # 페이드 아웃
        particle['size'] *= 0.98  # 크기 감소
        
        if particle['life'] > 0 and particle['alpha'] > 0:
            new_particles.append(particle)
    
    trade_point_particles = new_particles

def draw_trade_point_stars():
    """트레이드 포인트 별과 파티클 그리기 - 새로운 시스템 사용"""
    global trade_point_system
    trade_point_system.draw()
    return  # 기존 코드는 무시
    
    # 아래는 기존 코드 (실행되지 않음)
    for particle in trade_point_particles:
        if particle['alpha'] <= 0:
            continue
        
        # 색상 변화 (까마귀 파티클은 검은색, 일반 파티클은 형광색)
        color_shift = particle['color_shift']
        if color_shift == 0.0:  # 까마귀 파티클
            # 검은색에서 어두운 회색으로 변화
            gray_value = int(30 + particle['alpha'] * 0.2)
            r = gray_value
            g = gray_value
            b = gray_value
        elif color_shift < 0.33:
            # 노란색 → 흰색
            t = color_shift * 3
            r = int(255)
            g = int(255)
            b = int(100 + 155 * t)
        elif color_shift < 0.66:
            # 흰색 → 연한 파란색
            t = (color_shift - 0.33) * 3
            r = int(255 - 55 * t)
            g = int(255 - 30 * t)
            b = int(255)
        else:
            # 연한 파란색 → 노란색
            t = (color_shift - 0.66) * 3
            r = int(200 + 55 * t)
            g = int(225 + 30 * t)
            b = int(255 - 155 * t)
        
        # 파티클 그리기
        particle_surface = pygame.Surface((int(particle['size'] * 4), int(particle['size'] * 4)), pygame.SRCALPHA)
        pygame.draw.circle(particle_surface, (r, g, b, min(255, particle['alpha'])),
                         (int(particle['size'] * 2), int(particle['size'] * 2)), int(particle['size']))
        SCREEN.blit(particle_surface, (particle['x'] - particle['size'] * 2, particle['y'] - particle['size'] * 2))
    
    # 별 그리기
    for star in trade_point_stars:
        if star['collected']:
            continue
        
        # 투명도 계산
        alpha = min(255, star['life'] * 2)
        
        # 별의 실제 중심 좌표
        center_x = star['x']
        center_y = star['y']
        
        # 후광 효과 직접 그리기 (3단계) - 각 후광을 개별 서페이스로
        glow_alpha = int(alpha * 0.3 * star['glow_intensity'])
        for i in range(3):
            glow_size = star['size'] * (3 - i * 0.5)
            # 정확한 크기의 후광 서페이스 생성
            glow_surf_size = int(glow_size * 2 + 4)
            glow_surface = pygame.Surface((glow_surf_size, glow_surf_size), pygame.SRCALPHA)
            glow_color = (255, 240, 180, glow_alpha // (i + 1))
            pygame.draw.circle(glow_surface, glow_color, 
                             (glow_surf_size // 2, glow_surf_size // 2), int(glow_size))
            SCREEN.blit(glow_surface, (center_x - glow_surf_size // 2, center_y - glow_surf_size // 2))
        
        # 별 그리기를 위한 최소 크기 서페이스
        star_size = star['size'] * 2 + 4
        star_surface = pygame.Surface((star_size, star_size), pygame.SRCALPHA)
        local_center = star_size // 2
        
        # 5각 별 그리기
        points = []
        for i in range(10):
            angle = star['rotation'] + (i * math.pi / 5)
            if i % 2 == 0:
                # 외부 꼭지점
                radius = star['size']
            else:
                # 내부 꼭지점
                radius = star['size'] * 0.5
            x = local_center + radius * math.cos(angle)
            y = local_center + radius * math.sin(angle)
            points.append((x, y))
        
        # 별 색상 (은은한 형광 노란색)
        star_color = (255, 245, 200, alpha)
        if len(points) >= 3:
            pygame.draw.polygon(star_surface, star_color, points)
            
            # 테두리 (더 밝은 색)
            border_color = (255, 255, 230, int(alpha * 0.8))
            pygame.draw.polygon(star_surface, border_color, points, 2)
        
        # 중앙 반짝임
        sparkle_alpha = int(alpha * star['glow_intensity'])
        pygame.draw.circle(star_surface, (255, 255, 255, sparkle_alpha), (local_center, local_center), 3)
        
        # 화면에 그리기
        SCREEN.blit(star_surface, (center_x - local_center, center_y - local_center))

def update_trade_point_texts():
    """트레이드 포인트 텍스트 효과 업데이트"""
    global trade_point_texts
    new_texts = []
    
    for text_effect in trade_point_texts:
        # 수명 감소
        text_effect['life'] -= 1
        # 위로 이동
        text_effect['y'] -= 1.8
        # 페이드 아웃
        text_effect['alpha'] = min(255, text_effect['life'] * 3)
        # 스케일 애니메이션 (처음에 크게 나타났다가 작아짐)
        if text_effect['life'] > 70:
            text_effect['scale'] = 1.0 + (text_effect['life'] - 70) * 0.02
        else:
            text_effect['scale'] = 1.0
        
        # 수명이 남은 텍스트만 유지
        if text_effect['life'] > 0:
            new_texts.append(text_effect)
    
    trade_point_texts = new_texts

def draw_trade_point_texts():
    """트레이드 포인트 텍스트 효과 그리기 - 새로운 시스템에 포함됨"""
    # 새로운 시스템의 draw() 함수에서 이미 처리됨
    return
    
    # 아래는 기존 코드 (실행되지 않음)
    try:
        font = pygame.font.Font(resource_path("NeoDGM.ttf"), 20)
    except:
        font = pygame.font.Font(None, 20)
    
    for text_effect in trade_point_texts:
        if text_effect['alpha'] > 0:
            # 텍스트 렌더링
            text_surface = font.render(text_effect['text'], True, (255, 250, 200))
            
            # 스케일 적용
            if text_effect['scale'] != 1.0:
                scaled_size = (int(text_surface.get_width() * text_effect['scale']),
                              int(text_surface.get_height() * text_effect['scale']))
                text_surface = pygame.transform.scale(text_surface, scaled_size)
            
            # 투명도 적용
            text_surface.set_alpha(text_effect['alpha'])
            
            # 중앙 정렬로 그리기
            text_rect = text_surface.get_rect(center=(text_effect['x'], text_effect['y']))
            SCREEN.blit(text_surface, text_rect)

def update_stage3_hearts():
    """Stage 3 떨어지는 하트 업데이트 및 플레이어 충돌 체크"""
    global stage3_hearts, stage3_hearts_collected, stage3_trade_point_texts
    new_hearts = []
    for heart in stage3_hearts:
        # 물리 업데이트
        heart['x'] += heart['vx']
        heart['y'] += heart['vy']
        heart['vy'] += 0.15  # 중력 (잎사귀보다 약간 빠르게)
        heart['rotation'] += heart['rotation_speed']
        heart['life'] -= 1
        heart['sparkle_phase'] += 0.2  # 반짝임 애니메이션
        
        # 좌우 흔들림
        heart['x'] += math.sin(heart['y'] * 0.02 + heart['phase']) * 1.5
        
        # 플레이어 패들과 충돌 체크
        heart_rect = pygame.Rect(heart['x'] - heart['size'], heart['y'] - heart['size'],
                                 heart['size'] * 2, heart['size'] * 2)
        if heart_rect.colliderect(PLAYER) and heart['life'] > 0:
            # 트레이드 포인트용 카운터만 증가 (스킬 게이지는 증가하지 않음)
            stage3_hearts_collected += 1
            print(f"  !   : {stage3_hearts_collected}")
            
            # Star Point +1 텍스트 효과 추가 (세련된 버전)
            stage3_trade_point_texts.append({
                'x': heart['x'],
                'y': heart['y'] - 20,  # 하트 위에 표시
                'text': '+1 Star Point',  # 깔끔한 텍스트
                'life': 75,  # 75프레임 (1.25초) 동안 표시
                'alpha': 255
            })
            
            # 획득 효과음
            try:
                coin_sound = pygame.mixer.Sound(resource_path("sounds/coin.wav"))
                play_sound_with_volume(coin_sound)
            except:
                pass
            heart['life'] = 0  # 하트 제거
            continue
        
        # 화면 안에 있고 수명이 남은 하트만 유지
        if heart['life'] > 0 and heart['y'] < HEIGHT + 50:
            new_hearts.append(heart)
    stage3_hearts = new_hearts

def update_stage3_trade_point_texts():
    """Stage 3 트레이드 포인트 텍스트 효과 업데이트"""
    global stage3_trade_point_texts
    new_texts = []
    for text_effect in stage3_trade_point_texts:
        # 수명 감소
        text_effect['life'] -= 1
        # 위로 이동
        text_effect['y'] -= 1.5
        # 페이드 아웃
        text_effect['alpha'] = min(255, text_effect['life'] * 4)
        
        # 수명이 남은 텍스트만 유지
        if text_effect['life'] > 0:
            new_texts.append(text_effect)
    stage3_trade_point_texts = new_texts

def draw_stage3_trade_point_texts():
    """Stage 3 트레이드 포인트 텍스트 효과 그리기 (세련된 미니멀 스타일)"""
    try:
        # 적당한 크기의 폰트
        font = pygame.font.Font(resource_path("NeoDGM.ttf"), 20)
        font_small = pygame.font.Font(resource_path("NeoDGM.ttf"), 18)  # 그림자용
    except:
        font = pygame.font.Font(None, 20)
        font_small = pygame.font.Font(None, 18)
    
    for text_effect in stage3_trade_point_texts:
        if text_effect['alpha'] > 0:
            # 부드러운 스케일 애니메이션 (처음에 크게 나타났다가 작아짐)
            if text_effect['life'] > 65:  # 처음 10프레임
                scale = 1.2 - (75 - text_effect['life']) * 0.02
            else:
                scale = 1.0
            
            # 그림자 효과 (은은한 검은색)
            shadow_surface = font_small.render(text_effect['text'], True, (0, 0, 0))
            shadow_surface = pygame.transform.scale(shadow_surface,
                (int(shadow_surface.get_width() * scale),
                 int(shadow_surface.get_height() * scale)))
            shadow_alpha = int(text_effect['alpha'] * 0.3)
            shadow_surface.set_alpha(shadow_alpha)
            
            # 메인 텍스트 (흰색으로 깔끔하게)
            text_surface = font.render(text_effect['text'], True, (255, 255, 255))
            text_surface = pygame.transform.scale(text_surface,
                (int(text_surface.get_width() * scale),
                 int(text_surface.get_height() * scale)))
            text_surface.set_alpha(text_effect['alpha'])
            
            # 하이라이트 효과 (은은한 노란빛)
            highlight_surface = font.render(text_effect['text'], True, (255, 245, 200))
            highlight_surface = pygame.transform.scale(highlight_surface,
                (int(highlight_surface.get_width() * scale),
                 int(highlight_surface.get_height() * scale)))
            highlight_alpha = int(text_effect['alpha'] * 0.4 * (0.7 + 0.3 * math.sin(text_effect['life'] * 0.15)))
            highlight_surface.set_alpha(highlight_alpha)
            
            # 화면에 그리기 (위로 부드럽게 떠오르는 효과)
            float_y = text_effect['y'] - (75 - text_effect['life']) * 0.8  # 더 부드럽게 떠오름
            
            # 그림자 (약간 아래 오른쪽에)
            shadow_rect = shadow_surface.get_rect(center=(text_effect['x'] + 2, float_y + 2))
            SCREEN.blit(shadow_surface, shadow_rect)
            
            # 메인 텍스트
            text_rect = text_surface.get_rect(center=(text_effect['x'], float_y))
            SCREEN.blit(text_surface, text_rect)
            
            # 하이라이트 오버레이
            SCREEN.blit(highlight_surface, text_rect)

def draw_stage3_hearts():
    """Stage 3 떨어지는 하트 그리기"""
    for heart in stage3_hearts:
        # 투명도 계산 (페이드 아웃 효과)
        alpha = min(255, heart['life'] * 2)
        
        # 반짝임 효과
        sparkle = abs(math.sin(heart['sparkle_phase'])) * 0.5 + 0.5
        
        # 하트 그리기 (회전 적용)
        heart_surface = pygame.Surface((heart['size'] * 4, heart['size'] * 4), pygame.SRCALPHA)
        center_x = heart['size'] * 2
        center_y = heart['size'] * 2
        
        # 회전된 하트 그리기 (각도를 라디안으로 변환)
        rotation_rad = math.radians(heart['rotation'])
        cos_r = math.cos(rotation_rad)
        sin_r = math.sin(rotation_rad)
        
        # 하트 색상 (붉은빛 강조)
        # 붉은색과 핑크를 혼합하여 더 선명하게
        red_intensity = 0.7 + 0.3 * sparkle  # 반짝임에 따라 붉은색 강도 변화
        base_color = (int(255 * red_intensity), 20, 60)  # 선명한 붉은색
        sparkle_color = tuple(min(255, int(c + (255 - c) * sparkle * 0.5)) for c in base_color)
        
        # 붉은빛 후광 효과
        glow_size = heart['size'] * 2
        glow_alpha = int(alpha * 0.3 * (0.5 + 0.5 * sparkle))  # 반짝임과 함께 후광도 변화
        glow_surface = pygame.Surface((glow_size * 2, glow_size * 2), pygame.SRCALPHA)
        # 3단계 후광 그리기
        pygame.draw.circle(glow_surface, (255, 0, 0, glow_alpha // 3), 
                         (glow_size, glow_size), glow_size)
        pygame.draw.circle(glow_surface, (255, 50, 50, glow_alpha // 2), 
                         (glow_size, glow_size), int(glow_size * 0.7))
        pygame.draw.circle(glow_surface, (255, 100, 100, glow_alpha), 
                         (glow_size, glow_size), int(glow_size * 0.4))
        heart_surface.blit(glow_surface, (center_x - glow_size, center_y - glow_size))
        
        # 하트 상단 (두 원)
        left_circle_x = center_x - heart['size'] * 0.3
        left_circle_y = center_y - heart['size'] * 0.3
        right_circle_x = center_x + heart['size'] * 0.3
        right_circle_y = center_y - heart['size'] * 0.3
        
        # 회전 적용
        def rotate_point(px, py, cx, cy):
            dx = px - cx
            dy = py - cy
            return (cx + dx * cos_r - dy * sin_r,
                   cy + dx * sin_r + dy * cos_r)
        
        # 하트 모양 그리기
        # 두 원
        left_rot = rotate_point(left_circle_x, left_circle_y, center_x, center_y)
        right_rot = rotate_point(right_circle_x, right_circle_y, center_x, center_y)
        
        pygame.draw.circle(heart_surface, (*sparkle_color, alpha), 
                         (int(left_rot[0]), int(left_rot[1])), heart['size'] // 2)
        pygame.draw.circle(heart_surface, (*sparkle_color, alpha),
                         (int(right_rot[0]), int(right_rot[1])), heart['size'] // 2)
        
        # 하트 하단 (삼각형)
        points = [
            rotate_point(center_x - heart['size'], center_y, center_x, center_y),
            rotate_point(center_x, center_y + heart['size'], center_x, center_y),
            rotate_point(center_x + heart['size'], center_y, center_x, center_y)
        ]
        pygame.draw.polygon(heart_surface, (*sparkle_color, alpha), points)
        
        # 반짝임 효과 (별 모양)
        if sparkle > 0.7:
            star_size = heart['size'] // 3
            star_points = []
            for i in range(8):
                angle = i * math.pi / 4
                if i % 2 == 0:
                    dist = star_size
                else:
                    dist = star_size // 2
                px = center_x + math.cos(angle) * dist
                py = center_y + math.sin(angle) * dist
                star_points.append(rotate_point(px, py, center_x, center_y))
            pygame.draw.polygon(heart_surface, (255, 255, 255, int(alpha * sparkle)), star_points)
        
        # 화면에 그리기
        SCREEN.blit(heart_surface, (heart['x'] - center_x, heart['y'] - center_y))

def draw_stage2_leaves():
    """떨어지는 잎사귀 그리기 (디테일한 버전)"""
    for leaf in stage2_leaves:
        # 투명도 계산 (페이드 아웃 효과)
        alpha = min(255, leaf['life'] * 2)
        # 잎사귀 그리기 (회전 적용)
        leaf_surface = pygame.Surface((leaf['size'] * 3, leaf['size'] * 3), pygame.SRCALPHA)
        center = leaf['size'] * 1.5
        # 잎사귀 종류별로 다른 모양 그리기 (항상 디테일한 버전만 사용)
        leaf_type = leaf.get('type', 'tropical')  # 기본값을 tropical로 설정
        if leaf_type == 'maple':
            # 단풍잎 모양 (5개 끝)
            points = []
            for i in range(10):
                angle = leaf['rotation'] + i * 36
                rad = math.radians(angle)
                if i % 2 == 0:
                    length = leaf['size']
                else:
                    length = leaf['size'] * 0.5
                points.append((center + math.cos(rad) * length,
                             center + math.sin(rad) * length))
            pygame.draw.polygon(leaf_surface, (*leaf['color'], alpha), points)
        elif leaf_type == 'oak':
            # 물결 모양 타원 (참나무잎)
            for i in range(3):
                offset = i * 2
                pygame.draw.ellipse(leaf_surface, (*leaf['color'], max(0, alpha - i * 50)),
                                  (center - leaf['size']//2 + offset, 
                                   center - leaf['size'] + offset,
                                   leaf['size'] - offset * 2, 
                                   leaf['size'] * 2 - offset * 2))
        else:  # tropical 또는 기타
            # 열대 잎 (뾰족한 타원)
            points = [
                (center, center - leaf['size'] * 1.2),
                (center + leaf['size'] * 0.4, center),
                (center, center + leaf['size'] * 1.2),
                (center - leaf['size'] * 0.4, center)
            ]
            pygame.draw.polygon(leaf_surface, (*leaf['color'], alpha), points)
        # 잎맥 추가
        vein_color = tuple(max(0, c - 40) for c in leaf['color']) + (alpha//2,)
        pygame.draw.line(leaf_surface, vein_color,
                        (center, center - leaf['size']), 
                        (center, center + leaf['size']), 1)
        # 회전 적용
        rotated_leaf = pygame.transform.rotate(leaf_surface, leaf['rotation'])
        leaf_rect = rotated_leaf.get_rect(center=(int(leaf['x']), int(leaf['y'])))
        SCREEN.blit(rotated_leaf, leaf_rect)
def draw_tutorial_practice_room():
    """튜토리얼 연습장 배경 그리기 - Stage 2 스타일 + 사이버펑크"""
    # 중심점 먼저 정의
    center_x = WIDTH // 2
    center_y = HEIGHT // 2
    
    # 그라데이션 파란색 배경
    for i in range(HEIGHT):
        # 위에서 아래로 점점 밝아지는 그라데이션
        gradient_ratio = i / HEIGHT
        color_r = int(15 + gradient_ratio * 10)  # 15-25
        color_g = int(35 + gradient_ratio * 15)  # 35-50
        color_b = int(75 + gradient_ratio * 20)  # 75-95
        pygame.draw.line(SCREEN, (color_r, color_g, color_b), (0, i), (WIDTH, i))
    
    # 사이버펑크 바닥 그리드 패턴
    grid_color = (30, 50, 90)  # 어두운 파란색
    grid_bright = (50, 80, 140)  # 밝은 파란색
    neon_color = (0, 200, 255)  # 네온 청록색
    
    # 원근감을 위한 그리드 라인 (아래쪽이 더 넓게)
    grid_spacing = 40
    
    # 가로 그리드 라인 (원근감 적용)
    for i in range(15):
        y = HEIGHT - 100 - i * (grid_spacing - i * 2)  # 위로 갈수록 좁아짐
        if y > HEIGHT // 2:  # 중앙선 아래만
            alpha = int(100 - i * 5)  # 위로 갈수록 투명
            if alpha > 0:
                # 그리드 라인
                grid_surface = pygame.Surface((WIDTH, 2), pygame.SRCALPHA)
                grid_surface.fill((*grid_color, alpha))
                SCREEN.blit(grid_surface, (0, y))
                
                # 가끔 네온 효과
                if i % 3 == 0:
                    neon_surface = pygame.Surface((WIDTH, 1), pygame.SRCALPHA)
                    neon_surface.fill((*neon_color, alpha // 2))
                    SCREEN.blit(neon_surface, (0, y))
    
    # 세로 그리드 라인 (원근감)
    for i in range(-10, 11):
        x = center_x + i * grid_spacing
        # 중앙에서 멀수록 기울어짐
        start_x = x + i * 15
        end_x = x
        
        if 0 <= x <= WIDTH:
            # 그리드 라인
            pygame.draw.line(SCREEN, grid_color, 
                           (start_x, HEIGHT), 
                           (end_x, HEIGHT // 2), 1)
            
            # 가끔 네온 하이라이트
            if abs(i) % 4 == 0:
                neon_surface = pygame.Surface((2, HEIGHT // 2), pygame.SRCALPHA)
                for j in range(HEIGHT // 2):
                    alpha = int(50 * (j / (HEIGHT // 2)))
                    if alpha > 0:
                        neon_surface.set_at((0, j), (*neon_color, alpha))
                # 계산된 위치에 블릿
                line_x = start_x + (end_x - start_x) * j // (HEIGHT // 2)
                if 0 <= line_x < WIDTH:
                    SCREEN.blit(neon_surface, (line_x, HEIGHT // 2))
    
    # 사이버펑크 스캔라인 효과
    for y in range(0, HEIGHT, 4):
        scanline_surface = pygame.Surface((WIDTH, 1), pygame.SRCALPHA)
        scanline_surface.fill((0, 0, 0, 20))
        SCREEN.blit(scanline_surface, (0, y))
    
    # 스타디움 스타일 코트 라인 (은은한 색상)
    line_color = (150, 170, 200)  # 은은한 회청색
    line_width = 3
    
    # 중앙 원 (Stage 2처럼 하나의 원만)
    circle_radius = 80
    
    # 중앙 가로선 (원 밖에만 그리기)
    # 왼쪽 부분 (원 왼쪽까지)
    pygame.draw.line(SCREEN, line_color, 
                    (0, center_y), 
                    (center_x - circle_radius, center_y), 
                    line_width)
    
    # 오른쪽 부분 (원 오른쪽부터)
    pygame.draw.line(SCREEN, line_color, 
                    (center_x + circle_radius, center_y), 
                    (WIDTH, center_y), 
                    line_width)
    
    # 중앙 원 그리기 (네온 효과 추가)
    # 외부 글로우
    for i in range(5):
        glow_radius = circle_radius + i * 2
        glow_alpha = 30 - i * 5
        glow_surface = pygame.Surface((glow_radius * 2 + 10, glow_radius * 2 + 10), pygame.SRCALPHA)
        pygame.draw.circle(glow_surface, (*neon_color, glow_alpha), 
                         (glow_radius + 5, glow_radius + 5), glow_radius, 1)
        SCREEN.blit(glow_surface, (center_x - glow_radius - 5, center_y - glow_radius - 5))
    
    # 메인 원
    pygame.draw.circle(SCREEN, line_color, (center_x, center_y), circle_radius, line_width)

def draw_field():
    global psycho_bg_timer, earthquake_offset_x, earthquake_offset_y
    
    # Stage 50 (튜토리얼) - 연습장 배경
    if current_stage == 50:
        draw_tutorial_practice_room()
        return
    
    if current_stage == 3 and emotional_overdrive_active:
        # 깜빡이거나 색 바뀌는 배경
        psycho_bg_timer += 1
        if psycho_bg_timer % 35 < 15:
            # 밝은 보라색 계열
            SCREEN.fill((255, 100, 255))
        else:
            # 어두운 남보라 계열
            SCREEN.fill((100, 0, 150))
        # 또는 완전 무작위 컬러 배경 효과 (좀 더 강한 사이코 느낌)
        # random_color = (random.randint(100,255), random.randint(0,100), random.randint(100,255))
        # SCREEN.fill(random_color)
