def choose_server(show_text=True):
    global is_player_serve, is_waiting_for_serve, waiting_start_time, wait_delay
    global boss_fake_move, boss_fake_start_time, boss_fake_during_player_serve
    global rolling_charges, rolling_charge_timer, rolling_consecutive_count, rolling_cooldown, token_states
    global mega_smashing_active, mega_smashing_start_time, mega_smashing_bonus_applied, mega_smashing_boss_defense_count
    global power_smashing_freeze_active, power_smashing_freeze_start_time
    global rolling_active, rolling_timer, rolling_direction, rolling_stun_timer
    global last_hit_by  # 서브하는 사람에 따라 초기화
    global tutorial_needs_dash_practice  # 튜토리얼 대쉬 연습 플래그
    global smasher_pending_contact_offset
    # 고스트샷 및 파워스매싱 상태 초기화 (라운드 시작 시)
    mega_smashing_active = False
    mega_smashing_start_time = 0
    mega_smashing_bonus_applied = False
    mega_smashing_boss_defense_count = 0  # 보스 방어 카운터 리셋
    power_smashing_freeze_active = False
    power_smashing_freeze_start_time = 0
    smasher_pending_contact_offset = None
    # 고스트샷 관련 코드 제거됨
    # 스테이지 6과 튜토리얼(스테이지 50)에서는 항상 플레이어가 먼저 서브
    # 단, 튜토리얼 대쉬 연습 모드에서는 보스가 서브
    if current_stage == 50:
        # 대쉬 튜토리얼 체크
        if 'tutorial_needs_dash_practice' in globals() and tutorial_needs_dash_practice:
            is_player_serve = False  # 대쉬 연습 시 보스가 서브
            print("튜토리얼: 대쉬 연습 - 보스가 서브합니다")
        else:
            is_player_serve = True  # 일반 튜토리얼은 플레이어 서브
    elif current_stage == 6:
        is_player_serve = True
    else:
        is_player_serve = random.choice([True, False])
    
    # 서브하는 사람에 따라 last_hit_by 초기화
    last_hit_by = "player" if is_player_serve else "boss"
    game_vars.ball.last_hit_by = last_hit_by  # game_vars에도 업데이트
    
    # 스테이지 3에서 플레이어 서브일 때 꼬리 채찍 5초 지연
    global stage3_tail_whip_cooldown
    if current_stage == 3 and is_player_serve:
        stage3_tail_whip_cooldown = 300  # 5초 (60FPS * 5)
        print("Stage 3:   -   5")
    
    is_waiting_for_serve = True
    waiting_start_time = pygame.time.get_ticks()
    
    # 서브 완료 타이머 초기화
    global serve_completed_timer
    serve_completed_timer = 0
    
    # Stage 3 쿠로미 신비로운 궤적 효과 초기화
    global kuromi_spit_trail_active, kuromi_spit_trail_positions, kuromi_spit_trail_color_phase
    if current_stage == 3:
        kuromi_spit_trail_active = False
        kuromi_spit_trail_positions = []
        kuromi_spit_trail_color_phase = 0
        print("Stage 3: 쿠로미 궤적 이펙트 초기화")
    
    # 전설 아이템 라운드 효과 초기화 (물방울 파티클 등)
    legendary_manager = get_legendary_manager()
    if legendary_manager:
        legendary_manager.reset_round_effects()
    
    #  새 라운드 시작 시 토큰 시스템 초기화
    base_charges = 1
    holder_bonus = 1 if dashholder_obtained else 0
    amplification_bonus = academy.get_skill_bonus("dash_amplification") if 'academy' in globals() else 0
    max_charges = int(base_charges + holder_bonus + amplification_bonus)
    rolling_charges = max_charges
    rolling_charge_timer = 0
    rolling_consecutive_count = 0
    rolling_cooldown = 0
    # 토큰 상태 리스트 초기화 (모든 토큰 사용 가능)
    global token_states
    token_states = [True] * max_charges  # 모든 토큰 충전된 상태로 시작
    # 키 이벤트 큐 비우기 - 대쉬 버그 방지 (특히 윈도우)
    pygame.event.clear()  # 모든 이벤트 클리어
    pygame.event.pump()
    pygame.key.set_repeat()  # 키 반복 설정 리셋
    # 대쉬 매니저와 동기화
    # 레거시 대쉬 변수 명시적 초기화
    rolling_active = False
    rolling_timer = 0
    rolling_direction = 0
    rolling_stun_timer = 0
    rolling_dash_available_timer = 0  # 추가 초기화
    # 플레이어 속도 초기화
    global current_speed
    current_speed = 0
    if 'dash' in globals() and dash is not None:
        dash.reset_to_max()
        dash.is_active = False  # 명시적으로 비활성화
        dash.timer = 0
        dash.stun_timer = 0
    if is_player_serve:
        # 플레이어 서브: 스페이스바 대기
        wait_delay = 0
        boss_fake_move = False
        boss_fake_during_player_serve = False
    else:
        # 보스 서브
        if random.random() < 0.5:
            #  즉시 서브 (바로 serve_ball 호출)
            wait_delay = 0
            boss_fake_move = False
        else:
            #  간보기 서브 (1.5~2.5초 동안 움직이다가 서브)
            wait_delay = random.randint(1500, 2500)
            boss_fake_move = True
            boss_fake_start_time = pygame.time.get_ticks()
    boss_fake_during_player_serve = is_player_serve
    physics_manager.reset_ball(is_player_serve)
    # 튜토리얼 스테이지에서는 서브 화면 표시 안함
    if show_text and current_stage != 50:
        boss_name = boss_names.get(current_stage, "보스")
        serve_text = "플레이어 서브!" if is_player_serve else f"{boss_name} 서브!"
        show_fade_text(serve_text)
def create_prism_particle_burst(x, y):
    """프리즘 빛가루 파티클 생성 (Stage 3 꼬리 채찍 히트 전용)"""
    global prism_particles
    
    # 7가지 무지개 색상 정의
    rainbow_colors = [
        (255, 0, 0),      # 빨강
        (255, 127, 0),    # 주황
        (255, 255, 0),    # 노랑
        (0, 255, 0),      # 초록
        (0, 127, 255),    # 하늘
        (0, 0, 255),      # 파랑
        (127, 0, 255)     # 보라
    ]
    
    # 30~50개의 파티클 생성
    particle_count = random.randint(30, 50)
    
    for i in range(particle_count):
        # 랜덤 방향과 속도
        angle = random.uniform(0, math.pi * 2)
        speed = random.uniform(3, 10)
        vx = math.cos(angle) * speed
        vy = math.sin(angle) * speed
        
        # 무지개 색상 중 하나 선택 (순환적으로 또는 랜덤하게)
        color = rainbow_colors[i % len(rainbow_colors)]
        
        # 파티클 크기는 작게 (빛가루 느낌)
        size = random.uniform(2, 5)
        
        # 수명 (1~2초)
        lifetime = random.randint(60, 120)
        
        # 파티클 추가
        prism_particles.append({
            'x': x,
            'y': y,
            'vx': vx,
            'vy': vy,
            'color': color,
            'size': size,
            'lifetime': lifetime,
            'max_lifetime': lifetime,
            'sparkle': random.uniform(0, math.pi * 2)  # 반짝임 효과용
        })

def update_prism_particles():
    """프리즘 파티클 업데이트"""
    global prism_particles
    
    new_particles = []
    for particle in prism_particles:
        # 위치 업데이트
        particle['x'] += particle['vx']
        particle['y'] += particle['vy']
        
        # 중력 효과 (살짝 아래로)
        particle['vy'] += 0.1
        
        # 공기 저항 (속도 감소)
        particle['vx'] *= 0.98
        particle['vy'] *= 0.98
        
        # 반짝임 효과 업데이트
        particle['sparkle'] += 0.3
        
        # 수명 감소
        particle['lifetime'] -= 1
        
        # 화면 밖이거나 수명이 다한 파티클 제거
        if (particle['lifetime'] > 0 and 
            -50 < particle['x'] < WIDTH + 50 and 
            -50 < particle['y'] < HEIGHT + 50):
            new_particles.append(particle)
    
    prism_particles = new_particles

def draw_prism_particles(screen):
    """프리즘 파티클 그리기"""
    for particle in prism_particles:
        # 수명에 따른 투명도 계산
        alpha_ratio = particle['lifetime'] / particle['max_lifetime']
        
        # 반짝임 효과로 크기 변화
        sparkle_size = particle['size'] * (1 + math.sin(particle['sparkle']) * 0.3)
        
        # 빛나는 효과를 위해 여러 레이어로 그리기
        # 외곽 글로우
        glow_size = sparkle_size * 2
        glow_alpha = int(alpha_ratio * 50)
        glow_color = tuple(min(255, c + 100) for c in particle['color'])
        glow_surf = pygame.Surface((int(glow_size * 2), int(glow_size * 2)), pygame.SRCALPHA)
        pygame.draw.circle(glow_surf, (*glow_color, glow_alpha), 
                         (int(glow_size), int(glow_size)), int(glow_size))
        screen.blit(glow_surf, (int(particle['x'] - glow_size), int(particle['y'] - glow_size)))
        
        # 중심 파티클
        core_alpha = int(alpha_ratio * 255)
        core_surf = pygame.Surface((int(sparkle_size * 2), int(sparkle_size * 2)), pygame.SRCALPHA)
        pygame.draw.circle(core_surf, (*particle['color'], core_alpha),
                         (int(sparkle_size), int(sparkle_size)), int(sparkle_size))
        screen.blit(core_surf, (int(particle['x'] - sparkle_size), int(particle['y'] - sparkle_size)))
        
        # 중심 밝은 점
        if sparkle_size > 2:
            bright_size = max(1, sparkle_size / 3)
            bright_surf = pygame.Surface((int(bright_size * 2), int(bright_size * 2)), pygame.SRCALPHA)
            pygame.draw.circle(bright_surf, (255, 255, 255, core_alpha),
                             (int(bright_size), int(bright_size)), int(bright_size))
            screen.blit(bright_surf, (int(particle['x'] - bright_size), int(particle['y'] - bright_size)))

def create_impact_effect(x, y, ball_speed, is_player=True):
    """타격 이펙트 생성 - Phase 101: unified_effects 사용"""
    global impact_particles, last_impact_strength
    # 공 속도 계산 (속도 벡터의 크기)
    speed = math.sqrt(ball_speed[0]**2 + ball_speed[1]**2)
    # 속도에 따른 강도 계산 (2~6 범위, 매우 소소하게)
    strength = min(6, max(2, int(speed * 0.4)))  # 훨씬 작은 강도
    last_impact_strength = strength
    # 파티클 개수 - 매우 적게 (2~4개)
    particle_count = 2 + (strength // 3)  # 2~4개만
    
    # Phase 101: unified_effects 사용
    unified_effects.spawn_directional_particles(
        x, y, 
        direction=math.atan2(-ball_speed[1], -ball_speed[0]),
        spread=45,
        count=particle_count,
        color=Colors.WHITE,
        speed=strength * 2
    )
    
    # 기존 코드는 호환성을 위해 유지
    base_color = WHITE  # 심플한 흰색
    # 파티클 생성 - 스파크 라인 형태
    for _ in range(particle_count):
        # 각도: 충돌 지점에서 방사형으로 퍼짐 (격투게임 스타일)
        angle = random.uniform(0, 2 * math.pi)
        # 매우 빠른 초기 속도, 빠른 감속
        speed = random.uniform(8, 12)  # 빠른 초기 속도
        vx = math.cos(angle) * speed
        vy = math.sin(angle) * speed
        # 매우 작은 크기 (거의 티 안남)
        size = random.randint(1, 2)  # 1-2픽셀만
        # 파티클 추가 [x, y, vx, vy, size, alpha, color, life]
        impact_particles.append([
            x + random.uniform(-2, 2),  # 작은 위치 분산
            y + random.uniform(-2, 2),
            vx, vy, size, 180, base_color, 8  # 8프레임만 생존 (매우 빠름)
        ])
def update_impact_particles():
    """타격 이펙트 파티클 업데이트 - 격투게임 스타일"""
    global impact_particles
    for particle in impact_particles[:]:
        # 딕셔너리 형식과 리스트 형식 모두 지원
        if isinstance(particle, dict):
            # 딕셔너리 형식 업데이트
            particle["x"] += particle.get("vx", 0)
            particle["y"] += particle.get("vy", 0)
            particle["vx"] *= 0.85  # 빠른 감속
            particle["vy"] *= 0.85  # 빠른 감속
            particle["life"] = particle.get("life", 1) - 1
            particle["alpha"] = max(0, particle.get("alpha", 0) - 22)
            
            # 생명력이 다하면 제거
            if particle.get("life", 0) <= 0 or particle.get("alpha", 0) <= 0:
                impact_particles.remove(particle)
        else:
            # 리스트 형식 업데이트
            particle[0] += particle[2]  # x += vx
            particle[1] += particle[3]  # y += vy
            particle[2] *= 0.85  # 빠른 감속
            particle[3] *= 0.85  # 빠른 감속
            particle[7] -= 1  # 생명력 감소
            particle[5] = max(0, particle[5] - 22)  # 빠른 페이드아웃
            
            # 생명력이 다하면 제거
            if particle[7] <= 0 or particle[5] <= 0:
                impact_particles.remove(particle)
def draw_impact_particles():
    """타격 이펙트 파티클 그리기 - 격투게임 스타일"""
    for particle in impact_particles:
        # 딕셔너리 형식과 리스트 형식 모두 지원
        if isinstance(particle, dict):
            x = particle.get("x", 0)
            y = particle.get("y", 0)
            vx = particle.get("vx", 0)
            vy = particle.get("vy", 0)
            size = particle.get("size", 1)
            alpha = particle.get("alpha", 0)
            color = particle.get("color", (255, 255, 255))
            life = particle.get("life", 1)
        else:
            # 리스트 형식
            x, y, vx, vy, size, alpha, color, life = particle
        
        # 알파값이 있는 경우에만 그리기
        if alpha > 0:
            # 격투게임 스타일 - 스파크 라인 그리기
            color_with_alpha = (*color, alpha)
            # 속도 벡터를 이용한 라인 그리기 (스파크 효과)
            line_length = math.sqrt(vx*vx + vy*vy) * 0.8  # 속도에 비례한 라인 길이
            if line_length > 1:
                end_x = x + (vx / line_length) * min(line_length, 8)  # 최대 8픽셀 라인
                end_y = y + (vy / line_length) * min(line_length, 8)
                # 얇은 스파크 라인
                if size > 1:
                    draw.line(color, (int(x), int(y)), (int(end_x), int(end_y)), int(size))
                else:
                    # 1픽셀 점만 그리기
                    draw.circle(color, (int(x), int(y)), 1)
def calculate_bounce(paddle):
    global vertical_bounce_count, ball_angle, ball_impact_boost
    global perfect_timing_active, perfect_direction, perfect_timing_indicator_active
    global drive_speed_increase, smoke_zones, ball_vel
    global speed_defense_active, SPEED_DEFENSE_BLOCK_RATE
    global short_shot_active, short_shot_timer, short_shot_vertical_timer
    global short_shot_speed, short_shot_target_vx, short_shot_target_vy, short_shot_original_speed
    global player_up_pressed, player_collision_handled, player_collision_cooldown
    global special_gauge, short_shot_counter_window, short_shot_counter_pending
    global perfect_timing_active, perfect_timing_frame_count, perfect_timing_cooldown
    global perfect_timing_input_used, perfect_direction, perfect_timing_indicator_active
    global rolling_active, is_half_dash_active
    global ragnarok_original_speed
    global is_waiting_for_serve, stopwatch_active, stopwatch_timer
    global blacksmith_shield_swing_active, blacksmith_shield_swing_timer
    global suicide_drone_ball_boost_active, suicide_drone_ball_speed_backup
    
    # Stage 2 스피드 디펜스 80% 방어 처리
    if paddle == BOSS and current_stage == 2 and speed_defense_active:
        # 80% 확률로 방어 (20% 확률로 통과)
        if random.random() < SPEED_DEFENSE_BLOCK_RATE:
            # 방어 성공 - 정상 속도로 반사 (스피드 디펜스는 막을 확률만 있고 속도는 그대로)
            print(f"🛡️ 스피드 디펜스 방어 성공! (80% 확률)")
            # 방어 효과음
            try:
                play_sound_with_volume(SOUND_DEFENSE_BLOCK)
            except:
                pass
            # 방어 성공 시에도 정상적으로 공을 반사 (속도 감소 없음)
        else:
            # 20% 확률로 방어 실패 - 정상 처리
            print(f"⚠️ 스피드 디펜스 방어 실패! (20% 확률)")
    
    # 패들 타입 확인 (플레이어 vs 보스)
    is_player_paddle = (paddle == PLAYER)
    # Stage 2 정글지진: 플레이어 패들에 공이 닿으면 지진 효과를 강제 종료
    if is_player_paddle and current_stage == 2 and quake_active:
        force_end_quake_on_player_hit()
    # 드라이브 발동 여부를 반환하기 위한 변수
    drive_activated = False
    counter_bonus_applied = False
    counter_bonus_speed_gain = 0.0
    
    # 보스가 공을 칠 때 포세이돈 삼지창 회오리 가속 효과 해제
    if not is_player_paddle:  # 보스가 공을 칠 때
        try:
            from legendary_items import get_legendary_manager
            legendary_manager = get_legendary_manager()
            if legendary_manager:
                trident = legendary_manager.get_item("poseidon_trident")
                if trident and trident.active:
                    # deactivate_water_trail을 호출하여 boss_hit_count 증가시키기
                    trident.deactivate_water_trail()
        except Exception as e:
            print(f"[ERROR] 포세이돈 효과 처리 실패: {e}")
        if short_shot_active or short_shot_counter_pending:
            if short_shot_original_speed > 0:
                current_mag = math.hypot(ball_vel[0], ball_vel[1])
                if current_mag > 0:
                    restore_ratio = short_shot_original_speed / current_mag
                    ball_vel[0] *= restore_ratio
                    ball_vel[1] *= restore_ratio
            if short_shot_counter_pending:
                short_shot_counter_window = SHORT_SHOT_COUNTER_WINDOW_FRAMES
                print(f"[SHOT-BONUS] 보스 반격 감지 → 카운터 윈도우 시작 ({short_shot_counter_window}프레임)")
                # 쇼트 카운터 창이 열리면 퍼펙트 타이밍 윈도우도 강제로 활성화해 드라이브 입력을 보장
                perfect_timing_active = True
                perfect_timing_frame_count = 0
                perfect_timing_cooldown = 0
                perfect_timing_input_used = False
                perfect_direction = None
                refresh_perfect_timing_indicator()
            short_shot_counter_pending = False
            short_shot_active = False
            short_shot_timer = 0
            short_shot_vertical_timer = 0
            short_shot_speed = 0.0
            short_shot_target_vx = 0.0
            short_shot_target_vy = 0.0
            short_shot_original_speed = 0.0
            short_shot_current_angle = 0.0
            short_shot_target_angle = 0.0
            short_shot_target_y = 0.0
            short_shot_extra_vertical_frames = 0
            short_shot_curve_started = False
            short_shot_curve_elapsed_frames = 0
        else:
            if short_shot_counter_window > 0:
                print("[SHOT-BONUS] 보스 일반 반격으로 카운터 윈도우 취소")
                short_shot_counter_window = 0
                refresh_perfect_timing_indicator()
            if short_shot_counter_pending:
                print("[SHOT-BONUS] 보스가 쇼트를 반격하지 않아 대기 상태 해제")
                short_shot_counter_pending = False

    #  플레이어가 공을 칠 때 연막 감속 효과 해제
    if is_player_paddle:
        # 플레이어가 공을 되받더라도 보스 반격 기회는 유지하고,
        # 실제 드라이브 판정 후에만 카운터 윈도우 종료 여부를 판단한다.
        # 모든 연막 존에서 속도 복원 정보 확인
        for smoke_zone in smoke_zones:
            if hasattr(smoke_zone, "original_speed") and hasattr(smoke_zone, "affecting_ball"):
                # 원래 속도로 복원
                original_speed = smoke_zone["original_speed"]
                current_speed = math.hypot(ball_vel[0], ball_vel[1])
                if current_speed > 0:
                    speed_ratio = original_speed / current_speed
                    ball_vel[0] *= speed_ratio
                    ball_vel[1] *= speed_ratio
                    print(f"   !   ! ({current_speed:.1f} → {original_speed:.1f})")
                # 속도 복원 후 플래그 제거
                del smoke_zone["original_speed"]
                del smoke_zone["affecting_ball"]
                break
        
        #  라그나로크 해머가 활성화되어 있으면 50% 확률로 스턴공 발동
        try:
            from legendary_items import get_legendary_manager
            legendary_manager = get_legendary_manager()
            global ragnarok_speed_boost_active, ragnarok_stun_attempted_this_rally
            # ragnarok_stun_attempted_this_rally가 없으면 생성
            if 'ragnarok_stun_attempted_this_rally' not in globals():
                ragnarok_stun_attempted_this_rally = False
            
            if legendary_manager and "ragnarok_hammer" in legendary_manager.active_items:
                hammer = legendary_manager.items.get("ragnarok_hammer")
                # 이번 랠리에서 아직 스턴공을 시도하지 않았고, 현재 스턴공이 활성화되지 않은 경우에만
                if hammer and hammer.active and not ragnarok_speed_boost_active and not ragnarok_stun_attempted_this_rally:
                    # 이번 랠리에서 스턴공 시도함을 표시
                    ragnarok_stun_attempted_this_rally = True
                    # 50% 확률로 스턴공 발동
                    if random.random() < 0.5:
                        # 스턴공 발동 - 공속 50% 증가 (나중에 적용하기 위해 플래그만 설정)
                        ragnarok_speed_boost_active = True
                        print(f"⚡ 라그나로크 스턴공 발동 준비! (calculate_bounce)")
                    else:
                        print(f"[라그나로크] 스턴공 발동 실패 (50% 확률)")

        except Exception as e:
            print(f"[ERROR] 전설 아이템 효과 처리 실패 (calculate_bounce): {e}")

    scale_applied = paddle_scale_ratio if paddle_scale_ratio > 0 else 1.0
    effective_centerx = PLAYER.centerx
    umbrella_half_left = PADDLE_WIDTH / 2
    umbrella_half_right = PADDLE_WIDTH / 2

    if selected_character_type == "blacksmith" and blacksmith_umbrella_open:
        effective_centerx += int(round(blacksmith_umbrella_body_offset[0] * scale_applied))
        left_extent, right_extent = blacksmith_umbrella_hitbox_extents
        left_extent_scaled = left_extent * scale_applied * 0.85
        right_extent_scaled = right_extent * scale_applied * 0.85
        umbrella_half_left = max(umbrella_half_left, left_extent_scaled)
        umbrella_half_right = max(umbrella_half_right, right_extent_scaled)

    base_centerx = paddle.centerx if 'paddle' in locals() else PLAYER.centerx
    paddle_centerx = effective_centerx if selected_character_type == "blacksmith" else base_centerx
    half_width_pos = umbrella_half_right if BALL.centerx >= paddle_centerx else umbrella_half_left
    half_width_pos = max(half_width_pos, 1.0)
    rel_x = (BALL.centerx - paddle_centerx) / half_width_pos
    rel_x = max(-1.0, min(1.0, rel_x))
    # 기본 각도
    angle = rel_x * (math.pi / 3)
    # 기본 속도 (신성 월계수 효과 적용 후 재계산)
    speed = math.hypot(ball_vel[0], ball_vel[1])

    if (
        is_player_paddle
        and selected_character_type == "blacksmith"
        and blacksmith_umbrella_open
        and blacksmith_shield_swing_active
        and blacksmith_shield_swing_timer > 0
    ):
        swing_progress = 0.0
        if BLACKSMITH_SHIELD_SWING_DURATION > 0:
            swing_progress = 1.0 - (blacksmith_shield_swing_timer / BLACKSMITH_SHIELD_SWING_DURATION)
        if swing_progress < 0.5:
            print("[BLACKSMITH] Shield rising deflect triggered (no speed boost)")
            try:
                effects_manager.create_impact_effect(BALL.centerx, BALL.centery, 32, is_player=True)
                effects_manager.spawn_star_particles(BALL.centerx, BALL.centery, count=10)
            except Exception:
                pass
            blacksmith_trail_timer = BLACKSMITH_TRAIL_DURATION

    # 스매셔 쇼트 발동 처리 (플레이어 패들 전용)
    if (
        is_player_paddle
        and selected_character_type == "smasher"
        and player_up_pressed
        and not short_shot_active
        and special_gauge >= 100
    ):
        # 쇼트는 서브 상태나 스톱워치 정지 중에는 발동되지 않도록 가드
        if not is_waiting_for_serve and not (stopwatch_active and stopwatch_timer > 0):
            if speed < BALL_BASE_SPEED * 0.6:
                speed = BALL_BASE_SPEED * 0.6
            short_shot_active = True
            consume_special_gauge(100)
            short_shot_timer = SMASHER_SHOT_TOTAL_FRAMES
            short_shot_vertical_timer = SMASHER_SHOT_VERTICAL_FRAMES
            short_shot_original_speed = speed
            short_shot_speed = speed * SMASHER_SHOT_SPEED_MULTIPLIER
            short_shot_counter_pending = True

            vertical_angle = -math.pi / 2
            max_angle_rad = math.radians(SMASHER_SHOT_MAX_ANGLE_DEG)
            min_angle_rad = math.radians(25)
            boss_x = BOSS.centerx if 'BOSS' in globals() else WIDTH // 2
            boss_y = BOSS.centery if 'BOSS' in globals() else HEIGHT // 4
            dx = boss_x - BALL.centerx
            dy = boss_y - BALL.centery
            if dy >= 0:
                dy = -abs(dy) if dy != 0 else -BALL_BASE_SPEED
            raw_target_angle = math.atan2(dy, dx)
            angle_diff = raw_target_angle - vertical_angle
            direction_sign = -1 if angle_diff < 0 else 1
            abs_diff = abs(angle_diff)
            if abs_diff < min_angle_rad:
                abs_diff = min_angle_rad
            elif abs_diff > max_angle_rad:
                abs_diff = max_angle_rad
            short_shot_target_angle = vertical_angle + direction_sign * abs_diff
            short_shot_current_angle = vertical_angle
            short_shot_target_vx = math.cos(short_shot_target_angle) * short_shot_speed
            short_shot_target_vy = math.sin(short_shot_target_angle) * short_shot_speed
            short_shot_target_y = boss_y
            short_shot_extra_vertical_frames = 0
            short_shot_curve_started = False
            short_shot_curve_elapsed_frames = 0

            ball_vel[0] = math.cos(short_shot_current_angle) * short_shot_speed
            ball_vel[1] = math.sin(short_shot_current_angle) * short_shot_speed
            ball_angle = 270.0
            target_deg = math.degrees(short_shot_target_angle)
            if target_deg < 0:
                target_deg += FULL_ROTATION
            print(f"[SHOT] setup target={target_deg:.2f}°")

            player_collision_handled = True
            player_collision_cooldown = 15

            try:
                play_sound_with_volume(SOUND_STAGE6_BEAM_CHARGE)
            except Exception:
                pass
            print(f"[SHOT] activated speed={short_shot_speed:.2f}, target={target_deg:.1f}°")
            return False
    #  공속도에 따른 충돌 부스트 조정 (강화된 과속 방지 시스템)
    base_speed_threshold = 10.0  # 기준 속도 (더 낮은 속도부터 감소 시작)
    max_speed_threshold = 18.0   # 최대 속도 (더 낮은 속도에서 최소값 도달)
    # 공속도 비율 계산 (0.0 ~ 1.0)
    if speed <= base_speed_threshold:
        speed_ratio = 0.0
    elif speed >= max_speed_threshold:
        speed_ratio = 1.0
    else:
        speed_ratio = (speed - base_speed_threshold) / (max_speed_threshold - base_speed_threshold)
    #  수정: 속도가 높아져도 초기 임팩트 부스트는 유지
    #  각도 기반 부스트 시스템: 수평에 가까울수록 더 큰 부스트
    # 현재 공의 각도 계산 (Y속도와 X속도의 비율)
    ball_angle_deg = 90  # 기본값 (수직)
    if abs(ball_vel[0]) > 0.1:  # X속도가 거의 0이 아닐 때
        # atan2를 사용해 정확한 각도 계산 (라디안 → 도)
        ball_angle_rad = math.atan2(abs(ball_vel[1]), abs(ball_vel[0]))
        ball_angle_deg = math.degrees(ball_angle_rad)
    
    # 각도에 따른 부스트 계산 (수평에 가까울수록 높은 부스트)
    # 90도 (수직) = 2.0x, 0도 (수평) = 2.8x
    if ball_angle_deg >= 90:
        angle_boost_multiplier = 2.0  # 200%
    elif ball_angle_deg >= 80:
        # 90도에서 80도: 200% → 220%
        angle_ratio = (90 - ball_angle_deg) / 10
        angle_boost_multiplier = 2.0 + 0.2 * angle_ratio
    elif ball_angle_deg >= 70:
        # 80도에서 70도: 220% → 240%
        angle_ratio = (80 - ball_angle_deg) / 10
        angle_boost_multiplier = 2.2 + 0.2 * angle_ratio
    elif ball_angle_deg >= 60:
        # 70도에서 60도: 240% → 260%
        angle_ratio = (70 - ball_angle_deg) / 10
        angle_boost_multiplier = 2.4 + 0.2 * angle_ratio
    elif ball_angle_deg >= 45:
        # 60도에서 45도: 260% → 280%
        angle_ratio = (60 - ball_angle_deg) / 15
        angle_boost_multiplier = 2.6 + 0.2 * angle_ratio
    else:
        # 45도 미만: 최대 280%
        angle_boost_multiplier = 2.8
    
    base_boost = angle_boost_multiplier  # 각도 기반 부스트 적용
    min_boost = 1.1         # 최소 110% 부스트 (고속에서 적절한 반응 시간 확보)
    
    # 디버그 출력 (가끔씩만)
    if pygame.time.get_ticks() % 180 < 16:  # 3초마다
        print(f"   : {ball_angle_deg:.1f}° → {angle_boost_multiplier:.1%}")
    #  관성 보존: 저속에서 벽 충돌 후 자연스러운 속도 유지
    current_time = pygame.time.get_ticks()
    # 최근 벽 충돌 후 800ms 내에는 관성 보존 적용
    wall_collision_bonus = 1.0
    if last_wall_collision_time > 0 and current_time - last_wall_collision_time < 800:
        if speed < 12:  # 저속 구간에서만 적용
            momentum_factor = min(1.4, 1.0 + (12 - speed) * 0.06)  # 속도가 낮을수록 더 큰 보너스
            wall_collision_bonus = momentum_factor
            print(f"  : ={speed:.1f}, ={momentum_factor:.2f}x")
    #  완만한 감소 적용 (급격한 부스트 감소 방지)
    speed_ratio_softened = speed_ratio ** 0.7  # 더 완만한 곡선
    dynamic_boost = base_boost - (base_boost - min_boost) * speed_ratio_softened
    #  속도에 따른 동적 감속 시스템 설정
    global ball_boost_decay_rate, ball_min_boost
    # 감속 프레임 수 계산 (42프레임 → 35프레임까지 감소)
    base_decay_frames = 42        # 기본 감속 프레임 (느린 속도용)
    min_decay_frames = 35         # 최소 감속 프레임 (빠른 속도용) - 더 길게 감속
    dynamic_decay_frames = base_decay_frames - (base_decay_frames - min_decay_frames) * speed_ratio
    #  스무스 트랜지션 시스템: 속도 하락 완화 (70% → 55%로 조정)
    #  각도 기반: 수평에 가까울수록 더 낮은 최종 속도로 감속
    base_min_boost = 0.70         # 기본 최종 속도 (느린 속도용)
    min_min_boost = 0.55          # 최소 최종 속도 (빠른 속도용) - 감속 완화
    # 속도가 높을수록 더 낮은 값으로 감속 (기존보다 완화)
    dynamic_min_boost = base_min_boost - (base_min_boost - min_min_boost) * speed_ratio
    # 감속율 계산: dynamic_boost에서 dynamic_min_boost까지 dynamic_decay_frames에 걸쳐 감소
    adjusted_decay_frames = dynamic_decay_frames  # 기본값
    if dynamic_decay_frames > 0 and dynamic_boost > dynamic_min_boost:
        #  스무스 감속: 급격한 속도 변화 방지 (30% → 18%로 완화)
        speed_penalty_factor = 1.0 + speed_ratio * 0.18  # 고속일 때 감속 완화
        adjusted_decay_frames = dynamic_decay_frames / speed_penalty_factor
        ball_boost_decay_rate = (dynamic_min_boost / dynamic_boost) ** (1.0 / adjusted_decay_frames)
    else:
        ball_boost_decay_rate = 0.95  # 기본값
    ball_min_boost = dynamic_min_boost
    #  퍼펙트 타이밍 체크 (플레이어 패들만)
    perfect_shot = False
    if (
        paddle == PLAYER
        and perfect_timing_active
        and perfect_direction is not None
        and selected_character_type == "smasher"
    ):
        #  드라이브 발동을 위한 게이지 확인 (150 게이지 필요)
        if special_gauge >= 150:
            perfect_shot = True
            drive_activated = True  #  드라이브 발동 표시
            trigger_smasher_contact_animation(BALL.centerx - paddle.centerx)
            special_gauge -= 150  #  드라이브 발동 시 150 게이지 소모
            print(f"   !  ! ( 150 ,  : {special_gauge})")
            play_sound_with_volume(SOUND_DRIVE)  # 플레이어 드라이브 발동 효과음
            #  드라이브 성공 기록
            record_skill_usage(success=True)
            
            # 튜토리얼 드라이브 카운터 증가 (Chapter 3) - 왼쪽/오른쪽 분리
            global tutorial_drive_count, tutorial_drive_counter_active, tutorial_drive_completion_dialogue_shown
            global tutorial_left_drive_count, tutorial_right_drive_count
            if current_stage == 50 and tutorial_drive_counter_active:
                # 왼쪽/오른쪽 드라이브 구분
                if perfect_direction == -1:  # 왼쪽 드라이브
                    if tutorial_left_drive_count < 2:
                        tutorial_left_drive_count += 1
                        print(f"튜토리얼: 왼쪽 드라이브 성공 {tutorial_left_drive_count}/2")
                elif perfect_direction == 1:  # 오른쪽 드라이브  
                    if tutorial_right_drive_count < 2:
                        tutorial_right_drive_count += 1
                        print(f"튜토리얼: 오른쪽 드라이브 성공 {tutorial_right_drive_count}/2")
                
                # 총 드라이브 수 업데이트
                tutorial_drive_count = tutorial_left_drive_count + tutorial_right_drive_count
                
                print(f"튜토리얼: 드라이브 성공 {tutorial_drive_count}/4 (왼쪽: {tutorial_left_drive_count}/2, 오른쪽: {tutorial_right_drive_count}/2)")
                
                # 성공 피드백 표시
                if tutorial_drive_count == 1:
                    show_tutorial_success_feedback("드라이브 성공!", "normal")
                elif tutorial_drive_count == 2:
                    show_tutorial_success_feedback("멋져요!", "great")
                elif tutorial_drive_count == 3:
                    show_tutorial_success_feedback("한번만더!", "great")
                elif tutorial_drive_count == 4:
                    show_tutorial_success_feedback("드라이브 마스터!", "perfect")
                    # 카운터 축하 이펙트 활성화
                    global tutorial_drive_counter_celebration, tutorial_drive_counter_celebration_timer
                    tutorial_drive_counter_celebration = True
                    tutorial_drive_counter_celebration_timer = pygame.time.get_ticks()
                    
                    # 4회 완료 후 바로 축하 대화 표시
                    if not tutorial_drive_completion_dialogue_shown:
                        tutorial_drive_completion_dialogue_shown = True
                        # 게임 일시정지하고 대화 표시
                        tutorial_saved_ball_vel = ball_vel.copy()
                        ball_vel[0] = 0
                        ball_vel[1] = 0
                        print("튜토리얼: 드라이브 4회 완료! 축하 대화 표시")
                        
                        # 대화 시작 전에 게임 화면 그리기
                        draw_field()
                        draw_objects()
                        pygame.display.flip()
                        
                        # 드라이브 완료 대화 표시
                        dialogue_result = show_tutorial_drive_completion_dialogue()
                        print(f"🔍 DEBUG: dialogue_result = {dialogue_result}")
                        
                        # 대화 완료 후 Chapter 4로 전환
                        if dialogue_result == "proceed_to_chapter4" or dialogue_result == "skip_to_chapter4":
                            print("📚 드라이브 완료 대화 후 Chapter 4로 전환")
                            global tutorial_current_chapter
                            tutorial_current_chapter = 4
                            print(f"🔍 DEBUG: tutorial_current_chapter 변경됨 = {tutorial_current_chapter}")
                            # 챕터별 임시 게이지 오버라이드 해제 (Chapter 4는 500 고정)
                            tutorial_chapter1_max_gauge = None
                            tutorial_chapter2_max_gauge = None
                            tutorial_drive_chapter_max_gauge = None
                            print(f"🎮 Chapter 4: 게이지 오버라이드 해제 완료 - drive_gauge: {tutorial_drive_chapter_max_gauge}")
                            
                            # Chapter 4 타이틀 표시
                            show_chapter_title(4, "POWER SMASHING", "파워 스매싱")
                            
                            # Chapter 4 초기화: 최대 게이지를 500으로 설정
                            special_gauge_max = get_max_gauge()  # 500 반환
                            print(f"🎮 Chapter 4 시작: 최대 게이지 {special_gauge_max}로 설정")
                            
                            # 게이지 업데이트 강제 적용
                            game_state.special_gauge_max = special_gauge_max
                            print(f"🔍 DEBUG: game_state.special_gauge_max도 {game_state.special_gauge_max}로 업데이트")
                            
                            # Chapter 4 파워스매싱 튜토리얼 초기화
                            tutorial_power_practice_shown = False
                            tutorial_power_helper_dialogue_shown = False
                            tutorial_power_completion_dialogue_shown = False
                            tutorial_power_count = 0
                            tutorial_displayed_power_count = 0
                            tutorial_power_counter_active = False
                            tutorial_needs_power_practice = True
                            tutorial_power_reminder_active = False
                            tutorial_power_reminder_timer = 0
                            chapter4_dialogue_completed = False  # Chapter 4 대화 완료 플래그 초기화
                            chapter4_serve_reminder_active = False  # Chapter 4 서브 알림 플래그 초기화
                            chapter4_serve_reminder_timer = 0  # Chapter 4 서브 알림 타이머 초기화
                            chapter4_first_hit_after_dialogue = False  # Chapter 4 대화 후 첫 타격 플래그 초기화
                            chapter4_power_helper_shown = False  # Chapter 4 파워스매싱 도우미 표시 플래그 초기화
                            chapter4_power_helper_timer = 0  # Chapter 4 파워스매싱 도우미 타이머 초기화
                            
                            # Chapter 4 전환 직후 디버그 출력
                            print(f"[CHAPTER 4 INIT] Chapter 4 initialized successfully!")
                            print(f"[CHAPTER 4 INIT] tutorial_needs_power_practice: {tutorial_needs_power_practice}")
                            print(f"[CHAPTER 4 INIT] tutorial_power_practice_shown: {tutorial_power_practice_shown}")
                            print(f"[CHAPTER 4 INIT] tutorial_current_chapter: {tutorial_current_chapter}")
                            print(f"[CHAPTER 4 INIT] special_gauge_max: {special_gauge_max}")
                            
                            # 드라이브 카운터 비활성화
                            tutorial_drive_counter_active = False
                            tutorial_needs_drive_practice = False
                            
                            # Chapter 4 대화를 즉시 표시 (타이틀 후 바로)
                            # 먼저 게임 화면을 그려서 검은 화면이 아닌 게임 화면 위에 대화가 표시되도록 함
                            print("튜토리얼: Chapter 4 - POWER SMASHING 대화 즉시 시작 (handle_player)")
                            draw_field()
                            draw_objects()
                            pygame.display.flip()
                            
                            power_dialogue_result = show_tutorial_power_practice_dialogue()
                            if power_dialogue_result:
                                tutorial_power_practice_shown = True
                                tutorial_power_counter_active = True  # 카운터 활성화
                                chapter4_dialogue_completed = True  # Chapter 4 대화 완료 플래그 설정
                                chapter4_serve_reminder_active = True  # Chapter 4 서브 알림창 활성화 (변수명 수정)
                                chapter4_serve_reminder_timer = int(1.5 * FPS)  # 1.5초간 표시
                                print("튜토리얼: 파워스매싱 연습 대화 완료, 서브 알림 활성화 (handle_player)")
                        
                        # 공 속도 복원
                        if tutorial_saved_ball_vel:
                            ball_vel[0] = tutorial_saved_ball_vel[0]
                            ball_vel[1] = tutorial_saved_ball_vel[1]
            # 보스 반격 직후 보너스 적용 여부 확인
            if short_shot_counter_window > 0:
                counter_bonus_applied = True
                prev_speed = speed
                speed *= SHORT_SHOT_DRIVE_SPEED_MULTIPLIER
                counter_bonus_speed_gain = speed - prev_speed
                short_shot_counter_window = 0
                refresh_perfect_timing_indicator()
                print(f"⚡ 쇼트 카운터 보너스 발동! 속도 {prev_speed:.2f} → {speed:.2f} (+{counter_bonus_speed_gain:.2f})")
                effects_manager.spawn_short_shot_flash(BALL.centerx, BALL.centery)
                effects_manager.spawn_short_shot_flash(PLAYER.centerx, PLAYER.centery)

            # ️ 드라이브 스핀 효과 적용 (기본 커브량 + 공속 비례 추가 커브)
            global ball_spin_strength, ball_spin_direction, drive_ball_active, drive_hit_boss, drive_just_activated
            # 기본 커브량 유지
            base_spin = 0.25  # 기본 커브량 (현재 수준 유지)
            # 공속에 비례한 추가 커브량 계산
            speed_bonus_multiplier = speed * 0.015  # 공속 1당 0.015 추가 커브
            additional_spin = speed_bonus_multiplier
            spin_cap = 0.6
            if counter_bonus_applied:
                additional_spin += SHORT_SHOT_DRIVE_EXTRA_SPIN
                spin_cap = 0.68
            ball_spin_strength = base_spin + additional_spin
            # 최대 커브량 제한 (너무 과도하지 않게)
            ball_spin_strength = min(spin_cap, ball_spin_strength)
            ball_spin_direction = perfect_direction
            print(f"   - : {speed:.2f}, : {base_spin:.3f}, : {additional_spin:.3f},  : {ball_spin_strength:.3f}")
            drive_ball_active = True   # 드라이브 공 상태 활성화 (연두색)
            drive_hit_boss = False     # 드라이브 상태 초기화
            #  드라이브 별빛가루 파티클 생성
            spawn_drive_particles(BALL.centerx, BALL.centery, count=8)
            global drive_text_timer
            drive_text_timer = HALF_SECOND_FRAMES      # DRIVE! 텍스트 0.5초간 표시
            # 드라이브 성공 시 1.5% 속도 증가
            original_speed = speed
            speed *= 1.015
            #  드라이브로 증가한 속도량 추적 (보스 충돌 시 90% 감소용)
            drive_speed_increase = speed - original_speed
            print(f"   : {original_speed:.2f} → {speed:.2f} (: {drive_speed_increase:.2f})")
            #  패들 위치에 따른 드라이브 각도 조정 (균형잡힌 각도)
            if perfect_direction == -1:  # 왼쪽 드라이브
                # 패들 위치가 왼쪽일수록 각도 완화, 오른쪽일수록 각도 증가
                base_angle = -math.pi / 8.0  # 기본 22.5도
                position_factor = rel_x * 0.3  # 위치에 따른 조정 (-0.3 ~ +0.3)
                angle = base_angle + position_factor
            else:  # 오른쪽 드라이브
                # 패들 위치가 오른쪽일수록 각도 완화, 왼쪽일수록 각도 증가
                base_angle = math.pi / 8.0   # 기본 22.5도
                position_factor = rel_x * 0.3  # 위치에 따른 조정 (-0.3 ~ +0.3)
                angle = base_angle + position_factor
        else:
            print(f"    ! (: {special_gauge}, : 150)")
        # 퍼펙트 타이밍 상태 리셋
        perfect_timing_active = False
        perfect_direction = None
        refresh_perfect_timing_indicator()
        # 일반 충돌과 동일한 속도 처리
        #  속도에 관계없이 일정한 가속 적용 (완화된 증가율)
        base_multiplier = random.uniform(1.02, 1.07)  # 기본 가속 (2~7%, 평균 4.5%)
        speed *= base_multiplier
        #  임팩트 부스트 적용 (이제 최소 1.5배 보장)
        ball_impact_boost = dynamic_boost
        print(f"  :   {base_multiplier:.2f}x,  {dynamic_boost:.2f}x,  : {speed:.1f}")
    else:
        # 일반 충돌 시 동일한 가속 (완화된 증가율)
        base_multiplier = random.uniform(1.02, 1.07)  # 기본 가속 (2~7%, 평균 4.5%)
        speed *= base_multiplier
        #  임팩트 부스트 적용
        ball_impact_boost = dynamic_boost
    #  보스 충돌 처리 (플레이어가 아닌 경우)
    if not is_player_paddle:
        # 보스 충돌 시 추가 가속 (속도에 관계없이 일정, 크게 완화)
        boss_multiplier = random.uniform(1.01, 1.045)  # 보스 추가 가속 (1~4.5%, 평균 2.3%)
        speed *= boss_multiplier
    direction = -1 if paddle == PLAYER else 1
    vector = pygame.math.Vector2(0, direction).rotate_rad(angle)
    # === 다이나믹 물리효과 ===
    #  추가 속도 증가량 추적 (드라이브 외 일반 가속)
    if drive_activated:
        # 드라이브 발동 시에만 추가 가속 효과 추적
        if abs(rel_x) < 0.05:  # 극중앙 맞춤
            additional_speed = speed * 0.03  # 3% 증가
            speed *= 1.03
            drive_speed_increase += additional_speed
            # ️ 속도 증가에 따른 커브량 재계산
            base_spin = 0.25  # 기본 커브량 재선언
            speed_bonus_multiplier = speed * 0.015  # 증가된 공속에 비례한 커브
            ball_spin_strength = base_spin + speed_bonus_multiplier
            spin_cap = 0.6
            if counter_bonus_applied:
                ball_spin_strength += SHORT_SHOT_DRIVE_EXTRA_SPIN * 0.5
                spin_cap = 0.7
            ball_spin_strength = min(spin_cap, ball_spin_strength)  # 최대치 제한
            print(f"  +   : +{additional_speed:.2f} ( : {drive_speed_increase:.2f},  : {ball_spin_strength:.3f})")
        elif abs(rel_x) > 0.75:  # 스매시 zone
            additional_multiplier = random.uniform(1.015, 1.05)
            additional_speed = speed * (additional_multiplier - 1.0)
            speed *= additional_multiplier
            drive_speed_increase += additional_speed
            # ️ 속도 증가에 따른 커브량 재계산
            base_spin = 0.25  # 기본 커브량 재선언
            speed_bonus_multiplier = speed * 0.015  # 증가된 공속에 비례한 커브
            ball_spin_strength = base_spin + speed_bonus_multiplier
            spin_cap = 0.6
            if counter_bonus_applied:
                ball_spin_strength += SHORT_SHOT_DRIVE_EXTRA_SPIN * 0.5
                spin_cap = 0.7
            ball_spin_strength = min(spin_cap, ball_spin_strength)  # 최대치 제한
            print(f"  +   : +{additional_speed:.2f} ( : {drive_speed_increase:.2f},  : {ball_spin_strength:.3f})")
            curve = random.uniform(-5, 5)
            vector = vector.rotate(curve)
            ball_angle += random.uniform(3, 7) * (-1 if rel_x < 0 else 1)
    else:
        # 일반 상황에서는 기존 로직 유지
        if abs(rel_x) < 0.05:  # 극중앙 맞춤
            speed *= 1.03  # 살짝 가속 보정
        elif abs(rel_x) < 0.15:  # 중앙 zone
            curve = random.uniform(-35, 35)
            vector = vector.rotate(curve)
            spin = random.uniform(-2, 2)
            ball_angle += spin
        elif abs(rel_x) > 0.75:  # 스매시 zone
            speed *= random.uniform(1.015, 1.05)  # 스매시존 가속 (1.5~5%)
            curve = random.uniform(-5, 5)
            vector = vector.rotate(curve)
            ball_angle += random.uniform(3, 7) * (-1 if rel_x < 0 else 1)
    # 중앙 zone 처리 (드라이브 여부와 무관)
    if abs(rel_x) >= 0.05 and abs(rel_x) < 0.15:  # 중앙 zone
        curve = random.uniform(-35, 35)
        vector = vector.rotate(curve)
        spin = random.uniform(-2, 2)
        ball_angle += spin
        # 각도 제한 처리
        angle_limit = math.radians(60)
        if abs(angle) > angle_limit:
            angle = angle_limit * (1 if angle > 0 else -1)
            vector = pygame.math.Vector2(0, direction).rotate_rad(angle)
    else:  # 중간 zone
        if random.random() < 0.3:
            curve = random.uniform(-20, 20)
            vector = vector.rotate(curve)
            ball_angle += random.uniform(-2, 2)
    # 최종 속도 반영
    ball_vel[0] = speed * vector.x
    ball_vel[1] = speed * vector.y
    # 수직 튕김 방지 처리
    if abs(ball_vel[0]) < 0.5:
        vertical_bounce_count += 1
        correction = math.radians(random.choice([-3, 3]))  # 미세 꺾임
        vector = vector.rotate_rad(correction)
        ball_vel[0] = speed * vector.x
        ball_vel[1] = speed * vector.y
    else:
        vertical_bounce_count = 0
    # 완전 수직 튕김 보정
    if vertical_bounce_count >= 2:
        correction = math.radians(random.choice([-15, 15]))  # 강제 꺾임
        vector = vector.rotate_rad(correction)
        ball_vel[0] = speed * vector.x
        ball_vel[1] = speed * vector.y
        vertical_bounce_count = 0

    # 최소 발사 각도 보정 (너무 낮은 각도로 뻗어나가지 않도록 제한)
    min_bounce_angle_deg = 25
    min_vertical_ratio = math.sin(math.radians(min_bounce_angle_deg))
    current_speed = math.hypot(ball_vel[0], ball_vel[1])
    if current_speed > 0:
        vertical_ratio = abs(ball_vel[1]) / current_speed
        if vertical_ratio < min_vertical_ratio:
            horizontal_ratio = math.sqrt(max(0.0, 1.0 - min_vertical_ratio ** 2))
            ball_vel[1] = math.copysign(current_speed * min_vertical_ratio, ball_vel[1])
            ball_vel[0] = math.copysign(current_speed * horizontal_ratio, ball_vel[0])
            print(f"📐 최소 각도 보정 적용: |vy|/speed {vertical_ratio:.2f} → {min_vertical_ratio:.2f}")
    
    #  라그나로크 스턴공 효과 적용 (플래그가 설정되어 있으면)
    if is_player_paddle and ragnarok_speed_boost_active:
        # 라그나로크 발동 당시 공속을 저장해 보스 반격 시 완만하게 복구한다.
        ragnarok_original_speed = math.hypot(ball_vel[0], ball_vel[1])

        # 공속 30% 증가
        speed_boost_multiplier = 1.3
        ball_vel[0] *= speed_boost_multiplier
        ball_vel[1] *= speed_boost_multiplier
        new_ball_speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
        print(f"⚡ 라그나로크 스턴공 발동! 속도: {new_ball_speed:.1f} (50% 증가)")
        # 사운드 효과 재생
        try:
            play_ragnarok_shot_sound()
        except:
            pass
        # 시각적 효과
        try:
            create_impact_effect(BALL.centerx, BALL.centery, ball_vel, is_player=True)
        except:
            pass
    
    # 쇼트 카운터 보너스: 대쉬/파워스매싱 확장 처리 및 실패 시 초기화
    if is_player_paddle and short_shot_counter_window > 0 and not drive_activated:
        dash_combo_triggered = rolling_active or is_half_dash_active
        if dash_combo_triggered:
            prev_speed = math.hypot(ball_vel[0], ball_vel[1])
            speed_multiplier = SHORT_SHOT_DASH_SPEED_MULTIPLIER
            ball_vel[0] *= speed_multiplier
            ball_vel[1] *= speed_multiplier
            speed = prev_speed * speed_multiplier
            short_shot_counter_window = 0
            refresh_perfect_timing_indicator()
            dash_gain = speed - prev_speed
            print(f"⚡ 쇼트 카운터 대쉬 보너스! 속도 {prev_speed:.2f} → {speed:.2f} (+{dash_gain:.2f})")
            effects_manager.spawn_short_shot_flash(BALL.centerx, BALL.centery)
            effects_manager.spawn_short_shot_flash(PLAYER.centerx, PLAYER.centery)

    # 자폭드론 부스트 공을 보스가 쳤다면 무조건 원속도로 복원 (핵심 가드레일)
    if not is_player_paddle and suicide_drone_ball_boost_active and suicide_drone_ball_speed_backup > 0:
        current_speed = math.hypot(ball_vel[0], ball_vel[1])
        if current_speed > 0:
            restore_speed = suicide_drone_ball_speed_backup
            scale = restore_speed / current_speed
            ball_vel[0] *= scale
            ball_vel[1] *= scale
            try:
                game_vars.ball.vel[0] = ball_vel[0]
                game_vars.ball.vel[1] = ball_vel[1]
            except Exception:
                pass
            print(f"[DRONE] 보스 반격(보정): {current_speed:.2f} -> {restore_speed:.2f}, vel=({ball_vel[0]:.2f},{ball_vel[1]:.2f})")
        suicide_drone_ball_boost_active = False
        suicide_drone_ball_speed_backup = 0.0

    #  드라이브 발동 여부 반환
    return drive_activated
