                    #  악마의 주사위 효과 강제 종료 (기권 시)
                    from item_effects.devil_dice import deactivate_devil_dice
                    deactivate_devil_dice()
                    # 가로형 게이지 스택 정리 (기권 시)
                    try:
                        _hg_on_deactivate('devil_dice')
                    except Exception:
                        pass
                    
                    # 기권 처리 - 먼저 평가 결과 표시
                    try:
                        if player_analyzer:
                            show_death_evaluation()  # 기권 시에도 평가 결과 표시
                    except:
                        pass  # 평가 실패해도 계속 진행
                    # 기권 처리
                    earned = int(session_medal_earned * 0.5)
                    medal_score += earned
                    session_medal_earned = 0
                    # 아이템 관련 전부 초기화
                    items.reset_items()
                    try:
                        deactivate_vitamin_pill()
                    except Exception:
                        pass
                    # 듀스 시스템 리셋 (기권 시)
