                    #  가속화 스킬 레벨 초기화 (대쉬 사운드 원래대로)
                    acceleration_skill_level = 0
                    acceleration_height_bonus = 0  # 패들 높이 보너스 초기화
                    # 물자보급 스킬 초기화
                    supply_drop_state.active = False
